function setBoundedCacheValue(cache, key, value, limit) {
  if (!(cache instanceof Map) || !key) return;
  cache.delete(key);
  cache.set(key, value);
  while (cache.size > limit) {
    const oldestKey = cache.keys().next().value;
    if (oldestKey === undefined) break;
    cache.delete(oldestKey);
  }
}
