const WALLPAPER_FIT_MODES = new Set(['fill', 'fit', 'stretch', 'center', 'tile']);
const SCENE_WALLPAPER_PRESETS = Object.freeze(['cover-particles', 'topography', 'chladni']);
const SCENE_WALLPAPER_SOFT_GLOW_ID = 'soft-glow';
