function applyNativeMixerControl(source = {}) {
  const spatial = state.obrSpatialAudio;
  const previousSignature = nativeMixerControlSignature(spatial.mixerControl);
  const control = normalizeNativeMixerControl(source);
  spatial.mixerControl = control;
  spatial.requested = control.enabled;
  spatial.channelLayout = control.upmixOutputLayout;
  const nextSignature = nativeMixerControlSignature(control);
  if (previousSignature !== nextSignature) {
    notifyNativeAudioChainChanged('mixer-control');
  }
  syncGoogleObrToggle();
  return control;
}

async function refreshNativeMixerControl() {
  const spatial = state.obrSpatialAudio;
  if (spatial.mixerControlPromise) return spatial.mixerControlPromise;
  const request = apiJson('/api/audio/mixer')
    .then((snapshot) => applyNativeMixerControl(snapshot))
    .catch(() => {
      spatial.mixerControl = {
        ...spatial.mixerControl,
        attempted: true
      };
      return spatial.mixerControl;
    })
    .finally(() => {
      if (spatial.mixerControlPromise === request) spatial.mixerControlPromise = null;
    });
  spatial.mixerControlPromise = request;
  return request;
}

async function patchNativeMixerSpatialControl(parameters) {
  const current = await apiJson('/api/audio/mixer');
  const expectedRevision = Number(current?.revision);
  if (!Number.isSafeInteger(expectedRevision) || expectedRevision < 0) {
    throw new Error('调音台修订号无效');
  }
  const updated = await apiJson('/api/audio/mixer', {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ expectedRevision, parameters })
  });
  applyNativeMixerControl(updated);
  return updated;
}

function googleObrStatusLabel() {
  const spatial = state.obrSpatialAudio;
  const control = spatial.mixerControl || DEFAULT_NATIVE_MIXER_CONTROL;
  const serviceOwnsSpatial = control.loaded === true;
  const desiredObr = serviceOwnsSpatial ? control.obrEnabled === true : spatial.requested === true;
  const layout = GOOGLE_OBR_CHANNEL_LAYOUTS[normalizeGoogleObrChannelLayout(spatial.channelLayout)];
  if (spatial.enabled && desiredObr) return `Google OBR 官方内核运行中 · ${layout.label}`;
  if (spatial.enabled) {
    return control.upmixEnabled
      ? `原生调音链运行中 · 虚拟 ${control.upmixOutputLayout} 上混后双声道输出`
      : '原生调音链运行中 · 立体声调音输出';
  }
  if (spatial.recoveryTimer) return `Google OBR 正在恢复连接 · ${layout.label}`;
  if (spatial.loading) return '正在加载 Google OBR 官方内核';
  if (spatial.backend === 'waiting-for-audio' || (spatial.requested && spatial.backend === 'uninitialized')) {
    return 'Google OBR 已待命，播放音乐后启用';
  }
  if (spatial.backend === 'capture-stream-unsupported') return '当前音源无法接入 Google OBR';
  if (spatial.error) return `Google OBR 不可用：${spatial.error}`;
  return 'Google OBR 官方内核空间音频';
}

function syncGoogleObrToggle() {
  const button = els.qishuiPlaybackObrToggle;
  const layoutButton = els.qishuiPlaybackObrLayoutToggle;
  const spatial = state.obrSpatialAudio;
  const control = spatial.mixerControl || DEFAULT_NATIVE_MIXER_CONTROL;
  const serviceOwnsSpatial = control.loaded === true;
  const desiredObr = serviceOwnsSpatial ? control.obrEnabled === true : spatial.requested === true;
  const layout = GOOGLE_OBR_CHANNEL_LAYOUTS[normalizeGoogleObrChannelLayout(spatial.channelLayout)];
  document.documentElement.dataset.obrSpatialBackend = spatial.backend;
  document.documentElement.dataset.obrSpatialEnabled = String(spatial.enabled);
  document.documentElement.dataset.obrChannelLayout = layout.id;
  if (layoutButton) {
    layoutButton.textContent = layout.label;
    layoutButton.dataset.obrChannelLayout = layout.id;
    layoutButton.setAttribute('aria-label', `切换 Google OBR 声道布局，当前 ${layout.label}`);
    layoutButton.title = `Google OBR 虚拟声道：${layout.label}`;
    layoutButton.disabled = spatial.loading;
  }
  if (!button) return;
  const status = googleObrStatusLabel();
  const obrActive = spatial.enabled && desiredObr;
  const action = desiredObr ? '关闭' : '开启';
  const label = spatial.loading ? status : `${action}${status}`;
  button.classList.toggle('is-active', obrActive);
  button.classList.toggle('is-loading', spatial.loading);
  button.setAttribute('aria-pressed', String(desiredObr));
  button.setAttribute('aria-busy', String(spatial.loading));
  button.dataset.obrBackend = spatial.backend;
  button.setAttribute('aria-label', label);
  button.title = obrActive && spatial.processedBlocks
    ? `${label} · 已处理 ${spatial.processedBlocks} 个 PCM 块`
    : label;
}

function setAudioParamSmoothly(parameter, value, context, duration = 0.045) {
  if (!parameter || !context) return;
  const now = context.currentTime;
  const current = Number.isFinite(parameter.value) ? parameter.value : value;
  parameter.cancelScheduledValues(now);
  parameter.setValueAtTime(current, now);
  parameter.linearRampToValueAtTime(value, now + duration);
}

function setAudioParamEqualPower(parameter, value, context, duration = 0.018) {
  if (!parameter || !context) return;
  const now = context.currentTime;
  const target = Number.isFinite(Number(value)) ? Number(value) : 0;
  const current = Number.isFinite(parameter.value) ? parameter.value : target;
  const seconds = Math.max(0.001, Number(duration) || 0.018);
  parameter.cancelScheduledValues(now);
  parameter.setValueAtTime(current, now);
  if (Math.abs(target - current) < 0.0001) return;

  // AudioParam curves are rendered sample-accurately by the audio thread.
  // Sine-in/cosine-out keeps the dry/native hand-off close to constant power
  // while XAudio2 fades and flushes the obsolete timeline on its control path.
  const curve = new Float32Array(33);
  const increasing = target > current;
  for (let index = 0; index < curve.length; index += 1) {
    const progress = index / (curve.length - 1);
    const interpolation = increasing
      ? Math.sin(progress * Math.PI * 0.5)
      : 1 - Math.cos(progress * Math.PI * 0.5);
    curve[index] = current + (target - current) * interpolation;
  }
  parameter.setValueCurveAtTime(curve, now, seconds);
}

function ensureDryAudioOutput(analysis) {
  if (analysis.dryGain || !analysis.context || !analysis.analyser) return analysis.dryGain;
  analysis.dryGain = analysis.context.createGain();
  analysis.dryGain.gain.value = 1;
  analysis.analyser.connect(analysis.dryGain);
  analysis.dryGain.connect(analysis.context.destination);
  analysis.outputConnected = true;
  return analysis.dryGain;
}

function canUseNativeGoogleObr(channelLayout = state.obrSpatialAudio.channelLayout) {
  const nativeAudio = state.clientRuntime.nativeAudio || {};
  return (
    state.clientRuntime.nativeAudioActive
    && state.clientRuntime.settings.xAudio2
    && nativeAudio.spatialStreaming === true
    && typeof fetch === 'function'
    && typeof AudioWorkletNode === 'function'
  );
}

function nativeSpatialRequest(path) {
  return apiJson(path, {
    method: 'POST',
    headers: { 'X-FE-Monster-Audio': '1' }
  });
}

function notifyNativeAudioChainChanged(reason) {
  document.dispatchEvent(new CustomEvent('fe-native-audio-chain:change', {
    detail: {
      reason: safeText(reason, 'state-change'),
      backend: state.obrSpatialAudio.backend,
      enabled: state.obrSpatialAudio.enabled === true
    }
  }));
}

function recycleNativeSpatialBlock(graph, block) {
  if (!block || block.released) return false;
  block.released = true;
  const pcm = block.pcm;
  block.pcm = null;
  if (
    graph.disposed
    || !(pcm instanceof Float32Array)
    || !Number.isInteger(block.bufferId)
    || !Number.isInteger(block.poolEpoch)
  ) return false;
  try {
    graph.node.port.postMessage({
      type: 'recycle-pcm',
      pcm,
      bufferId: block.bufferId,
      poolEpoch: block.poolEpoch
    }, [pcm.buffer]);
    return true;
  } catch (error) {
    return false;
  }
}

function discardNativeSpatialBlocks(graph, options = {}) {
  const recycle = options.recycle === true && !graph.disposed;
  while (graph.blockQueue.length) {
    const block = graph.blockQueue.shift();
    if (recycle) {
      recycleNativeSpatialBlock(graph, block);
    } else if (block && !block.released) {
      block.released = true;
      block.pcm = null;
    }
  }
}

function enqueueNativeSpatialBlock(graph, pcm, ownership = {}) {
  if (graph.disposed || !(pcm instanceof Float32Array)) return false;
  const expectedBytes = GOOGLE_OBR_NATIVE_TRANSPORT_FRAMES * 2 * Float32Array.BYTES_PER_ELEMENT;
  if (pcm.byteLength !== expectedBytes) {
    failGoogleObr(new Error('原生 PCM 分块长度无效'), { announce: false, graph });
    return false;
  }
  if (!Number.isInteger(ownership.bufferId) || !Number.isInteger(ownership.poolEpoch)) {
    failGoogleObr(new Error('原生 PCM 分块所有权无效'), { announce: false, graph });
    return false;
  }
  const timelineEpoch = Number.isInteger(ownership.timelineEpoch)
    ? ownership.timelineEpoch
    : (Number.isInteger(graph.captureTimelineEpoch) ? graph.captureTimelineEpoch : 1);
  if (
    Number.isInteger(graph.captureTimelineEpoch)
    && timelineEpoch !== graph.captureTimelineEpoch
  ) {
    recycleNativeSpatialBlock(graph, {
      pcm,
      bufferId: ownership.bufferId,
      poolEpoch: ownership.poolEpoch,
      timelineEpoch,
      released: false
    });
    return false;
  }
  if (graph.blockQueue.length >= GOOGLE_OBR_NATIVE_MAX_PENDING_BLOCKS) {
    recycleNativeSpatialBlock(graph, graph.blockQueue.shift());
    if (graph.timelineTransitionActive) {
      graph.transportSeekDiscardedBlocks += 1;
    } else {
      graph.transportDroppedBlocks += 1;
    }
  }
  graph.blockQueue.push({
    pcm,
    bufferId: ownership.bufferId,
    poolEpoch: ownership.poolEpoch,
    timelineEpoch,
    nativeGeneration: graph.timelineTransitionActive ? 0 : graph.generation,
    released: false
  });
  pumpNativeSpatialBlocks(graph);
  return true;
}

async function pumpNativeSpatialBlocks(graph) {
  if (graph.disposed || graph.blockUploadActive || graph.timelineTransitionActive) return;
  graph.blockUploadActive = true;
  try {
    while (!graph.disposed && graph.blockQueue.length) {
      const block = graph.blockQueue.shift();
      if (
        (
          Number.isInteger(graph.captureTimelineEpoch)
          && block.timelineEpoch !== graph.captureTimelineEpoch
        )
        || !Number.isSafeInteger(Number(block.nativeGeneration))
        || Number(block.nativeGeneration) <= 0
      ) {
        recycleNativeSpatialBlock(graph, block);
        continue;
      }
      graph.activeBlock = block;
      try {
        const sequence = graph.nextBlockSequence;
        graph.nextBlockSequence += 1;
        const params = new URLSearchParams({
          session: String(graph.session),
          generation: String(block.nativeGeneration),
          inputChannels: '2',
          sequence: String(sequence)
        });
        let response = null;
        let payload = null;
        let uploadError = null;
        for (let attempt = 0; attempt < 3; attempt += 1) {
          try {
            response = await fetch(`/api/audio/spatial/block?${params}`, {
              method: 'POST',
              headers: {
                'Content-Type': 'application/octet-stream',
                'X-FE-Monster-Audio': '1'
              },
              body: block.pcm,
              signal: graph.streamAbort.signal
            });
            try {
              payload = await response.json();
            } catch (error) {
              payload = null;
            }
            if (response.ok && payload?.ok === true && Number(payload.sequence) === sequence) {
              if (attempt > 0) graph.transportRecoveredBlocks += 1;
              uploadError = null;
              break;
            }
            uploadError = new Error(
              safeText(payload?.error, `原生 PCM 分块失败：HTTP ${response.status}`)
            );
          } catch (error) {
            uploadError = error;
          }
          graph.transportRetryAttempts += 1;
          const obsoleteAttempt = graph.disposed
            || graph.timelineTransitionActive
            || block.timelineEpoch !== graph.captureTimelineEpoch
            || Number(block.nativeGeneration) !== Number(graph.generation);
          if (obsoleteAttempt) break;
        }
        const obsolete = graph.disposed
          || graph.timelineTransitionActive
          || (
            Number.isInteger(graph.captureTimelineEpoch)
            && block.timelineEpoch !== graph.captureTimelineEpoch
          )
          || Number(block.nativeGeneration) !== Number(graph.generation);
        if (
          uploadError
          && !obsolete
        ) {
          throw uploadError;
        }
        if (!obsolete) graph.uploadedBlocks += 1;
      } catch (error) {
        const obsolete = graph.disposed
          || graph.timelineTransitionActive
          || (
            Number.isInteger(graph.captureTimelineEpoch)
            && block.timelineEpoch !== graph.captureTimelineEpoch
          )
          || Number(block.nativeGeneration) !== Number(graph.generation);
        if (!obsolete) throw error;
      } finally {
        if (graph.activeBlock === block) graph.activeBlock = null;
        if (graph.disposed) {
          block.released = true;
          block.pcm = null;
        } else {
          recycleNativeSpatialBlock(graph, block);
        }
      }
    }
  } catch (error) {
    discardNativeSpatialBlocks(graph, { recycle: !graph.disposed });
    if (!graph.disposed && error?.name !== 'AbortError' && state.obrSpatialAudio.requested) {
      graph.transportRecoveryCount += 1;
      setAudioParamSmoothly(graph.dryGain?.gain, 1, graph.context, 0.018);
      beginNativeSpatialTimelineTransition('transport-recovery').catch((recoveryError) => {
        if (!graph.disposed) {
          failGoogleObr(recoveryError || error, { announce: false, graph });
        }
      });
    }
  } finally {
    graph.blockUploadActive = false;
    if (!graph.disposed && graph.blockQueue.length) pumpNativeSpatialBlocks(graph);
  }
}

async function createNativeGoogleObrGraph(analysis) {
  if (!analysis.context?.audioWorklet || typeof AudioWorkletNode !== 'function') {
    throw new Error('当前播放内核不支持原生 PCM AudioWorklet');
  }
  const control = state.obrSpatialAudio.mixerControl || DEFAULT_NATIVE_MIXER_CONTROL;
  const channelLayout = control.loaded === true
    ? (control.upmixOutputLayout === '7.1' ? '7.1' : '5.1')
    : normalizeGoogleObrChannelLayout(state.obrSpatialAudio.channelLayout);
  const layoutChannels = channelLayout === '7.1' ? 8 : 6;
  if (layoutChannels !== 6 && layoutChannels !== 8) {
    throw new Error('Rust 上混只用于 5.1 或 7.1 空间音频');
  }

  const sampleRate = Math.round(Number(analysis.context.sampleRate) || 48000);
  const algorithm = {
    passive: 1,
    'matrix-decode': 2,
    'ambient-extract': 3
  }[control.upmixAlgorithm] || 2;
  const startParams = new URLSearchParams({
    sampleRate: String(sampleRate),
    inputChannels: '2',
    layoutChannels: String(layoutChannels),
    algorithm: String(algorithm)
  });
  const start = await nativeSpatialRequest(`/api/audio/spatial/start?${startParams}`);
  if (!start?.ok || !Number(start.session) || !Number(start.generation)) {
    throw new Error(safeText(start?.error, '原生空间音频链路初始化失败'));
  }
  const session = Number(start.session);
  const generation = Number(start.generation);
  if (control.upmixEnabled && start.rustUpmixActive !== true) {
    await nativeSpatialRequest(
      `/api/audio/spatial/stop?session=${encodeURIComponent(session)}&generation=${encodeURIComponent(generation)}`
    ).catch(() => {});
    throw new Error('OxiMedia Rust 上混动态库未加载');
  }

  try {
    await analysis.context.audioWorklet.addModule(GOOGLE_OBR_NATIVE_WORKLET_URL);
    const node = new AudioWorkletNode(analysis.context, 'fe-native-pcm-bridge', {
      numberOfInputs: 1,
      numberOfOutputs: 1,
      outputChannelCount: [2],
      channelCount: 2,
      channelCountMode: 'explicit',
      channelInterpretation: 'speakers'
    });
    const wetGain = analysis.context.createGain();
    wetGain.gain.value = 0;
    const streamAbort = new AbortController();
    const graph = {
      context: analysis.context,
      inputNode: analysis.analyser,
      node,
      dryGain: ensureDryAudioOutput(analysis),
      wetGain,
      backend: GOOGLE_OBR_NATIVE_BACKEND,
      revision: GOOGLE_OBR_REVISION,
      channelLayout,
      mixerControlSignature: nativeMixerControlSignature(control),
      mixerControlRevision: control.revision,
      upmixEnabled: control.upmixEnabled,
      obrEnabled: control.obrEnabled,
      inputChannelCount: layoutChannels,
      ready: true,
      processedBlocks: 0,
      pendingProcess: null,
      disableTimer: 0,
      connected: true,
      nativeStream: true,
      session,
      generation,
      streamAbort,
      blockQueue: [],
      blockUploadActive: false,
      activeBlock: null,
      nextBlockSequence: 0,
      uploadedBlocks: 0,
      transportDroppedBlocks: 0,
      transportSeekDiscardedBlocks: 0,
      transportRetryAttempts: 0,
      transportRecoveredBlocks: 0,
      transportRecoveryCount: 0,
      poolStarvedFrames: 0,
      captureTimelineEpoch: 1,
      appliedTimelineEpoch: 1,
      timelineTransitionActive: false,
      timelineResetPromise: null,
      timelineResetCount: 0,
      timelineResetFailures: 0,
      timelineLastNativeResetMs: 0,
      timelineWorstNativeResetMs: 0,
      disposed: false,
      inputRms: 0,
      outputRms: 0,
      nativeQueueUnderruns: 0,
      nativeBuffersQueued: 0,
      nativeOutputLatencySeconds: 0,
      nativeClockOriginMediaTime: Number(els.audio?.currentTime) || 0,
      nativeClockOriginConsumedFrames: 0,
      nativeLastMediaTime: Number(els.audio?.currentTime) || 0
    };

    node.port.onmessage = (event) => {
      const message = event.data || {};
      if (message.type === 'pcm') {
        if (graph.disposed || !(message.pcm instanceof Float32Array)) return;
        try {
          const pcm = message.pcm;
          enqueueNativeSpatialBlock(graph, pcm, {
            bufferId: message.bufferId,
            poolEpoch: message.poolEpoch,
            timelineEpoch: message.timelineEpoch
          });
          graph.processedBlocks = Math.max(graph.processedBlocks, Number(message.blocks) || 0);
          graph.inputRms = Number(message.inputRms) || graph.inputRms;
          state.obrSpatialAudio.processedBlocks = graph.processedBlocks;
          state.obrSpatialAudio.inputRms = graph.inputRms;
        } catch (error) {
          if (!graph.disposed && state.obrSpatialAudio.requested) {
            failGoogleObr(error, { announce: false, graph });
          }
        }
        return;
      }
      if (message.type === 'metrics') {
        graph.processedBlocks = Math.max(graph.processedBlocks, Number(message.processedBlocks) || 0);
        graph.inputRms = Number(message.inputRms) || graph.inputRms;
        graph.poolStarvedFrames = Math.max(
          graph.poolStarvedFrames,
          Math.max(0, Number(message.poolStarvedFrames) || 0)
        );
        state.obrSpatialAudio.processedBlocks = graph.processedBlocks;
        state.obrSpatialAudio.inputRms = graph.inputRms;
        if (state.obrSpatialAudio.enabled) syncGoogleObrToggle();
      }
    };
    node.onprocessorerror = () => {
      if (!graph.disposed && state.obrSpatialAudio.requested) {
        failGoogleObr(new Error('原生 PCM AudioWorklet 已停止'), {
          announce: false,
          graph
        });
      }
    };

    analysis.analyser.connect(node);
    node.connect(wetGain);
    wetGain.connect(analysis.context.destination);
    return graph;
  } catch (error) {
    await nativeSpatialRequest(
      `/api/audio/spatial/stop?session=${encodeURIComponent(session)}&generation=${encodeURIComponent(generation)}`
    ).catch(() => {});
    throw error;
  }
}

async function waitForNativeGoogleObrPreroll(graph) {
  const startedAt = performance.now();
  const renderBlocksPerTransport = Math.ceil(
    GOOGLE_OBR_NATIVE_TRANSPORT_FRAMES / GOOGLE_OBR_NATIVE_RENDER_FRAMES
  );
  while (!graph.disposed && performance.now() - startedAt < 5000) {
    if (graph.transportDroppedBlocks > 0 || graph.poolStarvedFrames > 0) {
      throw new Error(
        graph.poolStarvedFrames > 0
          ? `原生 PCM 缓冲池耗尽：丢失 ${graph.poolStarvedFrames} 帧`
          : `原生 PCM 上传队列溢出：丢失 ${graph.transportDroppedBlocks} 块`
      );
    }
    const status = await apiJson('/api/audio/spatial/status');
    if (
      !status?.active
      || Number(status.session) !== Number(graph.session)
      || Number(status.generation) !== Number(graph.generation)
    ) {
      throw new Error('原生空间音频会话已中断');
    }
    if (
      Number(status.droppedBuffers) > 0
      || Number(status.bufferPoolExhaustions) > 0
      || Number(status.queueUnderruns) > 0
      || Number(status.lastResult) < 0
    ) {
      throw new Error(`原生空间音频队列异常：${Number(status.lastResult) || 'dropped'}`);
    }
    const processed = Number(status.obrProcessCalls) || 0;
    const rustCalls = Number(status.rustUpmixProcessCalls) || 0;
    const mixerCalls = Number(status.mixerProcessCalls) || Number(status.processCalls) || 0;
    const spatialRevisionCommitted = status.spatialRevisionCommitted === true;
    const spatialRevisionMatches = Number(status.spatialActiveRevision)
      === Number(graph.mixerControlRevision);
    if (
      status.voiceStarted === true
      && Number(status.buffersQueued) > 0
      && status.transitionPending !== true
      && spatialRevisionCommitted
      && spatialRevisionMatches
      && mixerCalls >= 1
      && (!graph.obrEnabled || processed >= renderBlocksPerTransport)
      && (!graph.upmixEnabled || rustCalls >= 1)
    ) {
      graph.outputRms = Number(status.outputEnergy) || 0;
      updateNativeGoogleObrMetrics(graph, status);
      state.obrSpatialAudio.outputRms = graph.outputRms;
      return status;
    }
    await new Promise((resolve) => window.setTimeout(resolve, 25));
  }
  throw new Error('原生 Rust/X3DAudio/OBR 链路未收到实时 PCM');
}

function updateNativeGoogleObrMetrics(graph, status = {}) {
  if (!graph?.nativeStream || graph.disposed) return 0;
  const spatial = state.obrSpatialAudio;
  const sampleRate = Math.max(
    1,
    Number(status.sampleRate) || Number(graph.context?.sampleRate) || 48000
  );
  const buffersQueued = Math.max(0, Number(status.buffersQueued) || 0);
  const buffersConsumed = Math.max(0, Number(status.buffersConsumed) || 0);
  const consumedFrames = buffersConsumed * GOOGLE_OBR_NATIVE_RENDER_FRAMES;
  const mediaTime = Math.max(0, Number(els.audio?.currentTime) || 0);
  const previousMediaTime = Number(graph.nativeLastMediaTime);
  const mediaClockJumped = Number.isFinite(previousMediaTime)
    && Math.abs(mediaTime - previousMediaTime) > 1;
  const fallbackLatency = clamp(
    (
      Math.max(1, Number(status.prerollTargetBuffers) || 1)
      * GOOGLE_OBR_NATIVE_RENDER_FRAMES
    ) / sampleRate,
    0,
    LYRIC_AUDIO_OUTPUT_LATENCY_MAX_SECONDS
  );

  if (
    !Number.isFinite(Number(graph.nativeClockOriginMediaTime))
    || !Number.isFinite(Number(graph.nativeClockOriginConsumedFrames))
  ) {
    graph.nativeClockOriginMediaTime = mediaTime;
    graph.nativeClockOriginConsumedFrames = consumedFrames;
  } else if (mediaClockJumped) {
    const preservedLatency = Math.max(
      0,
      Number(graph.nativeOutputLatencySeconds) || fallbackLatency
    );
    graph.nativeClockOriginMediaTime = mediaTime - preservedLatency;
    graph.nativeClockOriginConsumedFrames = consumedFrames;
  }

  const measuredLatency = (
    mediaTime - Number(graph.nativeClockOriginMediaTime)
  ) - (
    consumedFrames - Number(graph.nativeClockOriginConsumedFrames)
  ) / sampleRate;
  const outputLatency = clamp(
    Number.isFinite(measuredLatency) && measuredLatency >= 0
      ? measuredLatency
      : Number(graph.nativeOutputLatencySeconds) || fallbackLatency,
    0,
    LYRIC_AUDIO_OUTPUT_LATENCY_MAX_SECONDS
  );

  graph.nativeLastMediaTime = mediaTime;
  graph.nativeBuffersQueued = buffersQueued;
  graph.nativeQueueUnderruns = Math.max(0, Number(status.queueUnderruns) || 0);
  graph.nativeOutputLatencySeconds = outputLatency;
  spatial.nativeBuffersQueued = buffersQueued;
  spatial.nativeQueueUnderruns = graph.nativeQueueUnderruns;
  spatial.nativeOutputLatencySeconds = outputLatency;
  return outputLatency;
}

function refreshNativeGoogleObrHealth() {
  const spatial = state.obrSpatialAudio;
  const graph = spatial.graph;
  if (
    document.hidden
    || !spatial.requested
    || !spatial.enabled
    || !graph?.nativeStream
    || graph.disposed
  ) {
    return Promise.resolve(null);
  }
  if (spatial.nativeHealthRequest) return spatial.nativeHealthRequest;

  const previousUnderruns = Math.max(0, Number(graph.nativeQueueUnderruns) || 0);
  const request = apiJson('/api/audio/spatial/status')
    .then((status) => {
      if (
        spatial.graph !== graph
        || graph.disposed
        || !spatial.requested
        || !spatial.enabled
      ) {
        return null;
      }
      if (
        !status?.active
        || Number(status.session) !== Number(graph.session)
        || Number(status.generation) !== Number(graph.generation)
      ) {
        failGoogleObr(new Error('Native OBR session stopped'), { announce: false, graph });
        return status;
      }

      updateNativeGoogleObrMetrics(graph, status);
      const underruns = Math.max(0, Number(status.queueUnderruns) || 0);
      const unhealthy = Number(status.droppedBuffers) > 0
        || Number(status.bufferPoolExhaustions) > 0
        || Number(status.lastResult) < 0
        || graph.transportDroppedBlocks > 0
        || graph.poolStarvedFrames > 0;
      if (underruns > previousUnderruns || unhealthy) {
        const reason = underruns > previousUnderruns
          ? `Native XAudio2 queue underrun ${previousUnderruns} -> ${underruns}`
          : graph.poolStarvedFrames > 0
            ? `Native PCM pool starvation dropped ${graph.poolStarvedFrames} frames`
            : graph.transportDroppedBlocks > 0
              ? `Native PCM upload overflow dropped ${graph.transportDroppedBlocks} blocks`
              : 'Native OBR queue reported a render failure';
        failGoogleObr(new Error(reason), { announce: false, graph });
      }
      return status;
    })
    .catch(() => null)
    .finally(() => {
      if (spatial.nativeHealthRequest === request) spatial.nativeHealthRequest = null;
    });
  spatial.nativeHealthRequest = request;
  return request;
}

function setGoogleObrRuntimeBackend(active) {
  const spatial = state.obrSpatialAudio;
  if (active) {
    if (!spatial.previousRuntimeBackend) {
      spatial.previousRuntimeBackend = state.clientRuntime.audioSpatialBackend || 'x3daudio';
    }
    state.clientRuntime.audioSpatialBackend = spatial.graph?.backend || GOOGLE_OBR_BACKEND;
  } else if (spatial.previousRuntimeBackend) {
    state.clientRuntime.audioSpatialBackend = spatial.previousRuntimeBackend;
    spatial.previousRuntimeBackend = '';
  }
  applyRuntimeDataset();
}

function clearGoogleObrRecovery() {
  const spatial = state.obrSpatialAudio;
  window.clearTimeout(spatial.recoveryTimer);
  spatial.recoveryTimer = 0;
}

function connectOfficialGoogleObrGraph(graph) {
  if (!graph || graph.connected) return;
  graph.inputNode.connect(graph.node);
  graph.node.connect(graph.wetGain);
  graph.wetGain.connect(graph.context.destination);
  graph.connected = true;
}

function disconnectOfficialGoogleObrGraph(graph) {
  if (!graph || !graph.connected) return;
  try { graph.inputNode.disconnect(graph.node); } catch (error) {}
  try { graph.node.disconnect(graph.wetGain); } catch (error) {}
  try { graph.wetGain.disconnect(graph.context.destination); } catch (error) {}
  graph.connected = false;
}

function disposeOfficialGoogleObrGraph(graph = state.obrSpatialAudio.graph, options = {}) {
  if (!graph) return Promise.resolve(null);
  window.clearTimeout(graph.disableTimer);
  graph.disableTimer = 0;
  // Keep the dry path audible while a failed/reconfigured OBR graph is rebuilt.
  // The dry gain is owned by the shared analyser graph and remains connected
  // after the wet worklet is disposed.
  const now = Number(graph.context?.currentTime) || 0;
  const dryGain = graph.dryGain?.gain;
  const wetGain = graph.wetGain?.gain;
  try {
    dryGain?.cancelScheduledValues(now);
    wetGain?.cancelScheduledValues(now);
    if (dryGain) dryGain.value = 1;
    if (wetGain) wetGain.value = 0;
  } catch (error) {
    if (dryGain) dryGain.value = 1;
    if (wetGain) wetGain.value = 0;
  }
  if (graph.nativeStream) {
    graph.disposed = true;
    discardNativeSpatialBlocks(graph);
    if (graph.pendingProcess) {
      const pending = graph.pendingProcess;
      graph.pendingProcess = null;
      window.clearTimeout(pending.timeout);
      pending.reject(new Error('原生空间音频链路已重建'));
    }
    try { graph.node.port.postMessage({ type: 'set-enabled', enabled: false }); } catch (error) {}
    disconnectOfficialGoogleObrGraph(graph);
    try { graph.streamController?.close(); } catch (error) {}
    graph.streamAbort?.abort();
    const nativeAction = options.nativeAction === 'pause' ? 'pause' : 'stop';
    const nativeRelease = nativeSpatialRequest(
      `/api/audio/spatial/${nativeAction}?session=${encodeURIComponent(graph.session)}&generation=${encodeURIComponent(graph.generation)}`
    ).catch(() => null);
    try { graph.node.port.close(); } catch (error) {}
    graph.node.onprocessorerror = null;
    graph.ready = false;
    if (state.obrSpatialAudio.graph === graph) {
      state.obrSpatialAudio.graph = null;
      state.obrSpatialAudio.nativeBuffersQueued = 0;
      state.obrSpatialAudio.nativeQueueUnderruns = 0;
      state.obrSpatialAudio.nativeOutputLatencySeconds = 0;
    }
    return nativeRelease;
  }
  if (graph.pendingProcess) {
    const pending = graph.pendingProcess;
    graph.pendingProcess = null;
    window.clearTimeout(pending.timeout);
    pending.reject(new Error('Google OBR 音频链路已重建'));
  }
  try { graph.node.port.postMessage({ type: 'set-enabled', enabled: false }); } catch (error) {}
  disconnectOfficialGoogleObrGraph(graph);
  try { graph.node.port.close(); } catch (error) {}
  graph.node.onprocessorerror = null;
  graph.ready = false;
  if (state.obrSpatialAudio.graph === graph) state.obrSpatialAudio.graph = null;
  return Promise.resolve(null);
}

function beginNativeSpatialTimelineTransition(reason = 'seek') {
  const spatial = state.obrSpatialAudio;
  const graph = spatial.graph;
  if (!graph?.nativeStream || graph.disposed) return Promise.resolve(false);

  graph.captureTimelineEpoch = Math.max(
    Number(graph.captureTimelineEpoch) || 1,
    Number(graph.appliedTimelineEpoch) || 1
  ) + 1;
  graph.timelineTransitionActive = true;
  graph.timelineResetReason = safeText(reason, 'seek');
  graph.timelineResetRequestedAt = performance.now();
  setAudioParamEqualPower(graph.dryGain?.gain, 1, graph.context, 0.018);
  discardNativeSpatialBlocks(graph, { recycle: true });
  try {
    graph.node.port.postMessage({
      type: 'reset-timeline',
      timelineEpoch: graph.captureTimelineEpoch,
      fadeFrames: Math.max(1, Math.round((Number(graph.context?.sampleRate) || 48000) * 0.015))
    });
  } catch (error) {
    return Promise.reject(error);
  }
  return resetNativeSpatialTimeline(graph);
}

function resetNativeSpatialTimeline(graph) {
  if (!graph?.nativeStream || graph.disposed) return Promise.resolve(false);
  if (graph.timelineResetPromise) return graph.timelineResetPromise;

  const reset = (async () => {
    // The request starts immediately: browser dry gain and the XAudio2 voice
    // follow complementary short fades while media seeking itself remains
    // synchronous and neither audio render thread is blocked.
    while (
      !graph.disposed
      && Number(graph.appliedTimelineEpoch) !== Number(graph.captureTimelineEpoch)
    ) {
      const targetEpoch = graph.captureTimelineEpoch;
      const requestedGeneration = graph.generation;
      let response = null;
      let lastError = null;
      for (let attempt = 0; attempt < 3 && !graph.disposed; attempt += 1) {
        try {
          response = await nativeSpatialRequest(
            `/api/audio/spatial/timeline?session=${encodeURIComponent(graph.session)}`
              + `&generation=${encodeURIComponent(requestedGeneration)}`
          );
          if (response?.ok === true) break;
          lastError = new Error(safeText(response?.error, '原生音频时间线重置失败'));
        } catch (error) {
          lastError = error;
        }
        await new Promise((resolve) => window.setTimeout(resolve, 25 * (attempt + 1)));
      }
      if (graph.disposed) return false;
      const nextGeneration = Number(response?.generation);
      if (
        response?.ok !== true
        || Number(response?.session) !== Number(graph.session)
        || !Number.isSafeInteger(nextGeneration)
        || nextGeneration <= requestedGeneration
      ) {
        throw lastError || new Error('原生音频时间线 generation 未推进');
      }
      graph.generation = nextGeneration;
      graph.appliedTimelineEpoch = targetEpoch;
      graph.timelineResetCount += 1;
      const nativeResetMs = Number(response?.resetElapsedMs);
      if (Number.isFinite(nativeResetMs) && nativeResetMs >= 0) {
        graph.timelineLastNativeResetMs = nativeResetMs;
        graph.timelineWorstNativeResetMs = Math.max(
          Number(graph.timelineWorstNativeResetMs) || 0,
          nativeResetMs
        );
      }
    }
    if (graph.disposed) return false;

    const currentBlocks = [];
    while (graph.blockQueue.length) {
      const block = graph.blockQueue.shift();
      if (block?.timelineEpoch === graph.captureTimelineEpoch) {
        currentBlocks.push(block);
      } else {
        recycleNativeSpatialBlock(graph, block);
      }
    }
    // Keep only the newest 4096-frame block. It contributes sixteen of the
    // 24 production preroll quanta; the next live worklet block completes the
    // queue while browser dry audio remains audible. This bounds scrub latency.
    while (currentBlocks.length > 1) {
      recycleNativeSpatialBlock(graph, currentBlocks.shift());
      graph.transportSeekDiscardedBlocks += 1;
    }
    for (const block of currentBlocks) {
      block.nativeGeneration = graph.generation;
      graph.blockQueue.push(block);
    }
    graph.timelineTransitionActive = false;
    pumpNativeSpatialBlocks(graph);

    if (
      els.audio?.src
      && !els.audio.paused
      && !els.audio.ended
      && state.obrSpatialAudio.requested
    ) {
      await waitForNativeGoogleObrPreroll(graph);
      if (graph.disposed || graph.timelineTransitionActive) return false;
      const activation = await nativeSpatialRequest(
        `/api/audio/spatial/activate?session=${encodeURIComponent(graph.session)}`
          + `&generation=${encodeURIComponent(graph.generation)}`
      );
      if (!activation?.ok) {
        throw new Error(safeText(activation?.error, '原生空间音频无法恢复输出'));
      }
      setAudioParamEqualPower(graph.dryGain?.gain, 0, graph.context, 0.025);
    }
    return true;
  })();
  graph.timelineResetPromise = reset;
  reset.catch((error) => {
    graph.timelineResetFailures += 1;
    graph.timelineTransitionActive = false;
    setAudioParamEqualPower(graph.dryGain?.gain, 1, graph.context, 0.018);
    if (!graph.disposed && state.obrSpatialAudio.requested) {
      failGoogleObr(error, { announce: false, graph });
    }
  }).finally(() => {
    if (graph.timelineResetPromise === reset) graph.timelineResetPromise = null;
  });
  return reset;
}

function setAudioCurrentTimeWithNativeContinuity(target, reason = 'seek') {
  if (!els.audio || !Number.isFinite(Number(target))) return Promise.resolve(false);
  const transition = beginNativeSpatialTimelineTransition(reason);
  state.audioPositionSync.nativeSeekPromise = transition;
  transition.catch(() => false).finally(() => {
    if (state.audioPositionSync.nativeSeekPromise === transition) {
      state.audioPositionSync.nativeSeekPromise = null;
    }
  });
  // Move the media clock immediately. Native flush/preroll stays on the
  // control path while browser dry playback protects audible continuity.
  els.audio.currentTime = Number(target);
  return transition;
}

async function invalidateNativeGoogleObrTimeline(reason = 'timeline-change') {
  const spatial = state.obrSpatialAudio;
  if (spatial.timelineInvalidationPromise) return spatial.timelineInvalidationPromise;
  const graph = spatial.graph;
  if (!graph?.nativeStream || graph.disposed) return false;

  spatial.operationId += 1;
  spatial.enabled = false;
  spatial.loading = false;
  spatial.backend = 'waiting-for-audio';
  setGoogleObrRuntimeBackend(false);
  syncGoogleObrToggle();
  const invalidation = Promise.resolve(
    disposeOfficialGoogleObrGraph(graph, { nativeAction: 'pause', reason })
  ).then(() => true).finally(() => {
    if (spatial.timelineInvalidationPromise === invalidation) {
      spatial.timelineInvalidationPromise = null;
    }
  });
  spatial.timelineInvalidationPromise = invalidation;
  return invalidation;
}

function scheduleGoogleObrRecovery() {
  const spatial = state.obrSpatialAudio;
  if (
    !spatial.requested ||
    spatial.recoveryTimer ||
    !els.audio?.src ||
    document.hidden ||
    navigator.onLine === false
  ) return;
  const attempt = Math.min(spatial.recoveryAttempt, GOOGLE_OBR_RECOVERY_DELAYS.length - 1);
  const delay = GOOGLE_OBR_RECOVERY_DELAYS[attempt];
  spatial.recoveryAttempt = Math.min(spatial.recoveryAttempt + 1, GOOGLE_OBR_RECOVERY_DELAYS.length - 1);
  spatial.recoveryTimer = window.setTimeout(async () => {
    spatial.recoveryTimer = 0;
    if (!spatial.requested || !els.audio?.src) return;
    await ensureAudioAnalysis({ announceObrFailure: false });
    if (spatial.requested && !spatial.enabled) scheduleGoogleObrRecovery();
  }, delay);
  syncGoogleObrToggle();
}

function failGoogleObr(error, options = {}) {
  const spatial = state.obrSpatialAudio;
  const message = safeText(error && error.message ? error.message : error, '官方内核加载失败');
  if (options.graph?.nativeStream) {
    spatial.nativeFallback = true;
    spatial.nativeError = message;
  }
  if (options.graph) disposeOfficialGoogleObrGraph(options.graph);
  spatial.enabled = false;
  spatial.loading = false;
  spatial.requested = true;
  spatial.error = message;
  if (![GOOGLE_OBR_BACKEND, GOOGLE_OBR_NATIVE_BACKEND, 'capture-stream-unsupported'].includes(spatial.backend)) {
    spatial.backend = 'unavailable';
  }
  saveGoogleObrPreference(true);
  syncRealtimePolling();
  if (spatial.graph) {
    spatial.graph.node.port.postMessage({ type: 'set-enabled', enabled: false });
    setAudioParamSmoothly(spatial.graph.dryGain.gain, 1, spatial.graph.context);
    setAudioParamSmoothly(spatial.graph.wetGain.gain, 0, spatial.graph.context);
  }
  setGoogleObrRuntimeBackend(false);
  syncGoogleObrToggle();
  notifyNativeAudioChainChanged('failed');
  if (options.announce !== false) toast(`Google OBR 未启用：${message}`);
  if (options.recover !== false) scheduleGoogleObrRecovery();
  return false;
}

async function createOfficialGoogleObrGraph(analysis) {
  if (!analysis.context?.audioWorklet || typeof AudioWorkletNode !== 'function') {
    throw new Error('当前播放内核不支持 AudioWorklet');
  }

  const channelLayout = normalizeGoogleObrChannelLayout(state.obrSpatialAudio.channelLayout);
  await analysis.context.audioWorklet.addModule(GOOGLE_OBR_WORKLET_URL);
  const node = new AudioWorkletNode(analysis.context, 'fe-google-obr', {
    numberOfInputs: 1,
    numberOfOutputs: 1,
    outputChannelCount: [2],
    channelCount: 2,
    channelCountMode: 'explicit',
    channelInterpretation: 'speakers',
    processorOptions: { channelLayout }
  });
  const wetGain = analysis.context.createGain();
  wetGain.gain.value = 0;
  analysis.analyser.connect(node);
  node.connect(wetGain);
  wetGain.connect(analysis.context.destination);

  const graph = {
    context: analysis.context,
    inputNode: analysis.analyser,
    node,
    dryGain: ensureDryAudioOutput(analysis),
    wetGain,
    backend: '',
    revision: '',
    channelLayout,
    inputChannelCount: GOOGLE_OBR_CHANNEL_LAYOUTS[channelLayout].channels,
    ready: false,
    processedBlocks: 0,
    pendingProcess: null,
    disableTimer: 0,
    connected: true
  };

  await new Promise((resolve, reject) => {
    const timeout = window.setTimeout(
      () => reject(new Error('Google OBR 官方内核初始化超时')),
      15000
    );
    const settle = (callback, value) => {
      window.clearTimeout(timeout);
      callback(value);
    };
    node.port.onmessage = (event) => {
      const message = event.data || {};
      if (message.type === 'ready') {
        if (
          message.backend !== GOOGLE_OBR_BACKEND ||
          message.revision !== GOOGLE_OBR_REVISION
        ) {
          settle(reject, new Error('Google OBR 官方内核身份校验失败'));
          return;
        }
        graph.backend = message.backend;
        graph.revision = message.revision;
        graph.channelLayout = normalizeGoogleObrChannelLayout(message.channelLayout || channelLayout);
        graph.inputChannelCount = Number(message.inputChannelCount)
          || GOOGLE_OBR_CHANNEL_LAYOUTS[graph.channelLayout].channels;
        graph.ready = true;
        settle(resolve, graph);
        return;
      }
      if (message.type === 'metrics') {
        graph.processedBlocks = Math.max(graph.processedBlocks, Number(message.processedBlocks) || 0);
        state.obrSpatialAudio.processedBlocks = graph.processedBlocks;
        state.obrSpatialAudio.inputRms = Number(message.inputRms) || 0;
        state.obrSpatialAudio.outputRms = Number(message.outputRms) || 0;
        if (graph.pendingProcess && graph.processedBlocks > graph.pendingProcess.afterBlock) {
          const pending = graph.pendingProcess;
          graph.pendingProcess = null;
          window.clearTimeout(pending.timeout);
          pending.resolve(message);
        }
        if (state.obrSpatialAudio.enabled) syncGoogleObrToggle();
        return;
      }
      if (message.type === 'error') {
        const workletError = new Error(safeText(message.message, 'Google OBR Process 失败'));
        if (!graph.ready) settle(reject, workletError);
        else {
          if (graph.pendingProcess) {
            const pending = graph.pendingProcess;
            graph.pendingProcess = null;
            window.clearTimeout(pending.timeout);
            pending.reject(workletError);
          }
          if (state.obrSpatialAudio.requested) {
            failGoogleObr(workletError, { announce: false, graph });
          } else {
            disposeOfficialGoogleObrGraph(graph);
          }
        }
      }
    };
    node.onprocessorerror = () => {
      const processorError = new Error('Google OBR AudioWorklet 已停止');
      if (!graph.ready) settle(reject, processorError);
      else if (state.obrSpatialAudio.requested) {
        failGoogleObr(processorError, { announce: false, graph });
      } else {
        disposeOfficialGoogleObrGraph(graph);
      }
    };
  });

  return graph;
}

async function ensureOfficialGoogleObrGraph(analysis = state.audioAnalysis) {
  const spatial = state.obrSpatialAudio;
  const control = spatial.mixerControl || DEFAULT_NATIVE_MIXER_CONTROL;
  const channelLayout = control.loaded === true
    ? (control.upmixOutputLayout === '7.1' ? '7.1' : '5.1')
    : normalizeGoogleObrChannelLayout(spatial.channelLayout);
  const controlSignature = nativeMixerControlSignature(control);
  if (
    spatial.graph?.ready
    && spatial.graph.channelLayout === channelLayout
    && (!spatial.graph.nativeStream || spatial.graph.mixerControlSignature === controlSignature)
  ) return spatial.graph;
  if (spatial.graph?.ready) disposeOfficialGoogleObrGraph(spatial.graph);
  if (spatial.graphPromise) return spatial.graphPromise;
  const createPreferredGraph = async () => {
    if (control.loaded && control.enabled) {
      if (!canUseNativeGoogleObr(channelLayout)) {
        throw new Error('原生调音台链路不可用，已保留浏览器原声输出');
      }
      return createNativeGoogleObrGraph(analysis);
    }
    if (canUseNativeGoogleObr(channelLayout)) {
      try {
        return await createNativeGoogleObrGraph(analysis);
      } catch (error) {
        spatial.nativeError = safeText(error?.message, '原生空间音频链路不可用');
        spatial.nativeFallback = true;
      }
    }
    return createOfficialGoogleObrGraph(analysis);
  };
  spatial.graphPromise = createPreferredGraph()
    .then((graph) => {
      spatial.graph = graph;
      spatial.backend = graph.backend;
      spatial.revision = graph.revision;
      spatial.error = '';
      return graph;
    })
    .finally(() => {
      spatial.graphPromise = null;
    });
  return spatial.graphPromise;
}

function waitForGoogleObrProcessedBlock(graph) {
  if (graph.nativeStream) return waitForNativeGoogleObrPreroll(graph);
  if (graph.pendingProcess) return graph.pendingProcess.promise;
  const afterBlock = graph.processedBlocks;
  let resolvePending;
  let rejectPending;
  const promise = new Promise((resolve, reject) => {
    resolvePending = resolve;
    rejectPending = reject;
  });
  const timeout = window.setTimeout(() => {
    if (!graph.pendingProcess || graph.pendingProcess.promise !== promise) return;
    graph.pendingProcess = null;
    rejectPending(new Error('Google OBR 未收到实时 PCM'));
  }, 5000);
  graph.pendingProcess = {
    afterBlock,
    promise,
    resolve: resolvePending,
    reject: rejectPending,
    timeout
  };
  return promise;
}

async function activateOfficialGoogleObr(options = {}) {
  const spatial = state.obrSpatialAudio;
  if (spatial.activationPromise) return spatial.activationPromise;
  const analysis = state.audioAnalysis;
  if (analysis.sourceMode !== 'media') {
    spatial.backend = 'capture-stream-unsupported';
    return failGoogleObr('当前音源只能使用 captureStream，无法安全替换原声输出', options);
  }
  const operationId = ++spatial.operationId;
  let activationGraph = null;
  const activationIsCurrent = () => spatial.requested && operationId === spatial.operationId;
  const disposeStaleActivation = async (graph) => {
    if (!graph) return false;
    try { graph.node.port.postMessage({ type: 'set-enabled', enabled: false }); } catch (error) {}
    await disposeOfficialGoogleObrGraph(graph);
    return false;
  };
  const activation = (async () => {
    spatial.loading = true;
    spatial.error = '';
    syncGoogleObrToggle();
    const graph = await ensureOfficialGoogleObrGraph(analysis);
    activationGraph = graph;
    if (!activationIsCurrent()) return disposeStaleActivation(graph);
    window.clearTimeout(graph.disableTimer);
    graph.disableTimer = 0;
    connectOfficialGoogleObrGraph(graph);
    const processed = waitForGoogleObrProcessedBlock(graph);
    graph.node.port.postMessage({ type: 'set-enabled', enabled: true });
    await processed;
    if (!activationIsCurrent()) return disposeStaleActivation(graph);
    if (graph.nativeStream) {
      const nativeActivation = await nativeSpatialRequest(
        `/api/audio/spatial/activate?session=${encodeURIComponent(graph.session)}&generation=${encodeURIComponent(graph.generation)}`
      );
      if (!nativeActivation?.ok) {
        throw new Error(safeText(nativeActivation?.error, 'XAudio2 原生输出无法解除静音'));
      }
      if (!activationIsCurrent()) return disposeStaleActivation(graph);
    }
    setAudioParamSmoothly(graph.dryGain.gain, 0, graph.context);
    setAudioParamSmoothly(graph.wetGain.gain, 1, graph.context);
    spatial.enabled = true;
    spatial.loading = false;
    spatial.backend = graph.backend;
    spatial.revision = graph.revision;
    spatial.error = '';
    spatial.recoveryAttempt = 0;
    clearGoogleObrRecovery();
    setGoogleObrRuntimeBackend(true);
    saveGoogleObrPreference(true);
    syncRealtimePolling();
    syncGoogleObrToggle();
    notifyNativeAudioChainChanged('activated');
    if (options.announce !== false) {
      const control = spatial.mixerControl || DEFAULT_NATIVE_MIXER_CONTROL;
      toast(control.obrEnabled
        ? `Google OBR ${GOOGLE_OBR_CHANNEL_LAYOUTS[graph.channelLayout].label} 空间音频已开启`
        : control.upmixEnabled
          ? `虚拟 ${control.upmixOutputLayout} 上混与调音台已开启（双声道输出）`
          : '原生调音台已开启');
    }
    return true;
  })();
  spatial.activationPromise = activation;
  try {
    return await activation;
  } catch (error) {
    if (!activationIsCurrent()) {
      spatial.loading = false;
      if (activationGraph && !activationGraph.disposed) {
        await disposeOfficialGoogleObrGraph(activationGraph);
      }
      syncGoogleObrToggle();
      return false;
    }
    return failGoogleObr(error, options);
  } finally {
    if (spatial.activationPromise === activation) spatial.activationPromise = null;
  }
}

async function setGoogleObrSpatialAudioEnabled(enabled, options = {}) {
  const spatial = state.obrSpatialAudio;
  if (!enabled) {
    spatial.operationId += 1;
    clearGoogleObrRecovery();
    spatial.recoveryAttempt = 0;
    spatial.requested = false;
    spatial.enabled = false;
    spatial.loading = false;
    spatial.error = '';
    setGoogleObrRuntimeBackend(false);
    saveGoogleObrPreference(false);
    syncRealtimePolling();
    if (spatial.graph) {
      const graph = spatial.graph;
      window.clearTimeout(graph.disableTimer);
      setAudioParamSmoothly(graph.dryGain.gain, 1, graph.context);
      setAudioParamSmoothly(graph.wetGain.gain, 0, graph.context);
      graph.disableTimer = window.setTimeout(() => {
        graph.disableTimer = 0;
        if (graph.nativeStream) {
          disposeOfficialGoogleObrGraph(graph);
          return;
        }
        graph.node.port.postMessage({ type: 'set-enabled', enabled: false });
        disconnectOfficialGoogleObrGraph(graph);
      }, 70);
    }
    syncGoogleObrToggle();
    notifyNativeAudioChainChanged('disabled');
    if (options.announce !== false) toast('Google OBR 空间音频已关闭');
    return true;
  }

  if (options.preferNative === true) {
    spatial.nativeFallback = false;
    spatial.nativeError = '';
  }
  spatial.requested = true;
  spatial.error = '';
  saveGoogleObrPreference(true);
  if (!els.audio?.src || !audioAnalysisPlaybackActive()) {
    spatial.backend = 'waiting-for-audio';
    spatial.loading = false;
    syncGoogleObrToggle();
    if (options.announce !== false) toast('Google OBR 已待命，播放音乐后自动启用');
    return true;
  }

  const ready = await ensureAudioAnalysis({ announceObrFailure: options.announce !== false });
  return ready && spatial.enabled;
}

async function ensureNativeAudioMixerChain(request = {}) {
  const spatial = state.obrSpatialAudio;
  let control;
  if (request?.spatialMigrationNeeded === true) {
    const legacy = explicitLegacyGoogleObrPreference();
    if (legacy) {
      const legacyParameters = legacy.enabled
        ? legacy.channelLayout === 'stereo'
          ? { upmixEnabled: false, obrEnabled: true }
          : {
              upmixEnabled: true,
              obrEnabled: true,
              upmixOutputLayout: legacy.channelLayout === '7.1' ? '7.1' : '5.1'
            }
        : { upmixEnabled: false, obrEnabled: false };
      request = await patchNativeMixerSpatialControl(legacyParameters);
    }
  }
  if (request?.parameters && typeof request.parameters === 'object') {
    control = applyNativeMixerControl(request);
  } else {
    control = await refreshNativeMixerControl();
  }

  if (!control.enabled) {
    spatial.operationId += 1;
    spatial.requested = false;
    spatial.enabled = false;
    spatial.loading = false;
    spatial.error = '';
    clearGoogleObrRecovery();
    const graph = spatial.graph;
    if (graph) {
      setAudioParamSmoothly(graph.dryGain?.gain, 1, graph.context, 0.03);
      setAudioParamSmoothly(graph.wetGain?.gain, 0, graph.context, 0.03);
      await disposeOfficialGoogleObrGraph(graph);
    }
    setGoogleObrRuntimeBackend(false);
    syncRealtimePolling();
    syncGoogleObrToggle();
    notifyNativeAudioChainChanged('mixer-disabled');
    return true;
  }

  spatial.requested = true;
  spatial.channelLayout = control.upmixOutputLayout;
  spatial.nativeFallback = false;
  spatial.nativeError = '';
  if (spatial.graph?.ready && spatial.graph.nativeStream !== true) {
    spatial.operationId += 1;
    spatial.enabled = false;
    await disposeOfficialGoogleObrGraph(spatial.graph);
    spatial.backend = 'uninitialized';
  }
  if (!els.audio?.src || !audioAnalysisPlaybackActive()) {
    spatial.backend = 'waiting-for-audio';
    spatial.loading = false;
    syncGoogleObrToggle();
    return true;
  }
  const enabled = await ensureAudioAnalysis({
    announceObrFailure: false,
    skipMixerControlRefresh: true
  });
  return enabled === true
    && spatial.graph?.nativeStream === true
    && spatial.backend === GOOGLE_OBR_NATIVE_BACKEND;
}

function currentNativeAudioMixerChannelLayout() {
  return state.obrSpatialAudio.mixerControl?.upmixOutputLayout === '7.1' ? '7.1' : '5.1';
}

async function setNativeAudioMixerChannelLayout(value) {
  const channelLayout = value === '7.1' ? '7.1' : value === '5.1' ? '5.1' : '';
  if (!channelLayout) return false;
  const snapshot = await patchNativeMixerSpatialControl({ upmixOutputLayout: channelLayout });
  const nativeReady = await ensureNativeAudioMixerChain(snapshot);
  if (!els.audio?.src || !audioAnalysisPlaybackActive()) {
    return state.obrSpatialAudio.requested === true
      && currentNativeAudioMixerChannelLayout() === channelLayout;
  }
  if (!nativeReady) return false;
  const control = state.obrSpatialAudio.mixerControl || DEFAULT_NATIVE_MIXER_CONTROL;
  const expectedChannels = control.upmixEnabled
    ? (channelLayout === '7.1' ? 8 : 6)
    : 2;
  const startedAt = performance.now();
  let status = null;
  let committed = false;
  while (performance.now() - startedAt < 2000) {
    status = await apiJson('/api/audio/spatial/status');
    const rustReady = control.upmixEnabled !== true
      || (status.rustUpmixActive === true && Number(status.rustUpmixProcessCalls) > 0);
    const obrReady = control.obrEnabled !== true || Number(status.obrProcessCalls) > 0;
    committed = status?.active === true
      && status.transitionPending !== true
      && status.spatialRevisionCommitted === true
      && Number(status.spatialActiveRevision) === Number(control.revision)
      && Number(status.virtualBedChannels) === expectedChannels
      && Number(status.mixerProcessCalls) > 0
      && rustReady
      && obrReady;
    if (committed) break;
    if (Number(status?.spatialDesiredRevision) > Number(control.revision)) break;
    await new Promise((resolve) => window.setTimeout(resolve, 25));
  }
  // Layout changes are committed atomically inside the existing native
  // session. Keep the browser graph's diagnostics/signature aligned with the
  // confirmed route so a later health check does not rebuild a healthy graph.
  const graph = state.obrSpatialAudio.graph;
  if (committed && graph?.nativeStream === true) {
    graph.channelLayout = channelLayout;
    graph.inputChannelCount = expectedChannels;
    graph.mixerControlSignature = nativeMixerControlSignature(control);
    graph.mixerControlRevision = control.revision;
    graph.upmixEnabled = control.upmixEnabled;
    graph.obrEnabled = control.obrEnabled;
  }
  return committed;
}

async function setGoogleObrChannelLayout(value, options = {}) {
  const spatial = state.obrSpatialAudio;
  const channelLayout = normalizeGoogleObrChannelLayout(value);
  if (channelLayout === spatial.channelLayout) {
    syncGoogleObrToggle();
    return !spatial.requested
      || spatial.enabled
      || !els.audio?.src
      || !audioAnalysisPlaybackActive();
  }

  spatial.channelLayout = channelLayout;
  spatial.operationId += 1;
  spatial.nativeFallback = false;
  spatial.nativeError = '';
  clearGoogleObrRecovery();
  const staleActivation = spatial.activationPromise;
  const graph = spatial.graph;
  if (graph) {
    setAudioParamSmoothly(graph.dryGain.gain, 1, graph.context, 0.03);
    setAudioParamSmoothly(graph.wetGain.gain, 0, graph.context, 0.03);
    await disposeOfficialGoogleObrGraph(graph);
  }
  if (staleActivation) {
    try {
      await staleActivation;
    } catch (error) {
    }
    if (spatial.activationPromise === staleActivation) spatial.activationPromise = null;
  }
  spatial.enabled = false;
  spatial.loading = false;
  spatial.error = '';
  setGoogleObrRuntimeBackend(false);
  saveGoogleObrPreference(spatial.requested);
  syncRealtimePolling();
  syncGoogleObrToggle();
  notifyNativeAudioChainChanged('layout-changed');
  if (!spatial.requested || !els.audio?.src) return true;
  if (!audioAnalysisPlaybackActive()) {
    spatial.backend = 'waiting-for-audio';
    syncGoogleObrToggle();
    return true;
  }
  const ready = await ensureAudioAnalysis({ announceObrFailure: options.announce !== false });
  if (ready && options.announce !== false) {
    toast(`Google OBR 已切换到 ${GOOGLE_OBR_CHANNEL_LAYOUTS[channelLayout].label}`);
  }
  return ready && spatial.enabled;
}

function cycleGoogleObrChannelLayout() {
  const order = ['stereo', '5.1', '7.1'];
  const current = order.indexOf(normalizeGoogleObrChannelLayout(state.obrSpatialAudio.channelLayout));
  const next = order[(current + 1) % order.length];
  const parameters = next === 'stereo'
    ? { upmixEnabled: false }
    : { upmixEnabled: true, upmixOutputLayout: next };
  patchNativeMixerSpatialControl(parameters)
    .then((snapshot) => ensureNativeAudioMixerChain(snapshot))
    .catch((error) => failGoogleObr(error));
}

function toggleGoogleObrSpatialAudio() {
  const spatial = state.obrSpatialAudio;
  if (spatial.loading) return;
  const enabled = spatial.mixerControl?.obrEnabled !== true;
  patchNativeMixerSpatialControl({ obrEnabled: enabled })
    .then((snapshot) => {
      saveGoogleObrPreference(enabled);
      return ensureNativeAudioMixerChain(snapshot);
    })
    .catch((error) => failGoogleObr(error));
}

async function ensureAudioAnalysis(options = {}) {
  const AudioContextCtor = window.AudioContext || window.webkitAudioContext;
  if (!AudioContextCtor || !els.audio) return false;

  const analysis = state.audioAnalysis;
  if (
    !options.skipMixerControlRefresh
    && !state.obrSpatialAudio.mixerControl?.attempted
  ) {
    await refreshNativeMixerControl();
  }
  if (!audioAnalysisPlaybackActive()) {
    await suspendAudioAnalysis();
    return false;
  }
  try {
    if (!analysis.context) {
      analysis.context = new AudioContextCtor();
    }
    analysis.backend = 'web-audio';
    analysis.output = 'windows-wasapi';
    analysis.sampleRate = analysis.context.sampleRate || 0;
    if (!state.clientRuntime.nativeAudioActive) state.clientRuntime.audioBackend = 'web-audio';
    state.clientRuntime.audioSampleRate = analysis.sampleRate;
    applyRuntimeDataset();
    if (!await resumeAudioAnalysis()) {
      analysis.blocked = true;
      updateSpectrumUi();
      return false;
    }
    if (!audioAnalysisPlaybackActive()) {
      await suspendAudioAnalysis();
      return false;
    }
    if (!analysis.analyser) {
      analysis.analyser = analysis.context.createAnalyser();
      analysis.analyser.fftSize = 4096;
      analysis.analyser.smoothingTimeConstant = 0.8;
      analysis.data = new Uint8Array(analysis.analyser.frequencyBinCount);
      analysis.previousData = new Float32Array(analysis.analyser.frequencyBinCount);
    }
    if (!analysis.source) {
      const capture = els.audio.captureStream || els.audio.mozCaptureStream;
      const audioUrl = els.audio.currentSrc || els.audio.src;
      if (mediaIsSameOrigin(audioUrl)) {
        try {
          analysis.source = analysis.context.createMediaElementSource(els.audio);
          analysis.source.connect(analysis.analyser);
          analysis.sourceMode = 'media';
          ensureDryAudioOutput(analysis);
        } catch (error) {
          analysis.source = null;
        }
      }
      if (!analysis.source && capture) {
        analysis.source = analysis.context.createMediaStreamSource(capture.call(els.audio));
        analysis.source.connect(analysis.analyser);
        analysis.sourceMode = 'capture';
      }
      if (!analysis.source) {
        analysis.blocked = true;
        updateSpectrumUi();
        return false;
      }
    }
    analysis.ready = true;
    analysis.blocked = false;
    if (
      audioAnalysisPlaybackActive()
      && state.obrSpatialAudio.requested
      && !state.obrSpatialAudio.enabled
    ) {
      await activateOfficialGoogleObr({
        announce: options.announceObrFailure === true
      });
    }
    return true;
  } catch (error) {
    analysis.blocked = true;
    analysis.ready = false;
    if (state.obrSpatialAudio.requested) {
      failGoogleObr(error, { announce: options.announceObrFailure === true });
    }
    updateSpectrumUi();
    return false;
  }
}

function audioFrameResponse(baseResponse, responseScale) {
  return 1 - Math.pow(1 - baseResponse, responseScale);
}

function ensureAudioSpectrumAggregateLookup(analysis, dataLength, sampleRate) {
  const length = Math.max(1, Math.floor(Number(dataLength) || 1));
  const resolvedSampleRate = Math.max(1, Number(sampleRate) || 44100);
  if (
    analysis.aggregateLookupDataLength === length
    && analysis.aggregateLookupSampleRate === resolvedSampleRate
    && analysis.aggregateBandByBin?.length === length
  ) {
    return;
  }

  if (!analysis.aggregateBandByBin || analysis.aggregateBandByBin.length !== length) {
    analysis.aggregateBandByBin = new Uint8Array(length);
  }
  if (!analysis.aggregateBandCounts || analysis.aggregateBandCounts.length !== AUDIO_SPECTRUM_BAND_COUNT) {
    analysis.aggregateBandCounts = new Uint16Array(AUDIO_SPECTRUM_BAND_COUNT);
  }
  if (!analysis.aggregateBandSums || analysis.aggregateBandSums.length !== AUDIO_SPECTRUM_BAND_COUNT) {
    analysis.aggregateBandSums = new Float64Array(AUDIO_SPECTRUM_BAND_COUNT);
  }
  const lookup = analysis.aggregateBandByBin;
  const counts = analysis.aggregateBandCounts;
  lookup.fill(AUDIO_SPECTRUM_UNMAPPED);
  counts.fill(0);

  const lastIndex = length - 1;
  const scaleBin = length / 512;
  const assignRange = (band, rawStart, rawEnd) => {
    const start = clamp(Math.floor(rawStart), 0, lastIndex);
    const end = clamp(Math.floor(rawEnd), start, lastIndex);
    for (let index = start; index <= end; index += 1) lookup[index] = band;
    counts[band] = end - start + 1;
  };
  assignRange(0, 0, scaleBin);
  assignRange(1, 2 * scaleBin, 3 * scaleBin);
  assignRange(2, 4 * scaleBin, 7 * scaleBin);
  assignRange(3, 8 * scaleBin, 18 * scaleBin);
  assignRange(4, 19 * scaleBin, 46 * scaleBin);
  assignRange(5, 47 * scaleBin, 93 * scaleBin);
  assignRange(6, 94 * scaleBin, 186 * scaleBin);
  assignRange(7, 187 * scaleBin, 372 * scaleBin);

  const nyquist = resolvedSampleRate / 2;
  analysis.lowFrequencyRmsStart = clamp(
    Math.floor((SONIC_LOW_FREQUENCY_MIN_HZ / nyquist) * length),
    0,
    lastIndex
  );
  analysis.lowFrequencyRmsEnd = clamp(
    Math.ceil((SONIC_LOW_FREQUENCY_MAX_HZ / nyquist) * length),
    analysis.lowFrequencyRmsStart + 1,
    length
  );
  analysis.aggregateLookupDataLength = length;
  analysis.aggregateLookupSampleRate = resolvedSampleRate;
}

function updateAudioSpectrum() {
  const analysis = state.audioAnalysis;
  if (state.clientRuntime.nativeAudioActive && state.clientRuntime.settings.xAudio2) {
    analysis.lastUpdateAt = 0;
    analysis.live = false;
    analysis.blocked = false;
    return true;
  }
  if (!analysis.analyser || !analysis.data || els.audio.paused) {
    analysis.lastUpdateAt = 0;
    if (els.audio.paused) {
      analysis.live = false;
      applyBridgeVisual();
    }
    return false;
  }

  const now = performance.now();
  const referenceFrameMs = Math.max(8, Number(RENDER_PROFILE.targetFrameMs) || 1000 / 60);
  const elapsedMs = analysis.lastUpdateAt
    ? clamp(now - analysis.lastUpdateAt, 0.5, 100)
    : referenceFrameMs;
  analysis.lastUpdateAt = now;
  const responseScale = elapsedMs / referenceFrameMs;
  const derivativeScale = clamp(referenceFrameMs / elapsedMs, 0.25, 4);
  const standardResponse = audioFrameResponse(0.15, responseScale);
  const lowFrequencyAttackResponse = audioFrameResponse(0.34, responseScale);
  const lowFrequencyReleaseResponse = audioFrameResponse(0.075, responseScale);
  const fluxResponse = audioFrameResponse(0.4, responseScale);
  const beatResponse = audioFrameResponse(0.42, responseScale);

  analysis.analyser.getByteFrequencyData(analysis.data);
  if (!analysis.previousData || analysis.previousData.length !== analysis.data.length) {
    analysis.previousData = new Float32Array(analysis.data.length);
  }

  const data = analysis.data;
  const spectrumSampleRate = analysis.analyser.context?.sampleRate || analysis.sampleRate || 44100;
  ensureAudioSpectrumAggregateLookup(analysis, data.length, spectrumSampleRate);
  const lastDataIndex = data.length - 1;
  const scaleBin = data.length / 512;
  const aggregateBandByBin = analysis.aggregateBandByBin;
  const aggregateBandSums = analysis.aggregateBandSums;
  const aggregateBandCounts = analysis.aggregateBandCounts;
  aggregateBandSums.fill(0);

  let energySum = 0;
  let centroidNum = 0;
  let centroidDen = 0;
  let jumpVolatilitySum = 0;
  let lowFrequencySquareSum = 0;
  let fluxPulseRaw = 0;
  let fluxMeteorRaw = 0;
  const pulseStart = 0;
  const pulseEnd = clamp(Math.floor(16 * scaleBin), 0, lastDataIndex);
  const meteorStart = clamp(Math.floor(159 * scaleBin), 0, lastDataIndex);
  const meteorEnd = clamp(Math.floor(174 * scaleBin), 0, lastDataIndex);

  for (let index = 0; index < data.length; index += 1) {
    const value = (data[index] || 0) * AUDIO_BYTE_TO_UNIT;
    const previous = analysis.previousData[index] || 0;
    const diff = value - previous;
    energySum += value;
    centroidNum += index * value;
    centroidDen += value;
    jumpVolatilitySum += Math.abs(diff);
    if (diff > 0) {
      if (index >= pulseStart && index <= pulseEnd) fluxPulseRaw += diff;
      if (index >= meteorStart && index <= meteorEnd) fluxMeteorRaw += diff;
    }
    analysis.previousData[index] = value;

    const aggregateBand = aggregateBandByBin[index];
    if (aggregateBand !== AUDIO_SPECTRUM_UNMAPPED) aggregateBandSums[aggregateBand] += value;
    if (index >= analysis.lowFrequencyRmsStart && index < analysis.lowFrequencyRmsEnd) {
      lowFrequencySquareSum += value * value;
    }
  }

  const subBassRaw = aggregateBandSums[0] / Math.max(1, aggregateBandCounts[0]);
  const bassOnlyRaw = aggregateBandSums[1] / Math.max(1, aggregateBandCounts[1]);
  const lowMidRaw = aggregateBandSums[2] / Math.max(1, aggregateBandCounts[2]);
  const midOnlyRaw = aggregateBandSums[3] / Math.max(1, aggregateBandCounts[3]);
  const highMidRaw = aggregateBandSums[4] / Math.max(1, aggregateBandCounts[4]);
  const presenceRaw = aggregateBandSums[5] / Math.max(1, aggregateBandCounts[5]);
  const brillianceRaw = aggregateBandSums[6] / Math.max(1, aggregateBandCounts[6]);
  const airRaw = aggregateBandSums[7] / Math.max(1, aggregateBandCounts[7]);
  const lowFrequencyRaw = clamp(Math.sqrt(
    lowFrequencySquareSum
      / Math.max(1, analysis.lowFrequencyRmsEnd - analysis.lowFrequencyRmsStart)
  ), 0, 1);
  const bassRaw = (subBassRaw + bassOnlyRaw + lowMidRaw) / 3;
  const midRaw = (midOnlyRaw + highMidRaw) / 2;
  const trebleRaw = (presenceRaw + brillianceRaw + airRaw) / 3;
  const energyRaw = energySum / Math.max(1, data.length);
  const warmthRaw = energySum > 0
    ? (aggregateBandSums[0] + aggregateBandSums[1]
      + aggregateBandSums[2] + aggregateBandSums[3]) / energySum
    : 0;
  const brightnessRaw = energySum > 0
    ? (aggregateBandSums[5] + aggregateBandSums[6] + aggregateBandSums[7]) / energySum
    : 0;
  const sharpnessRaw = Math.max(0, brightnessRaw - analysis.previousBrightness) * 10 * derivativeScale;
  analysis.previousBrightness = brightnessRaw;
  const smoothnessRaw = Math.max(0, 1 - (jumpVolatilitySum / Math.max(1, data.length)) * 2);
  const activeThreshold = energyRaw * 1.5;
  let activeBandCount = 0;
  if (subBassRaw > activeThreshold) activeBandCount += 1;
  if (bassOnlyRaw > activeThreshold) activeBandCount += 1;
  if (lowMidRaw > activeThreshold) activeBandCount += 1;
  if (midOnlyRaw > activeThreshold) activeBandCount += 1;
  if (highMidRaw > activeThreshold) activeBandCount += 1;
  if (presenceRaw > activeThreshold) activeBandCount += 1;
  if (brillianceRaw > activeThreshold) activeBandCount += 1;
  if (airRaw > activeThreshold) activeBandCount += 1;
  const densityRaw = activeBandCount / 8;
  const spectralCentroidRaw = centroidDen > 0 ? centroidNum / centroidDen : 0;
  const active = bassRaw > 0.012 || midRaw > 0.012 || trebleRaw > 0.012;

  if (!active) {
    analysis.silenceFrames += responseScale;
    if (analysis.silenceFrames > 50) {
      analysis.live = false;
      analysis.blocked = true;
      analysis.lowFrequencyBands.fill(0);
      state.visual.lowFrequencyBands.fill(0);
      applyBridgeVisual();
      return false;
    }
  } else {
    analysis.silenceFrames = 0;
    analysis.blocked = false;
  }

  const beatRaw = clamp((bassRaw - analysis.previousBass) * 4.6 * derivativeScale + bassRaw * 0.38, 0, 1);
  analysis.previousBass = bassRaw;
  const dt = standardResponse;
  analysis.bass += (bassRaw - analysis.bass) * dt;
  const lowFrequencyRate = lowFrequencyRaw > analysis.lowFrequencyAmplitude
    ? lowFrequencyAttackResponse
    : lowFrequencyReleaseResponse;
  analysis.lowFrequencyAmplitude += (lowFrequencyRaw - analysis.lowFrequencyAmplitude) * lowFrequencyRate;
  const spectrumNyquist = spectrumSampleRate / 2;
  const lowFrequencyBandDivisor = Math.max(1, SONIC_LOW_FREQUENCY_BAND_COUNT - 1);
  const lowFrequencySpan = SONIC_LOW_FREQUENCY_MAX_HZ - SONIC_LOW_FREQUENCY_MIN_HZ;
  if (
    analysis.lowFrequencyLookupDataLength !== data.length
    || analysis.lowFrequencyLookupSampleRate !== spectrumSampleRate
  ) {
    analysis.lowFrequencyLookupDataLength = data.length;
    analysis.lowFrequencyLookupSampleRate = spectrumSampleRate;
    for (let index = 0; index < SONIC_LOW_FREQUENCY_BAND_COUNT; index += 1) {
      const progress = index / lowFrequencyBandDivisor;
      const frequencyHz = SONIC_LOW_FREQUENCY_MIN_HZ + lowFrequencySpan * progress;
      const binPosition = clamp((frequencyHz / spectrumNyquist) * data.length, 0, lastDataIndex);
      const lowerIndex = Math.floor(binPosition);
      analysis.lowFrequencyBinLower[index] = lowerIndex;
      analysis.lowFrequencyBinMix[index] = binPosition - lowerIndex;
    }
  }
  const lowFrequencyBinLower = analysis.lowFrequencyBinLower;
  const lowFrequencyBinMix = analysis.lowFrequencyBinMix;
  for (let index = 0; index < SONIC_LOW_FREQUENCY_BAND_COUNT; index += 1) {
    const lowerIndex = lowFrequencyBinLower[index];
    const upperIndex = Math.min(lastDataIndex, lowerIndex + 1);
    const mix = lowFrequencyBinMix[index];
    const rawAmplitude = clamp(
      ((data[lowerIndex] || 0) + ((data[upperIndex] || 0) - (data[lowerIndex] || 0)) * mix) / 255,
      0,
      1
    );
    const targetAmplitude = clamp(rawAmplitude * 1.55, 0, 1);
    const currentAmplitude = analysis.lowFrequencyBands[index] || 0;
    const response = targetAmplitude > currentAmplitude
      ? lowFrequencyAttackResponse
      : lowFrequencyReleaseResponse;
    const amplitude = currentAmplitude + (targetAmplitude - currentAmplitude) * response;
    analysis.lowFrequencyBands[index] = amplitude;
    state.visual.lowFrequencyBands[index] = amplitude;
  }
  analysis.mid += (midRaw - analysis.mid) * dt;
  analysis.treble += (trebleRaw - analysis.treble) * dt;
  analysis.energy += (energyRaw - analysis.energy) * dt;
  analysis.subBass += (subBassRaw - analysis.subBass) * dt;
  analysis.lowMid += (lowMidRaw - analysis.lowMid) * dt;
  analysis.highMid += (highMidRaw - analysis.highMid) * dt;
  analysis.presence += (presenceRaw - analysis.presence) * dt;
  analysis.brilliance += (brillianceRaw - analysis.brilliance) * dt;
  analysis.air += (airRaw - analysis.air) * dt;
  analysis.warmth += (warmthRaw - analysis.warmth) * dt;
  analysis.brightness += (brightnessRaw - analysis.brightness) * dt;
  analysis.sharpness += (sharpnessRaw - analysis.sharpness) * dt;
  analysis.smoothness += (smoothnessRaw - analysis.smoothness) * dt;
  analysis.density += (densityRaw - analysis.density) * dt;
  analysis.spectralCentroid += (spectralCentroidRaw - analysis.spectralCentroid) * dt;
  analysis.fluxPulse += (fluxPulseRaw - analysis.fluxPulse) * fluxResponse;
  analysis.fluxMeteor += (fluxMeteorRaw - analysis.fluxMeteor) * fluxResponse;
  analysis.beat += (beatRaw - analysis.beat) * beatResponse;
  analysis.live = true;

  state.visual.lowFrequencyAmplitude = clamp(analysis.lowFrequencyAmplitude * 1.55, 0, 1);
  state.visual.bass = clamp(Math.max(analysis.bass * 1.45, state.visual.lowFrequencyAmplitude), 0, 1);
  state.visual.mid = clamp(analysis.mid * 1.28, 0, 1);
  state.visual.treble = clamp(analysis.treble * 1.18, 0, 1);
  state.visual.energy = clamp(analysis.energy * 1.36, 0, 1);
  state.visual.beat = clamp(analysis.beat * 1.28, 0, 1);
  state.visual.subBass = clamp(Math.max(analysis.subBass, state.visual.lowFrequencyAmplitude), 0, 1);
  state.visual.lowMid = clamp(analysis.lowMid, 0, 1);
  state.visual.highMid = clamp(analysis.highMid, 0, 1);
  state.visual.presence = clamp(analysis.presence, 0, 1);
  state.visual.brilliance = clamp(analysis.brilliance, 0, 1);
  state.visual.air = clamp(analysis.air, 0, 1);
  state.visual.warmth = clamp(analysis.warmth, 0, 1);
  state.visual.brightness = clamp(analysis.brightness, 0, 1);
  state.visual.sharpness = clamp(analysis.sharpness, 0, 1);
  state.visual.smoothness = clamp(analysis.smoothness, 0, 1);
  state.visual.density = clamp(analysis.density, 0, 1);
  state.visual.spectralCentroid = analysis.spectralCentroid;
  state.visual.fluxPulse = analysis.fluxPulse;
  state.visual.fluxMeteor = analysis.fluxMeteor;
  updateSpectrumUi();
  return true;
}

function ensureLowFrequencyGraphSurface(canvas) {
  const graph = state.lowFrequencyGraph;
  if (!graph.surface || graph.surface.canvas !== canvas) {
    graph.resizeObserver?.disconnect?.();
    const rect = canvas.getBoundingClientRect();
    const surface = {
      canvas,
      context: canvas.getContext('2d'),
      cssWidth: Math.max(1, Number(rect.width) || Number(canvas.width) || 202),
      cssHeight: Math.max(1, Number(rect.height) || Number(canvas.height) || 64),
      dpr: 0,
      width: 0,
      height: 0,
      gradient: null,
      dirty: true
    };
    graph.surface = surface;
    const ResizeObserverCtor = window.ResizeObserver;
    if (typeof ResizeObserverCtor === 'function') {
      graph.resizeObserver = new ResizeObserverCtor((entries) => {
        const contentRect = entries?.[0]?.contentRect;
        const nextWidth = Number(contentRect?.width) || 0;
        const nextHeight = Number(contentRect?.height) || 0;
        if (nextWidth <= 0 || nextHeight <= 0) return;
        if (surface.cssWidth === nextWidth && surface.cssHeight === nextHeight) return;
        surface.cssWidth = nextWidth;
        surface.cssHeight = nextHeight;
        surface.dirty = true;
      });
      graph.resizeObserver.observe(canvas);
    }
  }

  const surface = graph.surface;
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const width = Math.max(1, Math.floor(surface.cssWidth * dpr));
  const height = Math.max(1, Math.floor(surface.cssHeight * dpr));
  if (surface.dirty || surface.dpr !== dpr || surface.width !== width || surface.height !== height) {
    surface.dirty = false;
    surface.dpr = dpr;
    surface.width = width;
    surface.height = height;
    if (canvas.width !== width) canvas.width = width;
    if (canvas.height !== height) canvas.height = height;
    if (surface.context) {
      surface.gradient = surface.context.createLinearGradient(0, 0, 0, height);
      surface.gradient.addColorStop(0, 'rgba(131, 228, 255, 0.24)');
      surface.gradient.addColorStop(1, 'rgba(131, 228, 255, 0.02)');
    }
  }
  return surface;
}

function appendLowFrequencyGraphSample(value) {
  const graph = state.lowFrequencyGraph;
  const capacity = 96;
  if (!(graph.history instanceof Float32Array) || graph.history.length !== capacity) {
    const previous = Array.from(graph.history || []).slice(-capacity);
    graph.history = new Float32Array(capacity);
    graph.history.set(previous, 0);
    graph.count = previous.length;
    graph.cursor = previous.length % capacity;
  }
  const cursor = Math.max(0, Number(graph.cursor) || 0) % capacity;
  graph.history[cursor] = clamp(value, 0, 1);
  graph.cursor = (cursor + 1) % capacity;
  graph.count = Math.min(capacity, Math.max(0, Number(graph.count) || 0) + 1);
}

function readLowFrequencyGraphSample(index) {
  const graph = state.lowFrequencyGraph;
  const history = graph.history;
  const count = Math.min(history.length, Math.max(0, Number(graph.count) || 0));
  const start = (Math.max(0, Number(graph.cursor) || 0) - count + history.length) % history.length;
  return history[(start + index) % history.length] || 0;
}

function drawLowFrequencyGraph(value) {
  if (!els.lowFrequencyGraph) return;
  const canvas = els.lowFrequencyGraph;
  const surface = ensureLowFrequencyGraphSurface(canvas);
  const context = surface.context;
  if (!context) return;
  const { width, height, dpr } = surface;
  appendLowFrequencyGraphSample(value);
  const historyCount = Math.min(
    state.lowFrequencyGraph.history.length,
    Math.max(0, Number(state.lowFrequencyGraph.count) || 0)
  );

  context.clearRect(0, 0, width, height);
  context.fillStyle = surface.gradient;
  context.fillRect(0, 0, width, height);

  context.strokeStyle = 'rgba(232, 249, 255, 0.12)';
  context.lineWidth = Math.max(1, dpr);
  for (let line = 1; line < 4; line += 1) {
    const y = (height * line) / 4;
    context.beginPath();
    context.moveTo(0, y);
    context.lineTo(width, y);
    context.stroke();
  }

  context.beginPath();
  for (let index = 0; index < historyCount; index += 1) {
    const item = readLowFrequencyGraphSample(index);
    const x = historyCount <= 1 ? width : (index / (historyCount - 1)) * width;
    const y = height - item * (height - 6 * dpr) - 3 * dpr;
    if (index === 0) context.moveTo(x, y);
    else context.lineTo(x, y);
  }
  context.strokeStyle = 'rgba(131, 228, 255, 0.96)';
  context.lineWidth = 2 * dpr;
  context.shadowBlur = 8 * dpr;
  context.shadowColor = 'rgba(131, 228, 255, 0.55)';
  context.stroke();
  context.shadowBlur = 0;
}

function updateSpectrumUi() {
  const lowFrequency = clamp(
    state.audioAnalysis.live && !state.clientRuntime.nativeAudioActive
      ? state.visual.lowFrequencyAmplitude
      : state.visual.lowFrequencyAmplitude || state.visualBridge.lowFrequencyAmplitude,
    0,
    1
  );
  state.lowFrequencyGraph.lastValue = lowFrequency;
  // The spectrum controls live in the runtime/settings surfaces. Keep the
  // latest value in state while those surfaces are closed, but do not wake
  // style/layout/paint for DOM that the user cannot see on every playback
  // frame. The next animation frame paints the current value when opened.
  if (!state.runtimeSettingsOpen) return;

  if (els.lowFrequencyValue) {
    const valueText = `${Math.round(lowFrequency * 100)}%`;
    if (els.lowFrequencyValue.textContent !== valueText) {
      els.lowFrequencyValue.textContent = valueText;
    }
  }
  if (els.lowFrequencyGraph) {
    const now = performance.now();
    const lastDrawAt = Number(state.lowFrequencyGraph.lastDrawAt) || 0;
    if (now < lastDrawAt || now - lastDrawAt >= 80) {
      state.lowFrequencyGraph.lastDrawAt = now;
      drawLowFrequencyGraph(lowFrequency);
    }
  }

  if (els.spectrumBassFill) {
    const value = Math.max(state.audioAnalysis.live ? state.visual.bass : state.visualBridge.bass, lowFrequency);
    setStylePropertyIfChanged(
      els.spectrumBassFill,
      'transform',
      `scaleX(${clamp(value, 0, 1).toFixed(3)})`
    );
  }
  if (els.spectrumStatus) {
    const status = state.visualBridge.source === 'xaudio2-native-loopback'
      ? 'XAudio2'
      : state.audioAnalysis.live
        ? '实时'
        : state.audioAnalysis.blocked
          ? '桥接'
          : '待机';
    if (els.spectrumStatus.textContent !== status) els.spectrumStatus.textContent = status;
  }
}

function buildDynamicCube() {
  if (!els.dynamicCubeCore || state.dynamicCube.built) return;
  if (!heavyWebGLRenderingAllowed()) return;
  if (!window.THREE) {
    state.dynamicCube.built = true;
    return;
  }
  const THREE = window.THREE;
  const cube = state.dynamicCube;
  const count = DYNAMIC_CUBE_GRID * DYNAMIC_CUBE_GRID * DYNAMIC_CUBE_GRID;
  const positions = new Float32Array(count * 3);
  const directions = new Float32Array(count * 3);
  const phases = new Float32Array(count);
  const weights = new Float32Array(count);
  const center = (DYNAMIC_CUBE_GRID - 1) / 2;
  els.dynamicCubeCore.style.setProperty('--cube-bound', `${DYNAMIC_CUBE_EXTENT}px`);

  const renderer = createDirectX11Renderer(THREE, { antialias: true });
  renderer.setClearColor(0x000000, 0);
  renderer.setPixelRatio(renderPixelRatio('webgl'));
  const renderQuality = createPresetRenderQuality(renderer, 0.22);
  renderer.domElement.className = 'dynamic-cube-canvas';
  els.dynamicCubeCore.textContent = '';
  els.dynamicCubeCore.appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  const camera = new THREE.OrthographicCamera(-48, 48, 48, -48, 0.1, 500);
  camera.position.set(0, 0, 160);
  camera.lookAt(0, 0, 0);

  const group = new THREE.Group();
  group.rotation.z = -0.035;
  scene.add(group);

  const ambient = new THREE.AmbientLight(0xffffff, 0.72);
  scene.add(ambient);
  const key = new THREE.DirectionalLight(0xffffff, 1.25);
  key.position.set(42, -58, 92);
  scene.add(key);
  const rim = new THREE.PointLight(0xdaf6ff, 1.8, 220);
  rim.position.set(-62, 54, 78);
  scene.add(rim);

  const geometry = new THREE.BoxGeometry(DYNAMIC_CUBE_SIZE, DYNAMIC_CUBE_SIZE, DYNAMIC_CUBE_SIZE);
  const material = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    vertexColors: true,
    emissive: 0xf7fdff,
    emissiveIntensity: 0.075,
    roughness: 0.5,
    metalness: 0.04
  });
  const mesh = new THREE.InstancedMesh(geometry, material, count);
  mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  group.add(mesh);

  const dummy = new THREE.Object3D();
  const color = new THREE.Color();
  let index = 0;
  for (let x = 0; x < DYNAMIC_CUBE_GRID; x += 1) {
    for (let y = 0; y < DYNAMIC_CUBE_GRID; y += 1) {
      for (let z = 0; z < DYNAMIC_CUBE_GRID; z += 1) {
        const px = (x - center) * DYNAMIC_CUBE_GAP;
        const py = (y - center) * DYNAMIC_CUBE_GAP;
        const pz = (z - center) * DYNAMIC_CUBE_GAP;
        const longest = Math.max(Math.abs(px), Math.abs(py), Math.abs(pz), 1);
        const edge = Math.max(Math.abs(x - center), Math.abs(y - center), Math.abs(z - center)) / center;
        const offset = index * 3;
        positions[offset] = px;
        positions[offset + 1] = py;
        positions[offset + 2] = pz;
        directions[offset] = px / longest;
        directions[offset + 1] = py / longest;
        directions[offset + 2] = pz / longest;
        phases[index] = (x * 1.8 + y * 2.35 + z * 1.32) % (Math.PI * 2);
        weights[index] = 0.46 + edge * 0.74;

        dummy.position.set(px, py, pz);
        dummy.scale.setScalar(1);
        dummy.updateMatrix();
        mesh.setMatrixAt(index, dummy.matrix);
        index += 1;
      }
    }
  }

  mesh.instanceMatrix.needsUpdate = true;
  cube.count = count;
  cube.positions = positions;
  cube.directions = directions;
  cube.phases = phases;
  cube.weights = weights;
  cube.renderer = renderer;
  cube.renderQuality = renderQuality;
  cube.scene = scene;
  cube.camera = camera;
  cube.group = group;
  cube.mesh = mesh;
  cube.dummy = dummy;
  cube.color = color;
  cube.built = true;
  observePresetRendererSize(cube, els.dynamicCubeCore, resizeDynamicCubeRenderer);
  applyDynamicCubePalette(cube.palette || fallbackLyricPalette(state.currentSong));
  applyPresetUpscaler({ force: true });
  if (renderQuality) renderQuality.render(scene, camera, performance.now());
  else renderer.render(scene, camera);
}

function observePresetRendererSize(owner, element, resizeRenderer) {
  if (!owner || !element || owner.resizeObserver || !('ResizeObserver' in window)) return;
  owner.resizeObserver = new ResizeObserver(() => resizeRenderer());
  owner.resizeObserver.observe(element);
}

function disposeThreeSceneResources(root) {
  if (!root?.traverse) return;
  const disposed = new Set();
  const disposeValue = (value) => {
    if (!value || disposed.has(value) || typeof value.dispose !== 'function') return;
    disposed.add(value);
    value.dispose();
  };
  root.traverse((object) => {
    disposeValue(object.geometry);
    const materials = Array.isArray(object.material) ? object.material : [object.material];
    materials.forEach((material) => {
      if (!material || disposed.has(material)) return;
      Object.values(material).forEach((value) => {
        if (value?.isTexture) disposeValue(value);
      });
      Object.values(material.uniforms || {}).forEach((uniform) => {
        if (uniform?.value?.isTexture) disposeValue(uniform.value);
      });
      disposeValue(material);
    });
  });
}

function disposePresetRenderer(owner, rootElement) {
  if (!owner) return;
  owner.resizeObserver?.disconnect?.();
  owner.resizeObserver = null;
  owner.renderQuality?.dispose?.();
  disposeThreeSceneResources(owner.scene);
  if (owner.renderer) {
    owner.renderer.renderLists?.dispose?.();
    owner.renderer.dispose?.();
    owner.renderer.forceContextLoss?.();
  }
  if (rootElement) rootElement.textContent = '';
}

function disposeDynamicCube() {
  const cube = state.dynamicCube;
  if (!cube.built) return;
  disposePresetRenderer(cube, els.dynamicCubeCore);
  Object.assign(cube, {
    built: false,
    count: 0,
    positions: null,
    directions: null,
    phases: null,
    weights: null,
    renderer: null,
    renderQuality: null,
    scene: null,
    camera: null,
    group: null,
    mesh: null,
    dummy: null,
    color: null,
    lastWidth: 0,
    lastHeight: 0,
    lastZoom: 1,
    lastRenderAt: 0,
    push: 0,
    bass: 0,
    energy: 0
  });
}

function resizeDynamicCubeRenderer() {
  const cube = state.dynamicCube;
  if (!cube.renderer || !cube.camera || !els.dynamicCubeCore) return;
  const rect = els.dynamicCubeCore.getBoundingClientRect();
  const width = Math.max(1, Math.floor(rect.width));
  const height = Math.max(1, Math.floor(rect.height));
  const zoom = clamp(state.playbackVisual.zoom || 1, 0.58, 2.35);
  if (width === cube.lastWidth && height === cube.lastHeight && Math.abs(zoom - cube.lastZoom) < 0.001) return;
  cube.lastWidth = width;
  cube.lastHeight = height;
  cube.lastZoom = zoom;
  if (cube.renderQuality) cube.renderQuality.resize(width, height, cube.renderer.getPixelRatio?.() || renderPixelRatio('webgl'));
  else cube.renderer.setSize(width, height, false);
  const aspect = width / Math.max(1, height);
  // The old 460px rig kept the model compact but clipped expanding voxels at its edges.
  // Preserve that apparent scale while letting the renderer cover the complete stage.
  const legacyRigHeight = Math.max(1, Math.min((window.innerHeight || height) * 0.6, 460));
  const legacyDepthScale = 1200 / (1200 + 72);
  const legacyMotionScale = reducedMotion ? 0.88 : 1;
  const view = (92 / zoom) * (height / (legacyRigHeight * legacyDepthScale * legacyMotionScale));
  const verticalOffset = view * 0.03;
  cube.camera.left = -view * aspect / 2;
  cube.camera.right = view * aspect / 2;
  cube.camera.top = view / 2 - verticalOffset;
  cube.camera.bottom = -view / 2 - verticalOffset;
  cube.camera.updateProjectionMatrix();
}

function updateDynamicCubeVisibility() {
  const visible = state.playbackPage && state.diyPreset === 'cube';
  if (els.dynamicCubeScene) els.dynamicCubeScene.hidden = !visible;
  els.appShell.classList.toggle('has-dynamic-cube', visible);
  if (visible) buildDynamicCube();
  else disposeDynamicCube();
}

function updateDynamicCubeMotion() {
  const cube = state.dynamicCube;
  if (!state.playbackPage || state.diyPreset !== 'cube' || !cube.mesh || !cube.renderer || !cube.scene || !cube.camera) return;
  const nowMs = performance.now();
  cube.lastRenderAt = nowMs;
  const bass = Math.max(state.visual.bass, els.audio.paused ? 0.04 : 0.22);
  const energy = Math.max(state.visual.energy, els.audio.paused ? 0.04 : 0.18);
  const beat = Math.max(state.visual.beat, els.audio.paused ? 0 : 0.12);
  const frameStep = state.playbackVisual.frameStep || 1;
  cube.bass += (bass - cube.bass) * (1 - Math.pow(0.68, frameStep));
  cube.energy += (energy - cube.energy) * (1 - Math.pow(0.76, frameStep));

  const t = nowMs / 1000;
  const heart = Math.pow(Math.max(0, Math.sin(t * Math.PI * (1.15 + state.lyricSpeed * 0.26))), 8);
  const motionScale = reducedMotion ? 0.28 : 1;
  const pushBase = (0.7 + cube.bass * 7.8 + beat * 2.7 + heart * cube.bass * 3.4) * state.cubeIntensity * motionScale;
  const scaleBase = 0.96 + cube.bass * 0.11 + beat * 0.035;
  if (els.dynamicCubeScene) {
    setStylePropertyIfChanged(els.dynamicCubeScene, '--scene-rotate-x', `${state.playbackVisual.pitch}rad`);
    setStylePropertyIfChanged(els.dynamicCubeScene, '--scene-rotate-y', `${state.playbackVisual.yaw}rad`);
    setStylePropertyIfChanged(els.dynamicCubeScene, '--cube-glow-alpha', (0.18 + cube.energy * 0.36 + beat * 0.16).toFixed(3));
  }

  if (!cube.resizeObserver) resizeDynamicCubeRenderer();
  cube.group.rotation.x = state.playbackVisual.pitch;
  cube.group.rotation.y = state.playbackVisual.yaw;

  const positions = cube.positions;
  const directions = cube.directions;
  const phases = cube.phases;
  const weights = cube.weights;
  const dummy = cube.dummy;
  for (let index = 0; index < cube.count; index += 1) {
    const offset = index * 3;
    const wave = 0.78 + Math.sin(t * (2.1 + state.lyricSpeed * 0.88) + phases[index]) * 0.16;
    const push = pushBase * weights[index] * wave;
    const drift = Math.sin(t * 1.25 + phases[index]) * cube.energy * 0.55;
    dummy.position.set(
      positions[offset] + directions[offset] * push + directions[offset + 1] * drift,
      positions[offset + 1] + directions[offset + 1] * push - directions[offset] * drift,
      positions[offset + 2] + directions[offset + 2] * push * 0.74
    );
    dummy.scale.setScalar(scaleBase);
    dummy.updateMatrix();
    cube.mesh.setMatrixAt(index, dummy.matrix);
  }
  cube.mesh.instanceMatrix.needsUpdate = true;
  if (cube.renderQuality) cube.renderQuality.render(cube.scene, cube.camera, nowMs);
  else cube.renderer.render(cube.scene, cube.camera);
}

function syncFreeCubeControls() {
  const heartActive = state.freeCube.mode === 'heart';
  const backgroundActive = !!state.freeCube.backgroundEnabled;
  if (els.freeCubeHeartButton) {
    els.freeCubeHeartButton.classList.toggle('is-active', heartActive);
    els.freeCubeHeartButton.setAttribute('aria-pressed', String(heartActive));
  }
  if (els.freeCubeBackgroundButton) {
    const effectiveBackgroundActive = backgroundActive && !heartActive;
    els.freeCubeBackgroundButton.classList.toggle('is-active', effectiveBackgroundActive);
    els.freeCubeBackgroundButton.setAttribute('aria-pressed', String(effectiveBackgroundActive));
    els.freeCubeBackgroundButton.setAttribute('aria-disabled', String(heartActive));
    els.freeCubeBackgroundButton.disabled = heartActive;
    els.freeCubeBackgroundButton.title = heartActive ? '心动模式使用透明背景' : '切换柔光背景';
  }
}

function applyFreeCubePalette(palette) {
  const source = palette || fallbackLyricPalette(state.currentSong);
  state.freeCube.palette = source;
  if (state.freeCube.runtime && window.FeFreeCubeRuntime) {
    window.FeFreeCubeRuntime.setPalette(state.freeCube.runtime, source);
  }
}

function buildFreeCube() {
  if (!els.freeCubeCore || state.freeCube.runtime || !window.FeFreeCubeRuntime || !window.THREE) return;
  if (!heavyWebGLRenderingAllowed()) return;
  const lowEndAndroid = ANDROID_CLIENT && RENDER_PROFILE.tier === 'economy';
  const cubeCount = lowEndAndroid ? 720 : MOBILE_RENDER_TARGET ? 1100 : 1800;
  const particleCount = lowEndAndroid ? 480 : MOBILE_RENDER_TARGET ? 760 : 1400;
  state.freeCube.runtime = window.FeFreeCubeRuntime.create(els.freeCubeCore, {
    cubeCount,
    particleCount,
    mode: state.freeCube.mode,
    backgroundEnabled: state.freeCube.backgroundEnabled,
    palette: state.freeCube.palette || fallbackLyricPalette(state.currentSong),
    pixelRatio: renderPixelRatio('webgl'),
    createRenderer: (options) => createDirectX11Renderer(window.THREE, options)
  });
  syncFreeCubeControls();
}

function disposeFreeCube() {
  const runtime = state.freeCube.runtime;
  if (!runtime || !window.FeFreeCubeRuntime) return;
  const before = window.FeFreeCubeRuntime.diagnostics(runtime);
  window.FeFreeCubeRuntime.dispose(runtime);
  state.freeCube.lastDiagnostics = {
    ...before,
    ...window.FeFreeCubeRuntime.diagnostics(runtime),
    mode: state.freeCube.mode,
    backgroundEnabled: state.freeCube.backgroundEnabled
  };
  state.freeCube.runtime = null;
}

function resizeFreeCubeRenderer() {
  if (!state.freeCube.runtime || !window.FeFreeCubeRuntime) return;
  window.FeFreeCubeRuntime.resize(state.freeCube.runtime, renderPixelRatio('webgl'));
}

function updateFreeCubeVisibility() {
  const visible = state.playbackPage && isFreeCubePreset();
  if (els.freeCubeScene) els.freeCubeScene.hidden = !visible;
  if (els.appShell) els.appShell.classList.toggle('has-free-cubes', visible);
  if (visible) buildFreeCube();
  else disposeFreeCube();
  syncFreeCubeControls();
}

function setFreeCubeMode(mode) {
  state.freeCube.mode = mode === 'heart' ? 'heart' : 'free';
  if (state.freeCube.runtime && window.FeFreeCubeRuntime) {
    window.FeFreeCubeRuntime.setMode(state.freeCube.runtime, state.freeCube.mode);
  }
  syncFreeCubeControls();
  renderDiySelectedPresetConfig();
  saveVisualSettingsPreferences();
}

function toggleFreeCubeHeart() {
  setFreeCubeMode(state.freeCube.mode === 'heart' ? 'free' : 'heart');
}

function setFreeCubeBackground(enabled) {
  state.freeCube.backgroundEnabled = enabled !== false;
  if (state.freeCube.runtime && window.FeFreeCubeRuntime) {
    window.FeFreeCubeRuntime.setBackgroundEnabled(state.freeCube.runtime, state.freeCube.backgroundEnabled);
  } else if (els.freeCubeScene) {
    els.freeCubeScene.classList.toggle('has-soft-background', state.freeCube.backgroundEnabled);
  }
  syncFreeCubeControls();
  renderDiySelectedPresetConfig();
  saveVisualSettingsPreferences();
}

function updateFreeCubeMotion() {
  const runtime = state.freeCube.runtime;
  if (!state.playbackPage || !isFreeCubePreset() || !runtime || !window.FeFreeCubeRuntime) return;
  const playing = !!els.audio && !els.audio.paused;
  const lowFrequency = playing
    ? Math.max(Number(state.visual.lowFrequencyAmplitude) || 0, Number(state.visual.bass) || 0)
    : 0;
  const frame = state.freeCube.frame;
  frame.now = performance.now();
  frame.bass = lowFrequency;
  frame.lowFrequencyBands = playing ? state.visual.lowFrequencyBands : null;
  frame.energy = playing ? state.visual.energy : 0;
  frame.beat = playing ? state.visual.beat : 0;
  frame.yaw = state.playbackVisual.yaw;
  frame.pitch = state.playbackVisual.pitch;
  frame.zoom = state.playbackVisual.zoom;
  frame.dragging = state.playbackVisual.dragging;
  frame.reducedMotion = reducedMotion;
  frame.pixelRatio = presetFsrOutputPixelRatio(state.presetFsr.lastDiagnostics);
  window.FeFreeCubeRuntime.update(runtime, frame);
}

function freeCubeRuntimeSnapshot() {
  if (state.freeCube.runtime && window.FeFreeCubeRuntime) {
    return {
      ...window.FeFreeCubeRuntime.diagnostics(state.freeCube.runtime),
      selected: isFreeCubePreset(),
      controlsVisible: !!els.freeCubePresetControls && !els.freeCubePresetControls.hidden
    };
  }
  return {
    ...(state.freeCube.lastDiagnostics || {}),
    active: false,
    selected: isFreeCubePreset(),
    mode: state.freeCube.mode,
    backgroundEnabled: state.freeCube.backgroundEnabled,
    canvasCount: els.freeCubeCore ? els.freeCubeCore.querySelectorAll('canvas').length : 0,
    controlsVisible: !!els.freeCubePresetControls && !els.freeCubePresetControls.hidden
  };
}

function previewFreeCubeBass(value) {
  if (!state.freeCube.runtime || !window.FeFreeCubeRuntime) return false;
  return window.FeFreeCubeRuntime.setBassPreview(state.freeCube.runtime, value);
}

function clearFreeCubeBassPreview() {
  if (!state.freeCube.runtime || !window.FeFreeCubeRuntime) return false;
  return window.FeFreeCubeRuntime.clearBassPreview(state.freeCube.runtime);
}

function buildVoidPrism() {
  if (!els.voidPrismCore || state.voidPrism.runtime || !window.FeVoidPrismRuntime || !window.THREE) return;
  if (!heavyWebGLRenderingAllowed()) return;
  const lyric = state.lyricDisplayText || playbackLyricText();
  const subtitle = state.lyricSubtitleText || playbackLyricSubtitle();
  const fontFamily = activeTextFontFamilyStack();
  state.voidPrism.runtime = window.FeVoidPrismRuntime.create(els.voidPrismCore, {
    lyric,
    subtitle,
    palette: fallbackLyricPalette(state.currentSong),
    fontFamily,
    pixelRatio: renderPixelRatio('webgl'),
    createRenderer: (options) => createDirectX11Renderer(window.THREE, options)
  });
  state.voidPrism.lastLyricText = lyric;
  state.voidPrism.lastLyricSubtitle = subtitle;
  state.voidPrism.lastLyricFontStack = fontFamily;
}

function disposeVoidPrism() {
  const runtime = state.voidPrism.runtime;
  if (!runtime || !window.FeVoidPrismRuntime) return;
  const before = window.FeVoidPrismRuntime.diagnostics(runtime);
  window.FeVoidPrismRuntime.dispose(runtime);
  state.voidPrism.lastDiagnostics = {
    ...before,
    ...window.FeVoidPrismRuntime.diagnostics(runtime)
  };
  state.voidPrism.runtime = null;
  state.voidPrism.lastLyricText = '';
  state.voidPrism.lastLyricSubtitle = '';
  state.voidPrism.lastLyricFontStack = '';
}

function resizeVoidPrismRenderer() {
  if (!state.voidPrism.runtime || !window.FeVoidPrismRuntime) return;
  window.FeVoidPrismRuntime.resize(state.voidPrism.runtime, renderPixelRatio('webgl'));
}

function updateVoidPrismVisibility() {
  const visible = state.playbackPage && isVoidPrismPreset();
  if (els.voidPrismScene) els.voidPrismScene.hidden = !visible;
  if (els.appShell) els.appShell.classList.toggle('has-void-prism', visible);
  if (visible) buildVoidPrism();
  else disposeVoidPrism();
}

function updateVoidPrismMotion() {
  const runtime = state.voidPrism.runtime;
  if (!state.playbackPage || !isVoidPrismPreset() || !runtime || !window.FeVoidPrismRuntime) return;
  const playing = !!els.audio && !els.audio.paused;
  const lyric = state.lyricDisplayText || playbackLyricText();
  const subtitle = state.lyricSubtitleText || playbackLyricSubtitle();
  const fontFamily = activeTextFontFamilyStack();
  if (
    lyric !== state.voidPrism.lastLyricText
    || subtitle !== state.voidPrism.lastLyricSubtitle
    || fontFamily !== state.voidPrism.lastLyricFontStack
  ) {
    window.FeVoidPrismRuntime.setLyric(runtime, lyric, subtitle, undefined, fontFamily);
    state.voidPrism.lastLyricText = lyric;
    state.voidPrism.lastLyricSubtitle = subtitle;
    state.voidPrism.lastLyricFontStack = fontFamily;
  }
  const frame = state.voidPrism.frame;
  frame.now = performance.now();
  frame.bass = playing ? Math.max(Number(state.visual.lowFrequencyAmplitude) || 0, Number(state.visual.bass) || 0) : 0;
  frame.energy = playing ? Number(state.visual.energy) || 0 : 0;
  frame.yaw = state.playbackVisual.yaw;
  frame.pitch = state.playbackVisual.pitch;
  frame.zoom = state.playbackVisual.zoom;
  frame.pixelRatio = presetFsrOutputPixelRatio(state.presetFsr.lastDiagnostics);
  window.FeVoidPrismRuntime.update(runtime, frame);
}

function voidPrismRuntimeSnapshot() {
  if (state.voidPrism.runtime && window.FeVoidPrismRuntime) {
    return {
      ...window.FeVoidPrismRuntime.diagnostics(state.voidPrism.runtime),
      selected: isVoidPrismPreset()
    };
  }
  return {
    ...(state.voidPrism.lastDiagnostics || {}),
    active: false,
    selected: isVoidPrismPreset(),
    canvasCount: els.voidPrismCore ? els.voidPrismCore.querySelectorAll('canvas').length : 0
  };
}

function applyChladniPalette(palette) {
  const source = palette || fallbackLyricPalette(state.currentSong);
  state.chladni.palette = source;
  if (els.chladniScene) {
    const fallback = [source.glow, source.primary, source.highlight];
    const coverColors = [0, 1, 2].map((index) => source.coverColors?.[index] || fallback[index]);
    const softColors = coverColors.map((color, index) => playbackGlowColor(color, index));
    els.chladniScene.style.setProperty('--chladni-a', rgbTriplet(softColors[0]));
    els.chladniScene.style.setProperty('--chladni-b', rgbTriplet(softColors[1]));
    els.chladniScene.style.setProperty('--chladni-hot', rgbTriplet(softColors[2]));
    els.chladniScene.style.setProperty('--chladni-depth', rgbTriplet(source.depth));
  }
  if (state.chladni.runtime && window.FeChladniRuntime) {
    window.FeChladniRuntime.setPalette(state.chladni.runtime, source);
  }
}

function syncChladniModeControls() {
  const planeActive = state.chladni.mode === 'plane';
  if (els.chladniPlaneButton) {
    els.chladniPlaneButton.classList.toggle('is-active', planeActive);
    els.chladniPlaneButton.setAttribute('aria-pressed', String(planeActive));
  }
  if (els.chladniCubeButton) {
    els.chladniCubeButton.classList.toggle('is-active', !planeActive);
    els.chladniCubeButton.setAttribute('aria-pressed', String(!planeActive));
  }
}

function setChladniMode(mode) {
  state.chladni.mode = mode === 'plane' ? 'plane' : 'cube';
  if (state.chladni.runtime && window.FeChladniRuntime) {
    window.FeChladniRuntime.setMode(state.chladni.runtime, state.chladni.mode);
  }
  syncChladniModeControls();
  renderDiySelectedPresetConfig();
  requestOrbFrame();
}

function buildChladni() {
  if (!els.chladniCore || state.chladni.runtime || !window.FeChladniRuntime || !window.THREE) return;
  if (!heavyWebGLRenderingAllowed()) return;
  const lowEndAndroid = ANDROID_CLIENT && RENDER_PROFILE.tier === 'economy';
  const particleCount = lowEndAndroid
    ? 72000
    : MOBILE_RENDER_TARGET
      ? 120000
      : 500000;
  const planeParticleCount = lowEndAndroid
    ? 72000
    : MOBILE_RENDER_TARGET
      ? 100000
      : 600000;
  state.chladni.runtime = window.FeChladniRuntime.create(els.chladniCore, {
    particleCount,
    planeParticleCount,
    mode: state.chladni.mode,
    palette: state.chladni.palette || fallbackLyricPalette(state.currentSong),
    pixelRatio: renderPixelRatio('webgl'),
    createRenderer: (options) => createDirectX11Renderer(window.THREE, options)
  });
  syncSceneWallpaperSurface('chladni');
  syncChladniModeControls();
}

function disposeChladni() {
  const runtime = state.chladni.runtime;
  if (!runtime || !window.FeChladniRuntime) return;
  const before = window.FeChladniRuntime.diagnostics(runtime);
  window.FeChladniRuntime.dispose(runtime);
  state.chladni.lastDiagnostics = {
    ...before,
    ...window.FeChladniRuntime.diagnostics(runtime)
  };
  state.chladni.runtime = null;
}

function resizeChladniRenderer() {
  if (!state.chladni.runtime || !window.FeChladniRuntime) return;
  window.FeChladniRuntime.resize(state.chladni.runtime, renderPixelRatio('webgl'));
}

function updateChladniVisibility() {
  const visible = state.playbackPage && isChladniPreset();
  if (els.chladniScene) els.chladniScene.hidden = !visible;
  if (els.appShell) els.appShell.classList.toggle('has-chladni', visible);
  if (visible) buildChladni();
  else disposeChladni();
  syncChladniModeControls();
}

function updateChladniMotion() {
  const runtime = state.chladni.runtime;
  if (!state.playbackPage || !isChladniPreset() || !runtime || !window.FeChladniRuntime) return;
  const playing = isPlaybackClockRunning();
  const live = state.audioAnalysis.live ? state.audioAnalysis : state.visual;
  const frame = state.chladni.frame;
  frame.now = performance.now();
  frame.playing = playing;
  frame.bass = playing
    ? Math.max(Number(live.lowFrequencyAmplitude) || 0, Number(live.bass) || 0, Number(live.subBass) || 0)
    : 0;
  frame.energy = playing ? Number(live.energy) || 0 : 0;
  frame.mid = playing ? Math.max(Number(live.mid) || 0, Number(live.highMid) || 0) : 0;
  frame.treble = playing ? Math.max(Number(live.treble) || 0, Number(live.brilliance) || 0) : 0;
  frame.beat = playing ? Number(live.beat) || 0 : 0;
  frame.yaw = state.playbackVisual.yaw;
  frame.pitch = state.playbackVisual.pitch;
  frame.zoom = state.playbackVisual.zoom;
  frame.reducedMotion = reducedMotion;
  frame.pixelRatio = presetFsrOutputPixelRatio(state.presetFsr.lastDiagnostics);
  window.FeChladniRuntime.update(runtime, frame);
}

function chladniRuntimeSnapshot() {
  if (state.chladni.runtime && window.FeChladniRuntime) {
    return {
      ...window.FeChladniRuntime.diagnostics(state.chladni.runtime),
      selected: isChladniPreset(),
      controlsVisible: !!els.chladniPresetControls && !els.chladniPresetControls.hidden
    };
  }
  return {
    ...(state.chladni.lastDiagnostics || {}),
    active: false,
    selected: isChladniPreset(),
    displayMode: state.chladni.mode,
    canvasCount: els.chladniCore ? els.chladniCore.querySelectorAll('canvas').length : 0
  };
}

const SOUNDSCAPE_WORKSHOP_ENTRY_URL = 'assets/soundscape-workshop/runtime.html';

function soundscapeWorkshopApi() {
  return window.FeSoundscapeRuntime || null;
}

function soundscapeWorkshopPropertyValue(sourceProperty) {
  const api = soundscapeWorkshopApi();
  if (!api?.get) return undefined;
  return api.get(state.soundscapeWorkshop.runtime, sourceProperty);
}

function soundscapeWorkshopStateSnapshot() {
  const api = soundscapeWorkshopApi();
  if (!api?.get) return null;
  const runtime = state.soundscapeWorkshop.runtime;
  if (!runtime) return {
    requestedParameters: api.diagnostics?.()?.requestedParameters || {},
    effectiveParameters: api.get(null) || {}
  };
  return api.get(runtime);
}

function soundscapeWorkshopRequestedPropertyValue(sourceProperty) {
  const snapshot = soundscapeWorkshopStateSnapshot();
  return snapshot?.requestedParameters?.[sourceProperty]
    ?? snapshot?.effectiveParameters?.[sourceProperty]
    ?? soundscapeWorkshopPropertyValue(sourceProperty);
}

async function applySoundscapeWorkshopProperty(sourceProperty, value) {
  const api = soundscapeWorkshopApi();
  if (!api?.apply) throw new Error('音域回响运行模块尚未加载');
  await api.apply(state.soundscapeWorkshop.runtime, { [sourceProperty]: value });
  scheduleClientPreferencesSync();
  renderSoundscapeWorkshopControls({ refreshOnly: true });
  renderDiySelectedPresetConfig();
  return sourceProperty === 'gridSize'
    ? soundscapeWorkshopRequestedPropertyValue(sourceProperty)
    : soundscapeWorkshopPropertyValue(sourceProperty);
}

function soundscapeWorkshopControlValueLabel(parameter, value) {
  if (parameter.sourceProperty === 'gridSize') {
    const snapshot = soundscapeWorkshopStateSnapshot();
    const requested = snapshot?.requestedParameters?.gridSize ?? value;
    const effective = snapshot?.effectiveParameters?.gridSize ?? value;
    if (Number(requested) !== Number(effective)) {
      return `已保存 ${requested}×${requested} · 当前 ${effective}×${effective}`;
    }
    return `${effective}×${effective}`;
  }
  if (parameter.type === 'boolean') return value ? '开启' : '关闭';
  if (parameter.type === 'enum') {
    return parameter.options?.find((option) => String(option.value) === String(value))?.label || String(value);
  }
  return String(value);
}

function renderSoundscapeWorkshopControls(options = {}) {
  const host = els.soundscapeWorkshopControls;
  const api = soundscapeWorkshopApi();
  if (!host || !api?.catalog) return;
  const parameters = api.catalog();
  if (!Array.isArray(parameters)) return;
  if (options.refreshOnly === true && host.childElementCount) {
    parameters.forEach((parameter) => {
      const control = host.querySelector(`[data-soundscape-property="${CSS.escape(parameter.sourceProperty)}"]`);
      if (!control) return;
      const effectiveValue = soundscapeWorkshopPropertyValue(parameter.sourceProperty);
      const value = parameter.sourceProperty === 'gridSize'
        ? soundscapeWorkshopRequestedPropertyValue(parameter.sourceProperty)
        : effectiveValue;
      if (control.type === 'checkbox') control.checked = value === true;
      else control.value = String(value);
      const output = host.querySelector(`[data-soundscape-output="${CSS.escape(parameter.sourceProperty)}"]`);
      if (output) output.textContent = soundscapeWorkshopControlValueLabel(parameter, effectiveValue);
    });
    return;
  }
  host.replaceChildren();
  const fragment = document.createDocumentFragment();
  parameters.forEach((parameter) => {
    const row = document.createElement('label');
    row.className = `soundscape-workshop-control soundscape-workshop-control--${parameter.type}`;
    row.dataset.soundscapeGroup = safeText(parameter.group, 'appearance');
    const copy = document.createElement('span');
    const title = document.createElement('strong');
    title.textContent = parameter.name;
    const meta = document.createElement('small');
    meta.textContent = parameter.purpose;
    copy.append(title, meta);
    const controlId = `soundscape-${parameter.sourceProperty}-control`;
    let control;
    if (parameter.type === 'boolean') {
      control = document.createElement('input');
      control.type = 'checkbox';
      control.className = 'ui-switch';
      control.checked = soundscapeWorkshopPropertyValue(parameter.sourceProperty) === true;
    } else if (parameter.type === 'enum') {
      control = document.createElement('select');
      (parameter.options || []).forEach((option) => {
        const element = document.createElement('option');
        element.value = String(option.value);
        element.textContent = option.label;
        control.appendChild(element);
      });
      control.value = String(parameter.sourceProperty === 'gridSize'
        ? soundscapeWorkshopRequestedPropertyValue(parameter.sourceProperty)
        : soundscapeWorkshopPropertyValue(parameter.sourceProperty));
    } else {
      control = document.createElement('input');
      control.type = 'range';
      control.min = String(parameter.range.min);
      control.max = String(parameter.range.max);
      control.step = String(parameter.range.step);
      control.value = String(soundscapeWorkshopPropertyValue(parameter.sourceProperty));
    }
    control.id = controlId;
    control.dataset.petParameterIgnore = 'true';
    control.dataset.soundscapeProperty = parameter.sourceProperty;
    const output = document.createElement('output');
    output.htmlFor = controlId;
    output.dataset.soundscapeOutput = parameter.sourceProperty;
    output.textContent = soundscapeWorkshopControlValueLabel(parameter, soundscapeWorkshopPropertyValue(parameter.sourceProperty));
    const commit = async () => {
      let nextValue = parameter.type === 'boolean'
        ? control.checked === true
        : parameter.type === 'number' ? Number(control.value) : control.value;
      if (parameter.requiresExplicitSelection && parameter.highImpactValues?.map(Number).includes(Number(nextValue))) {
        const confirmed = window.confirm(`网格 ${nextValue}×${nextValue} 会显著增加显存和功耗，确认应用吗？`);
        if (!confirmed) {
          renderSoundscapeWorkshopControls({ refreshOnly: true });
          return;
        }
      }
      try {
        nextValue = await applySoundscapeWorkshopProperty(parameter.sourceProperty, nextValue);
        output.textContent = soundscapeWorkshopControlValueLabel(parameter, nextValue);
      } catch (error) {
        renderSoundscapeWorkshopControls({ refreshOnly: true });
        showToast(error?.message || '音域回响参数应用失败');
      }
    };
    if (parameter.type === 'number') {
      control.addEventListener('input', () => {
        output.textContent = soundscapeWorkshopControlValueLabel(parameter, Number(control.value));
      });
    }
    control.addEventListener('change', commit);
    row.append(copy, control, output);
    fragment.appendChild(row);
  });
  host.appendChild(fragment);
  state.soundscapeWorkshop.controlsRendered = true;
}

function soundscapeWorkshopGestureEvent(gesture) {
  const iframe = state.soundscapeWorkshop.runtime?.iframe
    || els.soundscapeWorkshopHost?.querySelector('iframe');
  const rect = iframe?.getBoundingClientRect();
  if (!rect?.width || !rect?.height || !els.stage) return null;
  const clientX = rect.left + Number(gesture.x) * rect.width;
  const clientY = rect.top + Number(gesture.y) * rect.height;
  const screenLeft = Number.isFinite(Number(globalThis.screenX))
    ? Number(globalThis.screenX)
    : Number(globalThis.screenLeft) || 0;
  const screenTop = Number.isFinite(Number(globalThis.screenY))
    ? Number(globalThis.screenY)
    : Number(globalThis.screenTop) || 0;
  return {
    target: els.stage,
    currentTarget: els.stage,
    clientX,
    clientY,
    screenX: screenLeft + clientX,
    screenY: screenTop + clientY,
    pointerId: Number(gesture.pointerId) || 0,
    button: Number(gesture.button) || 0,
    buttons: Number(gesture.buttons) || 0,
    isPrimary: gesture.isPrimary !== false,
    altKey: gesture.altKey === true,
    ctrlKey: gesture.ctrlKey === true,
    metaKey: gesture.metaKey === true,
    shiftKey: gesture.shiftKey === true,
    deltaX: Number(gesture.deltaX) || 0,
    deltaY: Number(gesture.deltaY) || 0,
    deltaZ: Number(gesture.deltaZ) || 0,
    preventDefault() {},
    stopPropagation() {}
  };
}

function resetSoundscapeWorkshopTextTransform(event) {
  if (resetTextPresetTransform(event)) return true;
  if (
    !isSoundscapeWorkshopPreset()
    || state.textPreset === 'none'
    || state.textPreset === 'book'
    || state.multiRowLyricsEnabled
    || state.textComposerSettings?.layoutMode === 'multi'
  ) return false;
  clearTextPresetHoldTimer();
  state.textPresetTransforms[state.textPreset] = normalizeTextPresetTransform();
  updateTextPresetTransform({ persist: true });
  return true;
}

function handleSoundscapeWorkshopGesture(gesture) {
  if (!isSoundscapeWorkshopPreset() || !state.playbackPage) return;
  const event = soundscapeWorkshopGestureEvent(gesture);
  if (!event) return;
  if (gesture.kind === 'pointerdown') {
    beginWindowDragGesture(event);
    if (state.windowDragPointerId === event.pointerId) return;
    beginTextPresetGesture(event);
  } else if (gesture.kind === 'pointermove') {
    if (state.windowDragPointerId === event.pointerId) {
      moveWindowDragGesture(event);
      return;
    }
    moveTextPresetGesture(event);
  } else if (gesture.kind === 'pointerup' || gesture.kind === 'pointercancel') {
    if (state.windowDragPointerId === event.pointerId) {
      endWindowDragGesture(event);
      return;
    }
    endTextPresetGesture(event);
  }
  else if (gesture.kind === 'wheel') scaleTextPresetFromWheel(event);
  else if (gesture.kind === 'dblclick') resetSoundscapeWorkshopTextTransform(event);
}

function handleSoundscapeWorkshopPlayerIntent(intent) {
  if (!intent || !isSoundscapeWorkshopPreset() || !state.playbackPage) return;
  if (intent.kind === 'seek') {
    if (!els.qishuiPlaybackProgressRange) return;
    els.qishuiPlaybackProgressRange.value = String(Math.round(clamp(Number(intent.ratio) || 0, 0, 1) * 1000));
    if (!beginQishuiPlaybackSeek()) return;
    previewQishuiPlaybackSeek();
    void commitQishuiPlaybackSeek();
    return;
  }
  if (intent.kind === 'previous' || intent.kind === 'next') {
    switchQishuiPlaybackTrack(intent.kind === 'previous' ? -1 : 1);
    return;
  }
  if (intent.kind !== 'controller-drag') return;
  const api = soundscapeWorkshopApi();
  const runtime = state.soundscapeWorkshop.runtime;
  if (!api?.apply || !runtime) return;
  const controllerX = Math.round(clamp((1 - Number(intent.x)) * 100, 0, 80));
  const controllerY = Math.round(clamp(Number(intent.y) * 100, 0, 90));
  try {
    api.apply(runtime, { controllerX, controllerY });
    scheduleClientPreferencesSync();
    renderSoundscapeWorkshopControls({ refreshOnly: true });
    renderDiySelectedPresetConfig();
  } catch (error) {
    showToast(error?.message || '播放器位置更新失败');
  }
}

function handleSoundscapeWorkshopTerminalError(snapshot) {
  state.soundscapeWorkshop.lastDiagnostics = snapshot || null;
  if (els.soundscapeWorkshopStatus) {
    els.soundscapeWorkshopStatus.hidden = false;
    els.soundscapeWorkshopStatus.dataset.state = 'error';
    els.soundscapeWorkshopStatus.textContent = '音域回响加载失败 · 重新选择可重试';
  }
  const fallback = normalizeDiyPreset(state.soundscapeWorkshop.previousUsablePreset || 'wallpaper');
  showToast('音域回响加载失败，已恢复上一个可用场景；重新选择可重试');
  window.setTimeout(() => {
    if (isSoundscapeWorkshopPreset()) setDiyPreset(fallback);
  }, 0);
}

function buildSoundscapeWorkshop() {
  const api = soundscapeWorkshopApi();
  if (!els.soundscapeWorkshopHost || state.soundscapeWorkshop.runtime || !api?.create) return;
  renderSoundscapeWorkshopControls();
  if (els.soundscapeWorkshopStatus) {
    els.soundscapeWorkshopStatus.hidden = false;
    delete els.soundscapeWorkshopStatus.dataset.state;
    els.soundscapeWorkshopStatus.textContent = '正在加载音域回响';
  }
  state.soundscapeWorkshop.runtime = api.create(els.soundscapeWorkshopHost, {
    entryUrl: SOUNDSCAPE_WORKSHOP_ENTRY_URL,
    onReady: () => {
      if (els.soundscapeWorkshopStatus) els.soundscapeWorkshopStatus.hidden = true;
      renderSoundscapeWorkshopControls({ refreshOnly: true });
    },
    onTerminalError: handleSoundscapeWorkshopTerminalError,
    onGesture: handleSoundscapeWorkshopGesture,
    onPlayerIntent: handleSoundscapeWorkshopPlayerIntent
  });
  api.activate?.(state.soundscapeWorkshop.runtime);
}

function disposeSoundscapeWorkshop() {
  const runtime = state.soundscapeWorkshop.runtime;
  const api = soundscapeWorkshopApi();
  if (!runtime || !api) return;
  state.soundscapeWorkshop.lastDiagnostics = api.diagnostics?.(runtime) || null;
  api.deactivate?.(runtime);
  api.dispose?.(runtime);
  state.soundscapeWorkshop.runtime = null;
  state.soundscapeWorkshop.lastMediaSignature = '';
}

function updateSoundscapeWorkshopVisibility() {
  const visible = state.playbackPage && isSoundscapeWorkshopPreset();
  if (els.soundscapeWorkshopScene) els.soundscapeWorkshopScene.hidden = !visible;
  if (els.appShell) els.appShell.classList.toggle('has-soundscape-workshop', visible);
  if (visible) buildSoundscapeWorkshop();
  else disposeSoundscapeWorkshop();
  syncPlaybackChromeClasses();
}

function soundscapeWorkshopAudioValues() {
  if (state.audioAnalysis.live) {
    return state.audioAnalysis.data || state.audioAnalysis.frequencyData || [];
  }
  // Desktop client native-audio path: the Web Audio analyser is suspended in
  // favor of XAudio2 loopback capture, so state.visual carries the 512-bin
  // low-frequency spectrum (20-150 Hz) reported by the native audio bridge.
  // That spectrum is pre-amplified and often pinned near 1.0, so soft-compress
  // it into the Workshop's 0-1 working range: beats keep dynamic movement
  // instead of pinning every cube at full lift.
  const bands = state.visual.lowFrequencyBands;
  if (!bands || !bands.length) return [];
  const values = new Float32Array(bands.length);
  for (let index = 0; index < bands.length; index += 1) {
    const value = Number(bands[index]) || 0;
    values[index] = Math.min(1, value * 0.6 + value * value * 0.15);
  }
  return values;
}

function updateSoundscapeWorkshopMotion() {
  const runtime = state.soundscapeWorkshop.runtime;
  const api = soundscapeWorkshopApi();
  if (!runtime || !api || !state.playbackPage || !isSoundscapeWorkshopPreset()) return;
  const analysis = state.audioAnalysis.live ? state.audioAnalysis : state.visual;
  api.updateAudio?.(runtime, soundscapeWorkshopAudioValues(), {
    playing: isPlaybackClockRunning(),
    bass: Number(analysis.bass) || 0,
    energy: Number(analysis.energy) || 0
  });
  const media = {
    title: safeText(state.currentSong?.title, ''),
    artist: safeText(state.currentSong?.artist, ''),
    thumbnail: safeText(state.currentSong?.cover || state.currentSong?.coverUrl, ''),
    isPlaying: isPlaybackClockRunning(),
    position: Number(els.audio?.currentTime) || 0,
    duration: Number(els.audio?.duration) || Number(state.currentSong?.duration) || 0
  };
  api.updateMedia?.(runtime, media);
}

function soundscapeWorkshopRuntimeSnapshot() {
  const api = soundscapeWorkshopApi();
  const runtime = state.soundscapeWorkshop.runtime;
  if (runtime && api?.diagnostics) return api.diagnostics(runtime);
  return {
    ...(state.soundscapeWorkshop.lastDiagnostics || {}),
    mounted: false,
    ready: false,
    parameters: api?.get?.(null) || {}
  };
}

function threeColorFromRgb(THREE, color) {
  return new THREE.Color(
    clamp((color && color.r) || 0, 0, 255) / 255,
    clamp((color && color.g) || 0, 0, 255) / 255,
    clamp((color && color.b) || 0, 0, 255) / 255
  );
}

function createSonicTopographyTheme(palette) {
  const THREE = window.THREE;
  const source = palette || fallbackLyricPalette(state.currentSong);
  const baseRgb = mixRgb(source.depth, { r: 0, g: 0, b: 0 }, 0.72);
  const base = threeColorFromRgb(THREE, baseRgb);
  const cool = threeColorFromRgb(THREE, vividCubeColor(source.glow, 0.02, 1.32));
  const warm = threeColorFromRgb(THREE, vividCubeColor(source.primary, 0.04, 1.22));
  const hot = threeColorFromRgb(THREE, vividCubeColor(source.highlight, 0.08, 1.1));
  const depth = threeColorFromRgb(THREE, source.depth);
  return {
    uBaseColor1: base.clone(),
    uBaseColor2: base.clone().lerp(new THREE.Color(0xffffff), 0.12),
    uCoolCore: cool.clone(),
    uCoolEdge: cool.clone().lerp(depth, 0.35),
    uWarmCore: warm.clone(),
    uWarmEdge: hot.clone().lerp(depth, 0.18),
    uRippleColor: hot.clone().lerp(cool, 0.28),
    uGlowIntensity: 1.36 + relativeLuminance(source.glow) * 0.74
  };
}

function createSonicTopographyMaterial(THREE, theme) {
  const lowFrequencySpectrumData = new Uint8Array(SONIC_LOW_FREQUENCY_BAND_COUNT);
  const lowFrequencySpectrum = new THREE.DataTexture(
    lowFrequencySpectrumData,
    SONIC_LOW_FREQUENCY_BAND_COUNT,
    1,
    THREE.LuminanceFormat,
    THREE.UnsignedByteType
  );
  lowFrequencySpectrum.magFilter = THREE.NearestFilter;
  lowFrequencySpectrum.minFilter = THREE.NearestFilter;
  lowFrequencySpectrum.generateMipmaps = false;
  lowFrequencySpectrum.flipY = false;
  lowFrequencySpectrum.unpackAlignment = 1;
  lowFrequencySpectrum.needsUpdate = true;

  const uniforms = {
    uTime: { value: 0 },
    uAudioTime: { value: 0 },
    uSubBass: { value: 0 },
    uBass: { value: 0 },
    uLowFrequencyAmplitude: { value: 0 },
    uLowFrequencySpectrum: { value: lowFrequencySpectrum },
    uLowMid: { value: 0 },
    uMid: { value: 0 },
    uHighMid: { value: 0 },
    uPresence: { value: 0 },
    uBrilliance: { value: 0 },
    uAir: { value: 0 },
    uWarmth: { value: 0 },
    uBrightness: { value: 0 },
    uSharpness: { value: 0 },
    uSmoothness: { value: 0.7 },
    uDensity: { value: 0.2 },
    uSpectralCentroid: { value: 0 },
    uEnergy: { value: 0 },
    uAudioPulse: { value: 0 },
    uIdleBreath: { value: 0.14 },
    uRipples: {
      value: Array.from({ length: SONIC_TOPOGRAPHY_RIPPLES }, () => ({
        pos: new THREE.Vector2(),
        time: -100,
        strength: 0,
        isActive: 0,
        rippleType: 0
      }))
    },
    uBaseColor1: { value: theme.uBaseColor1.clone() },
    uBaseColor2: { value: theme.uBaseColor2.clone() },
    uCoolCore: { value: theme.uCoolCore.clone() },
    uCoolEdge: { value: theme.uCoolEdge.clone() },
    uWarmCore: { value: theme.uWarmCore.clone() },
    uWarmEdge: { value: theme.uWarmEdge.clone() },
    uCenterColumnColor: { value: theme.uWarmCore.clone() },
    uCoreColumnColor: { value: theme.uWarmCore.clone() },
    uOuterColumnColor: { value: theme.uCoolEdge.clone() },
    uGroundColor: { value: theme.uCoolEdge.clone() },
    uGroundEmission: { value: DEFAULT_SONIC_SETTINGS.groundEmission },
    uRainEnabled: { value: DEFAULT_SONIC_SETTINGS.rainEnabled ? 1 : 0 },
    uRainIntensity: { value: DEFAULT_SONIC_SETTINGS.rainIntensity },
    uRainWetReflectance: { value: DEFAULT_SONIC_SETTINGS.rainWetReflectance },
    uRainWetGlow: { value: DEFAULT_SONIC_SETTINGS.rainWetGlow },
    uRainAudioLight: { value: 0 },
    uGroundMoundHeight: { value: DEFAULT_SONIC_SETTINGS.groundMoundHeight },
    uGroundEntrance: { value: 0 },
    uSonicBrightness: { value: DEFAULT_SONIC_SETTINGS.brightness },
    uFluorescence: { value: DEFAULT_SONIC_SETTINGS.fluorescence },
    uFluorescenceScatter: { value: DEFAULT_SONIC_SETTINGS.fluorescenceScatter },
    uSonicExposure: { value: DEFAULT_SONIC_SETTINGS.exposure },
    uColumnHeightScale: { value: DEFAULT_SONIC_SETTINGS.columnHeight },
    uRippleColor: { value: theme.uRippleColor.clone() },
    uGlowIntensity: { value: theme.uGlowIntensity },
    uTyndallBounceColor: { value: new THREE.Color(0xf4fbff) },
    uTyndallReceiverBounce: { value: 0 },
    uAtmosphereDaylightFill: { value: 0 },
    uAtmosphereLightStrength: { value: 0 },
    uAtmosphereAudioDrive: { value: 0 },
    uTyndallLightDirection: { value: new THREE.Vector2(72, -48).normalize() },
    uTyndallGoboPhase: { value: 0 }
  };

  const vertexShader = `
    uniform float uTime;
    uniform float uAudioTime;
    uniform float uSubBass;
    uniform float uBass;
    uniform float uLowFrequencyAmplitude;
    uniform sampler2D uLowFrequencySpectrum;
    uniform float uLowMid;
    uniform float uMid;
    uniform float uHighMid;
    uniform float uSmoothness;
    uniform float uDensity;
    uniform float uEnergy;
    uniform float uAudioPulse;
    uniform float uIdleBreath;
    uniform float uColumnHeightScale;
    uniform float uGroundMoundHeight;
    uniform float uGroundEntrance;
    attribute float aBassColumnBand;
    attribute float aGroundMoundMask;
    attribute vec4 aGroundMoundColumnProfile;
    attribute vec4 aTerrainSeed;
    attribute vec2 aTerrainSmallLocal;

    struct Ripple {
      vec2 pos;
      float time;
      float strength;
      float isActive;
      float rippleType;
    };
    uniform Ripple uRipples[10];

    varying vec2 vUv;
    varying float vElevation;
    varying float vDistance;
    varying vec2 vRippleAnim;
    varying vec3 vNormal;
    varying float vRelativeY;
    varying vec2 vInstancePos;
    varying float vBassColumnBlend;
    varying float vBassColumnRadialMix;
    varying float vBassColumnCoreMix;
    varying vec3 vViewDirection;
    varying vec3 vViewNormal;

    vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
    vec2 mod289(vec2 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
    vec3 permute(vec3 x) { return mod289(((x * 34.0) + 1.0) * x); }

    float snoise(vec2 v) {
      const vec4 C = vec4(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439);
      vec2 i = floor(v + dot(v, C.yy));
      vec2 x0 = v - i + dot(i, C.xx);
      vec2 i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
      vec4 x12 = x0.xyxy + C.xxzz;
      x12.xy -= i1;
      i = mod289(i);
      vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0));
      vec3 m = max(0.5 - vec3(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), 0.0);
      m = m * m;
      m = m * m;
      vec3 x = 2.0 * fract(p * C.www) - 1.0;
      vec3 h = abs(x) - 0.5;
      vec3 ox = floor(x + 0.5);
      vec3 a0 = x - ox;
      m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);
      vec3 g;
      g.x = a0.x * x0.x + h.x * x0.y;
      g.yz = a0.yz * x12.xz + h.yz * x12.yw;
      return 130.0 * dot(m, g);
    }

    float sampleLowFrequencyBand(float bandIndex) {
      float sampleX = (clamp(bandIndex, 0.0, 511.0) + 0.5) / 512.0;
      return texture2D(uLowFrequencySpectrum, vec2(sampleX, 0.5)).r;
    }

    void main() {
      vUv = uv;
      vNormal = normal;

      vec4 instancePos = instanceMatrix * vec4(0.0, 0.0, 0.0, 1.0);
      vec2 pos2D = instancePos.xz;
      vInstancePos = pos2D;

      float centerDist = length(pos2D);
      vDistance = centerDist;
      float rnd = aTerrainSeed.x;

      vec2 movingPos = pos2D * 0.05 + vec2(uTime * 0.1, uTime * 0.05);
      float baseNoise = (snoise(movingPos) + 1.0) * 0.5;
      float wave = sin(pos2D.x * 0.15 + pos2D.y * 0.1 - uTime * 0.6) * 0.5 + 0.5;
      float globalFalloff = 1.0 - smoothstep(36.0, 70.0, centerDist);
      float idleField = (snoise(pos2D * 0.085 + vec2(uTime * 0.032, -uTime * 0.026)) + 1.0) * 0.5;
      float idleCluster = smoothstep(0.5, 0.96, idleField + rnd * 0.18);
      float idlePulse = 0.54 + sin(uTime * 0.72 + rnd * 6.283 + baseNoise * 2.4) * 0.46;
      float idleElevation = uIdleBreath * globalFalloff * (idleCluster * idlePulse * 0.76 + wave * 0.13);
      float lowDrive = max(uSubBass * 1.35, uBass);
      float lowGate = smoothstep(0.055, 0.22, lowDrive);
      float rhythmGate = lowGate * (0.32 + uAudioPulse * 0.68);

      vec2 bassColumnGrid = pos2D / ${SONIC_TOPOGRAPHY_SPACING.toFixed(2)};
      vec2 bassColumnDelta = bassColumnGrid - vec2(${SONIC_BASS_COLUMN_CLUSTER.center.toFixed(1)});
      float bassColumnRadiusSquared = dot(bassColumnDelta, bassColumnDelta);
      float bassColumnRadius = sqrt(bassColumnRadiusSquared);
      float bassColumnCoreMask = 1.0 - step(
        ${(SONIC_BASS_COLUMN_CLUSTER.radius ** 2 + 0.5).toFixed(1)},
        bassColumnRadiusSquared
      );
      float bassColumnTransition = 1.0 - smoothstep(
        ${SONIC_BASS_COLUMN_CLUSTER.radius.toFixed(1)},
        ${(SONIC_BASS_COLUMN_CLUSTER.radius + SONIC_BASS_COLUMN_CLUSTER.feather).toFixed(1)},
        bassColumnRadius
      );
      float bassColumnBlend = max(bassColumnCoreMask, bassColumnTransition);
      vBassColumnBlend = bassColumnBlend;
      float bassColumnRadialMix = smoothstep(
        ${(SONIC_BASS_COLUMN_CLUSTER.radius * 0.55).toFixed(1)},
        ${(SONIC_BASS_COLUMN_CLUSTER.radius + SONIC_BASS_COLUMN_CLUSTER.feather).toFixed(1)},
        bassColumnRadius
      );
      vBassColumnRadialMix = bassColumnRadialMix;
      float bassColumnHeightProfile = mix(
        ${SONIC_BASS_COLUMN_CLUSTER.innerHeightScale.toFixed(2)},
        ${SONIC_BASS_COLUMN_CLUSTER.outerHeightScale.toFixed(2)},
        bassColumnRadialMix
      );
      float bassColumnCoreHeightMix = 1.0 - smoothstep(
        ${SONIC_BASS_COLUMN_CLUSTER.coreRadius.toFixed(1)},
        ${(SONIC_BASS_COLUMN_CLUSTER.coreRadius + SONIC_BASS_COLUMN_CLUSTER.coreFeather).toFixed(1)},
        bassColumnRadius
      );
      bassColumnHeightProfile = mix(
        bassColumnHeightProfile,
        ${SONIC_BASS_COLUMN_CLUSTER.coreHeightScale.toFixed(2)},
        bassColumnCoreHeightMix
      );
      vBassColumnCoreMix = bassColumnCoreHeightMix;
      float bassColumnCenterMask = (1.0 - step(0.5, abs(bassColumnDelta.x)))
        * (1.0 - step(0.5, abs(bassColumnDelta.y)));
      float bassColumnBandIndex = aBassColumnBand;
      float bassColumnLayerSeed = fract(
        rnd * 7.91 + aTerrainSeed.y * 4.37
          + aTerrainSeed.z * 2.13 + aTerrainSeed.w * 1.19
      );
      float bassColumnLayerTier = floor(bassColumnLayerSeed * 7.0) / 6.0;
      float bassColumnPatchTier = floor(
        fract(aTerrainSeed.y * 3.73 + aTerrainSeed.w * 2.11) * 4.0
      ) / 3.0;
      float bassColumnPedestalScale = mix(0.05, 5.8, bassColumnLayerTier)
        * mix(0.82, 1.0, bassColumnPatchTier);
      float bassColumnPedestalRadial = mix(
        0.65,
        1.45,
        smoothstep(0.58, 4.2, bassColumnHeightProfile)
      );
      float bassColumnDynamicScale = 1.35 + bassColumnHeightProfile * 0.62
        + bassColumnPatchTier * 0.12;
      float bassColumnDrive = 0.0;
      if (bassColumnBlend > 0.001) {
        float bassColumnBandDrive = sampleLowFrequencyBand(bassColumnBandIndex);
        bassColumnDrive = mix(
          bassColumnBandDrive,
          clamp(uLowFrequencyAmplitude, 0.0, 1.0),
          bassColumnCenterMask
        );
      }
      float bassColumnPedestalLift = bassColumnBlend
        * bassColumnPedestalRadial * bassColumnPedestalScale
        * min(uColumnHeightScale, 1.35);
      float bassColumnCoreLowFrequencyGainMask = bassColumnCoreHeightMix
        * bassColumnCoreHeightMix;
      float bassColumnCoreLowFrequencyGain = mix(
        1.0,
        ${SONIC_CENTER_COLUMN_CORE_LOW_FREQUENCY_GAIN.toFixed(2)},
        bassColumnCoreLowFrequencyGainMask
      );
      float bassColumnImpactDrive = bassColumnDrive * (
        1.0 + ${SONIC_LOW_FREQUENCY_IMPACT_CURVE_STRENGTH.toFixed(2)}
          * (1.0 - bassColumnDrive)
      );
      float bassColumnLift = bassColumnBlend * bassColumnImpactDrive * bassColumnDynamicScale
        * bassColumnCoreLowFrequencyGain * uColumnHeightScale;

      vec2 smallBassLocal = aTerrainSmallLocal - 0.5;
      float smallBassSeed = aTerrainSeed.y;
      vec2 smallBassCenter = (aTerrainSeed.zw - 0.5) * 0.26;
      float smallBassDistance = length(smallBassLocal - smallBassCenter);
      float smallBassPresence = step(0.84, smallBassSeed);
      float smallBassShape = (1.0 - smoothstep(0.07, 0.31, smallBassDistance))
        * smallBassPresence * (1.0 - bassColumnBlend);
      float smallBassPulse = 0.72
        + sin(uAudioTime * (1.1 + smallBassSeed * 0.7) + smallBassSeed * 6.283) * 0.28;
      float smallBassDrive = clamp(max(uLowFrequencyAmplitude, lowDrive) * lowGate, 0.0, 1.0);
      float smallBassLift = smallBassShape * smallBassDrive * smallBassPulse
        * (0.65 + smallBassSeed * 0.35) * 1.25 * uColumnHeightScale;

      float subRegion = 1.0 - smoothstep(0.0, 31.0, centerDist);
      float subLift = uSubBass * rhythmGate * subRegion * 1.05;

      float bassNoise = snoise(pos2D * 0.1 - vec2(0.0, uTime * 0.2));
      float bassRegion = 1.0 - smoothstep(6.0, 44.0, centerDist + bassNoise * 5.0);
      float bassLift = uBass * rhythmGate * bassRegion
        * smoothstep(0.0, 1.0, rnd + uDensity * 0.5) * 0.9;

      float lowMidNoise = snoise(pos2D * 0.05 + vec2(uTime * 0.1, 0.0));
      float lowMidLift = uLowMid * rhythmGate * (lowMidNoise * 0.5 + 0.5) * 0.42;

      float riverFlow = sin(pos2D.x * 0.2 + pos2D.y * 0.2 + snoise(pos2D * 0.1) * 2.0 - uTime * 2.0);
      float midLift = uMid * rhythmGate * max(0.0, riverFlow) * 0.42;

      float highMidRegion = smoothstep(10.0, 45.0, centerDist);
      float highMidLift = 0.0;
      if (fract(rnd * 13.3) > 0.8) {
        highMidLift = uHighMid * rhythmGate * highMidRegion * fract(rnd * 7.7) * 0.34;
      }

      float kickSurface = mix(baseNoise, wave, uSmoothness * 0.5 + 0.2)
        * lowDrive * rhythmGate * 0.28;
      float terrainAudioElevation = smallBassLift + subLift + bassLift
        + lowMidLift + midLift + highMidLift + kickSurface;
      if (rnd > 0.99) {
        terrainAudioElevation += uEnergy * rhythmGate * 0.28;
      }
      float audioColumnLiftCap = ${SONIC_AUDIO_COLUMN_MAX_LIFT.toFixed(2)}
        * min(uColumnHeightScale, 1.35);
      terrainAudioElevation = min(
        terrainAudioElevation * globalFalloff,
        audioColumnLiftCap
      );
      float centerColumnLiftCap = ${SONIC_CENTER_COLUMN_MAX_LIFT.toFixed(2)}
        * min(uColumnHeightScale, 1.35);
      float centerColumnRawLift = bassColumnLift * globalFalloff;
      float centerColumnKnee = centerColumnLiftCap
        * ${SONIC_CENTER_COLUMN_SOFT_KNEE_RATIO.toFixed(2)};
      float centerColumnKneeSpan = max(centerColumnLiftCap - centerColumnKnee, 0.001);
      float centerColumnAudioLift = centerColumnRawLift <= centerColumnKnee
        ? centerColumnRawLift
        : centerColumnKnee + centerColumnKneeSpan * (
            1.0 - exp(-(centerColumnRawLift - centerColumnKnee) / centerColumnKneeSpan)
          );
      float audioElevation = terrainAudioElevation + centerColumnAudioLift;

      // Every fixed peak is a dense column cluster. The compact static profile
      // gives every terrain cell a persistent tier, a phase bucket and one of
      // 512 low-frequency bands without adding another mesh or draw call.
      vec2 groundGridCell = floor(bassColumnGrid + vec2(0.5));
      float moundColumnLevel = floor(
        aGroundMoundColumnProfile.x * ${Number(SONIC_GROUND_MOUND_COLUMN_LEVELS - 1).toFixed(1)} + 0.5
      ) / ${Number(SONIC_GROUND_MOUND_COLUMN_LEVELS - 1).toFixed(1)};
      float moundColumnPhase = floor(
        aGroundMoundColumnProfile.y * ${Number(SONIC_GROUND_MOUND_COLUMN_PHASE_BUCKETS - 1).toFixed(1)} + 0.5
      ) / ${Number(SONIC_GROUND_MOUND_COLUMN_PHASE_BUCKETS - 1).toFixed(1)};
      float moundColumnBandIndex = floor(aGroundMoundColumnProfile.z * 255.0 + 0.5)
        + floor(aGroundMoundColumnProfile.w + 0.5) * 256.0;
      float moundColumnBandDrive = sampleLowFrequencyBand(moundColumnBandIndex);
      float moundColumnStaticBase = mix(
        ${SONIC_GROUND_MOUND_COLUMN_STATIC_MIN.toFixed(2)},
        ${SONIC_GROUND_MOUND_COLUMN_STATIC_MAX.toFixed(2)},
        moundColumnLevel
      );
      float groundPhaseJitter = rnd * 1.45 - 0.725
        + (moundColumnPhase - 0.5) * 1.7;
      float groundPhase = dot(groundGridCell, vec2(0.47, 0.71)) + groundPhaseJitter;
      float groundRing = centerDist / ${SONIC_TOPOGRAPHY_SPACING.toFixed(2)};
      float groundRingWaveA = 0.5 + 0.5 * sin(
        groundRing * 0.42 - uAudioTime * 0.64 + groundPhaseJitter * 0.38
      );
      float groundRingWaveB = 0.5 + 0.5 * sin(
        groundRing * 0.79 + uAudioTime * 0.37 + groundPhase * 1.31
      );
      float groundCrossWave = 0.5 + 0.5 * sin(
        dot(groundGridCell, vec2(0.31, -0.27)) - uAudioTime * 0.49
          + groundPhaseJitter * 0.7
      );
      float groundLayeredWave = groundRingWaveA * 0.48
        + groundRingWaveB * 0.32 + groundCrossWave * 0.2;
      float groundEntranceCursor = uGroundEntrance * 1.34
        - clamp(centerDist / 78.0, 0.0, 1.0) * 0.24 - rnd * 0.06;
      float groundEntrance = smoothstep(0.0, 1.0, groundEntranceCursor);
      float moundLowDrive = clamp(
        uLowFrequencyAmplitude * 0.72 + uSubBass * 0.18 + uBass * 0.1,
        0.0,
        1.0
      );
      float moundColumnAudioDrive = clamp(
        moundColumnBandDrive * 0.78 + moundLowDrive * 0.22,
        0.0,
        1.0
      );
      float moundColumnImpactDrive = moundColumnAudioDrive * (
        1.0 + ${SONIC_LOW_FREQUENCY_IMPACT_CURVE_STRENGTH.toFixed(2)}
          * (1.0 - moundColumnAudioDrive)
      );
      float moundColumnAudioLift = moundColumnImpactDrive * mix(
        ${SONIC_GROUND_MOUND_COLUMN_AUDIO_MIN.toFixed(2)},
        ${SONIC_GROUND_MOUND_COLUMN_AUDIO_MAX.toFixed(2)},
        moundColumnLevel
      );
      float groundMoundLift = aGroundMoundMask
        * (1.0 - bassColumnBlend * 0.58) * uGroundMoundHeight
        * (moundColumnStaticBase + moundColumnAudioLift + groundLayeredWave * 0.05)
        * groundEntrance;

      float elevation = idleElevation + bassColumnPedestalLift + audioElevation + groundMoundLift;
      float rippleElevation = 0.0;
      float rippleIntensityNormal = 0.0;
      float rippleIntensityWhite = 0.0;
      float speed = 15.0;
      float width = 3.0;

      for (int i = 0; i < 10; i++) {
        if (uRipples[i].isActive > 0.0) {
          float dist = length(pos2D - uRipples[i].pos);
          float timeSince = uTime - uRipples[i].time;
          float curSpeed = speed;
          float curWidth = width;
          float curFadeDist = 15.0;
          float elevationScale = 4.0;

          if (uRipples[i].rippleType > 0.5) {
            curSpeed = 20.0;
            curWidth = 1.0;
            curFadeDist = 8.0;
            elevationScale = 1.0;
          }

          float waveRadius = timeSince * curSpeed;
          float d = dist - waveRadius;
          float rippleWave = exp(-d * d / curWidth);
          float fade = exp(-waveRadius / curFadeDist);
          float rPulse = rippleWave * fade * uRipples[i].strength;

          rippleElevation += rPulse * elevationScale;
          if (uRipples[i].rippleType > 0.5) {
            rippleIntensityWhite += rPulse;
          } else {
            rippleIntensityNormal += rPulse;
          }
        }
      }

      elevation += rippleElevation;
      vRippleAnim = vec2(clamp(rippleIntensityNormal, 0.0, 1.0), clamp(rippleIntensityWhite, 0.0, 1.0));
      vElevation = elevation;

      float yPos = position.y + 0.5;
      vRelativeY = yPos;
      float totalHeight = 1.0 + elevation;
      vec3 pos = position;
      pos.y = -0.5 + yPos * totalHeight;

      vec4 worldPosition = instanceMatrix * vec4(pos, 1.0);
      vec3 viewPosition = (viewMatrix * worldPosition).xyz;
      vViewDirection = normalize(-viewPosition);
      vViewNormal = normalize(normalMatrix * normal);
      gl_Position = projectionMatrix * viewMatrix * worldPosition;
    }
  `;

  const fragmentShader = `
    uniform float uTime;
    uniform float uPresence;
    uniform float uBrilliance;
    uniform float uAir;
    uniform float uSubBass;
    uniform float uBass;
    uniform float uMid;
    uniform float uHighMid;
    uniform float uWarmth;
    uniform float uBrightness;
    uniform float uSharpness;
    uniform vec3 uBaseColor1;
    uniform vec3 uBaseColor2;
    uniform vec3 uCoolCore;
    uniform vec3 uCoolEdge;
    uniform vec3 uWarmCore;
    uniform vec3 uWarmEdge;
    uniform vec3 uCenterColumnColor;
    uniform vec3 uCoreColumnColor;
    uniform vec3 uOuterColumnColor;
    uniform vec3 uGroundColor;
    uniform float uGroundEmission;
    uniform float uRainEnabled;
    uniform float uRainIntensity;
    uniform float uRainWetReflectance;
    uniform float uRainWetGlow;
    uniform float uRainAudioLight;
    uniform float uSonicBrightness;
    uniform float uFluorescence;
    uniform float uFluorescenceScatter;
    uniform float uSonicExposure;
    uniform float uAudioPulse;
    uniform vec3 uTyndallBounceColor;
    uniform float uTyndallReceiverBounce;
    uniform float uAtmosphereDaylightFill;
    uniform float uAtmosphereLightStrength;
    uniform float uAtmosphereAudioDrive;
    uniform vec2 uTyndallLightDirection;
    uniform float uTyndallGoboPhase;
    uniform vec3 uRippleColor;
    uniform float uGlowIntensity;

    varying vec2 vUv;
    varying float vElevation;
    varying float vDistance;
    varying vec2 vRippleAnim;
    varying vec3 vNormal;
    varying float vRelativeY;
    varying vec2 vInstancePos;
    varying float vBassColumnBlend;
    varying float vBassColumnRadialMix;
    varying float vBassColumnCoreMix;
    varying vec3 vViewDirection;
    varying vec3 vViewNormal;

    float random(vec2 st) {
      return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
    }

    void main() {
      bool isTop = vNormal.y > 0.5;
      float distFromTop = 1.0 - vRelativeY;
      float rnd = random(vInstancePos);
      float centerDist = length(vInstancePos);
      float normElevation = clamp(vElevation / 8.0, 0.0, 1.0);
      float viewFacing = clamp(abs(dot(normalize(vViewNormal), normalize(vViewDirection))), 0.0, 1.0);
      float fresnelGlow = pow(1.0 - viewFacing, 2.35);
      float sheenTravel = fract(uTime * 0.075 + rnd * 0.37);
      float sheenCoordinate = fract(vUv.x * 0.62 + vUv.y * 0.38 + rnd * 0.18);
      float topSheen = isTop
        ? (1.0 - smoothstep(0.0, 0.16, abs(sheenCoordinate - sheenTravel)))
          * (0.28 + normElevation * 0.72)
        : 0.0;
      float sideLightRibs = isTop
        ? 0.0
        : pow(sin(vRelativeY * 22.0 + rnd * 6.283 + uTime * 0.45) * 0.5 + 0.5, 9.0)
          * (0.18 + normElevation * 0.82);
      float surfaceEdgeX = 1.0 - smoothstep(0.012, 0.065, vUv.x)
        + smoothstep(0.935, 0.988, vUv.x);
      float surfaceEdgeY = 1.0 - smoothstep(0.012, 0.065, vUv.y)
        + smoothstep(0.935, 0.988, vUv.y);
      float surfaceEdge = min(surfaceEdgeX + surfaceEdgeY, 1.0);

      vec3 cBase1 = uBaseColor1;
      vec3 cBase2 = uBaseColor2;
      vec3 coolCore = uCoolCore;
      vec3 coolEdge = uCoolEdge;
      vec3 warmCore = uWarmCore;
      vec3 warmEdge = uWarmEdge;

      float warmBlend = smoothstep(0.0, 1.0, uWarmth * 1.5 + (0.5 - centerDist / 94.0));
      vec3 zoneCore = mix(coolCore, warmCore, warmBlend);
      vec3 zoneEdge = mix(coolEdge, warmEdge, warmBlend);
      vec3 targetGlow = mix(zoneCore, zoneEdge, fract(rnd * 11.0));
      vec3 middleOuterColumnColor = mix(uCoreColumnColor, uOuterColumnColor, vBassColumnRadialMix);
      vec3 sonicColumnColor = mix(middleOuterColumnColor, uCenterColumnColor, vBassColumnCoreMix);
      targetGlow = mix(targetGlow, sonicColumnColor, vBassColumnBlend * (0.78 + normElevation * 0.18));
      float distFade = 1.0 - smoothstep(46.0, 88.0, centerDist);
      targetGlow = mix(targetGlow, vec3(0.4, 0.8, 1.0), uBrightness * 0.6);
      float groundSurfaceMask = 1.0 - vBassColumnBlend;
      targetGlow = mix(targetGlow, uGroundColor, groundSurfaceMask * 0.86);
      float visualFloor = clamp(0.035 + uBrightness * 0.05 + uAir * 0.04, 0.035, 0.16);
      vec3 currentGlow = mix(cBase2, targetGlow, max(normElevation, visualFloor)) * uGlowIntensity * distFade;
      currentGlow = mix(currentGlow, uRippleColor, vRippleAnim.x);
      currentGlow = mix(currentGlow, vec3(1.0, 1.0, 1.0), vRippleAnim.y);

      vec3 terrainBodyColor = mix(cBase1, cBase2, vRelativeY * distFade);
      vec3 groundBodyColor = mix(uGroundColor * 0.12, uGroundColor * 0.38, vRelativeY * distFade);
      vec3 bodyColor = mix(terrainBodyColor, groundBodyColor, groundSurfaceMask * 0.9);
      // A rising column exposes much more side area in a single frame. Keep a
      // bass-coupled color floor over that whole body so the new surface never
      // reads as a black rectangle between the lit cap and the ground.
      float columnBodyEnergy = vBassColumnBlend * clamp(
        max(uSubBass * 1.1, uBass) * 0.62 + uAudioPulse * 0.26 + normElevation * 0.34,
        0.0,
        1.0
      );
      vec3 columnBodyGlow = mix(
        sonicColumnColor * 0.42,
        currentGlow,
        0.58 + vRelativeY * 0.18
      );
      bodyColor = mix(
        bodyColor,
        columnBodyGlow,
        columnBodyEnergy * mix(0.32, 0.46, vRelativeY)
      );
      vec3 topBaseColor = mix(cBase2, uGroundColor * 0.28, groundSurfaceMask);
      vec3 finalColor;

      if (isTop) {
        float topIntensity = smoothstep(0.0, 0.4, normElevation);
        float twinkleDistFalloff = 1.0 - smoothstep(36.0, 72.0, centerDist);
        float twinkleMultiplier = mix(twinkleDistFalloff, 1.0, smoothstep(0.01, 0.1, normElevation));

        bool isSparkleTarget = fract(rnd * 31.0) > 0.95;
        if (isSparkleTarget && normElevation < 0.1) {
          topIntensity += uAir * 2.0 * twinkleMultiplier;
        }

        finalColor = mix(topBaseColor, currentGlow, topIntensity);

        finalColor += currentGlow * surfaceEdge * 0.8 * (topIntensity + 0.3);

        float flashChance = smoothstep(0.3, 1.0, uPresence);
        if (fract(rnd * 53.0) > 0.98 - flashChance * 0.1) {
          float flashSync = sin(uTime * 40.0 + rnd * 100.0) * 0.5 + 0.5;
          finalColor += mix(vec3(1.0), vec3(0.5, 1.0, 1.0), rnd) * flashSync * uPresence * (1.0 + uSharpness * 2.0) * twinkleMultiplier;
        }

        if (surfaceEdge > 0.5 && fract(rnd * 89.0 + uTime * 2.0) > 0.98) {
          finalColor += vec3(1.0) * uBrilliance * 0.45 * twinkleMultiplier;
        }
      } else {
        float verticalFalloff = mix(1.0, 3.0, uSharpness);
        float sideGlow = (1.0 - smoothstep(0.0, 0.5 / verticalFalloff, distFromTop))
          * normElevation;
        if (normElevation < 0.02) sideGlow = 0.0;
        finalColor = mix(bodyColor, currentGlow, sideGlow * 1.5);
        float rimGlow = (1.0 - smoothstep(0.0, 0.03, distFromTop)) * normElevation;
        finalColor += currentGlow * rimGlow;
      }

      // Fluorescence stays inside the existing terrain shader: grazing-angle
      // emission, a narrow structural edge, travelling top sheen, and fine
      // side-light ribs create four readable light layers without another draw
      // call or a costly bloom post-process.
      float fluorescenceEnergy = uFluorescence
        * clamp(0.22 + normElevation * 0.58 + uAudioPulse * 0.28 + vRippleAnim.y * 0.24, 0.0, 1.35);
      float fluorescenceHalo = pow(clamp(fresnelGlow, 0.0, 1.0), 0.78);
      float fluorescenceEdgeCore = pow(surfaceEdge, 1.35)
        * (isTop ? 0.72 : 0.3) * (0.68 + normElevation * 0.32);
      vec3 fluorescentEmission = mix(
        targetGlow,
        vec3(0.94, 0.985, 1.0),
        clamp(topSheen * 0.62 + fluorescenceHalo * 0.34 + fluorescenceEdgeCore * 0.24, 0.0, 0.72)
      ) * fluorescenceEnergy;
      float fluorescentDetail = fluorescenceHalo * (isTop ? 0.38 : 0.74)
        + fluorescenceEdgeCore
        + topSheen * 0.72
        + sideLightRibs * 0.58;
      fluorescentEmission /= 1.0 + max(0.0, max(
        fluorescentEmission.r,
        max(fluorescentEmission.g, fluorescentEmission.b)
      ) - 0.72) * 1.15;
      finalColor += fluorescentEmission * fluorescentDetail * 1.08;
      float fluorescenceScatterEnergy = uFluorescenceScatter * clamp(
        0.1 + fluorescenceEnergy * 0.44 + fluorescenceHalo * 0.18 + uAudioPulse * 0.08,
        0.0,
        1.35
      );

      // Ground emission stays in this terrain material and is explicitly
      // masked away from the bass-column cluster. Small mounds therefore
      // inherit the ground palette while remaining elevation-only geometry.
      float groundEmissionDetail = isTop
        ? 0.32 + surfaceEdge * 0.5 + fresnelGlow * 0.18 + topSheen * 0.26
        : 0.16 + fresnelGlow * 0.46 + sideLightRibs * 0.14;
      vec3 groundEmission = uGroundColor * uGroundEmission * groundSurfaceMask
        * groundEmissionDetail * (0.42 + normElevation * 0.58) * distFade;
      float groundEmissionPeak = max(groundEmission.r, max(groundEmission.g, groundEmission.b));
      groundEmission /= 1.0 + max(0.0, groundEmissionPeak - 0.58) * 1.45;
      finalColor += groundEmission;

      // Wet optics are evaluated on the terrain top faces themselves. This
      // removes the old detached floor plane, so wet light cannot appear in
      // column gaps, outside the radial terrain edge, or over the wallpaper.
      float rainAmount = uRainEnabled * clamp(uRainIntensity / 1.5, 0.0, 1.0);
      float wetEnergy = rainAmount * min(
        0.18,
        uRainWetReflectance * 0.105 + uRainWetGlow * 0.065
      );
      if (isTop && wetEnergy > 0.0001) {
        float filmPhase = vUv.x * 31.0 + vUv.y * 19.0 + uTime * 0.34 + rnd * 12.7;
        float crossPhase = vUv.x * -17.0 + vUv.y * 37.0 - uTime * 0.23 + rnd * 21.4;
        float filmFlow = sin(filmPhase) * 0.5 + 0.5;
        float crossFlow = sin(crossPhase) * 0.5 + 0.5;
        float microFilm = smoothstep(0.42, 0.92, filmFlow * 0.58 + crossFlow * 0.42);
        float wetFresnel = pow(clamp(fresnelGlow, 0.0, 1.0), 0.72);
        vec2 filmGradient = vec2(
          cos(filmPhase) * 31.0 * 0.58 + cos(crossPhase) * -17.0 * 0.42,
          cos(filmPhase) * 19.0 * 0.58 + cos(crossPhase) * 37.0 * 0.42
        );
        float directionalGlint = pow(
          clamp(0.5 + 0.5 * dot(normalize(filmGradient + vec2(0.001)), normalize(uTyndallLightDirection)), 0.0, 1.0),
          12.0
        );
        float wetSpecular = clamp(
          wetFresnel * 0.62 + topSheen * 0.34 + microFilm * 0.12 + directionalGlint * 0.28,
          0.0,
          1.0
        );
        float wetDarkening = wetEnergy * (0.2 + (1.0 - wetFresnel) * 0.18);
        finalColor *= 1.0 - wetDarkening;
        vec3 wetTint = mix(
          mix(uRippleColor, uTyndallBounceColor, 0.42),
          vec3(0.93, 0.98, 1.0),
          0.34
        );
        vec3 wetReflection = wetTint * wetEnergy
          * (0.24 + wetSpecular * 1.15 + microFilm * uRainWetGlow * 0.18)
          * (0.96 + uRainAudioLight * 0.08);
        float wetPeak = max(wetReflection.r, max(wetReflection.g, wetReflection.b));
        wetReflection /= 1.0 + max(0.0, wetPeak - 0.2) * 2.8;
        finalColor += wetReflection;
      }

      finalColor += uRippleColor * vRippleAnim.x * 0.6;
      finalColor += vec3(1.0, 1.0, 1.0) * vRippleAnim.y * 1.2;

      // Approximate the soft local color return visible where the shafts meet
      // the terrain. This is intentionally a tiny emissive response on the
      // existing column shader rather than a second lighting or raytrace pass.
      vec2 receiverDirection = normalize(uTyndallLightDirection);
      vec2 receiverTangent = vec2(-receiverDirection.y, receiverDirection.x);
      float receiverAlong = dot(vInstancePos, receiverDirection) * 0.035;
      float receiverAcross = dot(vInstancePos, receiverTangent) * 0.12;
      float receiverGobo = random(floor(vInstancePos * 0.22 + uTyndallGoboPhase));
      float receiverCanopy = smoothstep(0.27, 0.78,
        receiverGobo * 0.58 + (sin(receiverAcross + receiverAlong * 0.7) * 0.5 + 0.5) * 0.42);
      float receiverBounceStrength = mix(0.28, 1.0, receiverCanopy)
        * mix(0.72, 1.0, smoothstep(-1.4, 1.2, receiverAlong));
      float receiverEmissiveIntensity = receiverBounceStrength
        * uTyndallReceiverBounce * mix(0.48, 1.0, smoothstep(0.25, 0.88, vRelativeY));
      vec3 receiverBounce = uTyndallBounceColor * receiverEmissiveIntensity;
      float receiverPeak = max(receiverBounce.r, max(receiverBounce.g, receiverBounce.b));
      receiverBounce /= 1.0 + max(0.0, receiverPeak - 0.38) * 1.8;
      finalColor += receiverBounce;

      // Layered Sonic atmosphere lives in this existing terrain draw. Bass
      // opens a bounded local color return while the occluded facets breathe
      // slightly darker; mid/high detail only catches stable edges and facets.
      // uAtmosphereAudioDrive falls to zero while paused or in reduced-motion
      // mode, so none of these audio accents keep flickering at rest.
      float atmosphereStrength = clamp(uAtmosphereLightStrength, 0.0, 1.0);
      float lowFrequencyLight = clamp(
        (uSubBass * 0.64 + uBass * 0.46 + uAudioPulse * 0.28) * uAtmosphereAudioDrive,
        0.0,
        1.0
      );
      float highFrequencyLight = clamp(
        (uMid * 0.12 + uHighMid * 0.36 + uPresence * 0.28 + uBrilliance * 0.3)
          * uAtmosphereAudioDrive,
        0.0,
        1.0
      );
      vec2 localPoolDelta = (vInstancePos + receiverDirection * 18.0) * vec2(0.74, 1.08);
      float localLightPool = 1.0 - smoothstep(10.0, 58.0, length(localPoolDelta));
      float canopyShadow = 1.0 - receiverCanopy;
      float bassShadowBreath = atmosphereStrength * lowFrequencyLight
        * localLightPool * canopyShadow;
      finalColor *= 1.0 - bassShadowBreath * 0.085;

      vec3 paletteAtmosphereLight = mix(targetGlow, uTyndallBounceColor, 0.58);
      float localReturnStrength = atmosphereStrength * localLightPool
        * mix(0.5, 1.0, receiverCanopy)
        * (isTop ? 0.026 + lowFrequencyLight * 0.095 : 0.011 + lowFrequencyLight * 0.04);
      float staticFacetDetail = smoothstep(
        0.62,
        0.94,
        random(floor(vInstancePos * 1.47) + vec2(17.3, 41.9))
      );
      float detailMask = isTop
        ? clamp(surfaceEdge * 0.68 + staticFacetDetail * 0.24, 0.0, 1.0)
        : clamp(fresnelGlow * 0.46 + surfaceEdge * 0.2, 0.0, 1.0);
      float detailReturnStrength = atmosphereStrength * highFrequencyLight
        * detailMask * mix(0.62, 1.0, receiverCanopy) * 0.13;
      vec3 atmosphereReturn = paletteAtmosphereLight * localReturnStrength
        + mix(targetGlow, vec3(0.96, 0.985, 1.0), 0.46) * detailReturnStrength;
      float atmosphereReturnPeak = max(
        atmosphereReturn.r,
        max(atmosphereReturn.g, atmosphereReturn.b)
      );
      atmosphereReturn /= 1.0 + max(0.0, atmosphereReturnPeak - 0.24) * 2.4;
      finalColor += atmosphereReturn;

      // Reuse the same terrain draw as a soft receiver for fluorescence that
      // escapes the Sonic columns. The broad falloff reads as nearby air and
      // ground glow without a bloom pass or another mesh.
      float fluorescenceReach = max(
        localLightPool,
        (1.0 - smoothstep(16.0, 82.0, centerDist)) * (0.42 + vBassColumnBlend * 0.38)
      );
      float fluorescenceScatterReceiver = fluorescenceScatterEnergy
        * fluorescenceReach * mix(0.52, 1.0, receiverCanopy)
        * (isTop ? 0.068 : 0.035);
      vec3 fluorescenceScatterReturn = mix(targetGlow, uTyndallBounceColor, 0.3)
        * fluorescenceScatterReceiver;
      float fluorescenceScatterPeak = max(
        fluorescenceScatterReturn.r,
        max(fluorescenceScatterReturn.g, fluorescenceScatterReturn.b)
      );
      fluorescenceScatterReturn /= 1.0
        + max(0.0, fluorescenceScatterPeak - 0.16) * 3.2;
      finalColor += fluorescenceScatterReturn;
      // Sunlight also contributes a soft, directional daylight fill. Keep its
      // low-frequency canopy variation so raised atmosphere settings reveal
      // more midtones without flattening the terrain or creating a light spot.
      float daylightShape = mix(0.42, 1.0, receiverCanopy)
        * mix(0.7, 1.0, smoothstep(-1.4, 1.2, receiverAlong));
      daylightShape *= isTop ? 1.0 : mix(0.62, 0.9, vRelativeY);
      finalColor += uTyndallBounceColor * uAtmosphereDaylightFill * daylightShape;

      float aerialFog = smoothstep(30.0, 65.0, vDistance);
      float farLightGradient = smoothstep(
        -52.0,
        54.0,
        dot(vInstancePos, receiverDirection)
      );
      vec3 atmosphericColor = mix(cBase1, cBase2, 0.4);
      vec3 farPaletteHaze = mix(uTyndallBounceColor, targetGlow, 0.34);
      atmosphericColor = mix(
        atmosphericColor,
        farPaletteHaze,
        atmosphereStrength * (0.075 + farLightGradient * 0.105)
      );
      float spatialFogMix = aerialFog * clamp(
        0.43 + atmosphereStrength * (0.045 + farLightGradient * 0.055),
        0.43,
        0.55
      );
      finalColor = mix(finalColor, atmosphericColor, spatialFogMix);
      finalColor *= uSonicBrightness * exp2(uSonicExposure);

      float alphaFade = 1.0 - smoothstep(55.0, 78.0, vDistance);
      gl_FragColor = vec4(finalColor, alphaFade);
    }
  `;

  const material = new THREE.ShaderMaterial({
    uniforms,
    vertexShader,
    fragmentShader,
    transparent: true
  });
  material.userData.lowFrequencySpectrum = lowFrequencySpectrum;
  material.userData.lowFrequencySpectrumData = lowFrequencySpectrumData;
  return material;
}

function sonicTopographyPaletteColors() {
  const topo = state.sonicTopography;
  const palette = topo.palette || fallbackLyricPalette(state.currentSong);
  const middle = palette?.highlight || palette?.glow || { r: 255, g: 255, b: 255 };
  return {
    center: rgbHexValue(mixRgb(middle, { r: 255, g: 255, b: 255 }, 0.58)),
    core: rgbHexValue(middle),
    outer: rgbHexValue(palette?.glow || palette?.primary || { r: 131, g: 228, b: 255 })
  };
}

function resolvedSonicTopographyColors() {
  const automatic = sonicTopographyPaletteColors();
  const settings = state.sonicTopography.settings || DEFAULT_SONIC_SETTINGS;
  return {
    center: settings.centerColor || automatic.center,
    core: settings.coreColor || automatic.core,
    outer: settings.outerColor || automatic.outer
  };
}

function resolvedSonicGroundColor() {
  const topo = state.sonicTopography;
  const paletteColors = sonicCoverBackgroundColors(topo.palette || fallbackLyricPalette(state.currentSong));
  const automatic = rgbHexValue(mixRgb(
    mixRgb(paletteColors[0], paletteColors[1], 0.58),
    paletteColors[2],
    0.18
  ));
  const settings = topo.settings || DEFAULT_SONIC_SETTINGS;
  return settings.groundColor || automatic;
}

function sonicTerrainMoundFieldAt(x, z) {
  const broad = Math.sin(x * 0.074 + z * 0.039 + 0.8) * 0.5 + 0.5;
  const diagonal = Math.sin(x * -0.047 + z * 0.11 + 2.15) * 0.5 + 0.5;
  const cross = Math.sin(x * 0.137 - z * 0.063 - 0.9) * 0.5 + 0.5;
  const layered = broad * 0.48 + diagonal * 0.34 + cross * 0.18;
  const ridge = Math.pow(clamp((layered - 0.24) / 0.76, 0, 1), 1.55);
  const unevenHeight = 0.76 + sonicRainHash(x * 0.19 + 17.3, z * 0.19 - 9.7) * 0.24;
  return 0.045 + ridge * 0.56 * unevenHeight;
}

function sonicGroundMoundMaskAt(x, z, settings) {
  const radius = settings.groundMoundRadius;
  let moundMask = sonicTerrainMoundFieldAt(x, z);
  const nearestGridX = clamp(
    Math.round((x + SONIC_GROUND_MOUND_GRID_EXTENT) / SONIC_GROUND_MOUND_GRID_SPACING),
    0,
    SONIC_GROUND_MOUND_GRID_SIZE - 1
  );
  const nearestGridZ = clamp(
    Math.round((z + SONIC_GROUND_MOUND_GRID_EXTENT) / SONIC_GROUND_MOUND_GRID_SPACING),
    0,
    SONIC_GROUND_MOUND_GRID_SIZE - 1
  );
  const firstGridX = Math.max(0, nearestGridX - SONIC_GROUND_MOUND_NEIGHBOR_CELLS);
  const lastGridX = Math.min(SONIC_GROUND_MOUND_GRID_SIZE - 1, nearestGridX + SONIC_GROUND_MOUND_NEIGHBOR_CELLS);
  const firstGridZ = Math.max(0, nearestGridZ - SONIC_GROUND_MOUND_NEIGHBOR_CELLS);
  const lastGridZ = Math.min(SONIC_GROUND_MOUND_GRID_SIZE - 1, nearestGridZ + SONIC_GROUND_MOUND_NEIGHBOR_CELLS);
  for (let gridZ = firstGridZ; gridZ <= lastGridZ; gridZ += 1) {
    for (let gridX = firstGridX; gridX <= lastGridX; gridX += 1) {
      const center = SONIC_GROUND_MOUND_CENTERS[gridZ * SONIC_GROUND_MOUND_GRID_SIZE + gridX];
      const moundRadius = radius * center.radiusScale;
      const innerRadius = moundRadius * 0.28;
      const transitionSpan = Math.max(0.001, moundRadius - innerRadius);
      const dx = x - center.x;
      const dz = z - center.z;
      const distanceSquared = dx * dx + dz * dz;
      if (distanceSquared >= moundRadius * moundRadius) continue;
      const distance = Math.sqrt(distanceSquared);
      const progress = clamp((distance - innerRadius) / transitionSpan, 0, 1);
      const smoothProgress = progress * progress * (3 - 2 * progress);
      const shape = 1 - smoothProgress;
      moundMask = Math.max(moundMask, shape * shape * center.heightScale);
    }
  }
  return moundMask;
}

function sonicGroundMoundMaskSignature(settings) {
  return `fixed-adjoining-full-terrain-v4:${settings.groundMoundRadius.toFixed(2)}`;
}

function fillSonicGroundMoundMask(target, settings) {
  const offset = (SONIC_TOPOGRAPHY_GRID * SONIC_TOPOGRAPHY_SPACING) / 2;
  let targetIndex = 0;
  for (let x = 0; x < SONIC_TOPOGRAPHY_GRID; x += 1) {
    const px = x * SONIC_TOPOGRAPHY_SPACING - offset;
    for (let z = 0; z < SONIC_TOPOGRAPHY_GRID; z += 1) {
      const pz = z * SONIC_TOPOGRAPHY_SPACING - offset;
      target[targetIndex] = sonicGroundMoundMaskAt(px, pz, settings);
      targetIndex += 1;
    }
  }
}

function updateSonicGroundMoundMask(settings = state.sonicTopography.settings) {
  const topo = state.sonicTopography;
  const attribute = topo.groundMoundMaskAttribute
    || topo.terrain?.geometry?.getAttribute?.('aGroundMoundMask');
  if (!attribute?.array) return;
  const signature = sonicGroundMoundMaskSignature(settings);
  if (signature === topo.groundMoundSignature) return;
  fillSonicGroundMoundMask(attribute.array, settings);
  attribute.needsUpdate = true;
  topo.groundMoundSignature = signature;
}

let sonicSettingsPreferenceSaveTimer = 0;

function saveSonicSettingsPreferences({ immediate = false } = {}) {
  if (communityScenePersistenceSuppressed()) {
    scheduleCommunitySceneSync();
    return;
  }
  window.clearTimeout(sonicSettingsPreferenceSaveTimer);
  sonicSettingsPreferenceSaveTimer = 0;
  const commit = () => {
    sonicSettingsPreferenceSaveTimer = 0;
    try {
      window.localStorage.setItem(SONIC_SETTINGS_PREFS_KEY, JSON.stringify(
        {
          ...normalizeSonicSettings(state.sonicTopography.settings),
          cameraFramingVersion: SONIC_CAMERA_FRAMING_VERSION
        }
      ));
    } catch (error) {}
  };
  if (immediate) {
    commit();
    return;
  }
  sonicSettingsPreferenceSaveTimer = window.setTimeout(
    commit,
    VISUAL_PREFERENCE_SAVE_DEBOUNCE_MS
  );
}

function flushSonicSettingsPreferences() {
  if (sonicSettingsPreferenceSaveTimer) saveSonicSettingsPreferences({ immediate: true });
}

function syncSonicSettingsControls() {
  const settings = normalizeSonicSettings(state.sonicTopography.settings);
  const colors = resolvedSonicTopographyColors();
  const groundColor = resolvedSonicGroundColor();
  const isAutomatic = !settings.centerColor && !settings.coreColor && !settings.outerColor;
  const isCustom = !!settings.centerColor && !!settings.coreColor && !!settings.outerColor;
  const isGroundAutomatic = !settings.groundColor;
  if (els.sonicCenterColorInput) els.sonicCenterColorInput.value = colors.center;
  if (els.sonicCoreColorInput) els.sonicCoreColorInput.value = colors.core;
  if (els.sonicOuterColorInput) els.sonicOuterColorInput.value = colors.outer;
  if (els.sonicGroundColorInput) els.sonicGroundColorInput.value = groundColor;
  if (els.sonicFountainColorInput) els.sonicFountainColorInput.value = settings.fountainColor;
  if (els.sonicStarfieldColorInput) els.sonicStarfieldColorInput.value = settings.starfieldColor;
  if (els.sonicGalaxyColorInput) els.sonicGalaxyColorInput.value = settings.galaxyColor;
  if (els.sonicFountainToggle) {
    els.sonicFountainToggle.checked = settings.fountainEnabled;
    els.sonicFountainToggle.setAttribute('aria-checked', String(settings.fountainEnabled));
  }
  if (els.sonicGroundMoundsToggle) {
    els.sonicGroundMoundsToggle.checked = settings.groundMoundsEnabled;
    els.sonicGroundMoundsToggle.setAttribute('aria-checked', String(settings.groundMoundsEnabled));
  }
  if (els.sonicStarfieldToggle) {
    els.sonicStarfieldToggle.checked = settings.starfieldEnabled;
    els.sonicStarfieldToggle.setAttribute('aria-checked', String(settings.starfieldEnabled));
  }
  const syncToggle = (input, checked) => {
    if (!input) return;
    input.checked = checked;
    input.setAttribute('aria-checked', String(checked));
  };
  syncToggle(els.sonicGalaxyToggle, settings.galaxyEnabled);
  syncToggle(els.sonicAtmosphereToggle, settings.atmosphereEnabled);
  syncToggle(els.sonicCoverBackgroundToggle, settings.coverBackgroundEnabled);
  syncToggle(els.sonicRainToggle, settings.rainEnabled);
  if (els.sonicTyndallToneSelect) els.sonicTyndallToneSelect.value = settings.tyndallTone;
  if (els.sonicPaletteMode) {
    els.sonicPaletteMode.textContent = isAutomatic
      ? '颜色跟随封面'
      : isCustom ? '核心、中间与外围自定义' : '部分颜色自定义';
  }
  if (els.sonicFollowCoverButton) {
    els.sonicFollowCoverButton.classList.toggle('is-active', isAutomatic);
    els.sonicFollowCoverButton.setAttribute('aria-pressed', String(isAutomatic));
  }
  if (els.sonicGroundPaletteMode) {
    els.sonicGroundPaletteMode.textContent = isGroundAutomatic
      ? '随封面实时取色'
      : '自定义地面颜色';
  }
  if (els.sonicGroundFollowCoverButton) {
    els.sonicGroundFollowCoverButton.classList.toggle('is-active', isGroundAutomatic);
    els.sonicGroundFollowCoverButton.setAttribute('aria-pressed', String(isGroundAutomatic));
  }
  const syncRange = (input, output, rawValue, text) => {
    if (input) {
      input.value = String(rawValue);
      input.setAttribute('aria-valuetext', text);
      syncElasticRangeVisual(input);
    }
    if (output) output.textContent = text;
  };
  syncRange(els.sonicBrightnessRange, els.sonicBrightnessValue, Math.round(settings.brightness * 100), `${Math.round(settings.brightness * 100)}%`);
  syncRange(els.sonicFluorescenceRange, els.sonicFluorescenceValue, Math.round(settings.fluorescence * 100), `${Math.round(settings.fluorescence * 100)}%`);
  syncRange(els.sonicFluorescenceScatterRange, els.sonicFluorescenceScatterValue, Math.round(settings.fluorescenceScatter * 100), `${Math.round(settings.fluorescenceScatter * 100)}%`);
  const exposureText = `${settings.exposure > 0 ? '+' : ''}${settings.exposure.toFixed(2)} EV`;
  syncRange(els.sonicExposureRange, els.sonicExposureValue, Math.round(settings.exposure * 100), exposureText);
  syncRange(els.sonicColumnHeightRange, els.sonicColumnHeightValue, Math.round(settings.columnHeight * 100), `${Math.round(settings.columnHeight * 100)}%`);
  syncRange(els.sonicFovRange, els.sonicFovValue, Math.round(settings.fov), `${Math.round(settings.fov)}°`);
  syncRange(els.sonicSmoothingRange, els.sonicSmoothingValue, Math.round(settings.smoothing * 100), `${Math.round(settings.smoothing * 100)}%`);
  syncRange(els.sonicGroundEmissionRange, els.sonicGroundEmissionValue, Math.round(settings.groundEmission * 100), `${Math.round(settings.groundEmission * 100)}%`);
  syncRange(els.sonicGroundMoundHeightRange, els.sonicGroundMoundHeightValue, Math.round(settings.groundMoundHeight * 100), `${Math.round(settings.groundMoundHeight * 100)}%`);
  syncRange(els.sonicGroundMoundRadiusRange, els.sonicGroundMoundRadiusValue, Math.round(settings.groundMoundRadius), `${Math.round(settings.groundMoundRadius)} 格`);
  syncRange(els.sonicRainIntensityRange, els.sonicRainIntensityValue, Math.round(settings.rainIntensity * 100), `${Math.round(settings.rainIntensity * 100)}%`);
  syncRange(els.sonicRainSpeedRange, els.sonicRainSpeedValue, Math.round(settings.rainSpeed * 100), `${Math.round(settings.rainSpeed * 100)}%`);
  const rainWindPercent = Math.round(settings.rainWind * 100);
  syncRange(els.sonicRainWindRange, els.sonicRainWindValue, rainWindPercent, `${rainWindPercent > 0 ? '+' : ''}${rainWindPercent}%`);
  syncRange(els.sonicRainLengthRange, els.sonicRainLengthValue, Math.round(settings.rainLength * 100), `${Math.round(settings.rainLength * 100)}%`);
  syncRange(els.sonicRainWidthRange, els.sonicRainWidthValue, Math.round(settings.rainWidth * 100), `${Math.round(settings.rainWidth * 100)}%`);
  syncRange(els.sonicRainRippleIntensityRange, els.sonicRainRippleIntensityValue, Math.round(settings.rainRippleIntensity * 100), `${Math.round(settings.rainRippleIntensity * 100)}%`);
  syncRange(els.sonicRainRippleSizeRange, els.sonicRainRippleSizeValue, Math.round(settings.rainRippleSize * 100), `${Math.round(settings.rainRippleSize * 100)}%`);
  syncRange(els.sonicRainRippleLifeRange, els.sonicRainRippleLifeValue, Math.round(settings.rainRippleLife * 100), `${Math.round(settings.rainRippleLife * 100)}%`);
  syncRange(els.sonicRainWetReflectanceRange, els.sonicRainWetReflectanceValue, Math.round(settings.rainWetReflectance * 100), `${Math.round(settings.rainWetReflectance * 100)}%`);
  syncRange(els.sonicRainWetGlowRange, els.sonicRainWetGlowValue, Math.round(settings.rainWetGlow * 100), `${Math.round(settings.rainWetGlow * 100)}%`);
  syncRange(els.sonicGalaxyIntensityRange, els.sonicGalaxyIntensityValue, Math.round(settings.galaxyIntensity * 100), `${Math.round(settings.galaxyIntensity * 100)}%`);
  syncRange(els.sonicFogDensityRange, els.sonicFogDensityValue, Math.round(settings.fogDensity * 100), `${Math.round(settings.fogDensity * 100)}%`);
  syncRange(els.sonicFogSpeedRange, els.sonicFogSpeedValue, Math.round(settings.fogSpeed * 100), `${Math.round(settings.fogSpeed * 100)}%`);
  syncRange(els.sonicFogGlowRange, els.sonicFogGlowValue, Math.round(settings.fogGlow * 100), `${Math.round(settings.fogGlow * 100)}%`);
  syncRange(els.sonicMistReflectanceRange, els.sonicMistReflectanceValue, Math.round(settings.mistReflectance * 100), `${Math.round(settings.mistReflectance * 100)}%`);
  syncRange(els.sonicMistEmissionRange, els.sonicMistEmissionValue, Math.round(settings.mistEmission * 100), `${Math.round(settings.mistEmission * 100)}%`);
  syncRange(els.sonicTyndallIntensityRange, els.sonicTyndallIntensityValue, Math.round(settings.tyndallIntensity * 100), `${Math.round(settings.tyndallIntensity * 100)}%`);
  syncRange(els.sonicTyndallSpreadRange, els.sonicTyndallSpreadValue, Math.round(settings.tyndallSpread * 100), `${Math.round(settings.tyndallSpread * 100)}%`);
  syncRange(els.sonicCoverBackgroundMixRange, els.sonicCoverBackgroundMixValue, Math.round(settings.coverBackgroundMix * 100), `${Math.round(settings.coverBackgroundMix * 100)}%`);
}

function sonicTopographyCameraFitRadius(aspect, fov) {
  const verticalFov = clamp(Number(fov) || SONIC_TOPOGRAPHY_CAMERA.fov, 42, 68) * Math.PI / 180;
  const safeAspect = clamp(Number(aspect) || 1, 0.3, 4);
  const horizontalFov = 2 * Math.atan(Math.tan(verticalFov / 2) * safeAspect);
  const fitFov = Math.min(verticalFov, horizontalFov);
  const activeRadius = Math.min(Math.SQRT2 * SONIC_TOPOGRAPHY_HALF, 78);
  return Math.hypot(activeRadius, 10) * 0.74 / Math.sin(fitFov / 2);
}

function updateSonicTopographyCameraFit() {
  const topo = state.sonicTopography;
  if (!topo.camera) return;
  // Settings are normalized when loaded/applied, so camera refits can reuse them.
  const settings = topo.settings || DEFAULT_SONIC_SETTINGS;
  topo.camera.fov = settings.fov;
  topo.baseCameraRadius = sonicTopographyCameraFitRadius(topo.camera.aspect, settings.fov);
  topo.camera.updateProjectionMatrix();
  fitSonicWallpaperSurface(topo);
  fitSonicWallpaperTexture(topo);
  if (topo.scene?.fog) {
    const activeRadius = Math.min(Math.SQRT2 * SONIC_TOPOGRAPHY_HALF, 78);
    const fogAmount = settings.fogEnabled ? settings.fogDensity : 0;
    if (!settings.fogEnabled) {
      topo.scene.fog.near = topo.baseCameraRadius + activeRadius * 2.6;
      topo.scene.fog.far = topo.scene.fog.near + activeRadius;
    } else {
      topo.scene.fog.near = topo.baseCameraRadius * (0.98 - fogAmount * 0.1);
      topo.scene.fog.far = topo.baseCameraRadius + activeRadius * (2.8 - fogAmount * 0.4);
    }
  }
}

function audioAnalysisPlaybackActive() {
  return !!els.audio?.src
    && !els.audio.paused
    && !els.audio.ended;
}

function setAudioAnalysisContextRunning(shouldRun) {
  const analysis = state.audioAnalysis;
  analysis.contextShouldRun = shouldRun === true;
  const previous = analysis.contextTransition || Promise.resolve(false);
  const transition = previous
    .catch(() => false)
    .then(async () => {
      const context = analysis.context;
      if (!context || context.state === 'closed') return false;
      try {
        if (analysis.contextShouldRun) {
          if (context.state !== 'running') await context.resume();
          return context.state === 'running';
        }
        if (context.state === 'running') await context.suspend();
        return context.state !== 'running';
      } catch (error) {
        return false;
      }
    });
  analysis.contextTransition = transition;
  const clearTransition = () => {
    if (analysis.contextTransition === transition) analysis.contextTransition = null;
  };
  transition.then(clearTransition, clearTransition);
  return transition;
}

function resumeAudioAnalysis() {
  return setAudioAnalysisContextRunning(true);
}

function suspendAudioAnalysis() {
  return setAudioAnalysisContextRunning(false);
}

function applySonicTopographySettings(options = {}) {
  const topo = state.sonicTopography;
  topo.settings = normalizeSonicSettings(topo.settings);
  const settings = topo.settings;
  const colors = resolvedSonicTopographyColors();
  if (topo.uniforms) {
    topo.uniforms.uCenterColumnColor?.value?.set?.(colors.center);
    topo.uniforms.uCoreColumnColor?.value?.set?.(colors.core);
    topo.uniforms.uOuterColumnColor?.value?.set?.(colors.outer);
    if (topo.uniforms.uGroundColor) topo.uniforms.uGroundColor.value.set(resolvedSonicGroundColor());
    if (topo.uniforms.uGroundEmission) topo.uniforms.uGroundEmission.value = settings.groundEmission;
    if (topo.uniforms.uRainEnabled) topo.uniforms.uRainEnabled.value = settings.rainEnabled ? 1 : 0;
    if (topo.uniforms.uRainIntensity) topo.uniforms.uRainIntensity.value = settings.rainIntensity;
    if (topo.uniforms.uRainWetReflectance) {
      topo.uniforms.uRainWetReflectance.value = settings.rainWetReflectance;
    }
    if (topo.uniforms.uRainWetGlow) topo.uniforms.uRainWetGlow.value = settings.rainWetGlow;
    if (topo.uniforms.uGroundMoundHeight) {
      topo.uniforms.uGroundMoundHeight.value = settings.groundMoundsEnabled
        ? settings.groundMoundHeight
        : 0;
    }
    if (topo.uniforms.uSonicBrightness) topo.uniforms.uSonicBrightness.value = settings.brightness;
    if (topo.uniforms.uFluorescence) topo.uniforms.uFluorescence.value = settings.fluorescence;
    if (topo.uniforms.uFluorescenceScatter) topo.uniforms.uFluorescenceScatter.value = settings.fluorescenceScatter;
    if (topo.uniforms.uSonicExposure) topo.uniforms.uSonicExposure.value = settings.exposure;
    if (topo.uniforms.uColumnHeightScale) topo.uniforms.uColumnHeightScale.value = settings.columnHeight;
  }
  updateSonicGroundMoundMask(settings);
  applySonicRainSettings(topo, settings);
  if (topo.particleMaterial?.color) topo.particleMaterial.color.set(settings.fountainColor);
  if (topo.starfield) topo.starfield.visible = settings.starfieldEnabled;
  if (topo.starfieldMaterial?.color) topo.starfieldMaterial.color.set(settings.starfieldColor);
  if (topo.galaxy) topo.galaxy.visible = settings.galaxyEnabled;
  if (topo.galaxyMaterial?.color) topo.galaxyMaterial.color.set(settings.galaxyColor);
  if (topo.galaxyMaterial) topo.galaxyMaterial.opacity = 0.08 + settings.galaxyIntensity * 0.56;
  const fluorescenceScatter = clamp(settings.fluorescenceScatter / 1.5, 0, 1);
  if (topo.fogGroup) {
    topo.fogGroup.visible = settings.atmosphereEnabled || fluorescenceScatter > 0.002;
  }
  const toneColor = settings.tyndallTone === 'cold'
    ? 0xb9dcff
    : settings.tyndallTone === 'warm' ? 0xffd29a : 0xf4fbff;
  const forwardScatterColor = settings.tyndallTone === 'cold'
    ? 0xe8f5ff
    : settings.tyndallTone === 'warm' ? 0xfff0d6 : 0xf8fbff;
  const mistScatterColor = settings.tyndallTone === 'cold'
    ? 0xdbe7ec
    : settings.tyndallTone === 'warm' ? 0xeee5d8 : 0xdfe8e7;
  const skyAtmosphereColor = settings.tyndallTone === 'cold'
    ? 0xf0f6ff
    : settings.tyndallTone === 'warm' ? 0xffe7bd : 0xfff1d6;
  const sonicAtmosphereContrast = settings.atmosphereEnabled
    ? clamp(0.42 + settings.fogDensity * 0.42 + settings.fogGlow * 0.1, 0.42, 1)
    : 0;
  const perceptualTyndallIntensity = settings.tyndallIntensity <= 0
    ? 0
    : Math.pow(clamp(settings.tyndallIntensity / 1.5, 0, 1), 0.72) * 1.5;
  const atmosphereLightStrength = clamp(
    (settings.atmosphereEnabled
      ? (
      0.36
        + settings.fogGlow * 0.24
        + perceptualTyndallIntensity * 0.14
        + settings.mistReflectance * 0.11
      )
      : 0)
      + fluorescenceScatter * 0.18,
    0,
    0.88
  );
  const beamVisibility = 1 - smoothstep(0.34, 0.96, settings.mistEmission);
  const daylightFill = settings.atmosphereEnabled
    ? clamp(
      sonicAtmosphereContrast * 0.2 + perceptualTyndallIntensity * 0.055,
      0,
      0.28
    )
    : 0;
  const atmosphereDaylightFill = settings.atmosphereEnabled
    ? clamp(
      0.018
        + smoothstep(0.56, 0.9, sonicAtmosphereContrast) * 0.135
        + smoothstep(0.78, 1.5, perceptualTyndallIntensity) * 0.035,
      0,
      0.18
    )
    : 0;
  const sonicHighlightShoulder = topo.sonicHighlightShoulder || 0.9;
  topo.atmosphereContrast = sonicAtmosphereContrast;
  if (topo.scene?.fog) {
    topo.scene.fog.near = 190 - sonicAtmosphereContrast * 98;
    topo.scene.fog.far = 410 - sonicAtmosphereContrast * 150;
  }
  if (topo.renderer) {
    topo.renderer.toneMappingExposure = clamp(
      sonicHighlightShoulder + settings.exposure * 0.045,
      0.82,
      1.0
    );
  }
  if (topo.ambientLight) {
    topo.ambientLight.color.set(toneColor);
    topo.ambientLight.intensity = 0.44 + daylightFill;
  }
  if (topo.keyLight) {
    topo.keyLight.color.set(toneColor);
    topo.keyLight.intensity = 0.9 + daylightFill * 0.58;
  }
  if (topo.tyndallLight) {
    topo.tyndallLight.visible = settings.atmosphereEnabled && beamVisibility > 0.002;
    topo.tyndallLight.color.set(toneColor);
    topo.tyndallLight.intensity = Math.min(
      perceptualTyndallIntensity * (0.72 + settings.mistReflectance * 0.32) * beamVisibility,
      SONIC_TYNDALL_TOTAL_ENERGY_CAP * 3.8
    );
  }
  const receiverBounceStrength = settings.atmosphereEnabled
    ? Math.min(
      perceptualTyndallIntensity * (0.09 + settings.mistReflectance * 0.15) * beamVisibility,
      SONIC_TYNDALL_TOTAL_ENERGY_CAP * 0.44
    )
    : 0;
  if (topo.uniforms?.uTyndallBounceColor) topo.uniforms.uTyndallBounceColor.value.set(toneColor);
  if (topo.uniforms?.uTyndallReceiverBounce) {
    topo.uniforms.uTyndallReceiverBounce.value = receiverBounceStrength;
  }
  if (topo.uniforms?.uAtmosphereDaylightFill) {
    topo.uniforms.uAtmosphereDaylightFill.value = atmosphereDaylightFill;
  }
  if (topo.uniforms?.uAtmosphereLightStrength) {
    topo.uniforms.uAtmosphereLightStrength.value = atmosphereLightStrength;
  }
  if (topo.uniforms?.uTyndallLightDirection) {
    topo.uniforms.uTyndallLightDirection.value.set(72, -48).normalize();
  }
  if (topo.tyndallGroundSheenMaterial?.uniforms) {
    const groundUniforms = topo.tyndallGroundSheenMaterial.uniforms;
    groundUniforms.uReflectionColor.value.set(toneColor);
    groundUniforms.uIntensity.value = receiverBounceStrength;
    groundUniforms.uReflectionFeather.value = clamp(0.7 + settings.tyndallSpread * 0.16, 0.7, 0.92);
    groundUniforms.uGoboOcclusion.value = clamp(0.78 - settings.fogDensity * 0.22, 0.48, 0.78);
    groundUniforms.uSheenDirection.value.set(72, -48).normalize();
  }
  if (topo.tyndallGroundSheen) topo.tyndallGroundSheen.visible = settings.atmosphereEnabled;
  if (topo.tyndallWallBounceMaterial?.uniforms) {
    const wallUniforms = topo.tyndallWallBounceMaterial.uniforms;
    wallUniforms.uReflectionColor.value.set(toneColor);
    wallUniforms.uIntensity.value = Math.min(receiverBounceStrength * 0.58, SONIC_TYNDALL_TOTAL_ENERGY_CAP * 0.24);
    wallUniforms.uReflectionFeather.value = clamp(0.76 + settings.tyndallSpread * 0.12, 0.76, 0.94);
    wallUniforms.uGoboOcclusion.value = clamp(0.82 - settings.fogDensity * 0.2, 0.54, 0.82);
    wallUniforms.uSheenDirection.value.set(72, -48).normalize();
  }
  if (topo.tyndallWallBounce) topo.tyndallWallBounce.visible = settings.atmosphereEnabled;
  topo.tyndallBeams?.forEach((beam) => {
    beam.visible = settings.atmosphereEnabled && beamVisibility > 0.002;
    const uniforms = beam.material?.uniforms;
    uniforms?.uColor?.value?.set?.(toneColor);
    uniforms?.uForwardScatterColor?.value?.set?.(forwardScatterColor);
    uniforms?.uMistScatterColor?.value?.set?.(mistScatterColor);
    if (uniforms?.uMistReflectance) uniforms.uMistReflectance.value = settings.mistReflectance;
    const spreadScale = 0.48 + settings.tyndallSpread * 0.68;
    beam.scale.x = beam.userData.baseWidth * spreadScale;
    const halo = beam.userData.halo;
    if (!halo) return;
    halo.visible = beam.visible || fluorescenceScatter > 0.002;
    const haloUniforms = halo.material?.uniforms;
    haloUniforms?.uColor?.value?.set?.(toneColor);
    haloUniforms?.uColor?.value?.lerp?.(topo.uniforms?.uOuterColumnColor?.value, fluorescenceScatter * 0.58);
    haloUniforms?.uForwardScatterColor?.value?.set?.(forwardScatterColor);
    haloUniforms?.uMistScatterColor?.value?.set?.(mistScatterColor);
    if (haloUniforms?.uMistReflectance) haloUniforms.uMistReflectance.value = settings.mistReflectance;
    halo.scale.x = halo.userData.baseWidth * spreadScale;
  });
  if (topo.background) topo.background.visible = settings.coverBackgroundEnabled;
  if (topo.backgroundMaterial?.uniforms?.uBackgroundMix) {
    topo.backgroundMaterial.uniforms.uBackgroundMix.value = settings.coverBackgroundMix;
    topo.backgroundMaterial.uniforms.uSkyAtmosphereColor?.value?.set?.(skyAtmosphereColor);
    if (topo.backgroundMaterial.uniforms.uAtmosphereStrength) {
      topo.backgroundMaterial.uniforms.uAtmosphereStrength.value = clamp(
        atmosphereLightStrength + fluorescenceScatter * 0.035,
        0,
        0.9
      );
    }
    if (topo.backgroundMaterial.uniforms.uSkyContribution) {
      topo.backgroundMaterial.uniforms.uSkyContribution.value = clamp(
        (settings.atmosphereEnabled
          ? 0.032 + settings.fogDensity * 0.052 + settings.mistEmission * 0.016
          : 0)
          + fluorescenceScatter * 0.012,
        0,
        0.12
      );
    }
  }
  updateSonicTopographyCameraFit();
  if (options.persist !== false) {
    saveSonicSettingsPreferences({ immediate: options.persistImmediately === true });
  }
  if (options.sync !== false) syncSonicSettingsControls();
  if (options.renderConfig !== false) renderDiySelectedPresetConfig();
}

function sonicCoverBackgroundColors(palette) {
  const source = palette || fallbackLyricPalette(state.currentSong);
  const fallback = [source?.primary, source?.glow, source?.highlight];
  return [0, 1, 2].map((index) => source?.coverColors?.[index] || fallback[index] || { r: 11, g: 15, b: 21 });
}

function createSonicWaterMistTexture(THREE) {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 256;
  const context = canvas.getContext('2d');
  context.clearRect(0, 0, canvas.width, canvas.height);
  context.globalCompositeOperation = 'screen';

  const octaveCanvas = document.createElement('canvas');
  octaveCanvas.width = canvas.width;
  octaveCanvas.height = canvas.height;
  const octaveContext = octaveCanvas.getContext('2d');
  const mistOctaves = [
    { count: 74, radius: 38, stretch: 2.8, alpha: 0.07, blur: 7 },
    { count: 128, radius: 19, stretch: 3.6, alpha: 0.052, blur: 3.5 },
    { count: 212, radius: 8, stretch: 4.8, alpha: 0.035, blur: 1.25 }
  ];

  mistOctaves.forEach((octave, octaveIndex) => {
    octaveContext.clearRect(0, 0, octaveCanvas.width, octaveCanvas.height);
    for (let index = 0; index < octave.count; index += 1) {
      const seedA = Math.sin((index + 1) * (37.219 + octaveIndex * 11.73)) * 43758.5453;
      const seedB = Math.sin((index + 1) * (83.117 + octaveIndex * 7.91)) * 24634.6345;
      const randomA = seedA - Math.floor(seedA);
      const randomB = seedB - Math.floor(seedB);
      const x = randomA * octaveCanvas.width;
      const y = (0.08 + randomB * 0.84) * octaveCanvas.height;
      const radius = octave.radius * (0.58 + randomB * 0.72);
      const stretch = octave.stretch * (0.74 + randomA * 0.52);
      octaveContext.save();
      octaveContext.translate(x, y);
      octaveContext.scale(stretch, 1);
      const gradient = octaveContext.createRadialGradient(0, 0, 0, 0, 0, radius);
      gradient.addColorStop(0, `rgba(255,255,255,${octave.alpha})`);
      gradient.addColorStop(0.38, `rgba(255,255,255,${octave.alpha * 0.66})`);
      gradient.addColorStop(0.76, `rgba(255,255,255,${octave.alpha * 0.2})`);
      gradient.addColorStop(1, 'rgba(255,255,255,0)');
      octaveContext.fillStyle = gradient;
      octaveContext.fillRect(-radius, -radius, radius * 2, radius * 2);
      octaveContext.restore();
    }
    context.save();
    context.filter = `blur(${octave.blur}px)`;
    context.globalAlpha = 0.72 + octaveIndex * 0.1;
    context.drawImage(octaveCanvas, 0, 0);
    context.restore();
  });

  context.save();
  context.filter = 'blur(0.8px)';
  context.lineCap = 'round';
  for (let index = 0; index < 28; index += 1) {
    const y = 18 + ((index * 29) % 216);
    const phase = (index * 61) % 137;
    context.beginPath();
    context.moveTo(-42, y);
    context.bezierCurveTo(118 + phase, y - 8, 324 - phase, y + 11, 554, y - 3);
    context.strokeStyle = `rgba(255,255,255,${0.012 + (index % 4) * 0.004})`;
    context.lineWidth = 0.6 + (index % 3) * 0.45;
    context.stroke();
  }
  context.restore();

  const texture = new THREE.CanvasTexture(canvas);
  texture.minFilter = THREE.LinearMipmapLinearFilter;
  texture.magFilter = THREE.LinearFilter;
  texture.generateMipmaps = true;
  texture.needsUpdate = true;
  return texture;
}

function createSonicBackgroundMaterial(THREE, colors) {
  const toColor = (color) => new THREE.Color(rgbHexValue(color));
  return new THREE.ShaderMaterial({
    uniforms: {
      uBackgroundColor1: { value: toColor(colors[0]) },
      uBackgroundColor2: { value: toColor(colors[1]) },
      uBackgroundColor3: { value: toColor(colors[2]) },
      uBackgroundMix: { value: DEFAULT_SONIC_SETTINGS.coverBackgroundMix },
      uBackgroundDither: { value: 0.82 / 255 },
      uSkyAtmosphereColor: { value: new THREE.Color(0xfff1d6) },
      uSkyContribution: { value: 0.045 },
      uAtmosphereStrength: { value: 0 },
      uAtmosphereBass: { value: 0 },
      uAtmosphereDetail: { value: 0 }
    },
    vertexShader: `
      varying vec3 vBackgroundDirection;
      void main() {
        vBackgroundDirection = normalize(position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform vec3 uBackgroundColor1;
      uniform vec3 uBackgroundColor2;
      uniform vec3 uBackgroundColor3;
      uniform float uBackgroundMix;
      uniform float uBackgroundDither;
      uniform vec3 uSkyAtmosphereColor;
      uniform float uSkyContribution;
      uniform float uAtmosphereStrength;
      uniform float uAtmosphereBass;
      uniform float uAtmosphereDetail;
      varying vec3 vBackgroundDirection;

      float backgroundHash(vec2 point) {
        return fract(sin(dot(point, vec2(12.9898, 78.233))) * 43758.5453123);
      }

      float backgroundNoise(vec3 point) {
        vec3 cell = floor(point);
        vec3 local = fract(point);
        local = local * local * (3.0 - 2.0 * local);
        float n000 = backgroundHash(cell.xy + cell.z * 19.19);
        float n100 = backgroundHash(cell.xy + vec2(1.0, 0.0) + cell.z * 19.19);
        float n010 = backgroundHash(cell.xy + vec2(0.0, 1.0) + cell.z * 19.19);
        float n110 = backgroundHash(cell.xy + vec2(1.0, 1.0) + cell.z * 19.19);
        float n001 = backgroundHash(cell.xy + (cell.z + 1.0) * 19.19);
        float n101 = backgroundHash(cell.xy + vec2(1.0, 0.0) + (cell.z + 1.0) * 19.19);
        float n011 = backgroundHash(cell.xy + vec2(0.0, 1.0) + (cell.z + 1.0) * 19.19);
        float n111 = backgroundHash(cell.xy + vec2(1.0, 1.0) + (cell.z + 1.0) * 19.19);
        float lower = mix(mix(n000, n100, local.x), mix(n010, n110, local.x), local.y);
        float upper = mix(mix(n001, n101, local.x), mix(n011, n111, local.x), local.y);
        return mix(lower, upper, local.z);
      }

      void main() {
        vec3 direction = normalize(vBackgroundDirection);
        float broadWarp = backgroundNoise(direction * 2.15 + vec3(2.7, 5.1, 1.3)) - 0.5;
        float fineWarp = backgroundNoise(direction * 5.4 + vec3(8.3, 1.7, 6.2)) - 0.5;
        vec3 warpedDirection = normalize(direction + vec3(
          broadWarp * 0.12,
          fineWarp * 0.07,
          (broadWarp - fineWarp) * 0.1
        ));

        float paletteWeightA = smoothstep(-0.48, 0.78, dot(warpedDirection, normalize(vec3(-0.72, 0.22, 0.66))));
        float paletteWeightB = smoothstep(-0.48, 0.78, dot(warpedDirection, normalize(vec3(0.76, 0.36, 0.54))));
        float paletteWeightC = smoothstep(-0.52, 0.74, dot(warpedDirection, normalize(vec3(-0.04, -0.86, -0.5))));
        paletteWeightA = paletteWeightA * paletteWeightA + 0.12;
        paletteWeightB = paletteWeightB * paletteWeightB + 0.12;
        paletteWeightC = paletteWeightC * paletteWeightC + 0.12;
        float paletteWeightSum = paletteWeightA + paletteWeightB + paletteWeightC;
        vec3 color = (
          uBackgroundColor1 * paletteWeightA
          + uBackgroundColor2 * paletteWeightB
          + uBackgroundColor3 * paletteWeightC
        ) / max(paletteWeightSum, 0.001);

        float luminance = dot(color, vec3(0.2126, 0.7152, 0.0722));
        color = mix(vec3(luminance), color, 0.84);
        float horizonLight = 0.84 + smoothstep(-0.82, 0.45, direction.y) * 0.16;
        float skyHeight = smoothstep(0.02, 0.92, direction.y);
        color = mix(color, uSkyAtmosphereColor, skyHeight * uSkyContribution);
        float vignette = 0.42 + (1.0 - abs(direction.y)) * 0.13;
        color *= horizonLight * vignette * (0.34 + uBackgroundMix * 0.48);

        // A palette-tinted far light and horizon veil deepen the space without
        // a bloom pass. The bass/detail uniforms are smoothed to zero when
        // playback stops, leaving a stable environmental gradient at rest.
        vec3 keyDirection = normalize(vec3(-0.66, 0.18, 0.73));
        float keyLobe = smoothstep(0.08, 0.92, dot(warpedDirection, keyDirection) * 0.5 + 0.5);
        keyLobe *= keyLobe;
        float horizonVeil = 1.0 - smoothstep(0.08, 0.72, abs(direction.y - 0.04));
        float shadowArc = smoothstep(
          0.22,
          0.82,
          backgroundNoise(warpedDirection * 3.7 + vec3(4.2, 8.1, 2.6))
        );
        color *= 1.0 - uAtmosphereStrength * uAtmosphereBass
          * (1.0 - shadowArc) * (0.018 + keyLobe * 0.034);
        vec3 farLightColor = mix(uBackgroundColor2, uSkyAtmosphereColor, 0.68);
        float farLightEnergy = uAtmosphereStrength * (
          horizonVeil * 0.024
          + keyLobe * (0.018 + uAtmosphereBass * 0.036)
          + shadowArc * uAtmosphereDetail * 0.018
        );
        vec3 farLight = farLightColor * farLightEnergy;
        float farLightPeak = max(farLight.r, max(farLight.g, farLight.b));
        farLight /= 1.0 + max(0.0, farLightPeak - 0.12) * 2.8;
        color += farLight;
        float dither = backgroundHash(gl_FragCoord.xy + direction.xy * 173.0) - 0.5;
        color += (vec3(dither)) * uBackgroundDither;
        gl_FragColor = vec4(max(color, vec3(0.0)), clamp(uBackgroundMix * 0.9, 0.0, 0.9));
      }
    `,
    side: THREE.BackSide,
    transparent: true,
    depthWrite: false,
    depthTest: false,
    toneMapped: false
  });
}

function createSonicTyndallBeamMaterial(THREE, color, phase) {
  return new THREE.ShaderMaterial({
    uniforms: {
      uColor: { value: new THREE.Color(color) },
      uForwardScatterColor: { value: new THREE.Color(0xf8fbff) },
      uMistScatterColor: { value: new THREE.Color(0xddeaf2) },
      uOpacity: { value: 0 },
      uTime: { value: 0 },
      uGoboPhase: { value: phase },
      uMistCoupling: { value: 0.2 },
      uMistReflectance: { value: DEFAULT_SONIC_SETTINGS.mistReflectance },
      uHaloStrength: { value: 0 },
      uGoboShadowDepth: { value: 0.62 },
      uEdgeFeather: { value: 0.3 },
      uAtmosphereVariation: { value: 0.5 }
    },
    vertexShader: `
      varying vec2 vBeamUv;
      void main() {
        vBeamUv = uv;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform vec3 uColor;
      uniform vec3 uForwardScatterColor;
      uniform vec3 uMistScatterColor;
      uniform float uOpacity;
      uniform float uTime;
      uniform float uGoboPhase;
      uniform float uMistCoupling;
      uniform float uMistReflectance;
      uniform float uGoboShadowDepth;
      uniform float uEdgeFeather;
      uniform float uAtmosphereVariation;
      varying vec2 vBeamUv;

      float beamHash(vec2 point) {
        return fract(sin(dot(point, vec2(127.1, 311.7))) * 43758.5453123);
      }

      float beamNoise(vec2 point) {
        vec2 cell = floor(point);
        vec2 local = fract(point);
        local = local * local * (3.0 - 2.0 * local);
        return mix(
          mix(beamHash(cell), beamHash(cell + vec2(1.0, 0.0)), local.x),
          mix(beamHash(cell + vec2(0.0, 1.0)), beamHash(cell + vec2(1.0)), local.x),
          local.y
        );
      }

      void main() {
        float beamSoftProgress = smoothstep(0.0, 0.9, vBeamUv.y);
        float taperWidth = mix(0.07, 0.86, beamSoftProgress);
        float lateral = abs(vBeamUv.x - 0.5) * 2.0;
        float edgeStart = taperWidth * mix(0.32, 0.58, uEdgeFeather);
        float edgeSoftness = 1.0 - smoothstep(edgeStart, taperWidth, lateral);
        float longitudinal = smoothstep(0.02, 0.16, vBeamUv.y)
          * (1.0 - smoothstep(0.82, 1.0, vBeamUv.y));
        float livingDrift = mix(0.72, 1.32, uAtmosphereVariation);
        vec2 drift = vec2(
          uTime * -0.018 * livingDrift + sin(uTime * 0.037 + uGoboPhase) * 0.08,
          uTime * 0.012 * livingDrift + uGoboPhase
        );
        float broadGobo = beamNoise(vBeamUv * vec2(4.8, 11.4) + drift);
        float fineGobo = beamNoise(vBeamUv * vec2(15.6, 31.0) - drift * 1.7);
        float occlusionBands = sin(vBeamUv.y * 52.0 + broadGobo * 5.0 + uGoboPhase) * 0.5 + 0.5;
        float gobo = smoothstep(0.22, 0.78, broadGobo * 0.52 + fineGobo * 0.3 + occlusionBands * 0.18);
        float goboOcclusion = mix(1.0 - uGoboShadowDepth, 1.0, gobo);
        float mistScatter = mix(0.48, 1.0, goboOcclusion) * mix(0.72, 1.08, uMistCoupling);
        vec3 scatterColor = mix(uForwardScatterColor, uMistScatterColor, 0.22 + gobo * 0.16);
        vec3 reflectedColor = mix(uColor, scatterColor, clamp(uMistReflectance * 0.22, 0.0, 0.42));
        vec3 sonicHighlightShoulder = reflectedColor
          / (1.0 + max(vec3(0.0), reflectedColor - vec3(0.72)) * 1.7);
        float atmosphereBreath = mix(0.82, 1.16, uAtmosphereVariation);
        float alpha = uOpacity * edgeSoftness * longitudinal * mistScatter * atmosphereBreath;
        gl_FragColor = vec4(sonicHighlightShoulder, alpha);
      }
    `,
    transparent: true,
    depthWrite: false,
    depthTest: true,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
    toneMapped: true
  });
}

function createSonicTyndallHaloMaterial(THREE, color, phase) {
  return new THREE.ShaderMaterial({
    uniforms: {
      uColor: { value: new THREE.Color(color) },
      uForwardScatterColor: { value: new THREE.Color(0xf8fbff) },
      uMistScatterColor: { value: new THREE.Color(0xddeaf2) },
      uOpacity: { value: 0 },
      uTime: { value: 0 },
      uGoboPhase: { value: phase },
      uMistCoupling: { value: 0.2 },
      uMistReflectance: { value: DEFAULT_SONIC_SETTINGS.mistReflectance },
      uHaloStrength: { value: 0.16 },
      uGoboShadowDepth: { value: 0.72 },
      uEdgeFeather: { value: 0.62 },
      uAtmosphereVariation: { value: 0.5 }
    },
    vertexShader: `
      varying vec2 vBeamUv;
      void main() {
        vBeamUv = uv;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform vec3 uColor;
      uniform vec3 uForwardScatterColor;
      uniform vec3 uMistScatterColor;
      uniform float uOpacity;
      uniform float uTime;
      uniform float uGoboPhase;
      uniform float uMistCoupling;
      uniform float uMistReflectance;
      uniform float uHaloStrength;
      uniform float uGoboShadowDepth;
      uniform float uEdgeFeather;
      uniform float uAtmosphereVariation;
      varying vec2 vBeamUv;

      float haloHash(vec2 point) {
        return fract(sin(dot(point, vec2(41.17, 289.31))) * 43758.5453123);
      }

      float haloNoise(vec2 point) {
        vec2 cell = floor(point);
        vec2 local = fract(point);
        local = local * local * (3.0 - 2.0 * local);
        return mix(
          mix(haloHash(cell), haloHash(cell + vec2(1.0, 0.0)), local.x),
          mix(haloHash(cell + vec2(0.0, 1.0)), haloHash(cell + vec2(1.0)), local.x),
          local.y
        );
      }

      void main() {
        float beamSoftProgress = smoothstep(0.0, 0.92, vBeamUv.y);
        float taperWidth = mix(0.12, 0.92, beamSoftProgress);
        float lateral = abs(vBeamUv.x - 0.5) * 2.0 / max(taperWidth, 0.08);
        float softHalo = exp(-lateral * lateral * mix(2.4, 4.8, uEdgeFeather));
        float longitudinal = smoothstep(0.04, 0.19, vBeamUv.y)
          * (1.0 - smoothstep(0.7, 1.0, vBeamUv.y));
        float haloDrift = mix(0.74, 1.28, uAtmosphereVariation);
        float breakup = 0.42 + haloNoise(
          vBeamUv * vec2(2.1, 10.4)
            + vec2(uGoboPhase + sin(uTime * 0.029 + uGoboPhase) * 0.06, -uTime * 0.011 * haloDrift)
        ) * 0.58;
        float occlusionBands = sin(vBeamUv.y * 34.0 + uGoboPhase * 3.0) * 0.5 + 0.5;
        float shadowedBreakup = mix(1.0 - uGoboShadowDepth, 1.0, breakup * (0.76 + occlusionBands * 0.24));
        float mistModulation = mix(0.08, shadowedBreakup, clamp(uMistCoupling, 0.0, 1.0));
        vec3 scatterColor = mix(uForwardScatterColor, uMistScatterColor, 0.32);
        vec3 haloColor = mix(uColor, scatterColor, clamp(0.18 + uMistReflectance * 0.16, 0.0, 0.42));
        vec3 sonicHighlightShoulder = haloColor
          / (1.0 + max(vec3(0.0), haloColor - vec3(0.68)) * 1.9);
        float atmosphereBreath = mix(0.84, 1.13, uAtmosphereVariation);
        float alpha = uOpacity * uHaloStrength * softHalo * longitudinal
          * mistModulation * atmosphereBreath;
        gl_FragColor = vec4(sonicHighlightShoulder, alpha);
      }
    `,
    transparent: true,
    depthWrite: false,
    depthTest: true,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
    toneMapped: true
  });
}

function createSonicGroundSheenMaterial(THREE) {
  return new THREE.ShaderMaterial({
    uniforms: {
      uReflectionColor: { value: new THREE.Color(0xf4fbff) },
      uIntensity: { value: 0 },
      uReflectionFeather: { value: 0.78 },
      uGoboOcclusion: { value: 0.66 },
      uSheenDirection: { value: new THREE.Vector2(72, -48).normalize() },
      uTime: { value: 0 }
    },
    vertexShader: `
      varying vec2 vGroundUv;
      void main() {
        vGroundUv = uv;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform vec3 uReflectionColor;
      uniform float uIntensity;
      uniform float uReflectionFeather;
      uniform float uGoboOcclusion;
      uniform vec2 uSheenDirection;
      uniform float uTime;
      varying vec2 vGroundUv;

      float groundHash(vec2 point) {
        return fract(sin(dot(point, vec2(91.17, 257.41))) * 43758.5453123);
      }

      float groundNoise(vec2 point) {
        vec2 cell = floor(point);
        vec2 local = fract(point);
        local = local * local * (3.0 - 2.0 * local);
        return mix(
          mix(groundHash(cell), groundHash(cell + vec2(1.0, 0.0)), local.x),
          mix(groundHash(cell + vec2(0.0, 1.0)), groundHash(cell + vec2(1.0)), local.x),
          local.y
        );
      }

      vec3 sonicHighlightShoulder(vec3 color) {
        float peak = max(color.r, max(color.g, color.b));
        return color / (1.0 + max(0.0, peak - 0.54) * 2.1);
      }

      void main() {
        vec2 groundPosition = vGroundUv * 2.0 - 1.0;
        vec2 lightDirection = normalize(uSheenDirection);
        vec2 lightTangent = vec2(-lightDirection.y, lightDirection.x);
        float alongLight = dot(groundPosition, lightDirection);
        float acrossLight = dot(groundPosition, lightTangent);
        float broadCanopy = groundNoise(groundPosition * 3.6 + lightDirection * uTime * 0.006);
        float fineCanopy = groundNoise(groundPosition * 10.8 - lightDirection * uTime * 0.011);
        float occlusionBands = sin(acrossLight * 23.0 + alongLight * 6.0 + broadCanopy * 4.0) * 0.5 + 0.5;
        float goboVisibility = smoothstep(0.24, 0.79,
          broadCanopy * 0.52 + fineCanopy * 0.26 + occlusionBands * 0.22);
        goboVisibility = mix(1.0 - uGoboOcclusion, 1.0, goboVisibility);

        // One continuous receiving plane: the direction changes its rough
        // sheen, while only the outer scene boundary fades. There is no radial
        // center, circle, ellipse or independent light decal in this material.
        float directionalIlluminance = mix(0.42, 1.0, smoothstep(-1.0, 0.92, alongLight));
        float roughSheen = mix(0.74, 1.0, pow(1.0 - clamp(abs(acrossLight) * 0.22, 0.0, 0.82),
          mix(1.4, 0.58, uReflectionFeather)));
        float edgeDistance = max(abs(groundPosition.x), abs(groundPosition.y));
        float boundaryFeather = 1.0 - smoothstep(0.985, 1.0, edgeDistance);
        float groundGrain = mix(0.9, 1.08, groundNoise(groundPosition * 34.0));
        float reflectedEnergy = min(
          uIntensity * directionalIlluminance * roughSheen * goboVisibility,
          0.085
        );
        vec3 groundBase = vec3(0.007, 0.011, 0.016) * groundGrain;
        vec3 reflected = sonicHighlightShoulder(uReflectionColor * reflectedEnergy);
        float alpha = boundaryFeather * (0.08 + reflectedEnergy * 0.82);
        gl_FragColor = vec4(groundBase + reflected, alpha);
      }
    `,
    transparent: true,
    depthWrite: false,
    depthTest: true,
    blending: THREE.NormalBlending,
    side: THREE.DoubleSide,
    toneMapped: true
  });
}

function createSonicWallBounceMaterial(THREE) {
  return new THREE.ShaderMaterial({
    uniforms: {
      uReflectionColor: { value: new THREE.Color(0xf4fbff) },
      uIntensity: { value: 0 },
      uReflectionFeather: { value: 0.82 },
      uGoboOcclusion: { value: 0.72 },
      uSheenDirection: { value: new THREE.Vector2(72, -48).normalize() },
      uTime: { value: 0 }
    },
    vertexShader: `
      varying vec2 vWallUv;
      void main() {
        vWallUv = uv;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform vec3 uReflectionColor;
      uniform float uIntensity;
      uniform float uReflectionFeather;
      uniform float uGoboOcclusion;
      uniform vec2 uSheenDirection;
      uniform float uTime;
      varying vec2 vWallUv;

      float wallHash(vec2 point) {
        return fract(sin(dot(point, vec2(43.71, 173.23))) * 43758.5453123);
      }

      void main() {
        vec2 wallPosition = vWallUv * 2.0 - 1.0;
        vec2 lightDirection = normalize(uSheenDirection);
        vec2 lightTangent = vec2(-lightDirection.y, lightDirection.x);
        float alongLight = dot(wallPosition, lightDirection);
        float acrossLight = dot(wallPosition, lightTangent);
        float canopy = wallHash(floor(wallPosition * 18.0 + vec2(uTime * 0.018, 0.0)));
        float occlusionBands = sin(acrossLight * 18.0 + alongLight * 7.0 + canopy * 4.2) * 0.5 + 0.5;
        float goboVisibility = mix(1.0 - uGoboOcclusion, 1.0,
          smoothstep(0.18, 0.84, canopy * 0.58 + occlusionBands * 0.42));
        float broadDirectionalSheen = mix(0.42, 1.0, smoothstep(-1.15, 0.88, alongLight));
        float softAcross = mix(0.7, 1.0,
          pow(1.0 - clamp(abs(acrossLight) * 0.28, 0.0, 0.84), mix(1.5, 0.62, uReflectionFeather)));
        float edgeFeather = (1.0 - smoothstep(0.76, 1.0, abs(wallPosition.x)))
          * (1.0 - smoothstep(0.82, 1.0, abs(wallPosition.y)));
        float bouncedEnergy = min(uIntensity * broadDirectionalSheen * softAcross * goboVisibility, 0.038);
        vec3 bouncedLight = uReflectionColor * bouncedEnergy;
        float peak = max(bouncedLight.r, max(bouncedLight.g, bouncedLight.b));
        bouncedLight /= 1.0 + max(0.0, peak - 0.32) * 2.4;
        gl_FragColor = vec4(bouncedLight, edgeFeather * bouncedEnergy * 1.35);
      }
    `,
    transparent: true,
    depthWrite: false,
    depthTest: false,
    blending: THREE.AdditiveBlending,
    side: THREE.BackSide,
    toneMapped: true
  });
}

function orientSonicTyndallPlane(THREE, plane, camera) {
  if (!plane?.userData?.start || !plane?.userData?.end || !camera) return;
  const data = plane.userData;
  data.along.copy(data.end).sub(data.start).normalize();
  data.view.copy(camera.position).sub(data.midpoint).normalize();
  data.across.crossVectors(data.along, data.view);
  if (data.across.lengthSq() < 0.0001) data.across.set(1, 0, 0);
  else data.across.normalize();
  data.normal.crossVectors(data.across, data.along).normalize();
  data.orientation.makeBasis(data.across, data.along, data.normal);
  plane.quaternion.setFromRotationMatrix(data.orientation);
}

function sonicRainHash(x, z) {
  const value = Math.sin(x * 12.9898 + z * 78.233) * 43758.5453123;
  return value - Math.floor(value);
}

function sonicRainSimplexMod289(value) {
  return value - Math.floor(value / 289) * 289;
}

function sonicRainSimplexPermute(value) {
  return sonicRainSimplexMod289(((value * 34) + 1) * value);
}

function sonicRainSimplexCorner(permutation, x, z) {
  let weight = Math.max(0.5 - x * x - z * z, 0);
  weight *= weight;
  weight *= weight;
  const gradient = 2 * (
    permutation * 0.024390243902439
      - Math.floor(permutation * 0.024390243902439)
  ) - 1;
  const height = Math.abs(gradient) - 0.5;
  const offset = Math.floor(gradient + 0.5);
  const direction = gradient - offset;
  weight *= 1.79284291400159
    - 0.85373472095314 * (direction * direction + height * height);
  return weight * (direction * x + height * z);
}

// Scalar port of the terrain vertex shader's 2D simplex noise. Keeping the
// impact-height solver on the same field prevents rain ripples from being
// buried when audio-driven columns rise, without raycasts or GPU readback.
function sonicRainSimplexNoise2D(x, z) {
  const skew = (x + z) * 0.366025403784439;
  let gridX = Math.floor(x + skew);
  let gridZ = Math.floor(z + skew);
  const unskew = (gridX + gridZ) * 0.211324865405187;
  const x0 = x - gridX + unskew;
  const z0 = z - gridZ + unskew;
  const stepX = x0 > z0 ? 1 : 0;
  const stepZ = x0 > z0 ? 0 : 1;
  const x1 = x0 + 0.211324865405187 - stepX;
  const z1 = z0 + 0.211324865405187 - stepZ;
  const x2 = x0 - 0.577350269189626;
  const z2 = z0 - 0.577350269189626;
  gridX = sonicRainSimplexMod289(gridX);
  gridZ = sonicRainSimplexMod289(gridZ);
  const firstPermutation = sonicRainSimplexPermute(gridZ);
  const secondPermutation = sonicRainSimplexPermute(gridZ + stepZ);
  const thirdPermutation = sonicRainSimplexPermute(gridZ + 1);
  const corner0 = sonicRainSimplexPermute(firstPermutation + gridX);
  const corner1 = sonicRainSimplexPermute(secondPermutation + gridX + stepX);
  const corner2 = sonicRainSimplexPermute(thirdPermutation + gridX + 1);
  return 130 * (
    sonicRainSimplexCorner(corner0, x0, z0)
      + sonicRainSimplexCorner(corner1, x1, z1)
      + sonicRainSimplexCorner(corner2, x2, z2)
  );
}

function sonicRainMoundMaskAt(x, z, settings) {
  return sonicGroundMoundMaskAt(x, z, settings);
}

function sonicRainGroundFootprintAt(x, z) {
  return x * x + z * z <= SONIC_RAIN_GROUND_RADIUS * SONIC_RAIN_GROUND_RADIUS;
}

// Matches the top faces of the instanced terrain boxes, including the small
// spacing between cells. Impacts use this mask so no ripple can appear in a
// transparent gap or beyond the radial edge of the visible Sonic ground.
function sonicRainGroundSurfaceAt(x, z) {
  if (!sonicRainGroundFootprintAt(x, z)) return false;
  const minGrid = -SONIC_TOPOGRAPHY_GRID / 2;
  const maxGrid = SONIC_TOPOGRAPHY_GRID / 2 - 1;
  const gridX = Math.round(x / SONIC_TOPOGRAPHY_SPACING);
  const gridZ = Math.round(z / SONIC_TOPOGRAPHY_SPACING);
  if (gridX < minGrid || gridX > maxGrid || gridZ < minGrid || gridZ > maxGrid) return false;
  const cellX = gridX * SONIC_TOPOGRAPHY_SPACING;
  const cellZ = gridZ * SONIC_TOPOGRAPHY_SPACING;
  const halfCell = SONIC_TOPOGRAPHY_SIZE * 0.5;
  return Math.abs(x - cellX) <= halfCell && Math.abs(z - cellZ) <= halfCell;
}

function updateSonicRainViewProjection(rain) {
  if (!rain?.camera || !rain.viewProjection) return;
  rain.camera.updateMatrixWorld();
  rain.viewProjection.multiplyMatrices(rain.camera.projectionMatrix, rain.camera.matrixWorldInverse);
}

// Manual clip-space projection avoids allocating vectors in the rain hot path.
// A small margin prevents visible pop-in while still excluding wallpaper-only
// and off-screen space where there is no rendered ground beneath the drop.
function sonicRainGroundVisibleAt(rain, x, y, z) {
  const elements = rain.viewProjection.elements;
  const clipX = elements[0] * x + elements[4] * y + elements[8] * z + elements[12];
  const clipY = elements[1] * x + elements[5] * y + elements[9] * z + elements[13];
  const clipZ = elements[2] * x + elements[6] * y + elements[10] * z + elements[14];
  const clipW = elements[3] * x + elements[7] * y + elements[11] * z + elements[15];
  if (clipW <= 0.0001) return false;
  const inverseW = 1 / clipW;
  const ndcX = clipX * inverseW;
  const ndcY = clipY * inverseW;
  const ndcZ = clipZ * inverseW;
  return ndcX >= -1.06 && ndcX <= 1.06
    && ndcY >= -1.08 && ndcY <= 1.04
    && ndcZ >= -1.02 && ndcZ <= 1.02;
}

// Rain collision uses the same deterministic grid, shared seeds, frequency
// field and wave phases as the GPU terrain, without raycasts, readPixels calls
// or frame allocations.
function sonicLowFrequencyImpactDrive(value) {
  const drive = clamp(Number(value) || 0, 0, 1);
  return drive * (1 + SONIC_LOW_FREQUENCY_IMPACT_CURVE_STRENGTH * (1 - drive));
}

function sonicCenterColumnSoftLimit(value, limit) {
  const safeValue = Math.max(0, Number(value) || 0);
  const safeLimit = Math.max(0.001, Number(limit) || 0);
  const knee = safeLimit * SONIC_CENTER_COLUMN_SOFT_KNEE_RATIO;
  if (safeValue <= knee) return safeValue;
  const kneeSpan = Math.max(0.001, safeLimit - knee);
  return knee + kneeSpan * (1 - Math.exp(-(safeValue - knee) / kneeSpan));
}

function sonicRainCollisionHeight(topo, x, z, timeSeconds) {
  const settings = topo.settings || DEFAULT_SONIC_SETTINGS;
  if (!sonicRainGroundSurfaceAt(x, z)) return 0.04;
  const gridX = Math.round(x / SONIC_TOPOGRAPHY_SPACING);
  const gridZ = Math.round(z / SONIC_TOPOGRAPHY_SPACING);
  const terrainGridHalf = SONIC_TOPOGRAPHY_GRID / 2;
  const terrainIndex = (gridX + terrainGridHalf) * SONIC_TOPOGRAPHY_GRID
    + gridZ + terrainGridHalf;
  const terrainMatrix = topo.terrain?.instanceMatrix?.array;
  const terrainMatrixOffset = terrainIndex * 16;
  const matrixCellX = terrainMatrix?.[terrainMatrixOffset + 12];
  const matrixCellZ = terrainMatrix?.[terrainMatrixOffset + 14];
  const cellX = Number.isFinite(matrixCellX)
    ? matrixCellX
    : gridX * SONIC_TOPOGRAPHY_SPACING;
  const cellZ = Number.isFinite(matrixCellZ)
    ? matrixCellZ
    : gridZ * SONIC_TOPOGRAPHY_SPACING;

  const audio = topo.frameAudio;
  const radius = Math.hypot(gridX, gridZ);
  const centerDistance = Math.hypot(cellX, cellZ);
  const terrainSeedValues = topo.terrainSeedAttribute?.array;
  const terrainSeedOffset = terrainIndex * 4;
  const randomValue = terrainSeedValues
    ? terrainSeedValues[terrainSeedOffset] / 255
    : sonicRainHash(cellX, cellZ);
  const terrainSeedY = terrainSeedValues
    ? terrainSeedValues[terrainSeedOffset + 1] / 255
    : sonicRainHash(Math.floor(cellX / 7) + 23.7, Math.floor(cellZ / 7) + 51.3);
  const terrainSeedZ = terrainSeedValues
    ? terrainSeedValues[terrainSeedOffset + 2] / 255
    : sonicRainHash(Math.floor(cellX / 7) + 7.1, Math.floor(cellZ / 7) + 19.7);
  const terrainSeedW = terrainSeedValues
    ? terrainSeedValues[terrainSeedOffset + 3] / 255
    : sonicRainHash(Math.floor(cellX / 7) + 31.9, Math.floor(cellZ / 7) + 11.3);
  const globalFalloff = smoothstep(70, 36, centerDistance);
  const baseNoise = (sonicRainSimplexNoise2D(
    cellX * 0.05 + timeSeconds * 0.1,
    cellZ * 0.05 + timeSeconds * 0.05
  ) + 1) * 0.5;
  const wave = Math.sin(cellX * 0.15 + cellZ * 0.1 - timeSeconds * 0.6) * 0.5 + 0.5;
  const idleField = (sonicRainSimplexNoise2D(
    cellX * 0.085 + timeSeconds * 0.032,
    cellZ * 0.085 - timeSeconds * 0.026
  ) + 1) * 0.5;
  const idleCluster = smoothstep(0.5, 0.96, idleField + randomValue * 0.18);
  const idlePulse = 0.54
    + Math.sin(timeSeconds * 0.72 + randomValue * 6.283 + baseNoise * 2.4) * 0.46;
  const idleBreath = topo.uniforms?.uIdleBreath?.value ?? 0.14;
  let elevation = idleBreath * globalFalloff
    * (idleCluster * idlePulse * 0.76 + wave * 0.13);
  const lowDrive = Math.max(audio.subBass * 1.35, audio.bass);
  const lowGate = smoothstep(0.055, 0.22, lowDrive);
  const audioPulse = clamp(topo.uniforms?.uAudioPulse?.value ?? topo.audioPulse ?? 0, 0, 1);
  const rhythmGate = lowGate * (0.32 + audioPulse * 0.68);

  const clusterCoreMask = radius * radius
    < SONIC_BASS_COLUMN_CLUSTER.radius * SONIC_BASS_COLUMN_CLUSTER.radius + 0.5 ? 1 : 0;
  const clusterTransition = 1 - smoothstep(
    SONIC_BASS_COLUMN_CLUSTER.radius,
    SONIC_BASS_COLUMN_CLUSTER.radius + SONIC_BASS_COLUMN_CLUSTER.feather,
    radius
  );
  const clusterBlend = Math.max(clusterCoreMask, clusterTransition);
  let bassColumnCoreMix = 0;
  let bassColumnHeightProfile = SONIC_BASS_COLUMN_CLUSTER.outerHeightScale;
  let bassColumnLift = 0;
  if (clusterBlend > 0.001) {
    const radialMix = smoothstep(
      SONIC_BASS_COLUMN_CLUSTER.radius * 0.55,
      SONIC_BASS_COLUMN_CLUSTER.radius + SONIC_BASS_COLUMN_CLUSTER.feather,
      radius
    );
    let heightProfile = SONIC_BASS_COLUMN_CLUSTER.innerHeightScale
      + (SONIC_BASS_COLUMN_CLUSTER.outerHeightScale - SONIC_BASS_COLUMN_CLUSTER.innerHeightScale) * radialMix;
    bassColumnCoreMix = 1 - smoothstep(
      SONIC_BASS_COLUMN_CLUSTER.coreRadius,
      SONIC_BASS_COLUMN_CLUSTER.coreRadius + SONIC_BASS_COLUMN_CLUSTER.coreFeather,
      radius
    );
    heightProfile += (SONIC_BASS_COLUMN_CLUSTER.coreHeightScale - heightProfile) * bassColumnCoreMix;
    const bandValue = topo.bassColumnBandAttribute?.array?.[terrainIndex];
    const bandIndex = clamp(Math.round(Number.isFinite(bandValue) ? bandValue : 0), 0,
      SONIC_LOW_FREQUENCY_BAND_COUNT - 1);
    const spectrumValue = topo.lowFrequencySpectrumData?.[bandIndex];
    const bandDrive = gridX === 0 && gridZ === 0
      ? audio.lowFrequencyAmplitude
      : Number.isFinite(spectrumValue)
        ? spectrumValue / 255
        : audio.lowFrequencyBands[bandIndex] || 0;
    const layerSeedValue = randomValue * 7.91 + terrainSeedY * 4.37
      + terrainSeedZ * 2.13 + terrainSeedW * 1.19;
    const layerSeed = layerSeedValue - Math.floor(layerSeedValue);
    const layerTier = Math.floor(layerSeed * 7) / 6;
    const patchTierValue = terrainSeedY * 3.73 + terrainSeedW * 2.11;
    const patchTier = Math.floor((patchTierValue - Math.floor(patchTierValue)) * 4) / 3;
    const dynamicScale = 1.35 + heightProfile * 0.62 + patchTier * 0.12;
    bassColumnHeightProfile = heightProfile;
    const centerColumnCoreLowFrequencyGainMask = bassColumnCoreMix * bassColumnCoreMix;
    const centerColumnCoreLowFrequencyGain = 1
      + (SONIC_CENTER_COLUMN_CORE_LOW_FREQUENCY_GAIN - 1)
        * centerColumnCoreLowFrequencyGainMask;
    const centerColumnImpactDrive = sonicLowFrequencyImpactDrive(bandDrive);
    bassColumnLift = clusterBlend * centerColumnImpactDrive * dynamicScale
      * centerColumnCoreLowFrequencyGain * settings.columnHeight;
  }
  const layerSeedValue = randomValue * 7.91 + terrainSeedY * 4.37
    + terrainSeedZ * 2.13 + terrainSeedW * 1.19;
  const layerSeed = layerSeedValue - Math.floor(layerSeedValue);
  const layerTier = Math.floor(layerSeed * 7) / 6;
  const patchTierValue = terrainSeedY * 3.73 + terrainSeedW * 2.11;
  const patchTier = Math.floor((patchTierValue - Math.floor(patchTierValue)) * 4) / 3;
  const pedestalScale = (0.05 + (5.8 - 0.05) * layerTier) * (0.82 + 0.18 * patchTier);
  const pedestalRadial = 0.65 + (1.45 - 0.65)
    * smoothstep(0.58, 4.2, bassColumnHeightProfile);
  const bassColumnPedestalLift = clusterBlend
    * pedestalRadial * pedestalScale * Math.min(settings.columnHeight, 1.35);

  const smallCellX = Math.floor(cellX / 7);
  const smallCellZ = Math.floor(cellZ / 7);
  const terrainSmallLocalValues = topo.terrainSmallLocalAttribute?.array;
  const terrainSmallLocalOffset = terrainIndex * 2;
  const smallLocalX = terrainSmallLocalValues
    ? terrainSmallLocalValues[terrainSmallLocalOffset] / 255 - 0.5
    : cellX / 7 - smallCellX - 0.5;
  const smallLocalZ = terrainSmallLocalValues
    ? terrainSmallLocalValues[terrainSmallLocalOffset + 1] / 255 - 0.5
    : cellZ / 7 - smallCellZ - 0.5;
  const smallSeed = terrainSeedY;
  const smallCenterX = (terrainSeedZ - 0.5) * 0.26;
  const smallCenterZ = (terrainSeedW - 0.5) * 0.26;
  const smallDistance = Math.hypot(smallLocalX - smallCenterX, smallLocalZ - smallCenterZ);
  const smallShape = (1 - smoothstep(0.07, 0.31, smallDistance))
    * (smallSeed >= 0.84 ? 1 : 0) * (1 - clusterBlend);
  const audioTerrainTime = Number.isFinite(topo.audioTerrainTime)
    ? topo.audioTerrainTime
    : timeSeconds;
  const smallPulse = 0.72
    + Math.sin(audioTerrainTime * (1.1 + smallSeed * 0.7) + smallSeed * 6.283) * 0.28;
  const smallBassDrive = clamp(
    Math.max(audio.lowFrequencyAmplitude, lowDrive) * lowGate,
    0,
    1
  );
  const smallBassLift = smallShape * smallBassDrive * smallPulse
    * (0.65 + smallSeed * 0.35) * 1.25 * settings.columnHeight;

  const subRegion = smoothstep(31, 0, centerDistance);
  const subLift = audio.subBass * rhythmGate * subRegion * 1.05;
  const bassNoise = sonicRainSimplexNoise2D(
    cellX * 0.1,
    cellZ * 0.1 - timeSeconds * 0.2
  );
  const bassRegion = smoothstep(44, 6, centerDistance + bassNoise * 5);
  const bassLift = audio.bass * rhythmGate * bassRegion
    * smoothstep(0, 1, randomValue + audio.density * 0.5) * 0.9;
  const lowMidNoise = sonicRainSimplexNoise2D(
    cellX * 0.05 + timeSeconds * 0.1,
    cellZ * 0.05
  );
  const lowMidLift = audio.lowMid * rhythmGate * (lowMidNoise * 0.5 + 0.5) * 0.42;
  const riverFlow = Math.sin(
    cellX * 0.2 + cellZ * 0.2
      + sonicRainSimplexNoise2D(cellX * 0.1, cellZ * 0.1) * 2
      - timeSeconds * 2
  );
  const midLift = audio.mid * rhythmGate * Math.max(0, riverFlow) * 0.42;
  const highMidRegion = smoothstep(10, 45, centerDistance);
  const highMidFraction = randomValue * 13.3 - Math.floor(randomValue * 13.3);
  const highMidLift = highMidFraction > 0.8
    ? audio.highMid * rhythmGate * highMidRegion
      * (randomValue * 7.7 - Math.floor(randomValue * 7.7)) * 0.34
    : 0;
  const kickMix = audio.smoothness * 0.5 + 0.2;
  const kickSurface = (baseNoise + (wave - baseNoise) * kickMix)
    * lowDrive * rhythmGate * 0.28;
  let terrainAudioElevation = smallBassLift + subLift + bassLift
    + lowMidLift + midLift + highMidLift + kickSurface;
  if (randomValue > 0.99) terrainAudioElevation += audio.energy * rhythmGate * 0.28;
  terrainAudioElevation = Math.min(
    terrainAudioElevation * globalFalloff,
    SONIC_AUDIO_COLUMN_MAX_LIFT * Math.min(settings.columnHeight, 1.35)
  );
  const centerColumnLiftCap = SONIC_CENTER_COLUMN_MAX_LIFT
    * Math.min(settings.columnHeight, 1.35);
  const centerColumnAudioLift = sonicCenterColumnSoftLimit(
    bassColumnLift * globalFalloff,
    centerColumnLiftCap
  );
  elevation += bassColumnPedestalLift + terrainAudioElevation + centerColumnAudioLift;

  const moundColumnProfiles = topo.groundMoundColumnProfileAttribute?.array;
  const moundColumnProfileOffset = terrainIndex * 4;
  const fallbackMoundPatchX = Math.floor((gridX + 2) / 4);
  const fallbackMoundPatchZ = Math.floor((gridZ + 2) / 4);
  const fallbackMoundPatchLevel = Math.floor(
    sonicRainHash(fallbackMoundPatchX + 83.7, fallbackMoundPatchZ - 41.9)
      * SONIC_GROUND_MOUND_COLUMN_LEVELS
  );
  const fallbackMoundMicroOffset = Math.floor(
    sonicRainHash(gridX * 1.37 - 13.1, gridZ * 1.91 + 27.3) * 3
  ) - 1;
  const fallbackMoundLevel = clamp(
    fallbackMoundPatchLevel + fallbackMoundMicroOffset,
    0,
    SONIC_GROUND_MOUND_COLUMN_LEVELS - 1
  );
  const encodedMoundLevel = moundColumnProfiles?.[moundColumnProfileOffset];
  const moundColumnLevelIndex = Number.isFinite(encodedMoundLevel)
    ? Math.round(encodedMoundLevel / 255 * (SONIC_GROUND_MOUND_COLUMN_LEVELS - 1))
    : fallbackMoundLevel;
  const moundColumnLevel = moundColumnLevelIndex / (SONIC_GROUND_MOUND_COLUMN_LEVELS - 1);
  const encodedMoundPhase = moundColumnProfiles?.[moundColumnProfileOffset + 1];
  const fallbackMoundPhase = Math.min(
    SONIC_GROUND_MOUND_COLUMN_PHASE_BUCKETS - 1,
    Math.floor(
      sonicRainHash(gridX * 0.73 + 59.2, gridZ * 1.17 - 31.4)
        * SONIC_GROUND_MOUND_COLUMN_PHASE_BUCKETS
    )
  );
  const moundColumnPhaseIndex = Number.isFinite(encodedMoundPhase)
    ? Math.round(encodedMoundPhase / 255 * (SONIC_GROUND_MOUND_COLUMN_PHASE_BUCKETS - 1))
    : fallbackMoundPhase;
  const moundColumnPhase = moundColumnPhaseIndex
    / (SONIC_GROUND_MOUND_COLUMN_PHASE_BUCKETS - 1);
  const fallbackMoundBand = Math.min(
    SONIC_LOW_FREQUENCY_BAND_COUNT - 1,
    Math.floor(
      sonicRainHash(gridX * 2.71 - 7.9, gridZ * 3.17 + 19.6)
        * SONIC_LOW_FREQUENCY_BAND_COUNT
    )
  );
  const encodedMoundBandLow = moundColumnProfiles?.[moundColumnProfileOffset + 2];
  const encodedMoundBandHigh = moundColumnProfiles?.[moundColumnProfileOffset + 3];
  const moundColumnBandIndex = Number.isFinite(encodedMoundBandLow)
    ? clamp(
        Math.round(encodedMoundBandLow) + (encodedMoundBandHigh >= 128 ? 256 : 0),
        0,
        SONIC_LOW_FREQUENCY_BAND_COUNT - 1
      )
    : fallbackMoundBand;
  const moundSpectrumValue = topo.lowFrequencySpectrumData?.[moundColumnBandIndex];
  const moundColumnBandDrive = Number.isFinite(moundSpectrumValue)
    ? moundSpectrumValue / 255
    : audio.lowFrequencyBands[moundColumnBandIndex] || 0;
  const moundColumnStaticBase = SONIC_GROUND_MOUND_COLUMN_STATIC_MIN
    + (SONIC_GROUND_MOUND_COLUMN_STATIC_MAX - SONIC_GROUND_MOUND_COLUMN_STATIC_MIN)
      * moundColumnLevel;
  const phaseJitter = randomValue * 1.45 - 0.725 + (moundColumnPhase - 0.5) * 1.7;
  const phase = gridX * 0.47 + gridZ * 0.71 + phaseJitter;
  const ring = centerDistance / SONIC_TOPOGRAPHY_SPACING;
  const ringWaveA = 0.5 + 0.5 * Math.sin(
    ring * 0.42 - audioTerrainTime * 0.64 + phaseJitter * 0.38
  );
  const ringWaveB = 0.5 + 0.5 * Math.sin(
    ring * 0.79 + audioTerrainTime * 0.37 + phase * 1.31
  );
  const crossWave = 0.5 + 0.5 * Math.sin(
    gridX * 0.31 - gridZ * 0.27 - audioTerrainTime * 0.49 + phaseJitter * 0.7
  );
  const layeredWave = ringWaveA * 0.48 + ringWaveB * 0.32 + crossWave * 0.2;
  const groundEntranceProgress = clamp(
    topo.uniforms?.uGroundEntrance?.value ?? topo.groundEntranceProgress ?? 0,
    0,
    1
  );
  const entranceCursor = groundEntranceProgress * 1.34
    - clamp(centerDistance / 78, 0, 1) * 0.24 - randomValue * 0.06;
  const entrance = smoothstep(0, 1, entranceCursor);
  const attributeMoundMask = topo.groundMoundMaskAttribute?.array?.[terrainIndex];
  const moundMask = Number.isFinite(attributeMoundMask)
    ? attributeMoundMask
    : sonicRainMoundMaskAt(cellX, cellZ, settings);
  if (settings.groundMoundsEnabled && moundMask > 0) {
    const moundLowDrive = clamp(
      audio.lowFrequencyAmplitude * 0.72 + audio.subBass * 0.18 + audio.bass * 0.1,
      0,
      1
    );
    const moundColumnAudioDrive = clamp(
      moundColumnBandDrive * 0.78 + moundLowDrive * 0.22,
      0,
      1
    );
    const moundColumnImpactDrive = sonicLowFrequencyImpactDrive(moundColumnAudioDrive);
    const moundColumnAudioLift = moundColumnImpactDrive
      * (SONIC_GROUND_MOUND_COLUMN_AUDIO_MIN
        + (SONIC_GROUND_MOUND_COLUMN_AUDIO_MAX - SONIC_GROUND_MOUND_COLUMN_AUDIO_MIN)
          * moundColumnLevel);
    elevation += moundMask * (1 - clusterBlend * 0.58) * settings.groundMoundHeight
      * (moundColumnStaticBase + moundColumnAudioLift + layeredWave * 0.05)
      * entrance;
  }

  let rippleElevation = 0;
  const terrainRipples = topo.ripples;
  if (terrainRipples) {
    for (let index = 0; index < terrainRipples.length; index += 1) {
      const ripple = terrainRipples[index];
      if (!ripple || ripple.isActive <= 0) continue;
      const whiteRipple = ripple.rippleType > 0.5;
      const speed = whiteRipple ? 20 : 15;
      const width = whiteRipple ? 1 : 3;
      const fadeDistance = whiteRipple ? 8 : 15;
      const elevationScale = whiteRipple ? 1 : 4;
      const timeSince = timeSeconds - ripple.time;
      const waveRadius = timeSince * speed;
      const distance = Math.hypot(cellX - ripple.pos.x, cellZ - ripple.pos.y);
      const delta = distance - waveRadius;
      const pulse = Math.exp(-(delta * delta) / width)
        * Math.exp(-waveRadius / fadeDistance) * ripple.strength;
      rippleElevation += pulse * elevationScale;
    }
  }
  return 1 + elevation + rippleElevation;
}

// One conservative ceiling per frame keeps the expensive exact height solver
// limited to drops that are genuinely near the tallest possible surface. It
// also follows interactive terrain ripples, whose peaks can rise well above the
// old fixed y=8 collision gate.
function sonicRainCollisionCeiling(topo, timeSeconds) {
  const settings = topo.settings || DEFAULT_SONIC_SETTINGS;
  const idleBreath = topo.uniforms?.uIdleBreath?.value ?? 0.14;
  let ceiling = 1 + idleBreath * 0.89
    + SONIC_AUDIO_COLUMN_MAX_LIFT * Math.min(settings.columnHeight, 1.35)
    // Covers the tallest fixed mask, static column tier, audio tier and phase
    // wave so rain cannot step through a user-maximized mound column cluster.
    + (settings.groundMoundsEnabled
      ? settings.groundMoundHeight * SONIC_GROUND_MOUND_COLUMN_MAX_RISE
      : 0);
  const terrainRipples = topo.ripples;
  if (terrainRipples) {
    for (let index = 0; index < terrainRipples.length; index += 1) {
      const ripple = terrainRipples[index];
      if (!ripple || ripple.isActive <= 0) continue;
      const whiteRipple = ripple.rippleType > 0.5;
      const speed = whiteRipple ? 20 : 15;
      const fadeDistance = whiteRipple ? 8 : 15;
      const elevationScale = whiteRipple ? 1 : 4;
      const waveRadius = Math.max(0, timeSeconds - ripple.time) * speed;
      ceiling += Math.exp(-waveRadius / fadeDistance)
        * ripple.strength * elevationScale;
    }
  }
  return ceiling + 0.25;
}

function resetSonicRainDrop(rain, index, initial = false) {
  const offset = index * SONIC_RAIN_DROP_STRIDE;
  const minGrid = -SONIC_TOPOGRAPHY_GRID / 2;
  const maxGrid = SONIC_TOPOGRAPHY_GRID / 2 - 1;
  const curtainLane = index % 7;
  let x = 0;
  let z = 0;
  let found = false;
  for (let attempt = 0; attempt < 14; attempt += 1) {
    const laneCenter = (-0.82 + curtainLane / 6 * 1.64) * rain.groundRadius;
    const candidateX = index % 4 === 0
      ? (Math.random() * 2 - 1) * rain.groundRadius
      : laneCenter + (Math.random() + Math.random() - 1) * rain.groundRadius * 0.18;
    const candidateZ = (Math.random() * 2 - 1) * rain.groundRadius;
    const gridX = clamp(Math.round(candidateX / SONIC_TOPOGRAPHY_SPACING), minGrid, maxGrid);
    const gridZ = clamp(Math.round(candidateZ / SONIC_TOPOGRAPHY_SPACING), minGrid, maxGrid);
    x = gridX * SONIC_TOPOGRAPHY_SPACING
      + (Math.random() * 2 - 1) * SONIC_TOPOGRAPHY_SIZE * 0.44;
    z = gridZ * SONIC_TOPOGRAPHY_SPACING
      + (Math.random() * 2 - 1) * SONIC_TOPOGRAPHY_SIZE * 0.44;
    if (sonicRainGroundSurfaceAt(x, z) && sonicRainGroundVisibleAt(rain, x, 1, z)) {
      found = true;
      break;
    }
  }
  if (!found) {
    const fallbackGrid = (index % 9) - 4;
    x = fallbackGrid * SONIC_TOPOGRAPHY_SPACING;
    z = (Math.floor(index / 9) % 9 - 4) * SONIC_TOPOGRAPHY_SPACING;
  }
  rain.dropData[offset] = x;
  rain.dropData[offset + 1] = initial ? 4 + Math.random() * 54 : 42 + Math.random() * 20;
  rain.dropData[offset + 2] = z;
  rain.dropData[offset + 3] = 0.72 + Math.random() * 0.72;
  rain.dropData[offset + 4] = 0.66 + Math.random() * 0.72;
  rain.dropData[offset + 5] = Math.random() * Math.PI * 2;
}

function spawnSonicRainRipple(rain, x, y, z, settings) {
  if (!rain.rippleData.length || settings.rainRippleIntensity <= 0) return;
  const index = rain.rippleIndex % SONIC_RAIN_QUALITY.ripples;
  const offset = index * SONIC_RAIN_RIPPLE_STRIDE;
  rain.rippleData[offset] = x;
  rain.rippleData[offset + 1] = y + 0.035;
  rain.rippleData[offset + 2] = z;
  rain.rippleData[offset + 3] = 0;
  rain.rippleData[offset + 4] = (0.68 + Math.random() * 0.34) * settings.rainRippleLife;
  rain.rippleData[offset + 5] = (0.78 + Math.random() * 0.32) * settings.rainRippleSize;
  rain.rippleData[offset + 6] = 0.78 + Math.random() * 0.22;
  rain.rippleImpacts[index * 2] = x;
  rain.rippleImpacts[index * 2 + 1] = z;
  rain.rippleRadiusScales[index] = rain.rippleData[offset + 5];
  rain.rippleImpactAttribute.needsUpdate = true;
  rain.rippleRadiusAttribute.needsUpdate = true;
  rain.rippleIndex = (index + 1) % SONIC_RAIN_QUALITY.ripples;
}

function spawnSonicRainSplash(rain, x, y, z, settings) {
  if (!rain.splashData.length || settings.rainRippleIntensity <= 0 || reducedMotion) return;
  const amount = SONIC_RAIN_QUALITY.splashPerImpact;
  for (let splashIndex = 0; splashIndex < amount; splashIndex += 1) {
    const index = rain.splashIndex % SONIC_RAIN_QUALITY.splashes;
    const offset = index * SONIC_RAIN_SPLASH_STRIDE;
    const angle = Math.random() * Math.PI * 2;
    const horizontalSpeed = 0.45 + Math.random() * 1.15;
    rain.splashData[offset] = x;
    rain.splashData[offset + 1] = y + 0.08;
    rain.splashData[offset + 2] = z;
    rain.splashData[offset + 3] = Math.cos(angle) * horizontalSpeed;
    rain.splashData[offset + 4] = 1.15 + Math.random() * 1.75;
    rain.splashData[offset + 5] = Math.sin(angle) * horizontalSpeed;
    rain.splashData[offset + 6] = 0;
    rain.splashData[offset + 7] = (0.24 + Math.random() * 0.2) * settings.rainRippleLife;
    rain.splashData[offset + 8] = 0.07 + Math.random() * 0.09;
    rain.splashIndex = (index + 1) % SONIC_RAIN_QUALITY.splashes;
  }
}

function createSonicRainStreakMaterial(THREE) {
  const material = new THREE.ShaderMaterial({
    uniforms: {
      uOpacity: { value: 0.26 },
      uGroundRadius: { value: SONIC_RAIN_GROUND_RADIUS },
      uGroundY: { value: 1 },
      uGroundSpacing: { value: SONIC_TOPOGRAPHY_SPACING },
      uGroundHalfCell: { value: SONIC_TOPOGRAPHY_SIZE * 0.5 }
    },
    vertexShader: `
      varying vec3 vRainColor;
      varying float vRainLength;
      varying vec3 vRainWorldPosition;
      void main() {
        vRainColor = instanceColor;
        vRainLength = position.y + 0.5;
        vec4 worldPosition = modelMatrix * instanceMatrix * vec4(position, 1.0);
        vRainWorldPosition = worldPosition.xyz;
        gl_Position = projectionMatrix * viewMatrix * worldPosition;
      }
    `,
    fragmentShader: `
      uniform float uOpacity;
      uniform float uGroundRadius;
      uniform float uGroundY;
      uniform float uGroundSpacing;
      uniform float uGroundHalfCell;
      varying vec3 vRainColor;
      varying float vRainLength;
      varying vec3 vRainWorldPosition;
      void main() {
        // Each instance is spawned above a real terrain top. Mask by that
        // physical x/z landing column instead of re-projecting every fragment
        // through the camera: camera-ray projection discarded most of the
        // visible curtain whenever a drop was above the camera or near the
        // horizon even though it still belonged to rendered ground.
        vec3 groundPoint = vec3(vRainWorldPosition.x, uGroundY, vRainWorldPosition.z);
        float groundMask = 1.0 - smoothstep(
          uGroundRadius - 2.0,
          uGroundRadius,
          length(groundPoint.xz)
        );
        if (groundMask <= 0.001) discard;
        // Project each streak pixel onto the same spaced grid as the terrain.
        // The radial mask removes the outer void; this cell mask also removes
        // every transparent seam between the individual column top faces.
        vec2 nearestGroundCell = floor(
          groundPoint.xz / uGroundSpacing + vec2(0.5)
        ) * uGroundSpacing;
        vec2 groundCellDelta = abs(groundPoint.xz - nearestGroundCell);
        float groundCellEdge = max(groundCellDelta.x, groundCellDelta.y);
        float groundCellMask = 1.0 - smoothstep(
          uGroundHalfCell - 0.018,
          uGroundHalfCell,
          groundCellEdge
        );
        if (groundCellMask <= 0.001) discard;
        float body = smoothstep(0.0, 0.2, vRainLength)
          * (1.0 - smoothstep(0.72, 1.0, vRainLength));
        float core = 0.52 + body * 0.48;
        gl_FragColor = vec4(
          vRainColor * (0.72 + body * 0.28),
          uOpacity * core * groundMask * groundCellMask
        );
        #include <tonemapping_fragment>
        #include <encodings_fragment>
      }
    `,
    transparent: true,
    depthWrite: false,
    depthTest: true,
    blending: THREE.NormalBlending,
    toneMapped: true
  });
  return material;
}

function createSonicRainMaterial(THREE, color) {
  const material = new THREE.ShaderMaterial({
    uniforms: {
      uColor: { value: new THREE.Color(color) },
      uIntensity: { value: DEFAULT_SONIC_SETTINGS.rainRippleIntensity }
    },
    vertexShader: `
      attribute float aRainFade;
      attribute float aRainProgress;
      attribute vec2 aRainImpact;
      attribute float aRainRadiusScale;
      varying float vRainFade;
      varying float vRainProgress;
      varying vec3 vRainWorldPosition;
      varying float vRainSeed;
      varying vec2 vRainImpact;
      varying float vRainRadiusScale;
      void main() {
        vRainFade = aRainFade;
        vRainProgress = aRainProgress;
        vRainImpact = aRainImpact;
        vRainRadiusScale = aRainRadiusScale;
        vec4 instancePosition = instanceMatrix * vec4(position, 1.0);
        vec4 worldPosition = modelMatrix * instancePosition;
        vRainWorldPosition = worldPosition.xyz;
        vRainSeed = fract(sin(dot(aRainImpact, vec2(12.9898, 78.233))) * 43758.5453);
        gl_Position = projectionMatrix * viewMatrix * worldPosition;
      }
    `,
    fragmentShader: `
      uniform vec3 uColor;
      uniform float uIntensity;
      varying float vRainFade;
      varying float vRainProgress;
      varying vec3 vRainWorldPosition;
      varying float vRainSeed;
      varying vec2 vRainImpact;
      varying float vRainRadiusScale;

      float rainBand(float radius, float center, float width) {
        float antialiasWidth = max(fwidth(radius) * 1.35, 0.004);
        return 1.0 - smoothstep(width, width + antialiasWidth, abs(radius - center));
      }

      void main() {
        float expansion = 1.0 - exp(-vRainProgress * 3.2);
        float maximumRadius = 0.13 + clamp(vRainRadiusScale, 0.4, 2.0) * 0.14;
        float waveRadius = maximumRadius * (0.2 + expansion * 0.8);
        vec2 point = (vRainWorldPosition.xz - vRainImpact) / max(waveRadius, 0.001);
        float radius = length(point);
        if (radius > 1.025) discard;

        float angle = atan(point.y, point.x);
        float angularNoise = sin(angle * 7.0 + vRainSeed * 19.0) * 0.55
          + sin(angle * 13.0 - vRainSeed * 31.0) * 0.3
          + sin(angle * 23.0 + vRainSeed * 47.0) * 0.15;
        float breakup = smoothstep(
          -0.42,
          0.54,
          sin(angle * 9.0 + vRainSeed * 37.0 + vRainProgress * 2.2)
            + angularNoise * 0.48
        );
        float primary = rainBand(radius, 0.79 + angularNoise * 0.012, 0.018)
          * (0.68 + breakup * 0.32);
        float trailing = rainBand(radius, 0.57 + angularNoise * 0.018, 0.014)
          * smoothstep(0.08, 0.32, vRainProgress)
          * (0.44 + (1.0 - breakup) * 0.32);
        float capillary = rainBand(radius, 0.92 - angularNoise * 0.009, 0.009)
          * smoothstep(0.18, 0.58, vRainProgress) * breakup * 0.42;
        float trough = rainBand(radius, 0.68 + angularNoise * 0.014, 0.026)
          * smoothstep(0.05, 0.28, vRainProgress);
        float impactMeniscus = (1.0 - smoothstep(0.02, 0.18, radius))
          * (1.0 - smoothstep(0.02, 0.28, vRainProgress));

        vec3 viewDirection = normalize(cameraPosition - vRainWorldPosition);
        vec2 radialDirection = point / max(radius, 0.001);
        float radialSlope = primary - trailing * 0.62 + capillary * 0.38 - trough * 0.24;
        vec3 waveNormal = normalize(vec3(
          -radialDirection.x * radialSlope * 0.34,
          1.0,
          -radialDirection.y * radialSlope * 0.34
        ));
        vec3 keyDirection = normalize(vec3(-0.52, 0.72, 0.45));
        float viewFacing = clamp(dot(waveNormal, viewDirection), 0.0, 1.0);
        float fresnel = 0.02 + 0.98 * pow(1.0 - viewFacing, 5.0);
        float specular = pow(
          max(dot(reflect(-keyDirection, waveNormal), viewDirection), 0.0),
          24.0
        );
        float crest = primary + trailing * 0.58 + capillary + impactMeniscus * 0.7;
        float opticalDetail = clamp(fresnel * 0.46 + specular * 0.86 + breakup * 0.1, 0.0, 1.0);
        float intensity = min(uIntensity, 1.5);
        float alpha = (crest * (0.24 + opticalDetail * 0.18) + trough * 0.045)
          * vRainFade * intensity;
        vec3 troughColor = uColor * 0.11;
        vec3 crestColor = mix(uColor * 0.62, vec3(0.96, 0.99, 1.0), opticalDetail * 0.7);
        vec3 waterColor = mix(crestColor, troughColor, clamp(trough * 0.72, 0.0, 0.72));
        gl_FragColor = vec4(waterColor, min(alpha, 0.5));
        #include <tonemapping_fragment>
        #include <encodings_fragment>
      }
    `,
    transparent: true,
    depthWrite: false,
    depthTest: true,
    blending: THREE.NormalBlending,
    side: THREE.DoubleSide,
    toneMapped: true
  });
  material.extensions.derivatives = true;
  return material;
}

function createSonicRainSystem(THREE, scene, group, dummy, theme, camera) {
  const streakGeometry = new THREE.BoxGeometry(1, 1, 1);
  const streakMaterial = createSonicRainStreakMaterial(THREE);
  const streakMesh = new THREE.InstancedMesh(
    streakGeometry,
    streakMaterial,
    SONIC_RAIN_QUALITY.streaks
  );
  streakMesh.name = 'SonicRainStreakBatch';
  streakMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  streakMesh.frustumCulled = false;
  streakMesh.renderOrder = 12;
  group.add(streakMesh);

  const rippleGeometry = new THREE.PlaneGeometry(1, 1, 1, 1);
  const rippleFades = new Float32Array(SONIC_RAIN_QUALITY.ripples);
  const rippleProgresses = new Float32Array(SONIC_RAIN_QUALITY.ripples);
  const rippleImpacts = new Float32Array(SONIC_RAIN_QUALITY.ripples * 2);
  const rippleRadiusScales = new Float32Array(SONIC_RAIN_QUALITY.ripples);
  const rippleFadeAttribute = new THREE.InstancedBufferAttribute(rippleFades, 1);
  const rippleProgressAttribute = new THREE.InstancedBufferAttribute(rippleProgresses, 1);
  const rippleImpactAttribute = new THREE.InstancedBufferAttribute(rippleImpacts, 2);
  const rippleRadiusAttribute = new THREE.InstancedBufferAttribute(rippleRadiusScales, 1);
  rippleFadeAttribute.setUsage(THREE.DynamicDrawUsage);
  rippleProgressAttribute.setUsage(THREE.DynamicDrawUsage);
  rippleImpactAttribute.setUsage(THREE.DynamicDrawUsage);
  rippleRadiusAttribute.setUsage(THREE.DynamicDrawUsage);
  rippleGeometry.setAttribute('aRainFade', rippleFadeAttribute);
  rippleGeometry.setAttribute('aRainProgress', rippleProgressAttribute);
  rippleGeometry.setAttribute('aRainImpact', rippleImpactAttribute);
  rippleGeometry.setAttribute('aRainRadiusScale', rippleRadiusAttribute);
  const rippleMaterial = createSonicRainMaterial(THREE, 0xbfeaff);
  const rippleMesh = new THREE.InstancedMesh(
    rippleGeometry,
    rippleMaterial,
    SONIC_RAIN_QUALITY.ripples
  );
  rippleMesh.name = 'SonicRainRippleBatch';
  rippleMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  rippleMesh.frustumCulled = false;
  rippleMesh.renderOrder = 14;
  group.add(rippleMesh);

  const splashGeometry = new THREE.TetrahedronGeometry(0.1, 0);
  const splashMaterial = new THREE.MeshBasicMaterial({
    color: 0xd9f5ff,
    transparent: true,
    opacity: 0.56,
    depthWrite: false,
    depthTest: true,
    blending: THREE.AdditiveBlending,
    toneMapped: false
  });
  const splashMesh = new THREE.InstancedMesh(
    splashGeometry,
    splashMaterial,
    SONIC_RAIN_QUALITY.splashes
  );
  splashMesh.name = 'SonicRainSplashBatch';
  splashMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  splashMesh.frustumCulled = false;
  splashMesh.renderOrder = 15;
  group.add(splashMesh);

  const rainColor = new THREE.Color();
  const coolWhiteColor = new THREE.Color(0xd8f4ff);
  const colorTarget = new THREE.Color(0xc8efff);
  const rain = {
    quality: SONIC_RAIN_QUALITY,
    groundRadius: SONIC_RAIN_GROUND_RADIUS,
    enabled: false,
    activeDropCount: 0,
    impactSequence: 0,
    rippleIndex: 0,
    splashIndex: 0,
    dropData: new Float32Array(SONIC_RAIN_QUALITY.streaks * SONIC_RAIN_DROP_STRIDE),
    rippleData: new Float32Array(SONIC_RAIN_QUALITY.ripples * SONIC_RAIN_RIPPLE_STRIDE),
    splashData: new Float32Array(SONIC_RAIN_QUALITY.splashes * SONIC_RAIN_SPLASH_STRIDE),
    rippleFades,
    rippleProgresses,
    rippleImpacts,
    rippleRadiusScales,
    rippleFadeAttribute,
    rippleProgressAttribute,
    rippleImpactAttribute,
    rippleRadiusAttribute,
    streakMesh,
    streakMaterial,
    rippleMesh,
    rippleMaterial,
    splashMesh,
    splashMaterial,
    coolWhiteColor,
    colorTarget,
    camera,
    viewProjection: new THREE.Matrix4(),
    dummy
  };
  updateSonicRainViewProjection(rain);
  for (let index = 0; index < SONIC_RAIN_QUALITY.streaks; index += 1) {
    resetSonicRainDrop(rain, index, true);
    const offset = index * SONIC_RAIN_DROP_STRIDE;
    const brightness = 0.68 + sonicRainHash(index, index * 0.37) * 0.32;
    rainColor.setRGB(brightness * 0.72, brightness * 0.9, brightness);
    streakMesh.setColorAt(index, rainColor);
    dummy.position.set(rain.dropData[offset], rain.dropData[offset + 1], rain.dropData[offset + 2]);
    dummy.rotation.set(0, 0, 0);
    dummy.scale.set(0.04, 1.6, 0.04);
    dummy.updateMatrix();
    streakMesh.setMatrixAt(index, dummy.matrix);
  }
  for (let index = 0; index < SONIC_RAIN_QUALITY.ripples; index += 1) {
    dummy.position.set(0, -1000, 0);
    dummy.rotation.set(-Math.PI / 2, 0, 0);
    dummy.scale.set(0, 0, 0);
    dummy.updateMatrix();
    rippleMesh.setMatrixAt(index, dummy.matrix);
  }
  for (let index = 0; index < SONIC_RAIN_QUALITY.splashes; index += 1) {
    dummy.position.set(0, -1000, 0);
    dummy.rotation.set(0, 0, 0);
    dummy.scale.set(0, 0, 0);
    dummy.updateMatrix();
    splashMesh.setMatrixAt(index, dummy.matrix);
  }
  streakMesh.instanceMatrix.needsUpdate = true;
  if (streakMesh.instanceColor) streakMesh.instanceColor.needsUpdate = true;
  rippleMesh.instanceMatrix.needsUpdate = true;
  splashMesh.instanceMatrix.needsUpdate = true;
  rippleFadeAttribute.needsUpdate = true;
  rippleProgressAttribute.needsUpdate = true;
  rippleImpactAttribute.needsUpdate = true;
  rippleRadiusAttribute.needsUpdate = true;
  if (theme?.uCoolEdge) {
    colorTarget.copy(theme.uCoolEdge).lerp(coolWhiteColor, 0.72);
    rippleMaterial.uniforms.uColor.value.copy(colorTarget);
  }
  return rain;
}

function applySonicRainSettings(topo, settings) {
  const rain = topo.rain;
  if (!rain) return;
  const enabled = settings.rainEnabled === true;
  if (rain.enabled && !enabled) {
    rain.rippleData.fill(0);
    rain.splashData.fill(0);
    rain.rippleFades.fill(0);
    rain.rippleProgresses.fill(0);
    rain.rippleImpacts.fill(0);
    rain.rippleRadiusScales.fill(0);
    const dummy = rain.dummy;
    for (let index = 0; index < SONIC_RAIN_QUALITY.ripples; index += 1) {
      dummy.position.set(0, -1000, 0);
      dummy.rotation.set(-Math.PI / 2, 0, 0);
      dummy.scale.set(0, 0, 0);
      dummy.updateMatrix();
      rain.rippleMesh.setMatrixAt(index, dummy.matrix);
    }
    for (let index = 0; index < SONIC_RAIN_QUALITY.splashes; index += 1) {
      dummy.position.set(0, -1000, 0);
      dummy.rotation.set(0, 0, 0);
      dummy.scale.set(0, 0, 0);
      dummy.updateMatrix();
      rain.splashMesh.setMatrixAt(index, dummy.matrix);
    }
    rain.rippleMesh.instanceMatrix.needsUpdate = true;
    rain.splashMesh.instanceMatrix.needsUpdate = true;
    rain.rippleFadeAttribute.needsUpdate = true;
    rain.rippleProgressAttribute.needsUpdate = true;
    rain.rippleImpactAttribute.needsUpdate = true;
    rain.rippleRadiusAttribute.needsUpdate = true;
  }
  rain.enabled = enabled;
  rain.activeDropCount = Math.min(
    SONIC_RAIN_QUALITY.streaks,
    Math.max(0, Math.round(SONIC_RAIN_QUALITY.streaks * settings.rainIntensity / 1.5))
  );
  rain.streakMesh.count = rain.activeDropCount;
  rain.streakMesh.visible = enabled && rain.activeDropCount > 0;
  rain.rippleMesh.visible = enabled && settings.rainRippleIntensity > 0;
  rain.splashMesh.visible = enabled && settings.rainRippleIntensity > 0 && !reducedMotion;
  const streakOpacity = clamp(0.1 + settings.rainIntensity * 0.22, 0.08, 0.42);
  rain.streakMaterial.opacity = streakOpacity;
  rain.streakMaterial.uniforms.uOpacity.value = streakOpacity;
  rain.rippleMaterial.uniforms.uIntensity.value = settings.rainRippleIntensity;
  rain.splashMaterial.opacity = clamp(settings.rainRippleIntensity * 0.52, 0.04, 0.66);
  if (topo.uniforms?.uRainEnabled) topo.uniforms.uRainEnabled.value = enabled ? 1 : 0;
  if (topo.uniforms?.uRainIntensity) topo.uniforms.uRainIntensity.value = settings.rainIntensity;
  if (topo.uniforms?.uRainWetReflectance) {
    topo.uniforms.uRainWetReflectance.value = settings.rainWetReflectance;
  }
  if (topo.uniforms?.uRainWetGlow) topo.uniforms.uRainWetGlow.value = settings.rainWetGlow;
}

function updateSonicRain(topo, dt, timeSeconds, audioLight) {
  const rain = topo.rain;
  const settings = topo.settings || DEFAULT_SONIC_SETTINGS;
  if (!rain || !rain.enabled || document.hidden) return;
  updateSonicRainViewProjection(rain);
  const dummy = rain.dummy;
  const drops = rain.dropData;
  const wind = settings.rainWind;
  const windVelocity = wind * 8.5;
  const streakLength = 2.1 * settings.rainLength;
  const streakWidth = 0.18 * settings.rainWidth;
  const activeCount = rain.activeDropCount;
  const collisionCeiling = sonicRainCollisionCeiling(topo, timeSeconds);
  const columnHeightScale = Math.min(settings.columnHeight, 1.35);
  const centerCollisionCeiling = collisionCeiling
    + (SONIC_CENTER_COLUMN_MAX_LIFT + SONIC_CENTER_COLUMN_PEDESTAL_MAX_LIFT)
      * columnHeightScale;
  const centerCollisionRadius = SONIC_BASS_COLUMN_CLUSTER.radius
    + SONIC_BASS_COLUMN_CLUSTER.feather;
  const centerCollisionRadiusSquared = centerCollisionRadius * centerCollisionRadius + 0.5;
  const streakOpacity = clamp(
    (0.1 + settings.rainIntensity * 0.22) * (0.96 + clamp(audioLight, 0, 1) * 0.08),
    0.08,
    0.44
  );
  rain.streakMaterial.opacity = streakOpacity;
  rain.streakMaterial.uniforms.uOpacity.value = streakOpacity;
  for (let index = 0; index < activeCount; index += 1) {
    const offset = index * SONIC_RAIN_DROP_STRIDE;
    const fallSpeed = 31 * settings.rainSpeed * drops[offset + 3];
    drops[offset] += windVelocity * dt;
    drops[offset + 1] -= fallSpeed * dt;
    drops[offset + 2] += windVelocity * 0.22 * dt;
    const overRenderedGround = sonicRainGroundFootprintAt(drops[offset], drops[offset + 2]);
    if (!overRenderedGround) resetSonicRainDrop(rain, index, false);

    let hasGroundSurface = false;
    let collisionHeight = 0.04;
    let dropCollisionCeiling = collisionCeiling;
    if (drops[offset + 1] > collisionCeiling && drops[offset + 1] <= centerCollisionCeiling) {
      const collisionGridX = Math.round(drops[offset] / SONIC_TOPOGRAPHY_SPACING);
      const collisionGridZ = Math.round(drops[offset + 2] / SONIC_TOPOGRAPHY_SPACING);
      const overCenterColumns = collisionGridX * collisionGridX + collisionGridZ * collisionGridZ
        <= centerCollisionRadiusSquared;
      if (overCenterColumns) dropCollisionCeiling = centerCollisionCeiling;
    }
    if (overRenderedGround && drops[offset + 1] <= dropCollisionCeiling) {
      hasGroundSurface = sonicRainGroundSurfaceAt(drops[offset], drops[offset + 2]);
    }
    if (hasGroundSurface) {
      collisionHeight = sonicRainCollisionHeight(
        topo,
        drops[offset],
        drops[offset + 2],
        timeSeconds
      );
    }
    if (drops[offset + 1] <= collisionHeight) {
      if (hasGroundSurface) {
        rain.impactSequence += 1;
        const rippleStride = settings.rainIntensity < 0.42 ? 3 : settings.rainIntensity < 0.9 ? 2 : 1;
        if (rain.impactSequence % rippleStride === 0) {
          spawnSonicRainRipple(rain, drops[offset], collisionHeight, drops[offset + 2], settings);
          spawnSonicRainSplash(rain, drops[offset], collisionHeight, drops[offset + 2], settings);
        }
      }
      resetSonicRainDrop(rain, index, false);
    }
    const length = streakLength * drops[offset + 4];
    dummy.position.set(drops[offset], drops[offset + 1] + length * 0.5, drops[offset + 2]);
    dummy.rotation.set(wind * 0.08, 0, -wind * 0.34);
    dummy.scale.set(streakWidth, length, streakWidth * 0.72);
    dummy.updateMatrix();
    rain.streakMesh.setMatrixAt(index, dummy.matrix);
  }
  if (activeCount > 0) rain.streakMesh.instanceMatrix.needsUpdate = true;

  const ripples = rain.rippleData;
  let rippleChanged = false;
  for (let index = 0; index < SONIC_RAIN_QUALITY.ripples; index += 1) {
    const offset = index * SONIC_RAIN_RIPPLE_STRIDE;
    const life = ripples[offset + 4];
    if (life <= 0) continue;
    ripples[offset + 3] += dt;
    const progress = ripples[offset + 3] / life;
    if (progress >= 1) {
      ripples[offset + 4] = 0;
      rain.rippleFades[index] = 0;
      rain.rippleProgresses[index] = 0;
      dummy.position.set(0, -1000, 0);
      dummy.rotation.set(-Math.PI / 2, 0, 0);
      dummy.scale.set(0, 0, 0);
    } else {
      const fadeIn = Math.min(1, progress * 10);
      const fade = fadeIn * Math.pow(1 - progress, 1.35) * ripples[offset + 6];
      rain.rippleFades[index] = fade;
      rain.rippleProgresses[index] = progress;
      const surfaceY = sonicRainCollisionHeight(
        topo,
        ripples[offset],
        ripples[offset + 2],
        timeSeconds
      ) + 0.035;
      ripples[offset + 1] = surfaceY;
      const cellX = Math.round(ripples[offset] / SONIC_TOPOGRAPHY_SPACING)
        * SONIC_TOPOGRAPHY_SPACING;
      const cellZ = Math.round(ripples[offset + 2] / SONIC_TOPOGRAPHY_SPACING)
        * SONIC_TOPOGRAPHY_SPACING;
      dummy.position.set(cellX, surfaceY, cellZ);
      dummy.rotation.set(-Math.PI / 2, 0, 0);
      dummy.scale.set(SONIC_TOPOGRAPHY_SIZE, SONIC_TOPOGRAPHY_SIZE, SONIC_TOPOGRAPHY_SIZE);
    }
    dummy.updateMatrix();
    rain.rippleMesh.setMatrixAt(index, dummy.matrix);
    rippleChanged = true;
  }
  if (rippleChanged) {
    rain.rippleMesh.instanceMatrix.needsUpdate = true;
    rain.rippleFadeAttribute.needsUpdate = true;
    rain.rippleProgressAttribute.needsUpdate = true;
  }

  const splashes = rain.splashData;
  let splashChanged = false;
  for (let index = 0; index < SONIC_RAIN_QUALITY.splashes; index += 1) {
    const offset = index * SONIC_RAIN_SPLASH_STRIDE;
    const life = splashes[offset + 7];
    if (life <= 0) continue;
    splashes[offset + 6] += dt;
    const progress = splashes[offset + 6] / life;
    if (progress >= 1) {
      splashes[offset + 7] = 0;
      dummy.position.set(0, -1000, 0);
      dummy.scale.set(0, 0, 0);
    } else {
      splashes[offset] += splashes[offset + 3] * dt;
      splashes[offset + 1] += splashes[offset + 4] * dt;
      splashes[offset + 2] += splashes[offset + 5] * dt;
      splashes[offset + 4] -= 8.8 * dt;
      const scale = splashes[offset + 8] * (1 - progress);
      dummy.position.set(splashes[offset], splashes[offset + 1], splashes[offset + 2]);
      dummy.rotation.set(0, progress * 4.2, 0);
      dummy.scale.set(scale, scale * 1.8, scale);
    }
    dummy.updateMatrix();
    rain.splashMesh.setMatrixAt(index, dummy.matrix);
    splashChanged = true;
  }
  if (splashChanged) rain.splashMesh.instanceMatrix.needsUpdate = true;

  if (topo.uniforms?.uRainAudioLight) {
    topo.uniforms.uRainAudioLight.value = clamp(audioLight, 0, 1);
  }
  const theme = topo.theme;
  if (theme?.uCoolEdge) {
    const colorResponse = clamp(dt * 2.2, 0, 1);
    rain.colorTarget.copy(theme.uCoolEdge).lerp(rain.coolWhiteColor, 0.72);
    rain.rippleMaterial.uniforms.uColor.value.lerp(rain.colorTarget, colorResponse);
  }
}

function buildSonicTopography() {
  if (!els.sonicTopographyCore || state.sonicTopography.built) return;
  if (!heavyWebGLRenderingAllowed()) return;
  if (!window.THREE) {
    state.sonicTopography.built = true;
    return;
  }
  const THREE = window.THREE;
  const topo = state.sonicTopography;
  const count = SONIC_TOPOGRAPHY_GRID * SONIC_TOPOGRAPHY_GRID;
  const offset = (SONIC_TOPOGRAPHY_GRID * SONIC_TOPOGRAPHY_SPACING) / 2;
  const theme = topo.theme || createSonicTopographyTheme(topo.palette || fallbackLyricPalette(state.currentSong));

  const renderer = createDirectX11Renderer(THREE, { antialias: SONIC_HARDWARE_ANTIALIAS });
  renderer.setClearColor(0x000000, 0);
  renderer.setPixelRatio(renderPixelRatio('webgl'));
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  const sonicHighlightShoulder = 0.9;
  renderer.toneMappingExposure = sonicHighlightShoulder;
  const renderQuality = createPresetRenderQuality(renderer, 0.2);
  renderer.domElement.className = 'sonic-topography-canvas';
  els.sonicTopographyCore.textContent = '';
  els.sonicTopographyCore.appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  scene.fog = new THREE.Fog(theme.uBaseColor1.clone(), 100, 320);
  const backgroundColors = sonicCoverBackgroundColors(topo.palette || fallbackLyricPalette(state.currentSong));
  const backgroundMaterial = createSonicBackgroundMaterial(THREE, backgroundColors);
  const background = new THREE.Mesh(new THREE.SphereGeometry(255, 32, 18), backgroundMaterial);
  background.renderOrder = -100;
  scene.add(background);
  const tyndallGroundSheenMaterial = createSonicGroundSheenMaterial(THREE);
  const tyndallGroundSheen = new THREE.Mesh(
    new THREE.PlaneGeometry(220, 220, 1, 1),
    tyndallGroundSheenMaterial
  );
  tyndallGroundSheen.name = 'SonicSunlitGroundReceiver';
  tyndallGroundSheen.rotation.x = -Math.PI / 2;
  tyndallGroundSheen.position.y = 0.015;
  tyndallGroundSheen.renderOrder = -5;
  tyndallGroundSheen.frustumCulled = false;
  scene.add(tyndallGroundSheen);

  const tyndallWallBounceMaterial = createSonicWallBounceMaterial(THREE);
  const tyndallWallBounce = new THREE.Mesh(
    new THREE.CylinderGeometry(147.4, 147.4, 142, 72, 1, true, Math.PI * 0.8, Math.PI * 0.9),
    tyndallWallBounceMaterial
  );
  tyndallWallBounce.name = 'SonicCurvedWallSunBounce';
  tyndallWallBounce.position.y = 12;
  tyndallWallBounce.rotation.y = Math.PI * 0.25;
  tyndallWallBounce.renderOrder = -89;
  tyndallWallBounce.frustumCulled = false;
  scene.add(tyndallWallBounce);
  const camera = new THREE.PerspectiveCamera(state.sonicTopography.settings.fov, 1, 0.1, 500);
  camera.position.set(SONIC_TOPOGRAPHY_CAMERA.x, SONIC_TOPOGRAPHY_CAMERA.y, SONIC_TOPOGRAPHY_CAMERA.z);
  camera.lookAt(0, SONIC_TOPOGRAPHY_CAMERA.targetY, 0);
  scene.add(camera);
  const wallpaperSurface = createSonicWallpaperSurface(THREE);
  camera.add(wallpaperSurface);

  const group = new THREE.Group();
  scene.add(group);

  const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
  scene.add(ambientLight);
  const keyLight = new THREE.DirectionalLight(0xffffff, 1);
  keyLight.position.set(10, 20, 10);
  scene.add(keyLight);

  const tyndallLightTarget = new THREE.Object3D();
  tyndallLightTarget.position.set(0, 0, 0);
  // A sun-like directional source illuminates the full receiving field. The
  // visible shafts are only the mist revealing this direction, never a
  // SpotLight footprint or a projected decal on the ground.
  const tyndallLight = new THREE.DirectionalLight(0xf4fbff, 0.7);
  tyndallLight.position.set(-72, 94, 48);
  tyndallLight.target = tyndallLightTarget;
  tyndallLight.castShadow = false;
  scene.add(tyndallLightTarget, tyndallLight);

  const tyndallPlaneGeometry = new THREE.PlaneGeometry(1, 1, 1, 16);
  const tyndallHalos = [];
  const tyndallBeams = Array.from({ length: SONIC_TYNDALL_BEAM_COUNT }, (_, index) => {
    const lane = index - (SONIC_TYNDALL_BEAM_COUNT - 1) * 0.5;
    const target = new THREE.Vector3(
      -1 + lane * 5.1,
      0.6 + (index % 2) * 0.7,
      -11 + Math.sin(index * 1.73) * 11
    );
    const phase = index / SONIC_TYNDALL_BEAM_COUNT * Math.PI * 2;
    const width = 1.45 + (index % 3) * 0.34;
    const length = target.distanceTo(tyndallLight.position);
    const midpoint = tyndallLight.position.clone().add(target).multiplyScalar(0.5);
    const material = createSonicTyndallBeamMaterial(THREE, 0xf4fbff, phase);
    const beam = new THREE.Mesh(tyndallPlaneGeometry, material);
    beam.position.copy(midpoint);
    beam.scale.set(width, length, 1);
    Object.assign(beam.userData, {
      start: tyndallLight.position.clone(),
      end: target,
      midpoint,
      along: new THREE.Vector3(),
      view: new THREE.Vector3(),
      across: new THREE.Vector3(),
      normal: new THREE.Vector3(),
      orientation: new THREE.Matrix4(),
      baseWidth: width,
      baseOpacity: 0.118 - (index % 4) * 0.008,
      driftRate: 0.17 + (index % 5) * 0.031,
      phase
    });
    orientSonicTyndallPlane(THREE, beam, camera);
    beam.renderOrder = 3;

    const haloMaterial = createSonicTyndallHaloMaterial(THREE, 0xf4fbff, phase + 0.37);
    const halo = new THREE.Mesh(tyndallPlaneGeometry, haloMaterial);
    halo.position.copy(midpoint);
    halo.scale.set(width * 3.1, length * 1.015, 1);
    Object.assign(halo.userData, {
      start: tyndallLight.position.clone(),
      end: target.clone(),
      midpoint: midpoint.clone(),
      along: new THREE.Vector3(),
      view: new THREE.Vector3(),
      across: new THREE.Vector3(),
      normal: new THREE.Vector3(),
      orientation: new THREE.Matrix4(),
      baseWidth: width * 3.1,
      baseOpacity: 0.058 - (index % 3) * 0.005,
      driftRate: 0.115 + (index % 4) * 0.024,
      phase
    });
    orientSonicTyndallPlane(THREE, halo, camera);
    halo.renderOrder = 2;
    beam.userData.halo = halo;
    tyndallHalos.push(halo);
    scene.add(halo, beam);
    return beam;
  });

  const bassColumnRadius = SONIC_BASS_COLUMN_CLUSTER.radius;
  const bassColumnCorePoints = [];
  for (let gridZ = -bassColumnRadius; gridZ <= bassColumnRadius; gridZ += 1) {
    const rowHalfWidth = Math.floor(Math.sqrt(bassColumnRadius ** 2 - gridZ ** 2));
    const row = [];
    for (let gridX = -rowHalfWidth; gridX <= rowHalfWidth; gridX += 1) {
      row.push({ x: gridX, z: gridZ });
    }
    if ((gridZ + bassColumnRadius) % 2 === 1) row.reverse();
    bassColumnCorePoints.push(...row);
  }
  const bassColumnPointKey = (gridX, gridZ) => `${gridX},${gridZ}`;
  const bassColumnBandByPoint = new Map();
  bassColumnBandByPoint.set(bassColumnPointKey(0, 0), 0);
  const spatiallyShuffledBassColumns = bassColumnCorePoints
    .filter((point) => point.x !== 0 || point.z !== 0)
    .map((point) => ({
      point,
      order: sonicRainHash(point.x * 1.731 + 17.3, point.z * 2.113 - 9.7)
    }))
    .sort((left, right) => (
      left.order - right.order
      || left.point.z - right.point.z
      || left.point.x - right.point.x
    ));
  spatiallyShuffledBassColumns.forEach(({ point }, nonCenterColumnIndex) => {
    const bandIndex = Math.floor(
      nonCenterColumnIndex * SONIC_LOW_FREQUENCY_BAND_COUNT / (SONIC_BASS_COLUMN_CLUSTER.count - 1)
    );
    bassColumnBandByPoint.set(bassColumnPointKey(point.x, point.z), bandIndex);
  });
  const smoothstepNumber = (start, end, value) => {
    const progress = clamp((value - start) / Math.max(0.001, end - start), 0, 1);
    return progress * progress * (3 - 2 * progress);
  };
  const fountainEmitters = new Array(SONIC_LOW_FREQUENCY_BAND_COUNT);
  bassColumnCorePoints.forEach((point) => {
    const band = bassColumnBandByPoint.get(bassColumnPointKey(point.x, point.z));
    if (!Number.isFinite(band)) return;
    const radius = Math.hypot(point.x, point.z);
    if (fountainEmitters[band] && fountainEmitters[band].radius <= radius) return;
    const radialMix = smoothstepNumber(
      SONIC_BASS_COLUMN_CLUSTER.radius * 0.55,
      SONIC_BASS_COLUMN_CLUSTER.radius + SONIC_BASS_COLUMN_CLUSTER.feather,
      radius
    );
    const radialHeight = SONIC_BASS_COLUMN_CLUSTER.innerHeightScale
      + (SONIC_BASS_COLUMN_CLUSTER.outerHeightScale - SONIC_BASS_COLUMN_CLUSTER.innerHeightScale) * radialMix;
    const coreMix = 1 - smoothstepNumber(
      SONIC_BASS_COLUMN_CLUSTER.coreRadius,
      SONIC_BASS_COLUMN_CLUSTER.coreRadius + SONIC_BASS_COLUMN_CLUSTER.coreFeather,
      radius
    );
    const heightProfile = radialHeight
      + (SONIC_BASS_COLUMN_CLUSTER.coreHeightScale - radialHeight) * coreMix;
    const x = point.x * SONIC_TOPOGRAPHY_SPACING;
    const z = point.z * SONIC_TOPOGRAPHY_SPACING;
    const randomValue = Math.sin(x * 12.9898 + z * 78.233) * 43758.5453123;
    const randomScale = randomValue - Math.floor(randomValue);
    fountainEmitters[band] = {
      x,
      z,
      radius,
      liftScale: (0.54 + randomScale * 0.42) * heightProfile
    };
  });
  const bassColumnBandValues = new Float32Array(count);
  const terrainSeedValues = new Uint8Array(count * 4);
  const terrainSmallLocalValues = new Uint8Array(count * 2);
  const groundMoundMaskValues = new Float32Array(count);
  const groundMoundColumnProfileValues = new Uint8Array(count * 4);
  fillSonicGroundMoundMask(groundMoundMaskValues, topo.settings);
  const geometry = new THREE.BoxGeometry(SONIC_TOPOGRAPHY_SIZE, 1, SONIC_TOPOGRAPHY_SIZE);
  const bassColumnBandAttribute = new THREE.InstancedBufferAttribute(bassColumnBandValues, 1);
  bassColumnBandAttribute.setUsage(THREE.StaticDrawUsage);
  geometry.setAttribute('aBassColumnBand', bassColumnBandAttribute);
  const terrainSeedAttribute = new THREE.InstancedBufferAttribute(terrainSeedValues, 4, true);
  terrainSeedAttribute.setUsage(THREE.StaticDrawUsage);
  geometry.setAttribute('aTerrainSeed', terrainSeedAttribute);
  const terrainSmallLocalAttribute = new THREE.InstancedBufferAttribute(
    terrainSmallLocalValues,
    2,
    true
  );
  terrainSmallLocalAttribute.setUsage(THREE.StaticDrawUsage);
  geometry.setAttribute('aTerrainSmallLocal', terrainSmallLocalAttribute);
  const groundMoundMaskAttribute = new THREE.InstancedBufferAttribute(groundMoundMaskValues, 1);
  groundMoundMaskAttribute.setUsage(THREE.DynamicDrawUsage);
  geometry.setAttribute('aGroundMoundMask', groundMoundMaskAttribute);
  const groundMoundColumnProfileAttribute = new THREE.InstancedBufferAttribute(
    groundMoundColumnProfileValues,
    4,
    true
  );
  groundMoundColumnProfileAttribute.setUsage(THREE.StaticDrawUsage);
  geometry.setAttribute('aGroundMoundColumnProfile', groundMoundColumnProfileAttribute);
  const material = createSonicTopographyMaterial(THREE, theme);
  const terrain = new THREE.InstancedMesh(geometry, material, count);
  terrain.instanceMatrix.setUsage(THREE.StaticDrawUsage);
  group.add(terrain);
  const tyndallColumnReceivers = [material];

  const meteorMesh = new THREE.InstancedMesh(
    new THREE.BoxGeometry(0.4, 1.2, 0.4),
    new THREE.MeshBasicMaterial({ color: 0xffffff, toneMapped: false }),
    SONIC_TOPOGRAPHY_METEORS
  );
  meteorMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  meteorMesh.frustumCulled = false;
  group.add(meteorMesh);

  const particleMesh = new THREE.InstancedMesh(
    new THREE.BoxGeometry(0.58, 0.58, 0.58),
    new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.6, toneMapped: false }),
    SONIC_TOPOGRAPHY_PARTICLES
  );
  particleMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  particleMesh.frustumCulled = false;
  group.add(particleMesh);

  const starfieldPositions = new Float32Array(SONIC_STARFIELD_PARTICLES * 3);
  const starfieldColors = new Float32Array(SONIC_STARFIELD_PARTICLES * 3);
  const starfieldDrift = new Float32Array(SONIC_STARFIELD_PARTICLES * 3);
  const starfieldPhase = new Float32Array(SONIC_STARFIELD_PARTICLES);
  const starfieldRadius = Math.max(54, Math.min(110, SONIC_TOPOGRAPHY_HALF * 1.05));
  let starfieldIndex = 0;
  const starfieldLayers = SONIC_STARFIELD_LAYERS.map((layer) => {
    const minRadius = starfieldRadius * layer.minRadiusScale;
    const maxRadius = starfieldRadius * layer.maxRadiusScale;
    for (let layerIndex = 0; layerIndex < layer.count; layerIndex += 1) {
      const angle = Math.random() * Math.PI * 2;
      const radius = minRadius + Math.random() * (maxRadius - minRadius);
      const offset = starfieldIndex * 3;
      const brightness = layer.brightness * (0.82 + Math.random() * 0.18);
      starfieldPositions[offset] = Math.cos(angle) * radius;
      starfieldPositions[offset + 1] = 3 + Math.random() * starfieldRadius * (0.52 + layer.brightness * 0.32);
      starfieldPositions[offset + 2] = Math.sin(angle) * radius;
      starfieldColors[offset] = brightness;
      starfieldColors[offset + 1] = brightness;
      starfieldColors[offset + 2] = brightness;
      starfieldDrift[offset] = layer.drift * (0.45 + Math.random() * 0.55);
      starfieldDrift[offset + 1] = layer.drift * (0.24 + Math.random() * 0.38);
      starfieldDrift[offset + 2] = layer.drift * (0.45 + Math.random() * 0.55);
      starfieldPhase[starfieldIndex] = Math.random() * Math.PI * 2;
      starfieldIndex += 1;
    }
    return Object.freeze({
      name: layer.name,
      count: layer.count,
      minRadius,
      maxRadius,
      brightness: layer.brightness,
      drift: layer.drift
    });
  });
  const starfieldGeometry = new THREE.BufferGeometry();
  const starfieldPositionAttribute = new THREE.BufferAttribute(starfieldPositions, 3);
  const starfieldColorAttribute = new THREE.BufferAttribute(starfieldColors, 3);
  const starfieldDriftAttribute = new THREE.BufferAttribute(starfieldDrift, 3);
  const starfieldPhaseAttribute = new THREE.BufferAttribute(starfieldPhase, 1);
  starfieldPositionAttribute.setUsage(THREE.StaticDrawUsage);
  starfieldColorAttribute.setUsage(THREE.StaticDrawUsage);
  starfieldDriftAttribute.setUsage(THREE.StaticDrawUsage);
  starfieldPhaseAttribute.setUsage(THREE.StaticDrawUsage);
  starfieldGeometry.setAttribute('position', starfieldPositionAttribute);
  starfieldGeometry.setAttribute('color', starfieldColorAttribute);
  starfieldGeometry.setAttribute('aStarDrift', starfieldDriftAttribute);
  starfieldGeometry.setAttribute('aStarPhase', starfieldPhaseAttribute);
  starfieldGeometry.computeBoundingSphere();
  const starfieldTexture = new THREE.CanvasTexture(createPlaybackParticleSprite(48, 0.08));
  const starfieldDriftUniforms = {
    uStarfieldTime: { value: 0 },
    uStarfieldAudio: { value: 0 }
  };
  const starfieldMaterial = new THREE.PointsMaterial({
    color: DEFAULT_SONIC_SETTINGS.starfieldColor,
    size: 0.22,
    sizeAttenuation: true,
    vertexColors: true,
    map: starfieldTexture,
    transparent: true,
    opacity: 0.82,
    alphaTest: 0.01,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    toneMapped: false
  });
  starfieldMaterial.userData.driftUniforms = starfieldDriftUniforms;
  starfieldMaterial.onBeforeCompile = (shader) => {
    shader.uniforms.uStarfieldTime = starfieldDriftUniforms.uStarfieldTime;
    shader.uniforms.uStarfieldAudio = starfieldDriftUniforms.uStarfieldAudio;
    shader.vertexShader = shader.vertexShader
      .replace(
        '#include <common>',
        '#include <common>\nattribute vec3 aStarDrift;\nattribute float aStarPhase;\nuniform float uStarfieldTime;\nuniform float uStarfieldAudio;'
      )
      .replace(
        '#include <begin_vertex>',
        `#include <begin_vertex>
        transformed += vec3(
          aStarDrift.x * sin(uStarfieldTime * 0.17 + aStarPhase),
          aStarDrift.y * sin(uStarfieldTime * 0.13 + aStarPhase * 1.37),
          aStarDrift.z * cos(uStarfieldTime * 0.15 + aStarPhase * 0.83)
        );`
      )
      .replace(
        '#include <pointsize_vertex>',
        '#include <pointsize_vertex>\ngl_PointSize *= 1.0 + uStarfieldAudio * 0.72;'
      );
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', '#include <common>\nuniform float uStarfieldAudio;')
      .replace(
        '#include <map_particle_fragment>',
        '#include <map_particle_fragment>\ndiffuseColor.rgb *= 1.0 + uStarfieldAudio * 0.78;'
      );
  };
  starfieldMaterial.customProgramCacheKey = () => 'fe-monster-sonic-starfield-audio-drift-v2';
  const starfield = new THREE.Points(starfieldGeometry, starfieldMaterial);
  starfield.frustumCulled = false;
  starfield.visible = false;
  starfield.userData.layers = starfieldLayers;
  scene.add(starfield);

  const galaxyPositions = new Float32Array(SONIC_GALAXY_PARTICLES * 3);
  const galaxyColors = new Float32Array(SONIC_GALAXY_PARTICLES * 3);
  const galaxyArmCount = 5;
  for (let index = 0; index < SONIC_GALAXY_PARTICLES; index += 1) {
    const progress = index / Math.max(1, SONIC_GALAXY_PARTICLES - 1);
    const arm = index % galaxyArmCount;
    const noiseA = Math.sin((index + 1) * 12.9898) * 43758.5453;
    const noiseB = Math.sin((index + 1) * 78.233) * 24634.6345;
    const randomA = noiseA - Math.floor(noiseA);
    const randomB = noiseB - Math.floor(noiseB);
    const radius = 4 + Math.pow(progress, 0.67) * (starfieldRadius * 1.2 - 4);
    const armAngle = arm / galaxyArmCount * Math.PI * 2;
    const angle = armAngle + radius * 0.115 + (randomA - 0.5) * (0.92 - progress * 0.52);
    const thickness = (randomB - 0.5) * (2.2 + radius * 0.075);
    const positionOffset = index * 3;
    galaxyPositions[positionOffset] = Math.cos(angle) * radius + Math.cos(angle + Math.PI / 2) * thickness;
    galaxyPositions[positionOffset + 1] = 2.4 + (randomA - 0.5) * (3.5 + radius * 0.038);
    galaxyPositions[positionOffset + 2] = Math.sin(angle) * radius + Math.sin(angle + Math.PI / 2) * thickness;
    const brightness = 0.34 + (1 - progress) * 0.58 + randomB * 0.08;
    galaxyColors[positionOffset] = brightness;
    galaxyColors[positionOffset + 1] = brightness;
    galaxyColors[positionOffset + 2] = brightness;
  }
  const galaxyGeometry = new THREE.BufferGeometry();
  galaxyGeometry.setAttribute('position', new THREE.BufferAttribute(galaxyPositions, 3));
  galaxyGeometry.setAttribute('color', new THREE.BufferAttribute(galaxyColors, 3));
  galaxyGeometry.computeBoundingSphere();
  const galaxyMaterial = new THREE.PointsMaterial({
    color: DEFAULT_SONIC_SETTINGS.galaxyColor,
    size: 0.18,
    sizeAttenuation: true,
    vertexColors: true,
    map: starfieldTexture,
    transparent: true,
    opacity: 0.37,
    alphaTest: 0.008,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    toneMapped: false
  });
  const galaxy = new THREE.Points(galaxyGeometry, galaxyMaterial);
  galaxy.frustumCulled = false;
  galaxy.renderOrder = -2;
  scene.add(galaxy);

  const fogGroup = new THREE.Group();
  const waterMistTexture = createSonicWaterMistTexture(THREE);
  const fogWrap = starfieldRadius * 1.42;
  const fogLayers = Array.from({ length: SONIC_WATER_MIST_LAYER_COUNT }, (_, index) => {
    const layerProgress = index / Math.max(1, SONIC_WATER_MIST_LAYER_COUNT - 1);
    const material = new THREE.SpriteMaterial({
      map: waterMistTexture,
      color: theme.uBaseColor2.clone(),
      transparent: true,
      opacity: 0.012,
      depthWrite: false,
      depthTest: true,
      blending: THREE.NormalBlending,
      toneMapped: false
    });
    material.rotation = (index % 2 === 0 ? -1 : 1) * (0.012 + layerProgress * 0.018);
    const mistLayer = new THREE.Sprite(material);
    const phase = index / SONIC_WATER_MIST_LAYER_COUNT * Math.PI * 2;
    const baseY = 4.5 + (index % 4) * 8.2 + layerProgress * 6.5;
    const baseScaleY = 12.5 + (index % 3) * 3.8 + layerProgress * 4.2;
    mistLayer.position.set(
      fogWrap - layerProgress * fogWrap * 2,
      baseY,
      -62 + layerProgress * 112 + Math.sin(phase) * 8
    );
    mistLayer.scale.set(starfieldRadius * (0.62 + (index % 3) * 0.08), baseScaleY, 1);
    mistLayer.userData.wrap = fogWrap;
    mistLayer.userData.speedScale = 0.68 + (index % 4) * 0.13;
    mistLayer.userData.opacityScale = 0.7 + (index % 5) * 0.09;
    mistLayer.userData.parallax = 0.58 + layerProgress * 0.72;
    mistLayer.userData.phase = phase;
    mistLayer.userData.baseY = baseY;
    mistLayer.userData.baseScaleX = mistLayer.scale.x;
    mistLayer.userData.baseScaleY = baseScaleY;
    mistLayer.userData.baseRotation = material.rotation;
    mistLayer.renderOrder = 4 + index;
    fogGroup.add(mistLayer);
    return mistLayer;
  });
  scene.add(fogGroup);

  const dummy = new THREE.Object3D();
  const rain = createSonicRainSystem(THREE, scene, group, dummy, theme, camera);
  let index = 0;
  for (let x = 0; x < SONIC_TOPOGRAPHY_GRID; x += 1) {
    for (let z = 0; z < SONIC_TOPOGRAPHY_GRID; z += 1) {
      const gridX = x - SONIC_TOPOGRAPHY_GRID / 2;
      const gridZ = z - SONIC_TOPOGRAPHY_GRID / 2;
      const px = x * SONIC_TOPOGRAPHY_SPACING - offset;
      const pz = z * SONIC_TOPOGRAPHY_SPACING - offset;
      let bassColumnBand = bassColumnBandByPoint.get(bassColumnPointKey(gridX, gridZ));
      const gridRadius = Math.hypot(gridX, gridZ);
      if (!Number.isFinite(bassColumnBand)
          && gridRadius < bassColumnRadius + SONIC_BASS_COLUMN_CLUSTER.feather) {
        let nearestDistanceSquared = Infinity;
        bassColumnCorePoints.forEach((point) => {
          const dx = gridX - point.x;
          const dz = gridZ - point.z;
          const distanceSquared = dx * dx + dz * dz;
          if (distanceSquared >= nearestDistanceSquared) return;
          nearestDistanceSquared = distanceSquared;
          bassColumnBand = bassColumnBandByPoint.get(bassColumnPointKey(point.x, point.z));
        });
      }
      bassColumnBandValues[index] = Number.isFinite(bassColumnBand) ? bassColumnBand : 0;
      const smallBassCellX = Math.floor(px / 7);
      const smallBassCellZ = Math.floor(pz / 7);
      const seedOffset = index * 4;
      terrainSeedValues[seedOffset] = Math.round(sonicRainHash(px, pz) * 255);
      terrainSeedValues[seedOffset + 1] = Math.round(
        sonicRainHash(smallBassCellX + 23.7, smallBassCellZ + 51.3) * 255
      );
      terrainSeedValues[seedOffset + 2] = Math.round(
        sonicRainHash(smallBassCellX + 7.1, smallBassCellZ + 19.7) * 255
      );
      terrainSeedValues[seedOffset + 3] = Math.round(
        sonicRainHash(smallBassCellX + 31.9, smallBassCellZ + 11.3) * 255
      );
      const smallLocalOffset = index * 2;
      terrainSmallLocalValues[smallLocalOffset] = Math.round(
        (px / 7 - smallBassCellX) * 255
      );
      terrainSmallLocalValues[smallLocalOffset + 1] = Math.round(
        (pz / 7 - smallBassCellZ) * 255
      );
      const moundColumnPatchX = Math.floor((gridX + 2) / 4);
      const moundColumnPatchZ = Math.floor((gridZ + 2) / 4);
      const moundColumnPatchLevel = Math.floor(
        sonicRainHash(moundColumnPatchX + 83.7, moundColumnPatchZ - 41.9)
          * SONIC_GROUND_MOUND_COLUMN_LEVELS
      );
      const moundColumnMicroOffset = Math.floor(
        sonicRainHash(gridX * 1.37 - 13.1, gridZ * 1.91 + 27.3) * 3
      ) - 1;
      const moundColumnLevel = clamp(
        moundColumnPatchLevel + moundColumnMicroOffset,
        0,
        SONIC_GROUND_MOUND_COLUMN_LEVELS - 1
      );
      const moundColumnPhase = Math.min(
        SONIC_GROUND_MOUND_COLUMN_PHASE_BUCKETS - 1,
        Math.floor(
          sonicRainHash(gridX * 0.73 + 59.2, gridZ * 1.17 - 31.4)
            * SONIC_GROUND_MOUND_COLUMN_PHASE_BUCKETS
        )
      );
      const moundColumnBand = Math.min(
        SONIC_LOW_FREQUENCY_BAND_COUNT - 1,
        Math.floor(
          sonicRainHash(gridX * 2.71 - 7.9, gridZ * 3.17 + 19.6)
            * SONIC_LOW_FREQUENCY_BAND_COUNT
        )
      );
      const moundColumnProfileOffset = index * 4;
      groundMoundColumnProfileValues[moundColumnProfileOffset] = Math.round(
        moundColumnLevel / (SONIC_GROUND_MOUND_COLUMN_LEVELS - 1) * 255
      );
      groundMoundColumnProfileValues[moundColumnProfileOffset + 1] = Math.round(
        moundColumnPhase / (SONIC_GROUND_MOUND_COLUMN_PHASE_BUCKETS - 1) * 255
      );
      groundMoundColumnProfileValues[moundColumnProfileOffset + 2] = moundColumnBand & 0xff;
      groundMoundColumnProfileValues[moundColumnProfileOffset + 3] = moundColumnBand >= 256 ? 255 : 0;
      dummy.position.set(px, 0.5, pz);
      dummy.rotation.set(0, 0, 0);
      dummy.scale.set(1, 1, 1);
      dummy.updateMatrix();
      terrain.setMatrixAt(index, dummy.matrix);
      index += 1;
    }
  }

  for (let i = 0; i < SONIC_TOPOGRAPHY_METEORS; i += 1) {
    dummy.position.set(0, -1000, 0);
    dummy.scale.set(0, 0, 0);
    dummy.updateMatrix();
    meteorMesh.setMatrixAt(i, dummy.matrix);
  }
  for (let i = 0; i < SONIC_TOPOGRAPHY_PARTICLES; i += 1) {
    dummy.position.set(0, -1000, 0);
    dummy.scale.set(0, 0, 0);
    dummy.updateMatrix();
    particleMesh.setMatrixAt(i, dummy.matrix);
  }

  terrain.instanceMatrix.needsUpdate = true;
  bassColumnBandAttribute.needsUpdate = true;
  terrainSeedAttribute.needsUpdate = true;
  terrainSmallLocalAttribute.needsUpdate = true;
  groundMoundMaskAttribute.needsUpdate = true;
  groundMoundColumnProfileAttribute.needsUpdate = true;
  meteorMesh.instanceMatrix.needsUpdate = true;
  particleMesh.instanceMatrix.needsUpdate = true;

  topo.count = count;
  topo.renderer = renderer;
  topo.renderQuality = renderQuality;
  topo.scene = scene;
  topo.camera = camera;
  topo.group = group;
  topo.terrain = terrain;
  topo.material = material;
  topo.uniforms = material.uniforms;
  topo.bassColumnBandAttribute = bassColumnBandAttribute;
  topo.terrainSeedAttribute = terrainSeedAttribute;
  topo.terrainSmallLocalAttribute = terrainSmallLocalAttribute;
  topo.groundMoundMaskAttribute = groundMoundMaskAttribute;
  topo.groundMoundColumnProfileAttribute = groundMoundColumnProfileAttribute;
  topo.groundMoundSignature = sonicGroundMoundMaskSignature(topo.settings);
  topo.lowFrequencySpectrum = material.userData.lowFrequencySpectrum;
  topo.lowFrequencySpectrumData = material.userData.lowFrequencySpectrumData;
  topo.meteorMesh = meteorMesh;
  topo.meteorMaterial = meteorMesh.material;
  topo.particleMesh = particleMesh;
  topo.particleMaterial = particleMesh.material;
  topo.starfield = starfield;
  topo.starfieldMaterial = starfieldMaterial;
  topo.galaxy = galaxy;
  topo.galaxyMaterial = galaxyMaterial;
  topo.fogGroup = fogGroup;
  topo.fogLayers = fogLayers;
  topo.ambientLight = ambientLight;
  topo.keyLight = keyLight;
  topo.tyndallLight = tyndallLight;
  topo.tyndallLightTarget = tyndallLightTarget;
  topo.tyndallBeams = tyndallBeams;
  topo.tyndallHalos = tyndallHalos;
  topo.tyndallGroundSheen = tyndallGroundSheen;
  topo.tyndallGroundSheenMaterial = tyndallGroundSheenMaterial;
  topo.tyndallColumnReceivers = tyndallColumnReceivers;
  topo.tyndallWallBounce = tyndallWallBounce;
  topo.tyndallWallBounceMaterial = tyndallWallBounceMaterial;
  topo.sonicHighlightShoulder = sonicHighlightShoulder;
  topo.mistBlackLiftGuard = 1;
  topo.background = background;
  topo.backgroundMaterial = backgroundMaterial;
  topo.wallpaperSurface = wallpaperSurface;
  fitSonicWallpaperSurface(topo);
  topo.backgroundTargetColors = backgroundColors.map((color) => new THREE.Color(rgbHexValue(color)));
  topo.atmosphereColor = new THREE.Color();
  topo.atmosphereAudioDrive = 0;
  topo.starfieldAudio = 0;
  topo.rain = rain;
  topo.dummy = dummy;
  topo.meteorTargetColor = new THREE.Color();
  topo.whiteColor = new THREE.Color(0xffffff);
  topo.theme = theme;
  topo.ripples = material.uniforms.uRipples.value;
  topo.meteors = Array.from({ length: SONIC_TOPOGRAPHY_METEORS }, () => ({ active: false, x: 0, y: -1000, z: 0, speed: 0, strength: 0 }));
  topo.particles = Array.from({ length: SONIC_TOPOGRAPHY_PARTICLES }, () => ({ active: false, x: 0, y: -1000, z: 0, vx: 0, vy: 0, vz: 0, life: 0, maxLife: 1, scale: 1 }));
  topo.fountainEmitters = fountainEmitters;
  applySonicTopographySettings({ persist: false, sync: true, renderConfig: false });
  topo.built = true;
  syncSceneWallpaperSurface('topography');
  observePresetRendererSize(topo, els.sonicTopographyCore, resizeSonicTopographyRenderer);
  applySonicTopographyPalette(topo.palette || fallbackLyricPalette(state.currentSong));
  applyPresetUpscaler({ force: true });
  if (renderQuality) renderQuality.render(scene, camera, performance.now());
  else renderer.render(scene, camera);
}

function resizeSonicTopographyRenderer() {
  const topo = state.sonicTopography;
  if (!topo.renderer || !topo.camera || !els.sonicTopographyCore) return;
  const rect = els.sonicTopographyCore.getBoundingClientRect();
  const width = Math.max(1, Math.floor(rect.width));
  const height = Math.max(1, Math.floor(rect.height));
  if (width === topo.lastWidth && height === topo.lastHeight) return;
  topo.lastWidth = width;
  topo.lastHeight = height;
  if (topo.renderQuality) topo.renderQuality.resize(width, height, topo.renderer.getPixelRatio?.() || renderPixelRatio('webgl'));
  else topo.renderer.setSize(width, height, false);
  topo.camera.aspect = width / Math.max(1, height);
  updateSonicTopographyCameraFit();
}

function disposeSonicTopography() {
  const topo = state.sonicTopography;
  if (!topo.built) return;
  disposeSonicWallpaperSurface(topo);
  disposePresetRenderer(topo, els.sonicTopographyCore);
  topo.lowFrequencySpectrum?.dispose?.();
  Object.assign(topo, {
    built: false,
    count: 0,
    renderer: null,
    renderQuality: null,
    scene: null,
    camera: null,
    group: null,
    terrain: null,
    material: null,
    uniforms: null,
    bassColumnBandAttribute: null,
    terrainSeedAttribute: null,
    terrainSmallLocalAttribute: null,
    groundMoundMaskAttribute: null,
    groundMoundColumnProfileAttribute: null,
    groundMoundSignature: '',
    groundEntranceStartedAt: 0,
    groundEntranceProgress: 0,
    lowFrequencySpectrum: null,
    lowFrequencySpectrumData: null,
    meteorMesh: null,
    meteorMaterial: null,
    particleMesh: null,
    particleMaterial: null,
    starfield: null,
    starfieldMaterial: null,
    galaxy: null,
    galaxyMaterial: null,
    fogGroup: null,
    fogLayers: [],
    ambientLight: null,
    keyLight: null,
    tyndallLight: null,
    tyndallLightTarget: null,
    tyndallBeams: [],
    tyndallHalos: [],
    background: null,
    backgroundMaterial: null,
    wallpaperSurface: null,
    wallpaperTexture: null,
    wallpaperVideo: null,
    wallpaperRequestId: 0,
    wallpaperSignature: '',
    backgroundTargetColors: [],
    atmosphereColor: null,
    atmosphereAudioDrive: 0,
    starfieldAudio: 0,
    rain: null,
    dummy: null,
    theme: null,
    ripples: [],
    rippleIndex: 0,
    meteors: [],
    meteorIndex: 0,
    particles: [],
    particleIndex: 0,
    fountainEmitters: [],
    lastWidth: 0,
    lastHeight: 0,
    lastMotionAt: 0,
    lastRenderAt: 0,
    autoYaw: 0,
    lastBeat: 0,
    lastMeteorAt: 0,
    lastFountainAt: 0,
    pulseCooldown: 0,
    meteorCooldown: 0,
    bass: 0,
    mid: 0,
    treble: 0,
    energy: 0,
    audioPulse: 0,
    wasAudioDriving: false,
    audioTerrainSource: '',
    audioTerrainTime: 0,
    projectilesActive: false,
    projectilesNeedClear: false
  });
  topo.frameAudio.lowFrequencyBands.fill(0);
  topo.frameAudio.lowFrequencyBandTargets.fill(0);
}

function sonicAtmosphereRuntimeSnapshot() {
  const topo = state.sonicTopography;
  return {
    hardwareAntialias: topo.renderer?.getContext?.()?.getContextAttributes?.()?.antialias === true,
    mistLayerCount: topo.fogLayers?.length || 0,
    beamCount: topo.tyndallBeams?.length || 0,
    haloCount: topo.tyndallHalos?.length || 0,
    groundReceiverCount: topo.tyndallGroundSheen ? 1 : 0,
    receiverBounceCount: (topo.tyndallColumnReceivers?.length || 0) + (topo.tyndallWallBounce ? 1 : 0),
    highlightShoulder: topo.sonicHighlightShoulder || 0,
    blackLiftGuard: topo.mistBlackLiftGuard ?? 1,
    atmosphereContrast: topo.atmosphereContrast ?? 0,
    terrainAtmosphereLightStrength: topo.uniforms?.uAtmosphereLightStrength?.value || 0,
    atmosphereAudioDrive: topo.atmosphereAudioDrive || 0,
    terrainUsesLayeredAtmosphere: !!topo.uniforms?.uAtmosphereAudioDrive,
    backgroundUsesLayeredAtmosphere: !!topo.backgroundMaterial?.uniforms?.uAtmosphereBass
      && !!topo.backgroundMaterial?.uniforms?.uAtmosphereDetail,
    groundUsesDirectionalSheen: !!topo.tyndallGroundSheenMaterial?.uniforms?.uSheenDirection,
    groundHasNoSpotGeometry: topo.tyndallGroundSheen?.geometry?.type === 'PlaneGeometry'
  };
}

function updateSonicTopographyVisibility() {
  const visible = state.playbackPage && isSonicTopographyPreset();
  if (els.sonicTopographyScene) els.sonicTopographyScene.hidden = !visible;
  els.appShell.classList.toggle('has-sonic-topography', visible);
  if (visible) buildSonicTopography();
  else disposeSonicTopography();
}

function wallpaperById(id) {
  return state.wallpapers.find((wallpaper) => String(wallpaper.id) === String(id)) || null;
}

function sceneWallpaperSetting(preset = state.diyPreset) {
  if (!SCENE_WALLPAPER_PRESETS.includes(preset)) return null;
  const normalized = normalizeSceneWallpaperSetting(state.sceneWallpaperSettings?.[preset]);
  state.sceneWallpaperSettings[preset] = normalized;
  return normalized;
}

function sceneWallpaperTextureUrl(wallpaper) {
  const kind = safeText(wallpaper?.kind, 'image');
  if (wallpaper?.kind === 'web') return safeText(wallpaper.previewUrl, '');
  if (kind === 'video') return safeText(wallpaper?.url, '');
  if (kind === 'scene') return safeText(wallpaper?.previewUrl, '');
  return safeText(wallpaper?.url || wallpaper?.previewUrl, '');
}

function createSonicWallpaperSurface(THREE) {
  const geometry = new THREE.PlaneGeometry(2, 2, 80, 40);
  const positions = geometry.getAttribute('position');
  for (let index = 0; index < positions.count; index += 1) {
    const x = positions.getX(index);
    const y = positions.getY(index);
    const v = (y + 1) * 0.5;
    const upper = clamp((v - 0.35) / 0.65, 0, 1);
    const dome = upper * upper * (3 - 2 * upper);
    const sideWrap = x * x * (0.26 + dome * 0.055);
    const midRecline = -v * 0.075;
    const topDome = dome * dome * 0.18;
    const centerInset = -(1 - x * x) * (1 - dome) * 0.025;
    positions.setZ(index, sideWrap + midRecline + topDome + centerInset);
  }
  positions.needsUpdate = true;
  geometry.computeVertexNormals();

  const material = new THREE.ShaderMaterial({
    uniforms: {
      uMap: { value: null },
      uOpacity: { value: 0 },
      uContainRegion: { value: new THREE.Vector2(0.9, 0.9) },
      uCoverScale: { value: new THREE.Vector2(1, 1) },
      uTexelSize: { value: new THREE.Vector2(1 / 1920, 1 / 1080) }
    },
    vertexShader: `
      varying vec2 vUv;
      void main() {
        vUv = uv;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      precision highp float;
      uniform sampler2D uMap;
      uniform float uOpacity;
      uniform vec2 uContainRegion;
      uniform vec2 uCoverScale;
      uniform vec2 uTexelSize;
      varying vec2 vUv;

      vec4 sampleBlurredCover(vec2 uv) {
        vec2 coverUv = (uv - 0.5) * uCoverScale + 0.5;
        vec2 blurStep = max(uTexelSize * 3.2, vec2(0.0005));
        vec4 color = texture2D(uMap, coverUv) * 0.36;
        color += texture2D(uMap, clamp(coverUv + vec2(blurStep.x, 0.0), 0.0, 1.0)) * 0.16;
        color += texture2D(uMap, clamp(coverUv - vec2(blurStep.x, 0.0), 0.0, 1.0)) * 0.16;
        color += texture2D(uMap, clamp(coverUv + vec2(0.0, blurStep.y), 0.0, 1.0)) * 0.16;
        color += texture2D(uMap, clamp(coverUv - vec2(0.0, blurStep.y), 0.0, 1.0)) * 0.16;
        return color;
      }

      void main() {
        vec4 blurredCover = sampleBlurredCover(vUv);
        vec2 containUv = (vUv - 0.5) / max(uContainRegion, vec2(0.001)) + 0.5;
        vec2 insideDistance = uContainRegion * 0.5 - abs(vUv - 0.5);
        float containMask = smoothstep(-0.006, 0.006, min(insideDistance.x, insideDistance.y));
        vec4 contained = texture2D(uMap, clamp(containUv, 0.0, 1.0));
        float lowerDetail = smoothstep(0.07, 0.29, vUv.y);
        float containMix = containMask * lowerDetail * contained.a;
        vec3 color = mix(blurredCover.rgb, contained.rgb, containMix);
        float bottomFeather = smoothstep(0.0, 0.28, vUv.y);
        float alpha = max(blurredCover.a, contained.a * containMask) * uOpacity * bottomFeather;
        gl_FragColor = vec4(color, alpha);
      }
    `,
    transparent: true,
    depthTest: false,
    depthWrite: false,
    side: THREE.FrontSide,
    toneMapped: false,
    fog: false
  });
  material.map = null;
  const wallpaperSurface = new THREE.Mesh(geometry, material);
  wallpaperSurface.name = 'SonicCameraConcaveUpperDomeWallpaper';
  wallpaperSurface.position.set(0, 0, -360);
  wallpaperSurface.userData.distance = 360;
  wallpaperSurface.userData.overscan = 1.08;
  wallpaperSurface.userData.bottomNdc = -0.08;
  wallpaperSurface.userData.topNdc = 1.08;
  wallpaperSurface.userData.verticalCoverage = 0.58;
  wallpaperSurface.userData.safeContentScale = 0.9;
  wallpaperSurface.userData.surface = 'camera-deep-concave-contain-dome';
  wallpaperSurface.renderOrder = -90;
  wallpaperSurface.visible = false;
  wallpaperSurface.frustumCulled = false;
  return wallpaperSurface;
}

function fitSonicWallpaperSurface(topo = state.sonicTopography) {
  const surface = topo?.wallpaperSurface;
  const camera = topo?.camera;
  if (!surface || !camera) return false;
  const distance = Number(surface.userData?.distance) || 360;
  const overscan = Number(surface.userData?.overscan) || 1.08;
  const bottomNdc = Number(surface.userData?.bottomNdc) || -0.08;
  const topNdc = Number(surface.userData?.topNdc) || 1.08;
  const centerNdc = (bottomNdc + topNdc) * 0.5;
  const halfSpanNdc = Math.max(0.1, (topNdc - bottomNdc) * 0.5);
  const visibleHeight = 2 * Math.tan(camera.fov * Math.PI / 360) * distance;
  const visibleWidth = visibleHeight * Math.max(0.1, camera.aspect || 1);
  surface.position.set(0, visibleHeight * 0.5 * centerNdc, -distance);
  surface.scale.set(
    visibleWidth * 0.5 * overscan,
    visibleHeight * 0.5 * halfSpanNdc,
    distance * 0.25
  );
  return true;
}

function fitSonicWallpaperTexture(topo = state.sonicTopography, texture = topo?.wallpaperTexture) {
  const surface = topo?.wallpaperSurface;
  const uniforms = surface?.material?.uniforms;
  if (!topo?.camera || !texture?.repeat?.set || !texture?.offset?.set
    || !uniforms?.uContainRegion?.value?.set || !uniforms?.uCoverScale?.value?.set) return false;
  const source = texture.image || texture.source?.data || null;
  const width = Number(source?.naturalWidth || source?.videoWidth || source?.width) || 0;
  const height = Number(source?.naturalHeight || source?.videoHeight || source?.height) || 0;
  if (!width || !height) return false;
  const sourceAspect = width / height;
  const viewportAspect = Math.max(0.1, topo.camera.aspect || 1);
  const overscan = Number(surface.userData?.overscan) || 1.08;
  const verticalCoverage = Number(surface.userData?.verticalCoverage) || 0.58;
  const safeContentScale = clamp(Number(surface.userData?.safeContentScale) || 0.9, 0.72, 1);
  const targetAspect = viewportAspect * overscan / verticalCoverage;
  let containX = safeContentScale;
  let containY = safeContentScale;
  let coverX = 1;
  let coverY = 1;
  if (sourceAspect > targetAspect) {
    containY *= targetAspect / sourceAspect;
    coverX = targetAspect / sourceAspect;
  } else {
    containX *= sourceAspect / targetAspect;
    coverY = sourceAspect / targetAspect;
  }
  texture.repeat.set(1, 1);
  texture.offset.set(0, 0);
  uniforms.uContainRegion.value.set(containX, containY);
  uniforms.uCoverScale.value.set(coverX, coverY);
  uniforms.uTexelSize?.value?.set(1 / width, 1 / height);
  surface.userData.sourceAspect = sourceAspect;
  surface.userData.targetAspect = targetAspect;
  surface.userData.containRegion = Object.freeze([containX, containY]);
  texture.needsUpdate = true;
  return true;
}

function disposeSonicWallpaperSurface(topo = state.sonicTopography) {
  if (!topo) return;
  topo.wallpaperRequestId = (topo.wallpaperRequestId || 0) + 1;
  if (topo.wallpaperVideo) {
    window.FeWallpaperVideoContinuity?.release?.(topo.wallpaperVideo);
    topo.wallpaperVideo.pause?.();
    topo.wallpaperVideo.removeAttribute?.('src');
    topo.wallpaperVideo.load?.();
    topo.wallpaperVideo = null;
  }
  topo.wallpaperTexture?.dispose?.();
  topo.wallpaperTexture = null;
  topo.wallpaperSignature = '';
  if (topo.wallpaperSurface?.material) {
    topo.wallpaperSurface.material.map = null;
    topo.wallpaperSurface.material.opacity = 0;
    if (topo.wallpaperSurface.material.uniforms?.uMap) {
      topo.wallpaperSurface.material.uniforms.uMap.value = null;
    }
    if (topo.wallpaperSurface.material.uniforms?.uOpacity) {
      topo.wallpaperSurface.material.uniforms.uOpacity.value = 0;
    }
    topo.wallpaperSurface.material.needsUpdate = true;
  }
  if (topo.wallpaperSurface) topo.wallpaperSurface.visible = false;
  if (topo.background) topo.background.visible = true;
}

function setSonicWallpaperSurface(request) {
  const topo = state.sonicTopography;
  const surface = topo.wallpaperSurface;
  if (!surface?.material || !window.THREE) return false;
  const config = request && typeof request === 'object' ? request : {};
  const enabled = config.enabled === true;
  const url = safeText(config.url, '').trim();
  const mediaKind = config.mediaKind === 'video' ? 'video' : 'image';
  const opacity = clamp(Number(config.opacity) || 0.68, 0.1, 1);
  const signature = enabled && url ? `${mediaKind}:${url}` : '';
  surface.material.opacity = opacity;
  if (surface.material.uniforms?.uOpacity) surface.material.uniforms.uOpacity.value = opacity;
  if (!signature) {
    disposeSonicWallpaperSurface(topo);
    return true;
  }
  if (signature === topo.wallpaperSignature) {
    if (topo.wallpaperTexture) {
      fitSonicWallpaperTexture(topo, topo.wallpaperTexture);
      surface.visible = true;
      if (topo.background) topo.background.visible = true;
    }
    return true;
  }

  topo.wallpaperRequestId = (topo.wallpaperRequestId || 0) + 1;
  const requestId = topo.wallpaperRequestId;
  topo.wallpaperSignature = signature;
  surface.visible = false;
  if (topo.background) topo.background.visible = true;
  surface.material.map = null;
  if (surface.material.uniforms?.uMap) surface.material.uniforms.uMap.value = null;
  if (topo.wallpaperVideo) {
    window.FeWallpaperVideoContinuity?.release?.(topo.wallpaperVideo);
    topo.wallpaperVideo.pause?.();
    topo.wallpaperVideo.removeAttribute?.('src');
    topo.wallpaperVideo.load?.();
    topo.wallpaperVideo = null;
  }
  topo.wallpaperTexture?.dispose?.();
  topo.wallpaperTexture = null;
  const applyTexture = (texture) => {
    if (!topo.built || topo.wallpaperRequestId !== requestId || topo.wallpaperSignature !== signature) {
      texture.dispose?.();
      return false;
    }
    if ('colorSpace' in texture && window.THREE.SRGBColorSpace) texture.colorSpace = window.THREE.SRGBColorSpace;
    else if ('encoding' in texture && window.THREE.sRGBEncoding !== undefined) texture.encoding = window.THREE.sRGBEncoding;
    texture.wrapS = window.THREE.ClampToEdgeWrapping;
    texture.wrapT = window.THREE.ClampToEdgeWrapping;
    fitSonicWallpaperTexture(topo, texture);
    texture.needsUpdate = true;
    topo.wallpaperTexture = texture;
    surface.material.map = texture;
    if (surface.material.uniforms?.uMap) surface.material.uniforms.uMap.value = texture;
    surface.material.needsUpdate = true;
    surface.visible = true;
    if (topo.background) topo.background.visible = true;
    requestOrbFrame();
    return true;
  };
  const failTexture = () => {
    if (topo.wallpaperRequestId !== requestId) return;
    topo.wallpaperSignature = '';
    surface.visible = false;
    surface.material.map = null;
    if (surface.material.uniforms?.uMap) surface.material.uniforms.uMap.value = null;
    if (topo.background) topo.background.visible = true;
  };

  if (mediaKind === 'video') {
    const video = document.createElement('video');
    video.crossOrigin = 'anonymous';
    video.preload = 'auto';
    video.muted = true;
    video.defaultMuted = true;
    video.playsInline = true;
    window.FeWallpaperVideoContinuity?.prepare(video);
    const texture = new window.THREE.VideoTexture(video);
    texture.minFilter = window.THREE.LinearFilter;
    texture.magFilter = window.THREE.LinearFilter;
    topo.wallpaperVideo = video;
    video.addEventListener('loadeddata', () => {
      if (!applyTexture(texture)) return;
      video.play().catch(() => {});
    }, { once: true });
    video.addEventListener('error', () => {
      window.FeWallpaperVideoContinuity?.release?.(video);
      texture.dispose?.();
      if (topo.wallpaperVideo === video) topo.wallpaperVideo = null;
      failTexture();
    }, { once: true });
    video.src = url;
    video.load();
    video.play().catch(() => {});
    return true;
  }

  const loader = new window.THREE.TextureLoader();
  loader.setCrossOrigin?.('anonymous');
  loader.load(
    url,
    applyTexture,
    undefined,
    failTexture
  );
  return true;
}

function sceneWallpaperChoices() {
  const seen = new Set();
  return state.wallpapers.filter((wallpaper) => {
    const id = safeText(wallpaper?.id, '');
    if (!id || seen.has(id) || !sceneWallpaperTextureUrl(wallpaper)) return false;
    seen.add(id);
    return true;
  });
}

function replaceLoadedWallpaperCatalogs(items, sources = []) {
  const input = Array.isArray(items) ? items : [];
  const requested = new Set(Array.isArray(sources) ? sources : []);
  if (requested.has('imported')) {
    state.wallpaperCatalogs.imported = input.filter((wallpaper) => wallpaper?.source === 'imported');
  }
  if (requested.has('live')) {
    state.wallpaperCatalogs.live = input.filter((wallpaper) => wallpaper?.source === 'wallpaper-engine');
  }
  const merged = new Map();
  [...state.wallpaperCatalogs.imported, ...state.wallpaperCatalogs.live].forEach((wallpaper) => {
    const id = safeText(wallpaper?.id, '');
    if (id) merged.set(id, wallpaper);
  });
  state.wallpapers = Array.from(merged.values());
}

async function refreshSceneWallpaperCatalog(options = {}) {
  if (state.sceneWallpaperCatalogLoading) return;
  if (state.wallpaperEngineCatalogLoaded && options.force !== true) return;
  state.sceneWallpaperCatalogLoading = true;
  state.community.messageBackgroundCatalogError = '';
  try {
    const payload = await apiJson(`/api/wallpapers?${query({ scan: true })}`);
    const items = Array.isArray(payload.wallpapers) ? payload.wallpapers : [];
    const sources = ['live'];
    if (items.some((wallpaper) => wallpaper?.source === 'imported')) sources.push('imported');
    replaceLoadedWallpaperCatalogs(items, sources);
    state.wallpaperEngineCatalogRevision = safeText(payload.catalogRevision, '');
    state.wallpaperEngineActiveId = safeText(
      payload.activeWallpaperId,
      safeText(Array.isArray(payload.activeWallpaperIds) ? payload.activeWallpaperIds[0] : '', '')
    );
    state.wallpaperEngineCatalogLoaded = true;
    syncAllSceneWallpaperSurfaces();
    syncSceneWallpaperControl();
    syncCommunityMessageBackground();
    if (state.diyPage === 'wallpaper') renderWallpaperList();
  } catch (error) {
    state.community.messageBackgroundCatalogError = error.message || 'Wallpaper Engine 壁纸读取失败';
    if (els.sceneWallpaperStatus && !sceneWallpaperDescriptor()?.wallpaperUrl) {
      els.sceneWallpaperStatus.textContent = error.message || 'Wallpaper Engine 壁纸读取失败';
    }
  } finally {
    state.sceneWallpaperCatalogLoading = false;
    if (state.community.messageBackgroundMenuOpen) renderCommunityMessageBackgroundChoices();
  }
}

function sceneWallpaperLiveRefreshActive() {
  if (document.hidden) return false;
  const activeSetting = state.sceneWallpaperSettings?.[state.diyPreset];
  const activeWallpaperEnginePreset = state.playbackPage
    && SCENE_WALLPAPER_PRESETS.includes(state.diyPreset)
    && activeSetting?.enabled === true
    && (
      activeSetting.followWallpaperEngine === true
      || safeText(activeSetting.wallpaperId, '').startsWith('wallpaper-engine:')
    );
  const browsingWallpaperEngine = state.diyPage === 'wallpaper'
    && state.wallpaperSource === 'live';
  return activeWallpaperEnginePreset
    || browsingWallpaperEngine
    || communityMessageBackgroundLiveRefreshActive();
}

function clearSceneWallpaperLiveRefresh() {
  window.clearTimeout(sceneWallpaperLiveRefreshTimer);
  sceneWallpaperLiveRefreshTimer = 0;
}

function syncSceneWallpaperLiveRefresh() {
  clearSceneWallpaperLiveRefresh();
  if (!sceneWallpaperLiveRefreshActive()) return;
  sceneWallpaperLiveRefreshTimer = window.setTimeout(async () => {
    sceneWallpaperLiveRefreshTimer = 0;
    await refreshSceneWallpaperCatalog({ force: true, live: true });
    syncSceneWallpaperLiveRefresh();
  }, SCENE_WALLPAPER_LIVE_REFRESH_MS);
}

function sceneWallpaperRuntimeUrl(wallpaper, url) {
  const source = safeText(url, '');
  const revision = safeText(state.wallpaperEngineCatalogRevision, '');
  if (!source || wallpaper?.source !== 'wallpaper-engine' || !revision) return source;
  const separator = source.includes('?') ? '&' : '?';
  return `${source}${separator}catalogRevision=${encodeURIComponent(revision)}`;
}

function sceneWallpaperDescriptor(preset = state.diyPreset) {
  const setting = sceneWallpaperSetting(preset);
  if (!setting) return null;
  const wallpaper = wallpaperById(
    setting.followWallpaperEngine
      ? state.wallpaperEngineActiveId || setting.wallpaperId
      : setting.wallpaperId
  );
  const resolvedUrl = sceneWallpaperRuntimeUrl(
    wallpaper,
    sceneWallpaperTextureUrl(wallpaper) || setting.wallpaperUrl
  );
  return {
    ...setting,
    wallpaperUrl: resolvedUrl,
    wallpaperName: safeText(wallpaper?.name || setting.wallpaperName, '场景壁纸'),
    mediaKind: safeText(wallpaper?.kind, setting.mediaKind) === 'video' ? 'video' : 'image'
  };
}

function syncSceneWallpaperSurface(preset = state.diyPreset) {
  const descriptor = sceneWallpaperDescriptor(preset);
  if (!descriptor) return;
  const request = {
    enabled: descriptor.enabled && !!descriptor.wallpaperUrl,
    url: descriptor.wallpaperUrl,
    mediaKind: descriptor.mediaKind,
    opacity: descriptor.opacity
  };
  if (preset === 'cover-particles') {
    const visible = coverParticlePresetVisible();
    els.coverParticleScene?.classList.toggle('has-scene-wallpaper', request.enabled && visible);
    if (visible) setCoverParticleWallpaper(request);
    else setCoverParticleWallpaper({ enabled: false });
  }
  if (preset === 'topography') setSonicWallpaperSurface(request);
  if (preset === 'chladni' && state.chladni.runtime && window.FeChladniRuntime?.setWallpaper) {
    els.chladniScene?.classList.toggle('has-scene-wallpaper', request.enabled);
    window.FeChladniRuntime.setWallpaper(state.chladni.runtime, request);
  } else if (preset === 'chladni') {
    els.chladniScene?.classList.toggle('has-scene-wallpaper', request.enabled);
  }
}

function syncAllSceneWallpaperSurfaces() {
  SCENE_WALLPAPER_PRESETS.forEach((preset) => syncSceneWallpaperSurface(preset));
}

function syncSceneWallpaperControl() {
  if (!els.sceneWallpaperControl) return;
  const preset = SCENE_WALLPAPER_PRESETS.includes(state.diyPreset) ? state.diyPreset : '';
  els.sceneWallpaperControl.hidden = !preset;
  els.sceneWallpaperControl.dataset.sceneWallpaperPreset = preset;
  if (!preset) return;
  if (!state.wallpaperEngineCatalogLoaded && !state.sceneWallpaperCatalogLoading) {
    void refreshSceneWallpaperCatalog();
  }
  syncSceneWallpaperLiveRefresh();
  const setting = sceneWallpaperSetting(preset);
  const descriptor = sceneWallpaperDescriptor(preset);
  const choices = sceneWallpaperChoices();
  if (els.sceneWallpaperSelect) {
    els.sceneWallpaperSelect.replaceChildren();
    const empty = document.createElement('option');
    empty.value = SCENE_WALLPAPER_SOFT_GLOW_ID;
    empty.textContent = choices.length ? '未选择' : '暂无可用壁纸';
    empty.textContent = '柔光背景（跟随封面取色）';
    els.sceneWallpaperSelect.appendChild(empty);
    const engineCurrent = document.createElement('option');
    engineCurrent.value = SCENE_WALLPAPER_ENGINE_CURRENT_ID;
    engineCurrent.textContent = state.wallpaperEngineActiveId
      ? '跟随 Wallpaper Engine 当前壁纸'
      : '跟随 Wallpaper Engine 当前壁纸（等待识别）';
    engineCurrent.disabled = !state.wallpaperEngineActiveId;
    els.sceneWallpaperSelect.appendChild(engineCurrent);
    choices.forEach((wallpaper) => {
      const option = document.createElement('option');
      option.value = safeText(wallpaper.id, '');
      option.textContent = `${wallpaper.active === true ? '正在播放 · ' : ''}${safeText(wallpaper.name, 'Wallpaper')}`;
      els.sceneWallpaperSelect.appendChild(option);
    });
    if (setting.wallpaperId && !choices.some((item) => String(item.id) === String(setting.wallpaperId))) {
      const persisted = document.createElement('option');
      persisted.value = setting.wallpaperId;
      persisted.textContent = setting.wallpaperName || '已保存的壁纸';
      els.sceneWallpaperSelect.appendChild(persisted);
    }
    els.sceneWallpaperSelect.value = setting.enabled && setting.followWallpaperEngine
      ? SCENE_WALLPAPER_ENGINE_CURRENT_ID
      : setting.enabled && setting.wallpaperId
        ? setting.wallpaperId
        : SCENE_WALLPAPER_SOFT_GLOW_ID;
  }
  if (els.sceneWallpaperEnabledToggle) {
    els.sceneWallpaperEnabledToggle.checked = setting.enabled;
    els.sceneWallpaperEnabledToggle.disabled = !descriptor.wallpaperUrl;
    els.sceneWallpaperEnabledToggle.setAttribute('aria-checked', String(setting.enabled));
  }
  if (els.sceneWallpaperOpacityRange) {
    const percent = Math.round(setting.opacity * 100);
    els.sceneWallpaperOpacityRange.value = String(percent);
    els.sceneWallpaperOpacityRange.setAttribute('aria-valuetext', `${percent}%`);
    syncElasticRangeVisual(els.sceneWallpaperOpacityRange);
    if (els.sceneWallpaperOpacityValue) els.sceneWallpaperOpacityValue.textContent = `${percent}%`;
  }
  const current = currentSceneWallpaperChoice();
  if (els.sceneWallpaperUseCurrentButton) {
    els.sceneWallpaperUseCurrentButton.disabled = !sceneWallpaperTextureUrl(current);
  }
  if (els.sceneWallpaperRemoveButton) els.sceneWallpaperRemoveButton.disabled = !descriptor.wallpaperUrl;
  if (els.sceneWallpaperStatus) {
    els.sceneWallpaperStatus.textContent = descriptor.wallpaperUrl
      ? `${setting.enabled ? '正在使用' : '已停用'} · ${setting.followWallpaperEngine ? '跟随 Wallpaper Engine · ' : ''}${descriptor.wallpaperName}`
      : '未添加壁纸';
    if (!descriptor.wallpaperUrl) {
      els.sceneWallpaperStatus.textContent = '柔光背景 · 跟随封面取色';
    }
  }
}

function setSceneWallpaperForPreset(preset, wallpaper, enabled = true) {
  if (!SCENE_WALLPAPER_PRESETS.includes(preset) || !wallpaper) return false;
  const wallpaperUrl = sceneWallpaperTextureUrl(wallpaper);
  if (!wallpaperUrl) {
    toast('该壁纸没有可用的图片预览或视频源，不能作为场景贴图');
    return false;
  }
  const previous = sceneWallpaperSetting(preset);
  state.sceneWallpaperSettings[preset] = normalizeSceneWallpaperSetting({
    ...previous,
    enabled,
    followWallpaperEngine: false,
    wallpaperId: safeText(wallpaper.id, ''),
    wallpaperUrl,
    wallpaperName: safeText(wallpaper.name, '场景壁纸'),
    mediaKind: safeText(wallpaper.kind, 'image') === 'video' ? 'video' : 'image',
    opacity: previous.wallpaperId ? previous.opacity : 1
  });
  saveSceneWallpaperPrefs();
  syncSceneWallpaperSurface(preset);
  syncSceneWallpaperControl();
  renderDiySelectedPresetConfig();
  requestOrbFrame();
  saveVisualSettingsPreferences();
  return true;
}

function currentSceneWallpaperChoice() {
  return wallpaperById(state.wallpaperEngineActiveId)
    || wallpaperById(state.activeWallpaperId);
}

function setSceneWallpaperFollowEngine(preset, enabled = true) {
  if (!SCENE_WALLPAPER_PRESETS.includes(preset)) return false;
  const wallpaper = wallpaperById(state.wallpaperEngineActiveId);
  if (!wallpaper || !sceneWallpaperTextureUrl(wallpaper)) {
    toast('暂未识别到 Wallpaper Engine 当前正在播放的壁纸');
    void refreshSceneWallpaperCatalog({ force: true, live: true });
    return false;
  }
  const previous = sceneWallpaperSetting(preset);
  state.sceneWallpaperSettings[preset] = normalizeSceneWallpaperSetting({
    ...previous,
    enabled,
    followWallpaperEngine: true,
    wallpaperId: safeText(wallpaper.id, ''),
    wallpaperUrl: sceneWallpaperTextureUrl(wallpaper),
    wallpaperName: safeText(wallpaper.name, 'Wallpaper Engine 当前壁纸'),
    mediaKind: safeText(wallpaper.kind, 'image') === 'video' ? 'video' : 'image'
  });
  saveSceneWallpaperPrefs();
  syncSceneWallpaperSurface(preset);
  syncSceneWallpaperControl();
  syncSceneWallpaperLiveRefresh();
  renderDiySelectedPresetConfig();
  requestOrbFrame();
  return true;
}

function updateSceneWallpaperSetting(preset, patch) {
  if (!SCENE_WALLPAPER_PRESETS.includes(preset)) return;
  state.sceneWallpaperSettings[preset] = normalizeSceneWallpaperSetting({
    ...sceneWallpaperSetting(preset),
    ...(patch || {})
  });
  saveSceneWallpaperPrefs();
  syncSceneWallpaperSurface(preset);
  syncSceneWallpaperControl();
  renderDiySelectedPresetConfig();
  requestOrbFrame();
  saveVisualSettingsPreferences();
}

function removeSceneWallpaper(preset) {
  if (!SCENE_WALLPAPER_PRESETS.includes(preset)) return;
  const opacity = sceneWallpaperSetting(preset)?.opacity || 1;
  state.sceneWallpaperSettings[preset] = normalizeSceneWallpaperSetting({ opacity });
  saveSceneWallpaperPrefs();
  syncSceneWallpaperSurface(preset);
  syncSceneWallpaperControl();
  renderDiySelectedPresetConfig();
  requestOrbFrame();
}

function selectSoftGlowBackground(preset = state.scenePreset) {
  if (!SCENE_WALLPAPER_PRESETS.includes(preset)) return false;
  removeSceneWallpaper(preset);
  if (preset === 'cover-particles') {
    state.coverParticle.backgroundEnabled = true;
    updateCoverParticleBackgroundMode();
  }
  setWallpaperStatus('已切回柔光背景 · 跟随封面取色');
  return true;
}

async function importSceneWallpaperFiles(files, preset = state.diyPreset) {
  await importWallpaperFiles(files);
  const imported = wallpaperById(state.activeWallpaperId);
  if (imported) setSceneWallpaperForPreset(preset, imported, true);
}

function visibleWallpapers() {
  const source = state.wallpaperSource === 'live' ? 'wallpaper-engine' : 'imported';
  return state.wallpapers.filter((wallpaper) => wallpaper && wallpaper.source === source);
}

function setWallpaperStatus(text) {
  if (els.wallpaperStatus) els.wallpaperStatus.textContent = text;
}

function updateWallpaperDiyVars() {
  if (els.wallpaperScene) {
    els.wallpaperScene.style.setProperty('--wallpaper-opacity', state.wallpaperOpacity.toFixed(2));
    els.wallpaperScene.style.setProperty('--wallpaper-brightness', state.wallpaperBrightness.toFixed(2));
    els.wallpaperScene.style.setProperty('--wallpaper-blur', `${Math.round(state.wallpaperBlur)}px`);
    els.wallpaperScene.dataset.wallpaperFit = state.wallpaperFitMode;
  }
  document.querySelectorAll('[data-wallpaper-fit]').forEach((button) => {
    const active = button.dataset.wallpaperFit === state.wallpaperFitMode;
    button.classList.toggle('is-active', active);
    button.setAttribute('aria-pressed', String(active));
  });
  if (els.wallpaperOpacityRange) els.wallpaperOpacityRange.value = String(Math.round(state.wallpaperOpacity * 100));
  if (els.wallpaperOpacityValue) els.wallpaperOpacityValue.textContent = `${Math.round(state.wallpaperOpacity * 100)}%`;
  if (els.wallpaperBrightnessRange) els.wallpaperBrightnessRange.value = String(Math.round(state.wallpaperBrightness * 100));
  if (els.wallpaperBrightnessValue) els.wallpaperBrightnessValue.textContent = `${Math.round(state.wallpaperBrightness * 100)}%`;
  if (els.wallpaperBlurRange) els.wallpaperBlurRange.value = String(Math.round(state.wallpaperBlur));
  if (els.wallpaperBlurValue) els.wallpaperBlurValue.textContent = `${Math.round(state.wallpaperBlur)}px`;
  if (els.wallpaperScaleRange) els.wallpaperScaleRange.value = String(Math.round(state.wallpaperScale * 100));
  if (els.wallpaperScaleValue) els.wallpaperScaleValue.textContent = `${Math.round(state.wallpaperScale * 100)}%`;
  [
    els.wallpaperOpacityRange,
    els.wallpaperBrightnessRange,
    els.wallpaperBlurRange,
    els.wallpaperScaleRange
  ].forEach(syncElasticRangeVisual);
}

function currentWallpaperIntrinsicSize() {
  if (els.wallpaperImage && !els.wallpaperImage.hidden && els.wallpaperImage.naturalWidth && els.wallpaperImage.naturalHeight) {
    return {
      width: els.wallpaperImage.naturalWidth,
      height: els.wallpaperImage.naturalHeight
    };
  }
  if (els.wallpaperVideo && !els.wallpaperVideo.hidden && els.wallpaperVideo.videoWidth && els.wallpaperVideo.videoHeight) {
    return {
      width: els.wallpaperVideo.videoWidth,
      height: els.wallpaperVideo.videoHeight
    };
  }
  return {
    width: state.wallpaperMediaWidth,
    height: state.wallpaperMediaHeight
  };
}

function scheduleWallpaperAutoSize() {
  if (wallpaperResizeFrame) return;
  wallpaperResizeFrame = window.requestAnimationFrame(() => {
    wallpaperResizeFrame = 0;
    updateWallpaperAutoSize();
  });
}

function initWallpaperAutoSizeObserver() {
  if (!els.wallpaperScene) return;
  if ('ResizeObserver' in window) {
    wallpaperResizeObserver = new ResizeObserver(scheduleWallpaperAutoSize);
    wallpaperResizeObserver.observe(els.wallpaperScene);
  } else {
    window.addEventListener('resize', scheduleWallpaperAutoSize, { passive: true });
  }
}

function updateWallpaperAutoSize() {
  if (!els.wallpaperScene) return;
  const rect = els.wallpaperScene.getBoundingClientRect();
  const sceneWidth = rect.width || window.innerWidth || document.documentElement.clientWidth || 0;
  const sceneHeight = rect.height || window.innerHeight || document.documentElement.clientHeight || 0;
  const intrinsic = currentWallpaperIntrinsicSize();
  const mediaWidth = intrinsic.width;
  const mediaHeight = intrinsic.height;
  const fitMode = normalizeWallpaperFitMode(state.wallpaperFitMode);
  const userScale = clamp(Number(state.wallpaperScale) || 1, 0.7, 1);
  const tileImage = fitMode === 'tile' && els.wallpaperImage && !els.wallpaperImage.hidden;

  els.wallpaperScene.classList.toggle('is-wallpaper-tile', !!tileImage);

  if (!sceneWidth || !sceneHeight || !mediaWidth || !mediaHeight) {
    els.wallpaperScene.style.setProperty('--wallpaper-fit', fitMode === 'stretch' ? 'fill' : 'cover');
    els.wallpaperScene.style.setProperty('--wallpaper-render-width', '100%');
    els.wallpaperScene.style.setProperty('--wallpaper-render-height', '100%');
    return;
  }

  const widthScale = sceneWidth / mediaWidth;
  const heightScale = sceneHeight / mediaHeight;
  let renderWidth = sceneWidth;
  let renderHeight = sceneHeight;

  if (fitMode === 'stretch') {
    els.wallpaperScene.style.setProperty('--wallpaper-fit', 'fill');
  } else if (fitMode === 'center' || fitMode === 'tile') {
    els.wallpaperScene.style.setProperty('--wallpaper-fit', 'contain');
    renderWidth = Math.max(1, Math.ceil(mediaWidth * userScale));
    renderHeight = Math.max(1, Math.ceil(mediaHeight * userScale));
  } else {
    const modeScale = fitMode === 'fill' ? Math.max(userScale, 1) : userScale;
    const fitScale = (fitMode === 'fit' ? Math.min(widthScale, heightScale) : Math.max(widthScale, heightScale)) * modeScale;
    els.wallpaperScene.style.setProperty('--wallpaper-fit', 'contain');
    renderWidth = Math.max(1, Math.ceil(mediaWidth * fitScale));
    renderHeight = Math.max(1, Math.ceil(mediaHeight * fitScale));
  }
  els.wallpaperScene.style.setProperty('--wallpaper-render-width', `${renderWidth}px`);
  els.wallpaperScene.style.setProperty('--wallpaper-render-height', `${renderHeight}px`);
}

function setWallpaperFitMode(mode) {
  state.wallpaperFitMode = normalizeWallpaperFitMode(mode);
  updateWallpaperDiyVars();
  scheduleWallpaperAutoSize();
  saveWallpaperPrefs();
}

function setWallpaperMediaSize(width, height) {
  state.wallpaperMediaWidth = Number(width) || 0;
  state.wallpaperMediaHeight = Number(height) || 0;
  updateWallpaperAutoSize();
}

function unloadWallpaperWebFrame() {
  if (!els.wallpaperWebFrame) return;
  els.wallpaperWebFrame.onload = null;
  els.wallpaperWebFrame.onerror = null;
  els.wallpaperWebFrame.hidden = true;
  els.wallpaperWebFrame.removeAttribute('data-active-src');
  if (els.wallpaperWebFrame.getAttribute('src') !== 'about:blank') {
    els.wallpaperWebFrame.src = 'about:blank';
  }
}

function wallpaperPresetVisible() {
  return state.playbackPage && state.diyPreset === 'wallpaper';
}

function releaseWallpaperMedia() {
  if (els.wallpaperImage) {
    els.wallpaperImage.onload = null;
    els.wallpaperImage.onerror = null;
    els.wallpaperImage.hidden = true;
    els.wallpaperImage.removeAttribute('src');
  }
  if (els.wallpaperVideo) {
    window.FeWallpaperVideoContinuity?.release?.(els.wallpaperVideo);
    els.wallpaperVideo.oncanplay = null;
    els.wallpaperVideo.onerror = null;
    els.wallpaperVideo.onloadedmetadata = null;
    els.wallpaperVideo.onloadeddata = null;
    els.wallpaperVideo.pause();
    els.wallpaperVideo.hidden = true;
    els.wallpaperVideo.removeAttribute('src');
    els.wallpaperVideo.load();
  }
  unloadWallpaperWebFrame();
  if (els.wallpaperScene) delete els.wallpaperScene.dataset.mediaSignature;
  els.wallpaperScene?.style.removeProperty('--wallpaper-tile-image');
  setWallpaperMediaSize(0, 0);
}

async function activateNativeWallpaperScene(wallpaper) {
  if (!wallpaper || wallpaper.kind !== 'scene' || wallpaper.requiresNativeEngine !== true) return false;
  const wallpaperId = safeText(wallpaper.id, '');
  if (!wallpaperId || state.wallpaperNativeActivationPending === wallpaperId) return false;
  state.wallpaperNativeActivationPending = wallpaperId;
  const wallpaperName = safeText(wallpaper.name, '场景壁纸');
  setWallpaperStatus(`正在索引「${wallpaperName}」的场景文件、着色器与脚本资源...`);
  try {
    const inventoryUrl = safeText(wallpaper.sceneInventoryUrl, '');
    if (inventoryUrl.startsWith('/api/wallpapers/scene?')) {
      try {
        const inventory = await apiJson(`${inventoryUrl}&refresh=true&limit=0`);
        const projectFiles = Math.max(0, Number(inventory.projectFileCount) || 0);
        const packageEntries = Math.max(0, Number(inventory.packageEntryCount) || 0);
        setWallpaperStatus(
          `已索引 ${projectFiles} 个项目文件和 ${packageEntries} 个包内资源，正在提交给 Wallpaper Engine 原生运行时...`
        );
      } catch (inventoryError) {
        console.warn('Wallpaper Engine scene inventory refresh failed; activating natively', inventoryError);
        setWallpaperStatus(`场景资源索引暂未完成，正在直接提交给 Wallpaper Engine：${wallpaperName}`);
      }
    }
    const payload = await apiJson('/api/wallpapers/activate', {
      method: 'POST',
      body: JSON.stringify({ id: wallpaperId })
    });
    state.wallpaperNativeActivationId = wallpaperId;
    setWallpaperStatus(payload.message || '场景壁纸已通过 Wallpaper Engine 应用到桌面');
    return true;
  } catch (error) {
    setWallpaperStatus(error.message || '无法启动 Wallpaper Engine 场景壁纸');
    return false;
  } finally {
    if (state.wallpaperNativeActivationPending === wallpaperId) {
      state.wallpaperNativeActivationPending = '';
    }
  }
}

function applyWallpaperMedia(wallpaper) {
  if (!els.wallpaperImage || !els.wallpaperVideo || !els.wallpaperEmpty) return;
  const wallpaperKind = safeText(wallpaper?.kind, 'image');
  const imageUrl = safeText(
    wallpaperKind === 'scene' ? (wallpaper?.previewUrl || wallpaper?.url) : wallpaper?.url,
    ''
  );
  const webEntryUrl = safeText(wallpaper?.entryUrl, '');
  const hasWallpaper = !!wallpaper && (
    (wallpaperKind === 'web' && !!webEntryUrl)
    || (wallpaperKind === 'scene' && (!!imageUrl || wallpaper.requiresNativeEngine === true))
    || !!imageUrl
  );
  const signatureUrl = wallpaperKind === 'web' ? webEntryUrl : imageUrl;
  const signature = hasWallpaper ? `${wallpaperKind}:${signatureUrl}` : '';
  const mediaSignature = els.wallpaperScene?.dataset.mediaSignature || '';
  els.wallpaperEmpty.textContent = '导入或选择壁纸';
  els.wallpaperEmpty.hidden = hasWallpaper;
  if (hasWallpaper && mediaSignature === signature) {
    if (wallpaperKind === 'video') {
      window.FeWallpaperVideoContinuity?.prepare(els.wallpaperVideo);
      els.wallpaperVideo.hidden = false;
      els.wallpaperVideo.play().catch(() => {});
    }
    return;
  }
  releaseWallpaperMedia();
  if (!hasWallpaper) return;
  if (els.wallpaperScene) els.wallpaperScene.dataset.mediaSignature = signature;

  if (wallpaperKind === 'web' && els.wallpaperWebFrame) {
    els.wallpaperWebFrame.onload = () => setWallpaperStatus(`网页壁纸「${safeText(wallpaper.name, 'Wallpaper')}」已加载`);
    els.wallpaperWebFrame.onerror = () => setWallpaperStatus('网页壁纸加载失败，请刷新 Wallpaper Engine 列表');
    els.wallpaperWebFrame.dataset.activeSrc = webEntryUrl;
    els.wallpaperWebFrame.src = webEntryUrl;
    els.wallpaperWebFrame.hidden = false;
    return;
  }

  if (wallpaperKind === 'video') {
    els.wallpaperVideo.preload = 'auto';
    els.wallpaperVideo.muted = true;
    els.wallpaperVideo.playsInline = true;
    window.FeWallpaperVideoContinuity?.prepare(els.wallpaperVideo);
    els.wallpaperVideo.onloadedmetadata = () => setWallpaperMediaSize(els.wallpaperVideo.videoWidth, els.wallpaperVideo.videoHeight);
    els.wallpaperVideo.onerror = () => setWallpaperStatus('动态壁纸加载失败，可尝试切换实时壁纸或更换视频编码');
    els.wallpaperVideo.oncanplay = () => els.wallpaperVideo.play().catch(() => {});
    els.wallpaperVideo.src = wallpaper.url;
    els.wallpaperVideo.hidden = false;
    els.wallpaperVideo.load();
    els.wallpaperVideo.play().catch(() => {});
    return;
  }

  if (!imageUrl) {
    els.wallpaperEmpty.textContent = wallpaperKind === 'scene'
      ? '选择后由 Wallpaper Engine 原生加载场景'
      : '壁纸预览不可用';
    els.wallpaperEmpty.hidden = false;
    return;
  }

  els.wallpaperImage.onload = () => setWallpaperMediaSize(els.wallpaperImage.naturalWidth, els.wallpaperImage.naturalHeight);
  els.wallpaperImage.onerror = () => setWallpaperStatus('壁纸图片加载失败，可尝试重新导入');
  els.wallpaperScene?.style.setProperty('--wallpaper-tile-image', `url(${JSON.stringify(imageUrl)})`);
  els.wallpaperImage.src = imageUrl;
  els.wallpaperImage.hidden = false;
}

function renderWallpaperList() {
  if (!els.wallpaperList) return;
  els.wallpaperList.textContent = '';
  const wallpapers = visibleWallpapers();
  const active = wallpapers.find((wallpaper) => String(wallpaper.id) === String(state.activeWallpaperId)) || wallpapers[0] || null;
  if (active && active.id !== state.activeWallpaperId) state.activeWallpaperId = active.id;
  state.activeWallpaperIds[state.wallpaperSource] = active?.id || '';
  if (wallpaperPresetVisible()) applyWallpaperMedia(active);
  else releaseWallpaperMedia();

  if (!wallpapers.length) {
    const empty = document.createElement('div');
    empty.className = 'diy-wallpaper-status';
    empty.textContent = state.wallpaperSource === 'live'
      ? '未识别到 Wallpaper Engine 库壁纸'
      : '没有已导入壁纸，先添加本地图片、GIF 或视频';
    els.wallpaperList.appendChild(empty);
    setWallpaperStatus(state.wallpaperSource === 'live' ? '实时壁纸为空' : '已导入壁纸为空');
    return;
  }

  wallpapers.forEach((wallpaper) => {
    const button = document.createElement('button');
    button.className = 'diy-wallpaper-item';
    button.type = 'button';
    button.dataset.wallpaperId = wallpaper.id;
    button.setAttribute('role', 'option');
    button.setAttribute('aria-selected', String(wallpaper.id === state.activeWallpaperId));
    button.classList.toggle('is-active', wallpaper.id === state.activeWallpaperId);

    const thumb = document.createElement('span');
    thumb.className = 'diy-wallpaper-thumb';
    const thumbnailUrl = wallpaper.previewUrl || (wallpaper.kind === 'video' ? '' : wallpaper.url);
    if (thumbnailUrl) {
      const image = document.createElement('img');
      image.alt = '';
      image.loading = 'lazy';
      image.decoding = 'async';
      image.src = thumbnailUrl;
      thumb.appendChild(image);
    }
    if (wallpaper.kind === 'video') {
      const videoMark = document.createElement('span');
      videoMark.className = 'diy-wallpaper-video-mark';
      videoMark.textContent = '动态';
      thumb.appendChild(videoMark);
    }

    const copy = document.createElement('span');
    copy.className = 'diy-wallpaper-copy';
    const title = document.createElement('strong');
    title.textContent = safeText(wallpaper.name, 'Wallpaper');
    const source = document.createElement('small');
    source.textContent = wallpaper.source === 'wallpaper-engine'
      ? `${wallpaper.active === true ? '正在播放 · ' : ''}Wallpaper Engine`
      : '已导入';
    copy.appendChild(title);
    copy.appendChild(source);

    const kind = document.createElement('span');
    kind.className = 'diy-wallpaper-kind';
    kind.textContent = wallpaper.kind === 'video'
      ? '动态'
      : wallpaper.kind === 'web'
        ? '网页'
        : wallpaper.kind === 'scene'
          ? `场景${Number(wallpaper.packageEntryCount) > 0 ? ` · ${Number(wallpaper.packageEntryCount)} 资源` : ''}`
          : '图片';

    button.appendChild(thumb);
    button.appendChild(copy);
    button.appendChild(kind);
    button.addEventListener('click', () => selectWallpaper(wallpaper.id));
    els.wallpaperList.appendChild(button);
  });

  setWallpaperStatus(`${wallpapers.length} 个${state.wallpaperSource === 'live' ? '实时' : '已导入'}壁纸可用`);
}

function selectWallpaper(id) {
  const wallpaper = wallpaperById(id);
  if (!wallpaper) return;
  state.activeWallpaperId = wallpaper.id;
  state.activeWallpaperIds[state.wallpaperSource] = wallpaper.id;
  if (SCENE_WALLPAPER_PRESETS.includes(state.scenePreset)) {
    setSceneWallpaperForPreset(state.scenePreset, wallpaper, true);
  }
  saveWallpaperPrefs();
  renderWallpaperList();
  if (wallpaper.kind === 'scene') activateNativeWallpaperScene(wallpaper);
}

async function refreshWallpapers(options = {}) {
  const requestedSource = options.source === 'live' || options.source === 'imported'
    ? options.source
    : state.wallpaperSource;
  state.wallpaperSource = requestedSource;
  if (state.wallpaperLoading) return;
  state.wallpaperLoading = true;
  setWallpaperStatus(requestedSource === 'live' ? '正在识别 Wallpaper Engine 库...' : '正在加载已导入壁纸...');
  try {
    const scan = options.scan ?? requestedSource === 'live';
    const payload = await apiJson(`/api/wallpapers?${query({ scan })}`);
    if (state.wallpaperSource !== requestedSource) return;
    const items = Array.isArray(payload.wallpapers) ? payload.wallpapers : [];
    const sources = [requestedSource];
    const otherSource = requestedSource === 'live' ? 'imported' : 'live';
    const otherCatalogSource = otherSource === 'live' ? 'wallpaper-engine' : 'imported';
    if (items.some((wallpaper) => wallpaper?.source === otherCatalogSource)) sources.push(otherSource);
    replaceLoadedWallpaperCatalogs(items, sources);
    if (requestedSource === 'live') {
      state.wallpaperEngineCatalogRevision = safeText(payload.catalogRevision, '');
      state.wallpaperEngineActiveId = safeText(
        payload.activeWallpaperId,
        safeText(Array.isArray(payload.activeWallpaperIds) ? payload.activeWallpaperIds[0] : '', '')
      );
      if (!state.activeWallpaperIds.live && state.wallpaperEngineActiveId) {
        state.activeWallpaperIds.live = state.wallpaperEngineActiveId;
        state.activeWallpaperId = state.wallpaperEngineActiveId;
        saveWallpaperPrefs();
      }
      state.wallpaperEngineCatalogLoaded = true;
      syncAllSceneWallpaperSurfaces();
    }
    syncCommunityMessageBackground();
    if (state.community.messageBackgroundMenuOpen) renderCommunityMessageBackgroundChoices();
    renderWallpaperList();
    syncSceneWallpaperLiveRefresh();
  } catch (error) {
    if (state.wallpaperSource === requestedSource) setWallpaperStatus(error.message || '壁纸加载失败');
  } finally {
    state.wallpaperLoading = false;
    if (state.wallpaperSource !== requestedSource) {
      refreshWallpapers({ source: state.wallpaperSource });
    }
  }
}

async function importWallpaperFiles(files) {
  const list = Array.from(files || []);
  if (!list.length) return;
  state.wallpaperSource = 'imported';
  setWallpaperStatus('正在导入壁纸...');
  for (const file of list) {
    setWallpaperStatus(`正在导入 ${file.name}...`);
    const response = await fetch(`/api/wallpapers/import?${query({ name: file.name })}`, {
      method: 'POST',
      headers: { 'Content-Type': file.type || 'application/octet-stream' },
      body: file
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok || payload.ok === false) {
      throw new Error(payload.error || `导入失败: ${file.name}`);
    }
    if (payload.wallpaper) state.activeWallpaperId = payload.wallpaper.id;
  }
  await refreshWallpapers({ source: 'imported', scan: false });
  saveWallpaperPrefs();
}

function updateWallpaperVisibility() {
  const visible = wallpaperPresetVisible();
  if (els.wallpaperScene) els.wallpaperScene.hidden = !visible;
  els.appShell.classList.toggle('has-wallpaper-mode', visible);
  if (visible) {
    const mediaMissing = (!els.wallpaperImage || els.wallpaperImage.hidden)
      && (!els.wallpaperVideo || els.wallpaperVideo.hidden)
      && (!els.wallpaperWebFrame || els.wallpaperWebFrame.hidden);
    if (mediaMissing && visibleWallpapers().length) renderWallpaperList();
    updateWallpaperAutoSize();
  }
  if (visible && !state.wallpapers.length && !state.wallpaperLoading) refreshWallpapers({ source: state.wallpaperSource });
  if (!visible) releaseWallpaperMedia();
  if (visible && els.wallpaperVideo && !els.wallpaperVideo.hidden) els.wallpaperVideo.play().catch(() => {});
}

function coverParticlePresetVisible() {
  return state.playbackPage && isCoverParticlePreset();
}

function playCoverParticleEngine() {
  const cover = state.coverParticle;
  const container = cover.engineContainer;
  if (!cover.engineVisible || !coverParticlePresetVisible() || !isPlaybackClockRunning() || cover.enginePlaying || typeof container?.play !== 'function') return;
  try {
    container.play();
    cover.enginePlaying = true;
  } catch (error) {}
}

function pauseCoverParticleEngine(force = false) {
  const cover = state.coverParticle;
  const container = cover.engineContainer;
  if (!container || (!force && !cover.enginePlaying)) return;
  if (typeof container.pause === 'function') {
    try { container.pause(); } catch (error) {}
  }
  cover.enginePlaying = false;
}

function disposeCoverParticleResources() {
  const cover = state.coverParticle;
  pauseCoverParticleEngine(true);
  cover.imageSignature = '';
  if (cover.image) {
    cover.image.onload = null;
    cover.image.onerror = null;
    cover.image.removeAttribute?.('src');
    cover.image = null;
  }
  const engineContainer = cover.engineContainer;
  cover.engineContainer = null;
  if (typeof engineContainer?.destroy === 'function') {
    try {
      engineContainer.destroy();
    } catch (error) {}
  }

  if (cover.gpuPoints && cover.gpuScene) cover.gpuScene.remove(cover.gpuPoints);
  cover.gpuGeometry?.dispose?.();
  cover.gpuMaterial?.dispose?.();
  cover.gpuRenderer?.renderLists?.dispose?.();
  cover.gpuRenderer?.dispose?.();
  cover.gpuRenderer = null;
  cover.gpuScene = null;
  cover.gpuCamera = null;
  cover.gpuGeometry = null;
  cover.gpuMaterial = null;
  cover.gpuPoints = null;
  cover.gpuSignature = '';
  cover.gpuRenderSignature = '';
  cover.gpuWidth = 0;
  cover.gpuHeight = 0;
  cover.gpuFailed = false;
  cover.particles = [];
  cover.sampleSignature = '';
  cover.energy = 0;
  cover.motionGate = 0;
  cover.wholeJump = 0;
  cover.bassJitter = 0;
  cover.lastWidth = 0;
  cover.lastHeight = 0;
  cover.lastDpr = 0;
  cover.fallbackGlowContext = null;
  cover.fallbackGlowBase = null;
  cover.fallbackGlowEnergy = null;
  cover.fallbackGlowWidth = 0;
  cover.fallbackGlowHeight = 0;
  cover.fallbackGlowCoverSize = 0;
  cover.fallbackLastFrameAt = 0;
  cover.renderFrame = { canvas: null, cssWidth: 0, cssHeight: 0, width: 0, height: 0 };

  const canvas = els.coverParticleCanvas;
  if (canvas) {
    canvas.width = 1;
    canvas.height = 1;
    canvas.style.width = '1px';
    canvas.style.height = '1px';
  }
  state.coverParticle.wallpaperRequestId += 1;
  disposeCoverParticleWallpaperMedia();
  state.coverParticle.wallpaperSignature = '';
  const wallpaperCanvas = els.coverParticleWallpaperCanvas;
  if (wallpaperCanvas) {
    wallpaperCanvas.width = 1;
    wallpaperCanvas.height = 1;
    wallpaperCanvas.hidden = true;
  }
  els.coverParticleScene?.classList.remove('has-scene-wallpaper');
}

function updateCoverParticleVisibility() {
  const visible = coverParticlePresetVisible();
  const visibilityChanged = visible !== state.coverParticle.engineVisible;
  state.coverParticle.engineVisible = visible;
  if (els.coverParticleScene) els.coverParticleScene.hidden = !visible;
  if (els.appShell) els.appShell.classList.toggle('has-cover-particle-scene', visible);
  updateCoverParticleBackgroundMode();
  if (visible) {
    applyCoverParticlePalette(state.coverParticle.palette || fallbackLyricPalette(state.currentSong));
    updateCoverParticleImage(state.currentSong);
    if (visibilityChanged) ensureCoverParticleEngine().then(playCoverParticleEngine);
    syncSceneWallpaperSurface('cover-particles');
  } else if (
    visibilityChanged
    || state.coverParticle.gpuRenderer
    || state.coverParticle.particles.length
    || state.coverParticle.wallpaperImage
  ) {
    disposeCoverParticleResources();
  }
}

function updateCoverParticleBackgroundMode() {
  const enabled = !!state.coverParticle.backgroundEnabled && coverParticlePresetVisible();
  if (els.coverParticleScene) els.coverParticleScene.classList.toggle('has-soft-background', enabled);
  if (els.diyCoverParticleBackgroundToggle) {
    const backgroundEnabled = !!state.coverParticle.backgroundEnabled;
    if (els.diyCoverParticleBackgroundToggle.checked !== backgroundEnabled) {
      els.diyCoverParticleBackgroundToggle.checked = backgroundEnabled;
    }
    const ariaPressed = String(backgroundEnabled);
    if (els.diyCoverParticleBackgroundToggle.getAttribute('aria-pressed') !== ariaPressed) {
      els.diyCoverParticleBackgroundToggle.setAttribute('aria-pressed', ariaPressed);
    }
  }
  if (els.diyCoverParticleBackgroundValue) {
    const backgroundValue = state.coverParticle.backgroundEnabled ? 'ON' : 'OFF';
    if (els.diyCoverParticleBackgroundValue.textContent !== backgroundValue) {
      els.diyCoverParticleBackgroundValue.textContent = backgroundValue;
    }
  }
  const motionPercent = coverParticleMotionPercent();
  if (els.diyCoverParticleMotionRange) {
    const motionValue = String(motionPercent);
    const motionAriaValue = `${motionPercent}%`;
    if (els.diyCoverParticleMotionRange.value !== motionValue) {
      els.diyCoverParticleMotionRange.value = motionValue;
    }
    if (els.diyCoverParticleMotionRange.getAttribute('aria-valuetext') !== motionAriaValue) {
      els.diyCoverParticleMotionRange.setAttribute('aria-valuetext', motionAriaValue);
    }
    syncElasticRangeVisual(els.diyCoverParticleMotionRange);
  }
  if (els.diyCoverParticleMotionValue) {
    const motionValue = `${motionPercent}%`;
    if (els.diyCoverParticleMotionValue.textContent !== motionValue) {
      els.diyCoverParticleMotionValue.textContent = motionValue;
    }
  }
  const floatSpeedPercent = coverParticleFloatSpeedPercent();
  if (els.diyCoverParticleFloatSpeedRange) {
    const floatSpeedValue = String(floatSpeedPercent);
    const floatSpeedAriaValue = `${floatSpeedPercent}%`;
    if (els.diyCoverParticleFloatSpeedRange.value !== floatSpeedValue) {
      els.diyCoverParticleFloatSpeedRange.value = floatSpeedValue;
    }
    if (els.diyCoverParticleFloatSpeedRange.getAttribute('aria-valuetext') !== floatSpeedAriaValue) {
      els.diyCoverParticleFloatSpeedRange.setAttribute('aria-valuetext', floatSpeedAriaValue);
    }
    syncElasticRangeVisual(els.diyCoverParticleFloatSpeedRange);
  }
  if (els.diyCoverParticleFloatSpeedValue) {
    const floatSpeedValue = `${floatSpeedPercent}%`;
    if (els.diyCoverParticleFloatSpeedValue.textContent !== floatSpeedValue) {
      els.diyCoverParticleFloatSpeedValue.textContent = floatSpeedValue;
    }
  }
}

function coverParticleMotionPercent() {
  return Math.round(clamp(Number(state.coverParticle.motionAmplitude) || 0, 0, 2) * 100);
}

function coverParticleMotionScale() {
  return clamp(Number(state.coverParticle.motionAmplitude) || 0, 0, 2) * (reducedMotion ? 0.35 : 1);
}

function coverParticleFloatSpeedPercent() {
  return Math.round(normalizeCoverParticleFloatSpeed(state.coverParticle.floatSpeed) * 100);
}

function coverParticleFloatSpeedScale() {
  return normalizeCoverParticleFloatSpeed(state.coverParticle.floatSpeed);
}

function addSonicTopographyRipple(x, z, strength = 1, white = false) {
  const topo = state.sonicTopography;
  if (!topo.ripples.length) return;
  const index = topo.rippleIndex % topo.ripples.length;
  const ripple = topo.ripples[index];
  ripple.pos.set(
    clamp(x, -SONIC_TOPOGRAPHY_HALF, SONIC_TOPOGRAPHY_HALF),
    clamp(z, -SONIC_TOPOGRAPHY_HALF, SONIC_TOPOGRAPHY_HALF)
  );
  ripple.time = performance.now() / 1000;
  ripple.strength = clamp(strength, 0.14, 4);
  ripple.isActive = 1;
  ripple.rippleType = white ? 1 : 0;
  topo.rippleIndex = (index + 1) % topo.ripples.length;
}

function addSonicTopographyPointerRipple(event) {
  const topo = state.sonicTopography;
  if (!topo.built || !isSonicTopographyPreset() || !topo.camera || !window.THREE) return;
  const THREE = window.THREE;
  const rect = els.stage.getBoundingClientRect();
  const pointer = new THREE.Vector2(
    ((event.clientX - rect.left) / Math.max(1, rect.width)) * 2 - 1,
    -(((event.clientY - rect.top) / Math.max(1, rect.height)) * 2 - 1)
  );
  const raycaster = new THREE.Raycaster();
  const ground = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
  const point = new THREE.Vector3();
  raycaster.setFromCamera(pointer, topo.camera);
  if (!raycaster.ray.intersectPlane(ground, point)) return;
  const held = performance.now() - (state.playbackVisual.pressStartedAt || performance.now());
  const strength = 0.55 + Math.min(2.4, held / 560);
  addSonicTopographyRipple(point.x, point.z, strength, false);
}

function spawnSonicTopographyParticle(x, y, z, speed) {
  const topo = state.sonicTopography;
  if (!topo.particles.length) return;
  const index = topo.particleIndex % topo.particles.length;
  const particle = topo.particles[index];
  particle.active = true;
  particle.x = x + (Math.random() - 0.5) * 1.5;
  particle.y = y + (Math.random() - 0.5) * 1.5;
  particle.z = z + (Math.random() - 0.5) * 1.5;
  particle.vx = (Math.random() - 0.5) * 2;
  particle.vy = Math.random() * 2 + speed * 10;
  particle.vz = (Math.random() - 0.5) * 2;
  particle.life = 0;
  particle.maxLife = 0.65 + Math.random() * 0.55;
  particle.scale = Math.random() * 0.52 + 0.16;
  topo.particleIndex = (index + 1) % topo.particles.length;
  topo.projectilesActive = true;
}

function spawnSonicTopographyMeteor(strength = 1) {
  const topo = state.sonicTopography;
  const now = performance.now();
  if (!topo.meteors.length || now - topo.lastMeteorAt < 440) return;
  topo.lastMeteorAt = now;
  const index = topo.meteorIndex % topo.meteors.length;
  const angle = Math.random() * Math.PI * 2;
  const distance = Math.random() * 25;
  const meteor = topo.meteors[index];
  meteor.active = true;
  meteor.x = Math.cos(angle) * distance;
  meteor.z = Math.sin(angle) * distance;
  meteor.y = 30 + Math.random() * 10;
  meteor.speed = 1 + Math.random() * 0.5 + strength * 1.5;
  meteor.strength = strength;
  topo.meteorIndex = (index + 1) % topo.meteors.length;
  topo.projectilesActive = true;
}

function updateSonicTopographyProjectiles(dt) {
  const topo = state.sonicTopography;
  const dummy = topo.dummy;
  if (!dummy || !topo.meteorMesh || !topo.particleMesh || !topo.projectilesActive) return;
  const clearAll = topo.projectilesNeedClear;
  let activeRemaining = false;
  let meteorMatricesChanged = false;
  for (let i = 0; i < topo.meteors.length; i += 1) {
    const meteor = topo.meteors[i];
    if (!meteor.active) {
      if (!clearAll) continue;
      dummy.position.set(0, -1000, 0);
      dummy.rotation.set(0, 0, 0);
      dummy.scale.set(0, 0, 0);
      dummy.updateMatrix();
      topo.meteorMesh.setMatrixAt(i, dummy.matrix);
      meteorMatricesChanged = true;
      continue;
    }
    meteor.y -= meteor.speed * 60 * dt;
    if (meteor.y <= 0) {
      meteor.active = false;
      addSonicTopographyRipple(meteor.x, meteor.z, Math.min(meteor.strength, 1.2), true);
      for (let p = 0; p < 10; p += 1) spawnSonicTopographyParticle(meteor.x, 0.5, meteor.z, meteor.speed * 1.5);
      dummy.position.set(0, -1000, 0);
      dummy.scale.set(0, 0, 0);
    } else {
      activeRemaining = true;
      if (Math.random() > 0.3) spawnSonicTopographyParticle(meteor.x, meteor.y, meteor.z, meteor.speed * 0.2);
      dummy.position.set(meteor.x, Math.max(0, meteor.y), meteor.z);
      dummy.rotation.set(0, 0, 0);
      dummy.scale.set(1.5, 1.5, 1.5);
    }
    dummy.updateMatrix();
    topo.meteorMesh.setMatrixAt(i, dummy.matrix);
    meteorMatricesChanged = true;
  }
  if (meteorMatricesChanged) topo.meteorMesh.instanceMatrix.needsUpdate = true;

  let particleMatricesChanged = false;
  for (let i = 0; i < topo.particles.length; i += 1) {
    const particle = topo.particles[i];
    if (!particle.active) {
      if (!clearAll) continue;
      dummy.position.set(0, -1000, 0);
      dummy.rotation.set(0, 0, 0);
      dummy.scale.set(0, 0, 0);
      dummy.updateMatrix();
      topo.particleMesh.setMatrixAt(i, dummy.matrix);
      particleMatricesChanged = true;
      continue;
    }
    particle.life += dt;
    if (particle.life >= particle.maxLife) {
      particle.active = false;
      dummy.position.set(0, -1000, 0);
      dummy.scale.set(0, 0, 0);
    } else {
      activeRemaining = true;
      particle.x += particle.vx * dt * 10;
      particle.y += particle.vy * dt * 10;
      particle.z += particle.vz * dt * 10;
      const fade = 1 - particle.life / particle.maxLife;
      const scale = particle.scale * fade;
      dummy.position.set(particle.x, particle.y, particle.z);
      dummy.rotation.set(0, 0, 0);
      dummy.scale.set(scale, scale, scale);
    }
    dummy.updateMatrix();
    topo.particleMesh.setMatrixAt(i, dummy.matrix);
    particleMatricesChanged = true;
  }
  if (particleMatricesChanged) topo.particleMesh.instanceMatrix.needsUpdate = true;
  topo.projectilesNeedClear = false;
  topo.projectilesActive = activeRemaining;
}

function resetSonicTopographyAudioMotion(topo) {
  if (!topo) return;
  topo.lastBeat = 0;
  topo.pulseCooldown = 0;
  topo.meteorCooldown = 0;
  topo.lastFountainAt = 0;
  topo.audioPulse = 0;
  topo.audioTerrainSource = '';
  topo.audioTerrainTime = 0;
  topo.wasAudioDriving = false;
  if (topo.frameAudio) {
    topo.frameAudio.lowFrequencyAmplitude = 0;
    topo.frameAudio.subBass = 0;
    topo.frameAudio.bass = 0;
    topo.frameAudio.lowMid = 0;
    topo.frameAudio.mid = 0;
    topo.frameAudio.highMid = 0;
    topo.frameAudio.energy = 0;
    topo.frameAudio.beat = 0;
    topo.frameAudio.fluxPulse = 0;
    topo.frameAudio.fluxMeteor = 0;
    topo.frameAudio.lowFrequencyBands?.fill(0);
    topo.frameAudio.lowFrequencyBandTargets?.fill(0);
  }
  if (topo.lowFrequencySpectrumData && topo.lowFrequencySpectrum) {
    topo.lowFrequencySpectrumData.fill(0);
    topo.lowFrequencySpectrum.needsUpdate = true;
  }
  if (topo.uniforms) {
    for (const uniformName of [
      'uLowFrequencyAmplitude',
      'uSubBass',
      'uBass',
      'uLowMid',
      'uMid',
      'uHighMid',
      'uEnergy',
      'uAudioPulse'
    ]) {
      if (topo.uniforms[uniformName]) topo.uniforms[uniformName].value = 0;
    }
    if (topo.uniforms.uAudioTime) topo.uniforms.uAudioTime.value = 0;
  }
  topo.ripples.forEach((ripple) => {
    ripple.strength = 0;
    ripple.isActive = 0;
    ripple.time = -100;
  });
  topo.meteors.forEach((meteor) => {
    meteor.active = false;
    meteor.y = -1000;
  });
  topo.particles.forEach((particle) => {
    particle.active = false;
    particle.y = -1000;
  });
  topo.projectilesNeedClear = true;
  topo.projectilesActive = true;
}

// A large bass jump reaches the fast response, while small fluctuations keep
// the ordinary attack. This adds impact without hard-stepping the 512 bands or
// changing the slower release that prevents black-frame dropouts.
function sonicBassAttackResponse(current, target, attackResponse, impactAttackResponse) {
  const rise = clamp((Number(target) || 0) - (Number(current) || 0), 0, 1);
  const nonlinearRise = rise * (2 - rise);
  return attackResponse + (impactAttackResponse - attackResponse) * nonlinearRise;
}

function updateSonicTopographyMotion() {
  const topo = state.sonicTopography;
  if (!state.playbackPage || !isSonicTopographyPreset() || !topo.uniforms || !topo.renderer || !topo.scene || !topo.camera) return;
  const nowMs = performance.now();
  topo.lastRenderAt = nowMs;
  const now = nowMs / 1000;
  const dt = topo.lastMotionAt ? clamp((nowMs - topo.lastMotionAt) / 1000, 1 / 360, 0.04) : 0.016;
  const simulationStep = dt * (1000 / RENDER_PROFILE.targetFrameMs);
  topo.lastMotionAt = nowMs;

  const audioDriving = isPlaybackClockRunning();
  const activeAudioSource = String(els.audio?.currentSrc || els.audio?.src || '');
  const hasAudioSource = activeAudioSource.length > 0;
  const audioEnded = els.audio?.ended === true;
  const sourceChanged = Boolean(
    topo.audioTerrainSource
    && hasAudioSource
    && topo.audioTerrainSource !== activeAudioSource
  );
  const sameSourcePaused = !audioDriving
    && topo.wasAudioDriving
    && hasAudioSource
    && !audioEnded
    && els.audio?.paused === true
    && topo.audioTerrainSource === activeAudioSource;
  const holdPausedAudio = sameSourcePaused;
  const missingSource = !hasAudioSource;
  if (audioDriving && sourceChanged) resetSonicTopographyAudioMotion(topo);
  if (audioDriving) {
    topo.audioTerrainSource = activeAudioSource;
    topo.audioTerrainTime = (Number(topo.audioTerrainTime) || 0) + dt;
  }
  const live = audioDriving
    ? (state.audioAnalysis.live ? state.audioAnalysis : state.visual)
    : null;
  const audio = topo.frameAudio;
  const lowFrequencyAmplitudeTarget = audioDriving
    ? clamp(Math.max(
        Number(live.lowFrequencyAmplitude) || 0,
        Number(state.visual.lowFrequencyAmplitude) || 0,
        Number(live.subBass) || 0,
        Number(live.bass) || 0
      ), 0, 1)
    : 0;
  const subBassTarget = audioDriving
    ? clamp(Math.max(Number(live.subBass) || 0, Number(state.visual.lowFrequencyAmplitude) || 0), 0, 1)
    : 0;
  const bassTarget = audioDriving
    ? clamp(Math.max(Number(live.bass) || 0, Number(state.visual.bass) || 0), 0, 1)
    : 0;
  const lowMidTarget = audioDriving ? clamp(live.lowMid || 0, 0, 1) : 0;
  // This is an animation-frame hot path. Settings are normalized by
  // applySonicTopographySettings(), so allocating another full object here is redundant.
  const settings = topo.settings || DEFAULT_SONIC_SETTINGS;
  const smoothing = settings.smoothing;
  const attackResponse = 1 - Math.exp(-dt / (SONIC_BASS_COLUMN_ATTACK_SECONDS * smoothing));
  const impactAttackResponse = 1 - Math.exp(
    -dt / (SONIC_BASS_COLUMN_IMPACT_ATTACK_SECONDS * smoothing)
  );
  const releaseResponse = 1 - Math.exp(-dt / (SONIC_BASS_COLUMN_RELEASE_SECONDS * smoothing));
  if (audioDriving) {
    const lowFrequencyAttackResponse = sonicBassAttackResponse(
      audio.lowFrequencyAmplitude,
      lowFrequencyAmplitudeTarget,
      attackResponse,
      impactAttackResponse
    );
    const subBassAttackResponse = sonicBassAttackResponse(
      audio.subBass,
      subBassTarget,
      attackResponse,
      impactAttackResponse
    );
    const bassAttackResponse = sonicBassAttackResponse(
      audio.bass,
      bassTarget,
      attackResponse,
      impactAttackResponse
    );
    const lowMidAttackResponse = sonicBassAttackResponse(
      audio.lowMid,
      lowMidTarget,
      attackResponse,
      impactAttackResponse
    );
    audio.lowFrequencyAmplitude += (lowFrequencyAmplitudeTarget - audio.lowFrequencyAmplitude)
      * (lowFrequencyAmplitudeTarget > audio.lowFrequencyAmplitude
        ? lowFrequencyAttackResponse
        : releaseResponse);
    audio.subBass += (subBassTarget - audio.subBass)
      * (subBassTarget > audio.subBass ? subBassAttackResponse : releaseResponse);
    audio.bass += (bassTarget - audio.bass)
      * (bassTarget > audio.bass ? bassAttackResponse : releaseResponse);
    audio.lowMid += (lowMidTarget - audio.lowMid)
      * (lowMidTarget > audio.lowMid ? lowMidAttackResponse : releaseResponse);
  } else if (holdPausedAudio) {
    // Keep the exact last low-frequency terrain frame while the same source is paused.
  } else {
    audio.lowFrequencyAmplitude = 0;
    audio.subBass = 0;
    audio.bass = 0;
    audio.lowMid = 0;
  }
  if (audioDriving) {
    audio.mid = clamp(live.mid || 0, 0, 1);
    audio.highMid = clamp(live.highMid || 0, 0, 1);
    audio.presence = clamp(live.presence || 0, 0, 1);
    audio.brilliance = clamp(live.brilliance || 0, 0, 1);
    audio.air = clamp(live.air || 0, 0, 1);
    audio.energy = clamp(live.energy || 0, 0, 1);
    audio.warmth = clamp(live.warmth || 0, 0, 1);
    audio.brightness = clamp(live.brightness || 0, 0, 1);
    audio.sharpness = clamp(live.sharpness || 0, 0, 1);
    audio.smoothness = clamp(live.smoothness == null ? 0.7 : live.smoothness, 0, 1);
    audio.density = clamp(live.density || 0, 0, 1);
    audio.spectralCentroid = Number(live.spectralCentroid) || 0;
    audio.fluxPulse = Number(live.fluxPulse) || 0;
    audio.fluxMeteor = Number(live.fluxMeteor) || 0;
    audio.beat = clamp(state.visual.beat || 0, 0, 1);
    topo.idleTone.presence = audio.presence;
    topo.idleTone.brilliance = audio.brilliance;
    topo.idleTone.air = audio.air;
    topo.idleTone.warmth = audio.warmth;
    topo.idleTone.brightness = audio.brightness;
  } else if (!holdPausedAudio) {
    const idleTone = topo.idleTone || {};
    audio.mid = 0;
    audio.highMid = 0;
    audio.presence = clamp(idleTone.presence ?? 0.16, 0.08, 0.42);
    audio.brilliance = clamp(idleTone.brilliance ?? 0.12, 0.06, 0.36);
    audio.air = clamp(idleTone.air ?? 0.18, 0.08, 0.44);
    audio.energy = 0.08;
    audio.warmth = clamp(idleTone.warmth ?? 0.46, 0.22, 0.72);
    audio.brightness = clamp(idleTone.brightness ?? 0.34, 0.18, 0.62);
    audio.smoothness = 0.86;
    audio.sharpness = 0;
    audio.density = 0;
    audio.spectralCentroid = 0;
    audio.fluxPulse = 0;
    audio.fluxMeteor = 0;
    audio.beat = 0;
  }

  if (audioDriving) {
    const minimumUsefulBandSignal = Math.max(0.01, lowFrequencyAmplitudeTarget * 0.08);
    const liveLowFrequencyBands = live ? live.lowFrequencyBands : null;
    const visualLowFrequencyBands = state.visual.lowFrequencyBands;
    const lowFrequencyBandSource = lowFrequencyBandsHaveSignal(
      liveLowFrequencyBands,
      minimumUsefulBandSignal
    )
      ? liveLowFrequencyBands
      : lowFrequencyBandsHaveSignal(visualLowFrequencyBands, minimumUsefulBandSignal)
        ? visualLowFrequencyBands
        : null;
    writeLowFrequencyBands(
      audio.lowFrequencyBandTargets,
      lowFrequencyBandSource,
      lowFrequencyAmplitudeTarget
    );
  } else if (holdPausedAudio) {
    // Hold both current and target bands so resume continues from the frozen frame.
  } else {
    writeLowFrequencyBands(audio.lowFrequencyBandTargets, null, 0);
  }
  let fountainBand = -1;
  let fountainRise = 0;
  let fountainAmplitude = 0;
  if (topo.lowFrequencySpectrumData && topo.lowFrequencySpectrum) {
    let spectrumChanged = false;
    for (let index = 0; index < SONIC_LOW_FREQUENCY_BAND_COUNT; index += 1) {
      const targetAmplitude = audioDriving ? audio.lowFrequencyBandTargets[index] || 0 : 0;
      let amplitude = audio.lowFrequencyBands[index] || 0;
      const previousAmplitude = amplitude;
      if (audioDriving) {
        const bandAttackResponse = sonicBassAttackResponse(
          amplitude,
          targetAmplitude,
          attackResponse,
          impactAttackResponse
        );
        amplitude += (targetAmplitude - amplitude)
          * (targetAmplitude > amplitude ? bandAttackResponse : releaseResponse);
      } else if (holdPausedAudio) {
        // Keep the last encoded spectrum byte and per-band column height.
        amplitude = previousAmplitude;
      } else {
        amplitude = 0;
      }
      audio.lowFrequencyBands[index] = amplitude;
      const rise = amplitude - previousAmplitude;
      if (rise > fountainRise && amplitude > 0.08) {
        fountainBand = index;
        fountainRise = rise;
        fountainAmplitude = amplitude;
      }
      const encodedAmplitude = Math.round(clamp(amplitude, 0, 1) * 255);
      if (topo.lowFrequencySpectrumData[index] !== encodedAmplitude) {
        topo.lowFrequencySpectrumData[index] = encodedAmplitude;
        spectrumChanged = true;
      }
    }
    if (spectrumChanged) topo.lowFrequencySpectrum.needsUpdate = true;
  }

  const uniforms = topo.uniforms;
  if (uniforms.uGroundEntrance) {
    if (reducedMotion) {
      topo.groundEntranceProgress = 1;
      uniforms.uGroundEntrance.value = 1;
    } else if (topo.groundEntranceProgress < 1) {
      if (!topo.groundEntranceStartedAt) topo.groundEntranceStartedAt = nowMs;
      const groundEntranceTime = clamp(
        (nowMs - topo.groundEntranceStartedAt) / (SONIC_GROUND_ENTRANCE_SECONDS * 1000),
        0,
        1
      );
      topo.groundEntranceProgress = groundEntranceTime * groundEntranceTime
        * (3 - 2 * groundEntranceTime);
      uniforms.uGroundEntrance.value = topo.groundEntranceProgress;
    }
  }
  uniforms.uTime.value = now;
  if (uniforms.uAudioTime) uniforms.uAudioTime.value = topo.audioTerrainTime || 0;
  uniforms.uSubBass.value = audio.subBass;
  uniforms.uBass.value = audio.bass;
  uniforms.uLowFrequencyAmplitude.value = audio.lowFrequencyAmplitude;
  uniforms.uLowMid.value = audio.lowMid;
  uniforms.uMid.value = audio.mid;
  uniforms.uHighMid.value = audio.highMid;
  uniforms.uPresence.value = audio.presence;
  uniforms.uBrilliance.value = audio.brilliance;
  uniforms.uAir.value = audio.air;
  uniforms.uEnergy.value = audio.energy;
  uniforms.uWarmth.value = audio.warmth;
  uniforms.uBrightness.value = audio.brightness;
  uniforms.uSharpness.value = audio.sharpness;
  uniforms.uSmoothness.value = audio.smoothness;
  uniforms.uDensity.value = audio.density;
  uniforms.uSpectralCentroid.value = audio.spectralCentroid;
  const targetIdleBreath = holdPausedAudio
    ? uniforms.uIdleBreath.value
    : audioDriving
      ? 0.015
      : (reducedMotion ? 0.035 : 0.145);
  if (!holdPausedAudio) {
    uniforms.uIdleBreath.value += (targetIdleBreath - uniforms.uIdleBreath.value)
      * clamp(dt * 3.5, 0, 1);
  }

  const theme = topo.theme || createSonicTopographyTheme(topo.palette || fallbackLyricPalette(state.currentSong));
  const lerpSpeed = clamp(3 * dt, 0, 1);
  uniforms.uBaseColor1.value.lerp(theme.uBaseColor1, lerpSpeed);
  uniforms.uBaseColor2.value.lerp(theme.uBaseColor2, lerpSpeed);
  uniforms.uCoolCore.value.lerp(theme.uCoolCore, lerpSpeed);
  uniforms.uCoolEdge.value.lerp(theme.uCoolEdge, lerpSpeed);
  uniforms.uWarmCore.value.lerp(theme.uWarmCore, lerpSpeed);
  uniforms.uWarmEdge.value.lerp(theme.uWarmEdge, lerpSpeed);
  uniforms.uRippleColor.value.lerp(theme.uRippleColor, lerpSpeed);
  uniforms.uGlowIntensity.value += (theme.uGlowIntensity - uniforms.uGlowIntensity.value) * lerpSpeed;

  if (topo.scene.fog && topo.scene.fog.color) {
    topo.scene.fog.color.lerp(theme.uBaseColor1, lerpSpeed);
    if (settings.atmosphereEnabled && topo.tyndallLight?.color) {
      const aerialSunlightCoupling = clamp(
        0.08 + settings.fogGlow * 0.04 + settings.mistReflectance * 0.03,
        0.08,
        0.22
      );
      topo.scene.fog.color.lerp(
        topo.tyndallLight.color,
        clamp(lerpSpeed * aerialSunlightCoupling, 0, 0.04)
      );
    }
  }
  if (topo.meteorMaterial && topo.meteorMaterial.color) {
    topo.meteorTargetColor.copy(theme.uWarmCore).lerp(topo.whiteColor, 0.7);
    topo.meteorMaterial.color.lerp(topo.meteorTargetColor, lerpSpeed);
  }

  const lowBassDrive = clamp(Math.max(audio.subBass * 1.25, audio.bass), 0, 1);
  if (!audioDriving) {
    if (holdPausedAudio) {
      // Freeze the height envelope and audio time; ambient rain/fog still use uTime.
    } else {
      // Ended, sourceChanged and missingSource states must clear a held song once.
      const shouldClearHeldAudio = (
        audioEnded || sourceChanged || missingSource || !sameSourcePaused
      ) && (topo.wasAudioDriving || Boolean(topo.audioTerrainSource));
      if (shouldClearHeldAudio) resetSonicTopographyAudioMotion(topo);
      topo.wasAudioDriving = false;
      topo.audioPulse += (0 - topo.audioPulse) * clamp(dt * 5.2, 0, 1);
    }
  } else {
    topo.wasAudioDriving = true;
    if (topo.pulseCooldown > 0) topo.pulseCooldown = Math.max(0, topo.pulseCooldown - simulationStep);
    if (topo.meteorCooldown > 0) topo.meteorCooldown = Math.max(0, topo.meteorCooldown - simulationStep);
    const lowBassTransient = Math.max(0, lowBassDrive - topo.lastBeat);
    const pulseStrength = clamp(Math.max(audio.fluxPulse * 1.45, lowBassTransient * 2.2, audio.beat * lowBassDrive * 0.72), 0, 1);
    const fountainEmitter = topo.fountainEmitters[fountainBand];
    if (settings.fountainEnabled
        && fountainEmitter
        && fountainRise > 0.006
        && nowMs - topo.lastFountainAt >= 32) {
      const burstCount = 6 + Math.min(12, Math.floor(fountainRise * 28 + fountainAmplitude * 4));
      const emissionY = 0.5
        + fountainAmplitude * fountainEmitter.liftScale * settings.columnHeight;
      const emissionSpeed = 0.05 + fountainRise * 0.6 + lowBassDrive * 0.05;
      for (let particle = 0; particle < burstCount; particle += 1) {
        spawnSonicTopographyParticle(
          fountainEmitter.x,
          emissionY,
          fountainEmitter.z,
          emissionSpeed
        );
      }
      topo.lastFountainAt = nowMs;
    }
    const pulseRateBase = pulseStrength > topo.audioPulse ? 0.34 : 0.075;
    const pulseRate = 1 - Math.pow(1 - pulseRateBase, simulationStep);
    topo.audioPulse += (pulseStrength - topo.audioPulse) * pulseRate;
    if (topo.pulseCooldown <= 0 && lowBassDrive > 0.075 && pulseStrength > 0.13) {
      const angle = Math.random() * Math.PI * 2;
      const distance = Math.random() * 25;
      addSonicTopographyRipple(Math.cos(angle) * distance, Math.sin(angle) * distance, Math.min(0.42 + pulseStrength * 1.65, 2.1), false);
      topo.pulseCooldown = 42;
    }
    const meteorStrength = clamp(Math.max(audio.fluxMeteor * lowBassDrive * 0.9, audio.beat * lowBassDrive * 0.42), 0, 1);
    if (topo.meteorCooldown <= 0 && meteorStrength > 0.3) {
      spawnSonicTopographyMeteor(clamp(meteorStrength * 1.25, 0.2, 1.45));
      topo.meteorCooldown = 260;
    }
    const beatRate = 1 - Math.pow(0.76, simulationStep);
    topo.lastBeat += (lowBassDrive - topo.lastBeat) * beatRate;
  }
  uniforms.uAudioPulse.value = clamp(topo.audioPulse || 0, 0, 1);

  const atmosphereAudioDriveTarget = audioDriving && !reducedMotion ? 1 : 0;
  const atmosphereAudioDriveResponse = clamp(
    dt * (atmosphereAudioDriveTarget > topo.atmosphereAudioDrive ? 7.5 : 4.2),
    0,
    1
  );
  topo.atmosphereAudioDrive += (
    atmosphereAudioDriveTarget - topo.atmosphereAudioDrive
  ) * atmosphereAudioDriveResponse;
  if (uniforms.uAtmosphereAudioDrive) {
    uniforms.uAtmosphereAudioDrive.value = topo.atmosphereAudioDrive;
  }
  const backgroundAtmosphereUniforms = topo.backgroundMaterial?.uniforms;
  if (backgroundAtmosphereUniforms?.uAtmosphereBass) {
    const targetBassLight = lowBassDrive * topo.atmosphereAudioDrive;
    const bassLight = backgroundAtmosphereUniforms.uAtmosphereBass;
    bassLight.value += (targetBassLight - bassLight.value) * clamp(
      dt * (targetBassLight > bassLight.value ? 8.5 : 4.4),
      0,
      1
    );
  }
  if (backgroundAtmosphereUniforms?.uAtmosphereDetail) {
    const targetDetailLight = clamp(
      audio.mid * 0.14 + audio.highMid * 0.34
        + audio.presence * 0.27 + audio.brilliance * 0.31,
      0,
      1
    ) * topo.atmosphereAudioDrive;
    const detailLight = backgroundAtmosphereUniforms.uAtmosphereDetail;
    detailLight.value += (targetDetailLight - detailLight.value) * clamp(
      dt * (targetDetailLight > detailLight.value ? 10 : 5),
      0,
      1
    );
  }

  if (!topo.resizeObserver) resizeSonicTopographyRenderer();

  const starfieldFlashTarget = audioDriving
    ? clamp(audio.energy * 0.58 + audio.beat * 0.72 + audio.brilliance * 0.16, 0, 1)
    : 0;
  topo.starfieldAudio += (starfieldFlashTarget - topo.starfieldAudio) * clamp(dt * 7.5, 0, 1);
  const starfieldAudioUniform = topo.starfieldMaterial?.userData?.driftUniforms?.uStarfieldAudio;
  if (starfieldAudioUniform) starfieldAudioUniform.value = topo.starfieldAudio;

  if (settings.starfieldEnabled && topo.starfield && !reducedMotion) {
    const driftTime = topo.starfieldMaterial?.userData?.driftUniforms?.uStarfieldTime;
    if (driftTime) driftTime.value += dt;
    topo.starfield.rotation.y += dt * 0.045;
  }
  if (settings.galaxyEnabled && topo.galaxy && !reducedMotion) {
    topo.galaxy.rotation.y += dt * 0.018;
  }
  if (topo.backgroundMaterial && topo.backgroundTargetColors.length >= 3) {
    const backgroundLerp = clamp(dt * 1.65, 0, 1);
    topo.backgroundMaterial.uniforms.uBackgroundColor1.value.lerp(topo.backgroundTargetColors[0], backgroundLerp);
    topo.backgroundMaterial.uniforms.uBackgroundColor2.value.lerp(topo.backgroundTargetColors[1], backgroundLerp);
    topo.backgroundMaterial.uniforms.uBackgroundColor3.value.lerp(topo.backgroundTargetColors[2], backgroundLerp);
  }
  const tyndallColor = topo.tyndallLight?.color;
  const mistClock = uniforms.uTime.value;
  const perceptualTyndallIntensity = settings.tyndallIntensity <= 0
    ? 0
    : Math.pow(clamp(settings.tyndallIntensity / 1.5, 0, 1), 0.72) * 1.5;
  const fluorescenceScatter = clamp(settings.fluorescenceScatter / 1.5, 0, 1);
  const maxMistSceneOpacity = SONIC_TYNDALL_TOTAL_ENERGY_CAP * 0.56;
  const mistBlackLiftGuard = clamp(
    1 - settings.mistEmission * 0.36 - settings.fogDensity * 0.14,
    0.48,
    1
  );
  topo.mistBlackLiftGuard = mistBlackLiftGuard;
  const fogLayers = topo.fogLayers;
  for (let mistIndex = 0; mistIndex < fogLayers.length; mistIndex += 1) {
    const mistLayer = fogLayers[mistIndex];
    if (settings.atmosphereEnabled && !reducedMotion) {
      mistLayer.position.x -= dt * (3.2 + settings.fogSpeed * 14)
        * mistLayer.userData.speedScale * mistLayer.userData.parallax;
      if (mistLayer.position.x < -mistLayer.userData.wrap) {
        mistLayer.position.x = mistLayer.userData.wrap;
      }
      mistLayer.position.y = mistLayer.userData.baseY
        + Math.sin(mistClock * (0.075 + mistLayer.userData.parallax * 0.018) + mistLayer.userData.phase) * 0.85;
      mistLayer.material.rotation = mistLayer.userData.baseRotation
        + Math.sin(mistClock * 0.052 + mistLayer.userData.phase) * 0.012;
    }
    if (!mistLayer.material) continue;
    topo.atmosphereColor?.copy(theme.uBaseColor2);
    topo.atmosphereColor?.lerp?.(
      topo.uniforms?.uOuterColumnColor?.value,
      fluorescenceScatter * 0.52
    );
    if (settings.atmosphereEnabled && tyndallColor && topo.atmosphereColor) {
      const weakScatter = clamp(0.045 + settings.mistReflectance * 0.11 + settings.fogGlow * 0.045, 0, 0.28);
      topo.atmosphereColor.lerp(tyndallColor, weakScatter);
    }
    if (topo.atmosphereColor) mistLayer.material.color.lerp(topo.atmosphereColor, clamp(dt * 2.2, 0, 1));
    const lightCoupling = settings.tyndallIntensity * settings.mistReflectance
      * (0.004 + settings.fogGlow * 0.006);
    const targetOpacity = (0.004 + settings.fogDensity * 0.03
      + settings.mistEmission * 0.038 + lightCoupling
      + fluorescenceScatter * 0.014) * mistLayer.userData.opacityScale;
    mistLayer.material.opacity += (Math.min(
      targetOpacity * mistBlackLiftGuard,
      maxMistSceneOpacity / SONIC_WATER_MIST_LAYER_COUNT
    ) - mistLayer.material.opacity) * clamp(dt * 2.7, 0, 1);
    const emissionFill = 1 + settings.mistEmission * 0.52 + fluorescenceScatter * 0.1;
    mistLayer.scale.x += (mistLayer.userData.baseScaleX * emissionFill - mistLayer.scale.x) * clamp(dt * 2, 0, 1);
    mistLayer.scale.y += (
      mistLayer.userData.baseScaleY * (1 + settings.mistEmission * 0.38) - mistLayer.scale.y
    ) * clamp(dt * 2, 0, 1);
  }
  const tyndallBeams = topo.tyndallBeams;
  for (let beamIndex = 0; beamIndex < tyndallBeams.length; beamIndex += 1) {
    const beam = tyndallBeams[beamIndex];
    const beamUniforms = beam.material?.uniforms;
    if (!beamUniforms) continue;
    const atmosphereBreath = 0.5 + 0.5 * Math.sin(
      mistClock * beam.userData.driftRate + beam.userData.phase
    );
    const beamVisibility = 1 - smoothstep(0.34, 0.96, settings.mistEmission);
    const mediumGain = settings.atmosphereEnabled ? 0.48 + settings.fogDensity * 0.52 : 0;
    const mistCoupling = clamp(
      settings.fogDensity * 0.68 + settings.fogGlow * 0.16 + settings.mistEmission * 0.3,
      0,
      1
    );
    const beamEnergyBudget = SONIC_TYNDALL_TOTAL_ENERGY_CAP * 1.2 / SONIC_TYNDALL_BEAM_COUNT;
    const rawBeamOpacity = beam.userData.baseOpacity * perceptualTyndallIntensity * mediumGain
      * (0.48 + settings.mistReflectance * 0.42) * beamVisibility;
    const targetOpacity = Math.min(rawBeamOpacity, beamEnergyBudget);
    beamUniforms.uOpacity.value += (targetOpacity - beamUniforms.uOpacity.value) * clamp(dt * 4, 0, 1);
    beamUniforms.uTime.value = mistClock;
    beamUniforms.uMistCoupling.value = mistCoupling;
    beamUniforms.uMistReflectance.value = settings.mistReflectance;
    beamUniforms.uAtmosphereVariation.value = atmosphereBreath;

    const halo = beam.userData.halo;
    if (!halo?.material?.uniforms) continue;
    const haloBreath = 0.5 + 0.5 * Math.sin(
      mistClock * halo.userData.driftRate + halo.userData.phase
    );
    const haloEnergyCap = SONIC_TYNDALL_TOTAL_ENERGY_CAP * 0.42 / SONIC_TYNDALL_BEAM_COUNT;
    const haloTargetOpacity = Math.min(
      halo.userData.baseOpacity * perceptualTyndallIntensity
        * mediumGain * (0.42 + settings.mistReflectance * 0.34) * beamVisibility
        + halo.userData.baseOpacity * fluorescenceScatter
          * (0.18 + settings.fluorescence * 0.12),
      haloEnergyCap
    );
    halo.material.uniforms.uOpacity.value += (
      haloTargetOpacity - halo.material.uniforms.uOpacity.value
    ) * clamp(dt * 3.2, 0, 1);
    halo.material.uniforms.uTime.value = mistClock;
    halo.material.uniforms.uMistCoupling.value = mistCoupling;
    halo.material.uniforms.uMistReflectance.value = settings.mistReflectance;
    halo.material.uniforms.uHaloStrength.value = clamp(
      0.09 + settings.fogGlow * 0.09 + fluorescenceScatter * 0.1,
      0.08,
      0.28
    );
    halo.material.uniforms.uAtmosphereVariation.value = haloBreath;
  }
  const reflectionEnergyCap = SONIC_TYNDALL_TOTAL_ENERGY_CAP * 0.32;
  if (topo.tyndallGroundSheenMaterial?.uniforms) {
    const groundUniforms = topo.tyndallGroundSheenMaterial.uniforms;
    groundUniforms.uTime.value = mistClock;
    groundUniforms.uIntensity.value = Math.min(groundUniforms.uIntensity.value, reflectionEnergyCap);
  }
  if (topo.tyndallWallBounceMaterial?.uniforms) {
    const wallUniforms = topo.tyndallWallBounceMaterial.uniforms;
    wallUniforms.uTime.value = mistClock;
    wallUniforms.uIntensity.value = Math.min(
      wallUniforms.uIntensity.value,
      reflectionEnergyCap * 0.38
    );
  }
  if (uniforms.uTyndallGoboPhase) uniforms.uTyndallGoboPhase.value = mistClock * 0.018;
  if (!state.playbackVisual.dragging && !reducedMotion) topo.autoYaw += dt * 0.05;
  const referenceRadius = Math.hypot(SONIC_TOPOGRAPHY_CAMERA.x, SONIC_TOPOGRAPHY_CAMERA.y, SONIC_TOPOGRAPHY_CAMERA.z);
  const baseRadius = topo.baseCameraRadius || referenceRadius;
  const radius = baseRadius / clamp(state.playbackVisual.zoom || 1, 0.58, 2.35);
  const baseAzimuth = Math.atan2(SONIC_TOPOGRAPHY_CAMERA.x, SONIC_TOPOGRAPHY_CAMERA.z);
  const baseElevation = Math.asin(SONIC_TOPOGRAPHY_CAMERA.y / referenceRadius);
  const yaw = baseAzimuth + topo.autoYaw + (state.playbackVisual.yaw - PLAYBACK_REST_YAW);
  const elevation = clamp(baseElevation + (state.playbackVisual.pitch - PLAYBACK_REST_PITCH), 0.1, Math.PI / 2 - 0.1);
  const horizontalRadius = Math.cos(elevation) * radius;
  topo.camera.position.set(
    Math.sin(yaw) * horizontalRadius,
    Math.sin(elevation) * radius,
    Math.cos(yaw) * horizontalRadius
  );
  topo.camera.lookAt(0, SONIC_TOPOGRAPHY_CAMERA.targetY, 0);
  for (let beamIndex = 0; beamIndex < tyndallBeams.length; beamIndex += 1) {
    const beam = tyndallBeams[beamIndex];
    orientSonicTyndallPlane(window.THREE, beam, topo.camera);
    if (beam.userData.halo) orientSonicTyndallPlane(window.THREE, beam.userData.halo, topo.camera);
  }

  const rainAudioLight = audioDriving
    ? clamp(audio.energy * 0.58 + audio.brilliance * 0.24 + audio.beat * 0.18, 0, 1)
    : 0;
  updateSonicRain(topo, dt, now, rainAudioLight);
  updateSonicTopographyProjectiles(dt);
  if (topo.renderQuality) topo.renderQuality.render(topo.scene, topo.camera, nowMs);
  else topo.renderer.render(topo.scene, topo.camera);
}

function hslToRgb(h, s, l) {
  const hue = ((h % 360) + 360) % 360 / 360;
  const sat = clamp(s, 0, 1);
  const light = clamp(l, 0, 1);
  if (sat === 0) {
    const value = Math.round(light * 255);
    return { r: value, g: value, b: value };
  }
  const q = light < 0.5 ? light * (1 + sat) : light + sat - light * sat;
  const p = 2 * light - q;
  const convert = (t) => {
    let next = t;
    if (next < 0) next += 1;
    if (next > 1) next -= 1;
    if (next < 1 / 6) return p + (q - p) * 6 * next;
    if (next < 1 / 2) return q;
    if (next < 2 / 3) return p + (q - p) * (2 / 3 - next) * 6;
    return p;
  };
  return {
    r: Math.round(convert(hue + 1 / 3) * 255),
    g: Math.round(convert(hue) * 255),
    b: Math.round(convert(hue - 1 / 3) * 255)
  };
}

function mixRgb(a, b, amount) {
  const t = clamp(amount, 0, 1);
  return {
    r: Math.round(a.r + (b.r - a.r) * t),
    g: Math.round(a.g + (b.g - a.g) * t),
    b: Math.round(a.b + (b.b - a.b) * t)
  };
}

function rgbCss(color, alpha = 1) {
  return `rgba(${color.r}, ${color.g}, ${color.b}, ${alpha})`;
}

function rgbFromHex(value) {
  const color = normalizeTextPaletteColor(value);
  return {
    r: Number.parseInt(color.slice(1, 3), 16),
    g: Number.parseInt(color.slice(3, 5), 16),
    b: Number.parseInt(color.slice(5, 7), 16)
  };
}

function relativeLuminance(color) {
  return (0.2126 * color.r + 0.7152 * color.g + 0.0722 * color.b) / 255;
}

function readableLyricColor(color, mixAmount = 0.34) {
  const lifted = mixRgb(color, { r: 255, g: 255, b: 255 }, mixAmount);
  if (relativeLuminance(lifted) < 0.62) return mixRgb(lifted, { r: 255, g: 255, b: 255 }, 0.28);
  return lifted;
}

function lyricPaletteFromBase(base, coverColors = []) {
  const normalizedCoverColors = [
    coverColors[0] || base,
    coverColors[1] || mixRgb(base, { r: 255, g: 255, b: 255 }, 0.28),
    coverColors[2] || mixRgb(base, { r: 34, g: 22, b: 54 }, 0.42)
  ].map((color) => ({
    r: clamp(Math.round(Number(color.r) || 0), 0, 255),
    g: clamp(Math.round(Number(color.g) || 0), 0, 255),
    b: clamp(Math.round(Number(color.b) || 0), 0, 255)
  }));
  return {
    primary: readableLyricColor(base, 0.26),
    glow: mixRgb(base, { r: 255, g: 255, b: 255 }, 0.16),
    highlight: readableLyricColor(base, 0.5),
    depth: mixRgb(base, { r: 0, g: 0, b: 0 }, 0.68),
    coverColors: normalizedCoverColors
  };
}

function proxiedImageUrl(url) {
  return url ? `/api/cover?url=${encodeURIComponent(url)}` : '';
}

function coverUrl(song) {
  const source = songCoverSource(song || {});
  return proxiedImageUrl(source);
}

function textPalettePresetId(preset = state.textPreset) {
  if (TEXT_PALETTE_PRESET_IDS.includes(preset)) return preset;
  if (TEXT_PALETTE_PRESET_IDS.includes(state.lastSelectableTextPreset)) return state.lastSelectableTextPreset;
  return DEFAULT_TEXT_PRESET;
}

function textPalettePreference(preset = state.textPreset) {
  const id = textPalettePresetId(preset);
  const preference = normalizeTextPalettePreference(state.textPalettePreferences?.[id]);
  state.textPalettePreferences[id] = preference;
  return preference;
}

function manualTextLyricPalette(color) {
  const base = rgbFromHex(color);
  const white = { r: 255, g: 255, b: 255 };
  const black = { r: 0, g: 0, b: 0 };
  return lyricPaletteFromBase(base, [
    base,
    mixRgb(base, white, 0.32),
    mixRgb(base, black, 0.46)
  ]);
}

function resolvedTextLyricPalette(coverPalette) {
  const preference = textPalettePreference();
  return preference.mode === 'manual'
    ? manualTextLyricPalette(preference.color)
    : coverPalette;
}

function playbackLyricPalettePreference() {
  const preference = normalizeTextPalettePreference(state.playbackLyricPalettePreference);
  state.playbackLyricPalettePreference = preference;
  return preference;
}

function resolvedPlaybackLyricPalette(coverPalette) {
  const preference = playbackLyricPalettePreference();
  return preference.mode === 'manual'
    ? manualTextLyricPalette(preference.color)
    : coverPalette;
}

function setImage(img, song) {
  const url = coverUrl(song);
  const frame = img.parentElement;
  if (!url) {
    img.removeAttribute('src');
    frame.classList.remove('has-cover');
    return;
  }
  img.src = url;
  frame.classList.add('has-cover');
}

function fallbackLyricPalette(song = state.currentSong) {
  const seedText = safeText(song && (song.title || song.artist || song.album), 'FE Monster');
  let hash = 0;
  for (let index = 0; index < seedText.length; index += 1) {
    hash = (hash * 31 + seedText.charCodeAt(index)) >>> 0;
  }
  const hue = 185 + (hash % 96);
  const coverColors = [
    hslToRgb(hue, 0.82, 0.62),
    hslToRgb(hue + 48, 0.76, 0.58),
    hslToRgb(hue + 112, 0.7, 0.56)
  ];
  return lyricPaletteFromBase(coverColors[0], coverColors);
}

function coverColorDistance(a, b) {
  return Math.hypot(a.r - b.r, a.g - b.g, a.b - b.b);
}

function extractCoverColors(data) {
  const buckets = new Map();
  let total = 0;
  const average = { r: 0, g: 0, b: 0 };
  for (let index = 0; index < data.length; index += 4) {
    if (data[index + 3] < 64) continue;
    const r = data[index];
    const g = data[index + 1];
    const b = data[index + 2];
    const max = Math.max(r, g, b);
    const min = Math.min(r, g, b);
    const saturation = max === 0 ? 0 : (max - min) / max;
    const luminance = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
    const key = `${r >> 5}:${g >> 5}:${b >> 5}`;
    const bucket = buckets.get(key) || { r: 0, g: 0, b: 0, count: 0, saturation: 0, luminance: 0 };
    bucket.r += r;
    bucket.g += g;
    bucket.b += b;
    bucket.count += 1;
    bucket.saturation += saturation;
    bucket.luminance += luminance;
    buckets.set(key, bucket);
    average.r += r;
    average.g += g;
    average.b += b;
    total += 1;
  }
  if (!total) return [];
  average.r = Math.round(average.r / total);
  average.g = Math.round(average.g / total);
  average.b = Math.round(average.b / total);
  const candidates = Array.from(buckets.values()).map((bucket) => {
    const saturation = bucket.saturation / bucket.count;
    const luminance = bucket.luminance / bucket.count;
    return {
      color: {
        r: Math.round(bucket.r / bucket.count),
        g: Math.round(bucket.g / bucket.count),
        b: Math.round(bucket.b / bucket.count)
      },
      score: bucket.count * (0.58 + saturation * 1.55) * (0.74 + (1 - Math.abs(luminance - 0.54)) * 0.42)
    };
  }).sort((a, b) => b.score - a.score);

  const selected = [];
  [92, 70, 48, 0].some((minimumDistance) => {
    candidates.forEach((candidate) => {
      if (selected.length >= 3) return;
      if (selected.every((color) => coverColorDistance(color, candidate.color) >= minimumDistance)) {
        selected.push(candidate.color);
      }
    });
    return selected.length >= 3;
  });
  if (selected.length < 3 && selected.every((color) => coverColorDistance(color, average) >= 24)) selected.push(average);
  return selected.slice(0, 3);
}

function sampleCoverBase(data) {
  let total = 0;
  let red = 0;
  let green = 0;
  let blue = 0;
  let best = { r: 131, g: 228, b: 255 };
  let bestScore = -1;
  for (let index = 0; index < data.length; index += 4) {
    if (data[index + 3] < 64) continue;
    const r = data[index];
    const g = data[index + 1];
    const b = data[index + 2];
    const max = Math.max(r, g, b);
    const min = Math.min(r, g, b);
    const saturation = max === 0 ? 0 : (max - min) / max;
    const luminance = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
    const score = saturation * 1.55 - Math.abs(luminance - 0.58) * 0.52 + luminance * 0.18;
    red += r;
    green += g;
    blue += b;
    total += 1;
    if (score > bestScore) {
      bestScore = score;
      best = { r, g, b };
    }
  }
  if (!total) return null;
  const average = {
    r: Math.round(red / total),
    g: Math.round(green / total),
    b: Math.round(blue / total)
  };
  return mixRgb(best, average, 0.28);
}

const COVER_PALETTE_SAMPLE_SIZE = 36;
const COVER_PALETTE_CACHE_LIMIT = 48;
const coverPaletteCache = new Map();
const coverPaletteLoads = new Map();
let coverPaletteSampleCanvas = null;
let coverPaletteSampleContext = null;

function coverPaletteSampler() {
  if (coverPaletteSampleCanvas && coverPaletteSampleContext) {
    return { canvas: coverPaletteSampleCanvas, context: coverPaletteSampleContext };
  }
  coverPaletteSampleCanvas = document.createElement('canvas');
  coverPaletteSampleCanvas.width = COVER_PALETTE_SAMPLE_SIZE;
  coverPaletteSampleCanvas.height = COVER_PALETTE_SAMPLE_SIZE;
  coverPaletteSampleContext = coverPaletteSampleCanvas.getContext('2d', { willReadFrequently: true });
  return { canvas: coverPaletteSampleCanvas, context: coverPaletteSampleContext };
}

function rememberCoverPalette(signature, palette) {
  if (!signature || !palette) return;
  coverPaletteCache.delete(signature);
  coverPaletteCache.set(signature, palette);
  while (coverPaletteCache.size > COVER_PALETTE_CACHE_LIMIT) {
    coverPaletteCache.delete(coverPaletteCache.keys().next().value);
  }
}

function cachedCoverPalette(signature) {
  const palette = coverPaletteCache.get(signature);
  if (!palette) return null;
  coverPaletteCache.delete(signature);
  coverPaletteCache.set(signature, palette);
  return palette;
}

function sampleCoverPalette(img) {
  if (!img || !img.complete || !img.naturalWidth || !img.naturalHeight) return null;
  const { context } = coverPaletteSampler();
  if (!context) return null;
  try {
    context.clearRect(0, 0, COVER_PALETTE_SAMPLE_SIZE, COVER_PALETTE_SAMPLE_SIZE);
    context.drawImage(img, 0, 0, COVER_PALETTE_SAMPLE_SIZE, COVER_PALETTE_SAMPLE_SIZE);
    const data = context.getImageData(
      0,
      0,
      COVER_PALETTE_SAMPLE_SIZE,
      COVER_PALETTE_SAMPLE_SIZE
    ).data;
    const coverColors = extractCoverColors(data);
    if (!coverColors.length) return null;
    const fallback = fallbackLyricPalette(state.currentSong).coverColors;
    while (coverColors.length < 3) coverColors.push(fallback[coverColors.length]);
    const base = sampleCoverBase(data) || mixRgb(coverColors[0], coverColors[1], 0.2);
    return lyricPaletteFromBase(base, coverColors);
  } catch (error) {
    return null;
  }
}

function rgbTriplet(color) {
  return `${Math.round(color.r)}, ${Math.round(color.g)}, ${Math.round(color.b)}`;
}

function vividCubeColor(color, whiteMix = 0.08, saturationBoost = 1.22) {
  const lifted = mixRgb(color, { r: 255, g: 255, b: 255 }, whiteMix);
  const average = (lifted.r + lifted.g + lifted.b) / 3;
  return {
    r: clamp(Math.round(average + (lifted.r - average) * saturationBoost), 0, 255),
    g: clamp(Math.round(average + (lifted.g - average) * saturationBoost), 0, 255),
    b: clamp(Math.round(average + (lifted.b - average) * saturationBoost), 0, 255)
  };
}

function applyDynamicCubePalette(palette) {
  if (!palette) return;
  const cube = state.dynamicCube;
  cube.palette = palette;

  if (els.dynamicCubeScene) {
    els.dynamicCubeScene.style.setProperty('--cube-cover-glow', rgbTriplet(palette.glow));
    els.dynamicCubeScene.style.setProperty('--cube-cover-hot', rgbTriplet(palette.highlight));
    els.dynamicCubeScene.style.setProperty('--cube-cover-depth', rgbTriplet(palette.depth));
  }

  if (!cube.mesh || !cube.positions || typeof cube.mesh.setColorAt !== 'function' || !window.THREE) return;

  const THREE = window.THREE;
  const white = { r: 255, g: 255, b: 255 };
  const base = vividCubeColor(palette.primary, 0.06, 1.28);
  const glow = vividCubeColor(palette.glow, 0.04, 1.34);
  const highlight = mixRgb(vividCubeColor(palette.highlight, 0.12, 1.18), white, 0.1);
  const depth = vividCubeColor(mixRgb(palette.depth, palette.primary, 0.24), 0.02, 1.18);
  const half = Math.max(1, DYNAMIC_CUBE_RADIUS);
  const planeSize = DYNAMIC_CUBE_GRID * DYNAMIC_CUBE_GRID;
  const color = cube.color || new THREE.Color();
  cube.color = color;

  if (cube.mesh.material) {
    cube.mesh.material.vertexColors = true;
    cube.mesh.material.color.setRGB(1, 1, 1);
    if (cube.mesh.material.emissive) {
      cube.mesh.material.emissive.setRGB(glow.r / 255, glow.g / 255, glow.b / 255);
    }
    cube.mesh.material.emissiveIntensity = 0.085 + relativeLuminance(glow) * 0.1;
    cube.mesh.material.needsUpdate = true;
  }

  for (let index = 0; index < cube.count; index += 1) {
    const x = Math.floor(index / planeSize);
    const yz = index - x * planeSize;
    const y = Math.floor(yz / DYNAMIC_CUBE_GRID);
    const z = yz - y * DYNAMIC_CUBE_GRID;
    const offset = index * 3;
    const nx = Math.abs(cube.positions[offset] / half);
    const ny = Math.abs(cube.positions[offset + 1] / half);
    const nz = Math.abs(cube.positions[offset + 2] / half);
    const edge = Math.max(nx, ny, nz);
    const surface = (nx * 0.42 + ny * 0.34 + nz * 0.24) / Math.max(0.001, nx + ny + nz);
    const checker = (x + y + z) % 2 === 0 ? 0.055 : -0.035;
    const stripe = ((x * 17 + y * 11 + z * 5) % 29) / 28;
    const topLight = (DYNAMIC_CUBE_GRID - 1 - y) / (DYNAMIC_CUBE_GRID - 1);
    let tone = mixRgb(base, glow, clamp(0.16 + edge * 0.26 + surface * 0.12 + stripe * 0.1 + checker, 0.06, 0.58));
    tone = mixRgb(tone, highlight, clamp(topLight * 0.13 + edge * 0.045, 0, 0.22));
    tone = mixRgb(tone, depth, clamp(z / (DYNAMIC_CUBE_GRID - 1) * 0.16 + (1 - edge) * 0.05, 0, 0.24));

    const lift = clamp(0.88 + checker + edge * 0.09 + topLight * 0.06, 0.72, 1.08);
    color.setRGB(
      clamp((tone.r * lift) / 255, 0, 1),
      clamp((tone.g * lift) / 255, 0, 1),
      clamp((tone.b * lift) / 255, 0, 1)
    );
    cube.mesh.setColorAt(index, color);
  }

  if (cube.mesh.instanceColor) {
    cube.mesh.instanceColor.setUsage(THREE.DynamicDrawUsage);
    cube.mesh.instanceColor.needsUpdate = true;
  }
}

function applySonicTopographyPalette(palette) {
  if (!palette || !window.THREE) return;
  const topo = state.sonicTopography;
  topo.palette = palette;
  topo.theme = createSonicTopographyTheme(palette);

  if (topo.backgroundTargetColors?.length >= 3) {
    sonicCoverBackgroundColors(palette).forEach((color, index) => {
      topo.backgroundTargetColors[index].set(rgbHexValue(color));
    });
  }

  if (!topo.uniforms || !topo.theme) return;
  topo.uniforms.uBaseColor1.value.copy(topo.theme.uBaseColor1);
  topo.uniforms.uBaseColor2.value.copy(topo.theme.uBaseColor2);
  topo.uniforms.uCoolCore.value.copy(topo.theme.uCoolCore);
  topo.uniforms.uCoolEdge.value.copy(topo.theme.uCoolEdge);
  topo.uniforms.uWarmCore.value.copy(topo.theme.uWarmCore);
  topo.uniforms.uWarmEdge.value.copy(topo.theme.uWarmEdge);
  topo.uniforms.uRippleColor.value.copy(topo.theme.uRippleColor);
  topo.uniforms.uGlowIntensity.value = topo.theme.uGlowIntensity;
  if (topo.scene && topo.scene.fog && topo.scene.fog.color) {
    topo.scene.fog.color.copy(topo.theme.uBaseColor1);
  }
  if (topo.meteorMaterial && topo.meteorMaterial.color) {
    topo.meteorMaterial.color.copy(topo.theme.uWarmCore).lerp(new window.THREE.Color(0xffffff), 0.7);
  }
  if (topo.particleMaterial && topo.particleMaterial.color && topo.meteorMaterial && topo.meteorMaterial.color) {
    topo.particleMaterial.color.copy(topo.meteorMaterial.color);
  }
  applySonicTopographySettings({ persist: false, sync: true, renderConfig: false });
}

function rgbHexValue(color) {
  const part = (value) => clamp(Math.round(Number(value) || 0), 0, 255).toString(16).padStart(2, '0');
  return `#${part(color && color.r)}${part(color && color.g)}${part(color && color.b)}`;
}

function applyCoverParticlePalette(palette) {
  const source = palette || fallbackLyricPalette(state.currentSong);
  state.coverParticle.palette = source;
  if (!els.coverParticleScene || !source || !coverParticlePresetVisible()) return;
  const fallback = [source.primary, source.glow, source.highlight];
  const coverColors = [0, 1, 2].map((index) => source.coverColors?.[index] || fallback[index]);
  const softColors = coverColors.map((color, index) => playbackGlowColor(color, index));
  els.coverParticleScene.style.setProperty('--cover-particle-a', rgbCss(softColors[0], 0.66));
  els.coverParticleScene.style.setProperty('--cover-particle-b', rgbCss(softColors[1], 0.58));
  els.coverParticleScene.style.setProperty('--cover-particle-c', rgbCss(softColors[2], 0.62));
}

function playbackGlowColor(color, index = 0) {
  const white = { r: 255, g: 255, b: 255 };
  const minimumLift = [0.1, 0.08, 0.06][index] ?? 0.08;
  const lift = clamp(
    minimumLift + Math.max(0, 0.48 - relativeLuminance(color)) * 0.72,
    minimumLift,
    0.42
  );
  return mixRgb(color, white, lift);
}

function applyQishuiPlaybackPalette(palette) {
  if (!els.qishuiPlaybackPhone || !palette) return;
  const fallback = [palette.primary, palette.glow, palette.depth];
  const colors = [0, 1, 2].map((index) => palette.coverColors?.[index] || fallback[index]);
  const black = { r: 0, g: 0, b: 0 };
  const softA = playbackGlowColor(colors[0], 0);
  const softB = playbackGlowColor(colors[1], 1);
  const softC = playbackGlowColor(colors[2], 2);
  const blended = mixRgb(mixRgb(softA, softB, 0.38), softC, 0.24);
  const surface = mixRgb(blended, black, 0.58);
  [els.qishuiPlaybackPhone, els.appShell].forEach((target) => {
    if (!target) return;
    target.style.setProperty('--playback-cover-a', rgbCss(softA, 0.24));
    target.style.setProperty('--playback-cover-b', rgbCss(softB, 0.22));
    target.style.setProperty('--playback-cover-c', rgbCss(softC, 0.23));
    target.style.setProperty('--playback-cover-surface', rgbCss(surface, 0.045));
  });
  applyQishuiPlaybackLyricPalette(palette);
}

function applyQishuiPlaybackLyricPalette(coverPalette) {
  if (!els.qishuiPlaybackPhone || !coverPalette) return;
  const lyricPalette = resolvedPlaybackLyricPalette(coverPalette);
  const white = { r: 255, g: 255, b: 255 };
  const black = { r: 0, g: 0, b: 0 };
  const base = readableLyricColor(
    mixRgb(lyricPalette.primary, lyricPalette.glow, 0.22),
    0.22
  );
  const current = readableLyricColor(
    mixRgb(lyricPalette.highlight, lyricPalette.primary, 0.16),
    0.18
  );
  const muted = readableLyricColor(mixRgb(base, lyricPalette.depth, 0.06), 0.08);
  const shadow = mixRgb(lyricPalette.depth, black, 0.48);
  const highlightEdge = mixRgb(current, white, 0.1);
  [els.qishuiPlaybackPhone, els.appShell].filter(Boolean).forEach((target) => {
    target.style.setProperty('--playback-lyric-base', rgbCss(base, 0.94));
    target.style.setProperty('--playback-lyric-base-rgb', rgbTriplet(base));
    target.style.setProperty('--playback-lyric-muted', rgbCss(muted, 0.9));
    target.style.setProperty('--playback-lyric-current', rgbCss(highlightEdge, 0.99));
    target.style.setProperty('--playback-lyric-current-rgb', rgbTriplet(highlightEdge));
    target.style.setProperty('--playback-lyric-shadow', rgbCss(shadow, 0.96));
    target.style.setProperty('--playback-lyric-shadow-rgb', rgbTriplet(shadow));
  });
  els.qishuiPlaybackPhone.style.setProperty('--book-hot', rgbCss(highlightEdge));
  els.qishuiPlaybackPhone.style.setProperty('--book-hot-rgb', rgbTriplet(highlightEdge));
  els.qishuiPlaybackPhone.style.setProperty('--book-depth', rgbCss(shadow));
  els.qishuiPlaybackPhone.style.setProperty('--book-depth-rgb', rgbTriplet(shadow));
  if (els.playbackLyricPaletteControl) {
    els.playbackLyricPaletteControl.style.setProperty(
      '--text-palette-auto-color',
      rgbCss(coverPalette.primary)
    );
  }
}

function applyLyricPalette(palette) {
  if (!palette) return;
  state.playbackVisual.palette = palette;
  applyQishuiPlaybackPalette(palette);
  const lyricPalette = resolvedTextLyricPalette(palette);
  const target = els.playbackLyricScene;
  if (target && textLyricsEnabled()) {
    const white = { r: 255, g: 255, b: 255 };
    const gradientStart = mixRgb(lyricPalette.highlight, white, 0.12);
    const gradientMid = mixRgb(lyricPalette.glow, white, 0.04);
    const gradientEnd = mixRgb(lyricPalette.primary, lyricPalette.depth, 0.14);
    const gradientTail = mixRgb(lyricPalette.depth, lyricPalette.primary, 0.22);
    const lyricCoverSoftA = mixRgb(lyricPalette.primary, lyricPalette.glow, 0.36);
    const lyricCoverSoftB = mixRgb(lyricPalette.highlight, lyricPalette.glow, 0.34);
    const lyricCoverSoftC = mixRgb(lyricPalette.depth, lyricPalette.primary, 0.3);
    const lyricFontBase = readableLyricColor(mixRgb(lyricPalette.primary, lyricPalette.glow, 0.18), 0.16);
    const lyricFontHot = readableLyricColor(mixRgb(lyricPalette.highlight, lyricPalette.primary, 0.16), 0.2);
    const lyricFontSoft = mixRgb(lyricFontBase, lyricPalette.depth, 0.12);
    const bookSoftA = mixRgb(lyricPalette.primary, lyricPalette.glow, 0.34);
    const bookSoftB = mixRgb(lyricPalette.highlight, lyricPalette.glow, 0.42);
    const bookSoftBase = mixRgb(lyricPalette.depth, lyricPalette.primary, 0.2);
    target.style.setProperty('--lyric-primary', rgbCss(lyricPalette.primary));
    target.style.setProperty('--lyric-glow', rgbCss(lyricPalette.glow));
    target.style.setProperty('--lyric-highlight', rgbCss(lyricPalette.highlight));
    target.style.setProperty('--lyric-depth', rgbCss(lyricPalette.depth));
    target.style.setProperty('--lyric-primary-rgb', rgbTriplet(lyricPalette.primary));
    target.style.setProperty('--lyric-highlight-rgb', rgbTriplet(lyricPalette.highlight));
    target.style.setProperty('--lyric-depth-rgb', rgbTriplet(lyricPalette.depth));
    target.style.setProperty('--lyric-glow-soft', rgbCss(lyricPalette.glow, 0.22));
    target.style.setProperty('--lyric-glow-hot', rgbCss(lyricPalette.glow, 0.36));
    target.style.setProperty('--lyric-gradient-start', rgbCss(gradientStart));
    target.style.setProperty('--lyric-gradient-mid', rgbCss(gradientMid));
    target.style.setProperty('--lyric-gradient-end', rgbCss(gradientEnd));
    target.style.setProperty('--lyric-gradient-tail', rgbCss(gradientTail, 0.34));
    target.style.setProperty('--lyric-gradient-shadow', rgbCss(lyricPalette.depth, 0.88));
    target.style.setProperty('--lyric-cover-soft-a', rgbCss(lyricCoverSoftA, 0.62));
    target.style.setProperty('--lyric-cover-soft-b', rgbCss(lyricCoverSoftB, 0.5));
    target.style.setProperty('--lyric-cover-soft-c', rgbCss(lyricCoverSoftC, 0.58));
    target.style.setProperty('--lyric-font-base', rgbCss(lyricFontBase));
    target.style.setProperty('--lyric-font-hot', rgbCss(lyricFontHot));
    target.style.setProperty('--lyric-font-soft', rgbCss(lyricFontSoft));
    target.style.setProperty('--lyric-font-base-rgb', rgbTriplet(lyricFontBase));
    target.style.setProperty('--lyric-font-hot-rgb', rgbTriplet(lyricFontHot));
    target.style.setProperty('--lyric-font-soft-rgb', rgbTriplet(lyricFontSoft));
    [target, els.appShell].filter(Boolean).forEach((bookTarget) => {
      bookTarget.style.setProperty('--book-glow', rgbCss(lyricPalette.glow));
      bookTarget.style.setProperty('--book-glow-rgb', rgbTriplet(lyricPalette.glow));
      bookTarget.style.setProperty('--book-glow-soft', rgbCss(lyricPalette.glow, 0.26));
      bookTarget.style.setProperty('--book-hot', rgbCss(lyricPalette.highlight));
      bookTarget.style.setProperty('--book-hot-rgb', rgbTriplet(lyricPalette.highlight));
      bookTarget.style.setProperty('--book-depth', rgbCss(lyricPalette.depth));
      bookTarget.style.setProperty('--book-depth-rgb', rgbTriplet(lyricPalette.depth));
      bookTarget.style.setProperty('--book-page', rgbCss(mixRgb(lyricPalette.depth, lyricPalette.primary, 0.18), 0.58));
      bookTarget.style.setProperty('--book-soft-a', rgbCss(bookSoftA, 0.72));
      bookTarget.style.setProperty('--book-soft-b', rgbCss(bookSoftB, 0.62));
      bookTarget.style.setProperty('--book-soft-base', rgbCss(bookSoftBase, 0.94));
    });
  }
  if (els.textPaletteControl) {
    els.textPaletteControl.style.setProperty('--text-palette-auto-color', rgbCss(palette.primary));
  }
  applyDynamicCubePalette(palette);
  applyFreeCubePalette(palette);
  applyChladniPalette(palette);
  applySonicTopographyPalette(palette);
  applyCoverParticlePalette(palette);
  syncTextPaletteControls();
  syncPlaybackLyricPaletteControls();
}

function applyCoverSample(img, signature) {
  if (signature !== state.playbackVisual.coverSignature) return false;
  const cached = cachedCoverPalette(signature);
  if (cached) {
    applyLyricPalette(cached);
    return true;
  }
  const palette = sampleCoverPalette(img);
  if (!palette) return false;
  rememberCoverPalette(signature, palette);
  applyLyricPalette(palette);
  return true;
}

function loadCoverPalette(url, signature) {
  if (!url) return;
  const cached = cachedCoverPalette(signature);
  if (cached) {
    if (signature === state.playbackVisual.coverSignature) applyLyricPalette(cached);
    return;
  }
  if (coverPaletteLoads.has(signature)) return;
  const img = new Image();
  img.crossOrigin = 'anonymous';
  img.decoding = 'async';
  coverPaletteLoads.set(signature, img);
  const finish = () => coverPaletteLoads.delete(signature);
  img.addEventListener('load', () => {
    applyCoverSample(img, signature);
    finish();
  }, { once: true });
  img.addEventListener('error', finish, { once: true });
  img.src = url;
}

function drawCoverParticleWallpaper() {
  const canvas = els.coverParticleWallpaperCanvas;
  const cover = state.coverParticle;
  const image = cover.wallpaperImage;
  const sourcePixelWidth = Number(image?.naturalWidth || image?.videoWidth) || 0;
  const sourcePixelHeight = Number(image?.naturalHeight || image?.videoHeight) || 0;
  if (!canvas || !sourcePixelWidth || !sourcePixelHeight) return;
  const rect = (canvas.parentElement || canvas).getBoundingClientRect();
  const width = Math.max(1, Math.round(rect.width || canvas.clientWidth || 1));
  const height = Math.max(1, Math.round(rect.height || canvas.clientHeight || 1));
  const dpr = clamp(window.devicePixelRatio || 1, 1, 2);
  const pixelWidth = Math.max(1, Math.round(width * dpr));
  const pixelHeight = Math.max(1, Math.round(height * dpr));
  const videoFrameTime = image === cover.wallpaperVideo
    ? Math.round((Number(image.currentTime) || 0) * 1000)
    : -1;
  const drawSignature = `${cover.wallpaperSignature}|${pixelWidth}x${pixelHeight}|${videoFrameTime}`;
  if (cover.wallpaperDrawSignature === drawSignature) return;
  if (canvas.width !== pixelWidth) canvas.width = pixelWidth;
  if (canvas.height !== pixelHeight) canvas.height = pixelHeight;
  const context = canvas.getContext('2d', { alpha: true });
  if (!context) return;
  context.setTransform(dpr, 0, 0, dpr, 0, 0);
  context.clearRect(0, 0, width, height);

  const sourceAspect = sourcePixelWidth / Math.max(1, sourcePixelHeight);
  const targetAspect = width / Math.max(1, height);
  let sourceX = 0;
  let sourceY = 0;
  let sourceWidth = sourcePixelWidth;
  let sourceHeight = sourcePixelHeight;
  if (sourceAspect > targetAspect) {
    sourceWidth = sourcePixelHeight * targetAspect;
    sourceX = (sourcePixelWidth - sourceWidth) * 0.5;
  } else {
    sourceHeight = sourcePixelWidth / targetAspect;
    sourceY = (sourcePixelHeight - sourceHeight) * 0.5;
  }

  const curveAngle = 0.22;
  const curveDenominator = Math.sin(curveAngle);
  for (let segment = 0; segment < COVER_PARTICLE_WALLPAPER_SEGMENTS; segment += 1) {
    const sourceU0 = segment / COVER_PARTICLE_WALLPAPER_SEGMENTS;
    const sourceU1 = (segment + 1) / COVER_PARTICLE_WALLPAPER_SEGMENTS;
    const normalized0 = sourceU0 * 2 - 1;
    const normalized1 = sourceU1 * 2 - 1;
    const destinationU0 = (Math.sin(normalized0 * curveAngle) / curveDenominator + 1) * 0.5;
    const destinationU1 = (Math.sin(normalized1 * curveAngle) / curveDenominator + 1) * 0.5;
    const destinationX = destinationU0 * width;
    const destinationWidth = Math.max(1, (destinationU1 - destinationU0) * width + 0.75);
    const center = (normalized0 + normalized1) * 0.5;
    const depth = 1 - Math.pow(Math.abs(center), 1.55);
    const destinationHeight = height * (1 - depth * 0.02);
    const destinationY = (height - destinationHeight) * 0.5;
    context.drawImage(
      image,
      sourceX + sourceWidth * sourceU0,
      sourceY,
      sourceWidth * (sourceU1 - sourceU0) + 0.5,
      sourceHeight,
      destinationX,
      destinationY,
      destinationWidth,
      destinationHeight
    );
  }

  const inwardShade = context.createRadialGradient(width * 0.5, height * 0.48, 0, width * 0.5, height * 0.5, width * 0.72);
  inwardShade.addColorStop(0, 'rgba(2, 5, 9, 0.12)');
  inwardShade.addColorStop(0.62, 'rgba(2, 5, 9, 0.03)');
  inwardShade.addColorStop(1, 'rgba(2, 5, 9, 0.2)');
  context.fillStyle = inwardShade;
  context.fillRect(0, 0, width, height);
  cover.wallpaperDrawSignature = drawSignature;
}

function disposeCoverParticleWallpaperMedia() {
  if (state.coverParticle.wallpaperVideo) {
    window.FeWallpaperVideoContinuity?.release?.(state.coverParticle.wallpaperVideo);
    state.coverParticle.wallpaperVideo.pause?.();
    state.coverParticle.wallpaperVideo.removeAttribute?.('src');
    state.coverParticle.wallpaperVideo.load?.();
    state.coverParticle.wallpaperVideo = null;
  }
  state.coverParticle.wallpaperImage = null;
  state.coverParticle.wallpaperDrawSignature = '';
}

function releaseCoverParticleWallpaperCanvas() {
  const canvas = els.coverParticleWallpaperCanvas;
  if (!canvas) return;
  canvas.width = 1;
  canvas.height = 1;
  canvas.hidden = true;
}

function scheduleCoverParticleWallpaperVideoFrame(video, requestId, signature) {
  if (typeof video?.requestVideoFrameCallback !== 'function') return;
  video.requestVideoFrameCallback(() => {
    const cover = state.coverParticle;
    if (cover.wallpaperVideo !== video
        || cover.wallpaperRequestId !== requestId
        || cover.wallpaperSignature !== signature) {
      return;
    }
    drawCoverParticleWallpaper();
    scheduleCoverParticleWallpaperVideoFrame(video, requestId, signature);
  });
}

function setCoverParticleWallpaper(request) {
  const canvas = els.coverParticleWallpaperCanvas;
  if (!canvas) return;
  const config = request && typeof request === 'object' ? request : {};
  const enabled = config.enabled === true;
  const url = safeText(config.url, '');
  const mediaKind = config.mediaKind === 'video' ? 'video' : 'image';
  const opacity = clamp(Number(config.opacity) || 0.68, 0.1, 1);
  const signature = enabled && url ? `${mediaKind}:${url}` : '';
  canvas.style.setProperty('--scene-wallpaper-opacity', opacity.toFixed(2));
  if (!signature) {
    state.coverParticle.wallpaperRequestId += 1;
    disposeCoverParticleWallpaperMedia();
    state.coverParticle.wallpaperSignature = '';
    releaseCoverParticleWallpaperCanvas();
    return;
  }
  canvas.hidden = false;
  if (
    state.coverParticle.wallpaperSignature === signature
    && (state.coverParticle.wallpaperImage || state.coverParticle.wallpaperVideo)
  ) {
    if (state.coverParticle.wallpaperImage) drawCoverParticleWallpaper();
    return;
  }
  const requestId = state.coverParticle.wallpaperRequestId + 1;
  state.coverParticle.wallpaperRequestId = requestId;
  state.coverParticle.wallpaperSignature = signature;
  disposeCoverParticleWallpaperMedia();

  if (mediaKind === 'video') {
    const video = document.createElement('video');
    video.crossOrigin = 'anonymous';
    video.preload = 'auto';
    video.muted = true;
    video.defaultMuted = true;
    video.playsInline = true;
    window.FeWallpaperVideoContinuity?.prepare(video);
    state.coverParticle.wallpaperVideo = video;
    video.addEventListener('loadeddata', () => {
      if (state.coverParticle.wallpaperRequestId !== requestId
          || state.coverParticle.wallpaperSignature !== signature) {
        return;
      }
      state.coverParticle.wallpaperImage = video;
      drawCoverParticleWallpaper();
      const supportsVideoFrames = typeof video.requestVideoFrameCallback === 'function';
      if (supportsVideoFrames) {
        scheduleCoverParticleWallpaperVideoFrame(video, requestId, signature);
      } else {
        video.addEventListener('timeupdate', drawCoverParticleWallpaper);
      }
      video.play().catch(() => {});
    }, { once: true });
    video.addEventListener('error', () => {
      if (state.coverParticle.wallpaperRequestId !== requestId) return;
      disposeCoverParticleWallpaperMedia();
      state.coverParticle.wallpaperSignature = '';
      releaseCoverParticleWallpaperCanvas();
      els.coverParticleScene?.classList.remove('has-scene-wallpaper');
    }, { once: true });
    video.src = url;
    video.load();
    video.play().catch(() => {});
    return;
  }

  const image = new Image();
  state.coverParticle.wallpaperImage = image;
  image.decoding = 'async';
  image.crossOrigin = 'anonymous';
  image.addEventListener('load', () => {
    if (state.coverParticle.wallpaperRequestId !== requestId || state.coverParticle.wallpaperSignature !== signature) return;
    state.coverParticle.wallpaperImage = image;
    drawCoverParticleWallpaper();
  }, { once: true });
  image.addEventListener('error', () => {
    if (state.coverParticle.wallpaperRequestId !== requestId) return;
    state.coverParticle.wallpaperImage = null;
    state.coverParticle.wallpaperSignature = '';
    releaseCoverParticleWallpaperCanvas();
    els.coverParticleScene?.classList.remove('has-scene-wallpaper');
  }, { once: true });
  image.src = url;
}

function resetCoverParticleSamples() {
  state.coverParticle.sampleSignature = '';
  state.coverParticle.particles = [];
  state.coverParticle.gpuSignature = '';
  state.coverParticle.gpuRenderSignature = '';
}

function updateCoverParticleImage(song = state.currentSong) {
  if (!coverParticlePresetVisible()) return false;
  const url = coverUrl(song);
  const signature = `${url}|${safeText(song && song.title, '')}`;
  if (signature === state.coverParticle.imageSignature) return true;
  const previousImage = state.coverParticle.image;
  if (previousImage) {
    previousImage.onload = null;
    previousImage.onerror = null;
    previousImage.removeAttribute?.('src');
    state.coverParticle.image = null;
  }
  state.coverParticle.imageSignature = signature;
  resetCoverParticleSamples();
  if (!url) {
    state.coverParticle.image = null;
    return false;
  }
  const image = new Image();
  state.coverParticle.image = image;
  image.crossOrigin = 'anonymous';
  image.decoding = 'async';
  image.onload = () => {
    if (state.coverParticle.imageSignature !== signature) return;
    state.coverParticle.image = image;
    resetCoverParticleSamples();
  };
  image.onerror = () => {
    if (state.coverParticle.imageSignature !== signature) return;
    state.coverParticle.image = null;
    resetCoverParticleSamples();
  };
  image.src = url;
  return true;
}

function updateLyricPalette(song = state.currentSong) {
  const url = coverUrl(song);
  const signature = `${url}|${safeText(song && song.title, '')}`;
  if (coverParticlePresetVisible()) updateCoverParticleImage(song);
  if (signature === state.playbackVisual.coverSignature) return;
  state.playbackVisual.coverSignature = signature;
  applyLyricPalette(fallbackLyricPalette(song));
  const img = els.dockCover;
  const applySample = () => {
    if (!applyCoverSample(img, signature)) loadCoverPalette(url, signature);
  };
  if (img && img.complete && img.naturalWidth) {
    window.requestAnimationFrame(applySample);
  } else if (img) {
    img.addEventListener('load', applySample, { once: true });
    img.addEventListener('error', () => loadCoverPalette(url, signature), { once: true });
  } else {
    loadCoverPalette(url, signature);
  }
}

function updateBookLyricCover(song = state.currentSong) {
  if (!els.bookLyricCover || !els.bookLyricCoverImage) return;
  const url = coverUrl(song);
  if (!url) {
    els.bookLyricCoverImage.removeAttribute('src');
    els.bookLyricCover.classList.remove('has-cover');
    return;
  }
  if (els.bookLyricCoverImage.getAttribute('src') !== url) els.bookLyricCoverImage.src = url;
  els.bookLyricCover.classList.add('has-cover');
}

function updateBookLyricArtist(subtitle = playbackLyricSubtitle()) {
  if (!els.bookLyricArtist) return;
  const text = safeText(subtitle, playbackLyricSubtitle());
  if (els.bookLyricArtist.__bookLyricArtistText !== text) {
    els.bookLyricArtist.__bookLyricArtistText = text;
    els.bookLyricArtist.textContent = text;
  }
  const hidden = !text;
  if (els.bookLyricArtist.hidden !== hidden) els.bookLyricArtist.hidden = hidden;
}

function bookLyricDisplayLines() {
  if (state.lyricLines.length) return state.lyricLines;
  return [{
    time: 0,
    text: playbackLyricText(),
    fallback: true
  }];
}

function bookLyricSignature(lines) {
  const first = lines[0] || {};
  const last = lines[lines.length - 1] || {};
  return [
    state.lyricSignature,
    state.bilingualLyricsEnabled ? 'bilingual' : 'original',
    lines.length,
    safeText(first.text, ''),
    playbackLyricTranslationText(first),
    Number(first.time) || 0,
    safeText(last.text, ''),
    playbackLyricTranslationText(last),
    Number(last.time) || 0
  ].join('|');
}

function appendBookLyricGlyphs(target, text, glyphTimings = [], options = {}) {
  const progressGlyphs = options.progress !== false;
  let glyphIndex = 0;
  Array.from(text).forEach((glyph) => {
    if (glyph === '\r') return;
    if (glyph === '\n') {
      target.appendChild(document.createElement('br'));
      return;
    }
    const span = document.createElement('span');
    span.className = progressGlyphs
      ? (glyph.trim() ? 'book-lyric-glyph' : 'book-lyric-glyph book-lyric-glyph--space')
      : (glyph.trim() ? 'book-lyric-base-glyph' : 'book-lyric-base-glyph book-lyric-base-glyph--space');
    span.textContent = glyph;
    if (glyph.trim()) {
      if (progressGlyphs) {
        span.dataset.bookGlyphIndex = String(glyphIndex);
        const timing = glyphTimings[glyphIndex];
        if (timing && Number.isFinite(timing.start) && Number.isFinite(timing.end) && timing.end > timing.start) {
          span.dataset.bookGlyphStart = timing.start.toFixed(3);
          span.dataset.bookGlyphEnd = timing.end.toFixed(3);
        }
      }
      glyphIndex += 1;
    }
    target.appendChild(span);
  });
  target.dataset.bookGlyphCount = String(glyphIndex);
}

function bookGlyphEase(value) {
  const x = clamp(value, 0, 1);
  return x * x * (3 - 2 * x);
}

const BOOK_LYRIC_VISUAL_LEAD_SECONDS = 0.34;
const BOOK_LYRIC_GLYPH_VISUAL_LEAD_SECONDS = 0.045;
const BOOK_LYRIC_MIN_GLYPH_VISUAL_SECONDS = 0.08;
const BOOK_LYRIC_GLYPH_SAMPLE_SECONDS = 0;
const BOOK_LYRIC_ROLL_WINDOW_GLYPHS = 1.2;
const LYRIC_TIMESTAMP_COMPENSATION_SECONDS = 0.22;
const MULTI_ROW_LYRIC_VISUAL_LEAD_SECONDS = LYRIC_TIMESTAMP_COMPENSATION_SECONDS;
const BOOK_LYRIC_SCROLL_SNAP_PX = 0.65;
const BOOK_LYRIC_SCROLL_MIN_STEP_SECONDS = 0;
const BOOK_LYRIC_SCROLL_MAX_STEP_SECONDS = 0.08;
const QISHUI_LYRIC_TRANSITION_SECONDS = 0.18;
const QISHUI_LYRIC_SCROLL_SETTLE_SECONDS = 0.024;
const QISHUI_SEEK_HANDOFF_TOLERANCE_SECONDS = 0.08;
const QISHUI_SEEK_HANDOFF_MAX_MS = 1600;

function resetLyricFrameSync() {
  state.lyricFrameTime = -1;
  state.lyricFramePreset = '';
  state.lyricFrameSignature = '';
}

function resetBookLyricScrollState(options = {}) {
  const store = options.store || state;
  const targetKey = options.targetKey || 'lyricBookScrollTarget';
  const frameAtKey = options.frameAtKey || 'lyricBookScrollFrameAt';
  const clockTimeKey = options.clockTimeKey || 'lyricBookScrollClockTime';
  const layoutVersionKey = options.layoutVersionKey || 'lyricBookLayoutVersion';
  store[targetKey] = Number.NaN;
  store[frameAtKey] = 0;
  store[clockTimeKey] = Number.NaN;
  store[layoutVersionKey] = (Number(store[layoutVersionKey]) || 0) + 1;
}

function bookLyricTargetScrollTop(line, options = {}) {
  const list = options.list || els.bookLyricList;
  const store = options.store || state;
  const layoutVersionKey = options.layoutVersionKey || 'lyricBookLayoutVersion';
  const layoutVersion = Number(store[layoutVersionKey]) || 0;
  if (!list || !line) return Number.NaN;
  const clientHeight = Number(list.clientHeight) || 0;
  const scrollHeight = Number(list.scrollHeight) || 0;
  if (clientHeight <= 0 || scrollHeight <= 0) return Number.NaN;
  if (
    line.__bookScrollVersion === layoutVersion
    && line.__bookScrollClientHeight === clientHeight
    && line.__bookScrollHeight === scrollHeight
    && Number.isFinite(line.__bookScrollTarget)
  ) {
    return line.__bookScrollTarget;
  }
  const maxScroll = Math.max(0, scrollHeight - clientHeight);
  const target = line.offsetTop - Math.max(0, (clientHeight - line.offsetHeight) / 2);
  const scrollTop = clamp(target, 0, maxScroll);
  line.__bookScrollVersion = layoutVersion;
  line.__bookScrollClientHeight = clientHeight;
  line.__bookScrollHeight = scrollHeight;
  line.__bookScrollTarget = scrollTop;
  return scrollTop;
}

function syncBookLyricScroll(line, options = {}) {
  const list = options.list || els.bookLyricList;
  const store = options.store || state;
  const targetKey = options.targetKey || 'lyricBookScrollTarget';
  const frameAtKey = options.frameAtKey || 'lyricBookScrollFrameAt';
  const clockTimeKey = options.clockTimeKey || 'lyricBookScrollClockTime';
  const lines = Array.isArray(options.lines) ? options.lines : state.lyricLines;
  const activeIndex = Number.isInteger(options.activeIndex) ? options.activeIndex : state.lyricIndex;
  if (!list || !line) return false;
  const target = bookLyricTargetScrollTop(line, options);
  if (!Number.isFinite(target)) return false;

  const now = performance.now();
  const previousTarget = Number(store[targetKey]);
  const targetChanged = !Number.isFinite(previousTarget) || Math.abs(previousTarget - target) > BOOK_LYRIC_SCROLL_SNAP_PX;
  store[targetKey] = target;

  const current = Number(list.scrollTop) || 0;
  const delta = target - current;
  if (Math.abs(delta) <= BOOK_LYRIC_SCROLL_SNAP_PX) {
    list.scrollTop = target;
    store[frameAtKey] = now;
    return true;
  }

  const clockTime = Number(options.clockTime);
  const previousClockTime = Number(store[clockTimeKey]);
  const usesMediaClock = Number.isFinite(clockTime);
  const lastAt = Number(store[frameAtKey]) || now;
  const dt = usesMediaClock
    ? clamp(
        Number.isFinite(previousClockTime) ? clockTime - previousClockTime : 0,
        0,
        BOOK_LYRIC_SCROLL_MAX_STEP_SECONDS
      )
    : clamp(
        (now - lastAt) / 1000,
        BOOK_LYRIC_SCROLL_MIN_STEP_SECONDS,
        BOOK_LYRIC_SCROLL_MAX_STEP_SECONDS
      );
  store[frameAtKey] = now;
  if (usesMediaClock) store[clockTimeKey] = clockTime;

  const reducedMotionEnabled = options.reducedMotion ?? state.orb.reducedMotion;
  const playbackRunning = options.playbackRunning ?? isPlaybackClockRunning();
  if (reducedMotionEnabled || !playbackRunning || Math.abs(delta) > list.clientHeight * 1.4) {
    list.scrollTop = target;
    return true;
  }
  if (usesMediaClock && dt <= 0) return false;

  const configuredResponseSeconds = Number(options.responseSeconds);
  let easedDelta = 0;
  if (usesMediaClock && Number.isFinite(configuredResponseSeconds) && configuredResponseSeconds > 0) {
    const responseSeconds = Math.max(0.001, configuredResponseSeconds);
    const step = clamp(1 - Math.exp(-dt / responseSeconds), 0, 0.94);
    easedDelta = delta * step;
  } else {
    const activeLine = lines[activeIndex] || {};
    const nextLine = lines[activeIndex + 1] || {};
    const lineStart = Number(activeLine.time);
    const nextStart = Number(nextLine.time);
    const lineGap = Number.isFinite(lineStart) && Number.isFinite(nextStart) && nextStart > lineStart
      ? nextStart - lineStart
      : 2.4;
    const responseSeconds = clamp(lineGap * 0.12, targetChanged ? 0.09 : 0.12, 0.26);
    const step = clamp(dt / responseSeconds, targetChanged ? 0.28 : 0.08, 0.82);
    easedDelta = delta * bookGlyphEase(step);
  }
  list.scrollTop = current + easedDelta;
  const observed = Number(list.scrollTop) || 0;
  // Chromium can quantize a sub-pixel scroll write back to the same CSS pixel.
  if (
    Math.abs(observed - current) < 0.01
    && Math.abs(delta) > BOOK_LYRIC_SCROLL_SNAP_PX
  ) {
    list.scrollTop = current + Math.sign(delta) * Math.min(1, Math.abs(delta));
  }
  if (Math.abs(target - list.scrollTop) <= BOOK_LYRIC_SCROLL_SNAP_PX) {
    list.scrollTop = target;
    return true;
  }
  return false;
}

function cachedBookLyricGlyphs(line) {
  if (!line) return [];
  if (Array.isArray(line.__bookGlyphs)) return line.__bookGlyphs;
  const glyphs = Array.from(line.querySelectorAll('.book-lyric-glyph:not(.book-lyric-glyph--space)'));
  let hasTimedGlyphs = false;
  glyphs.forEach((glyph, fallbackIndex) => {
    const index = Number(glyph.dataset.bookGlyphIndex);
    glyph.__bookGlyphIndex = Number.isFinite(index) ? index : fallbackIndex;
    const start = Number(glyph.dataset.bookGlyphStart);
    const end = Number(glyph.dataset.bookGlyphEnd);
    glyph.__bookGlyphStart = start;
    glyph.__bookGlyphEnd = end;
    if (Number.isFinite(start) && Number.isFinite(end) && end > start) hasTimedGlyphs = true;
  });
  line.__bookGlyphs = glyphs;
  line.__bookHasTimedGlyphs = hasTimedGlyphs;
  return glyphs;
}

function setBookLyricGlyphProgress(line, progressPercent, currentTime = Number.NaN) {
  if (!line) return;
  const glyphs = cachedBookLyricGlyphs(line);
  const progressValue = clamp(Number(progressPercent) || 0, 0, 100);
  const timed = !!line.__bookHasTimedGlyphs && Number.isFinite(Number(currentTime));
  const progressKey = timed
    ? `t:${Number(currentTime).toFixed(3)}`
    : `p:${progressValue.toFixed(2)}`;
  if (line.__bookGlyphProgress === progressKey) return;
  line.__bookGlyphProgress = progressKey;
  const mainBase = line.querySelector('.book-lyric-copy--base');
  const mainHot = line.querySelector('.book-lyric-copy--hot');
  setSequentialLyricHighlight(mainHot, mainBase, progressValue);
  const translationBase = line.querySelector('.book-lyric-translation-copy--base');
  const translationHot = line.querySelector('.book-lyric-translation-copy--hot');
  setSequentialLyricHighlight(translationHot, translationBase, progressValue);
  if (!glyphs.length) return;

  const head = progressValue / 100 * glyphs.length;
  glyphs.forEach((glyph, fallbackIndex) => {
    const glyphIndex = Number.isFinite(glyph.__bookGlyphIndex) ? glyph.__bookGlyphIndex : fallbackIndex;
    let hot = 0;
    let roll = 0;

    if (timed && Number.isFinite(glyph.__bookGlyphStart) && Number.isFinite(glyph.__bookGlyphEnd)) {
      const start = glyph.__bookGlyphStart - BOOK_LYRIC_GLYPH_VISUAL_LEAD_SECONDS;
      const end = Math.max(start + BOOK_LYRIC_MIN_GLYPH_VISUAL_SECONDS, glyph.__bookGlyphEnd);
      const timedProgress = (Number(currentTime) + BOOK_LYRIC_GLYPH_SAMPLE_SECONDS - start) / Math.max(0.001, end - start);
      hot = bookGlyphEase(timedProgress);
      roll = bookGlyphEase(1 - Math.abs(timedProgress - 0.72) / 0.72);
    } else {
      hot = bookGlyphEase(head - glyphIndex);
      roll = bookGlyphEase(1 - Math.abs(head - (glyphIndex + 0.5)) / BOOK_LYRIC_ROLL_WINDOW_GLYPHS);
    }

    const hotValue = hot.toFixed(4);
    const coreValue = Math.min(1, hot * 0.92 + roll * 0.18).toFixed(4);
    const glowValue = Math.min(1, hot * 0.78 + roll * 0.32).toFixed(4);
    const softValue = Math.min(1, hot * 0.52 + roll * 0.34).toFixed(4);
    const rollValue = Math.min(1, roll).toFixed(4);
    const signature = `${hotValue}|${coreValue}|${glowValue}|${softValue}|${rollValue}`;
    if (glyph.__bookGlyphSignature === signature) return;
    glyph.__bookGlyphSignature = signature;
    glyph.style.setProperty('--book-glyph-hot', hotValue);
    glyph.style.setProperty('--book-glyph-core', coreValue);
    glyph.style.setProperty('--book-glyph-glow', glowValue);
    glyph.style.setProperty('--book-glyph-glow-soft', softValue);
    glyph.style.setProperty('--book-glyph-roll', rollValue);
  });
}

function syncBookLyricFrame() {
  if (!state.playbackPage || state.textPreset !== 'book' || !state.lyricLines.length || !isPlaybackClockRunning()) return;
  syncPlaybackLyricAnimationFrame();
}

function fitBookLyricLinesToPage() {
  if (!els.bookLyricList) return;
  const entries = Array.from(els.bookLyricList.querySelectorAll('.book-lyric-line-text'))
    .map((text) => ({
      text,
      line: text.closest('.book-lyric-line'),
      base: text.querySelector('.book-lyric-copy--base')
    }))
    .filter(({ line, base }) => line && base);
  if (!entries.length) return;

  entries.forEach(({ text }) => {
    text.style.removeProperty('font-size');
    text.style.removeProperty('--book-line-fit-width');
    text.style.removeProperty('--book-line-fit-scale');
  });

  const minimumFontSize = window.innerWidth <= 620 ? 10 : 12;
  const measured = entries.map(({ text, line, base }) => {
    const lineStyle = getComputedStyle(line);
    const horizontalPadding = (Number.parseFloat(lineStyle.paddingLeft) || 0)
      + (Number.parseFloat(lineStyle.paddingRight) || 0);
    const availableWidth = Math.max(0, line.clientWidth - horizontalPadding - 2);
    const naturalWidth = Math.max(1, base.scrollWidth);
    const naturalFontSize = Number.parseFloat(getComputedStyle(text).fontSize) || 1;
    const fittedFontSize = availableWidth > 0 && naturalWidth > availableWidth
      ? Math.max(minimumFontSize, naturalFontSize * availableWidth / naturalWidth)
      : naturalFontSize;
    return { text, base, availableWidth, naturalFontSize, fittedFontSize };
  });

  measured.forEach(({ text, naturalFontSize, fittedFontSize }) => {
    if (fittedFontSize < naturalFontSize - 0.01) text.style.fontSize = `${fittedFontSize.toFixed(3)}px`;
  });

  measured.forEach(({ text, base, availableWidth }) => {
    if (availableWidth <= 0) return;
    const fittedWidth = Math.max(1, Math.ceil(base.scrollWidth));
    const scale = Math.min(1, availableWidth / fittedWidth);
    text.style.setProperty('--book-line-fit-width', `${fittedWidth}px`);
    text.style.setProperty('--book-line-fit-scale', scale.toFixed(5));
  });
  invalidateSequentialLyricHighlights(els.bookLyricList);
  resetBookLyricScrollState();
}

function scheduleBookLyricFit() {
  window.cancelAnimationFrame(state.lyricBookFitFrame);
  state.lyricBookFitFrame = window.requestAnimationFrame(() => {
    state.lyricBookFitFrame = 0;
    fitBookLyricLinesToPage();
  });
}

function createBookLyricLine(line, index, options = {}) {
  const button = document.createElement('button');
  const translationText = state.bilingualLyricsEnabled
    ? playbackLyricTranslationText(line).replace(/\s*\r?\n+\s*/g, ' ').trim()
    : '';
  button.className = ['book-lyric-line', options.lineClass].filter(Boolean).join(' ');
  button.type = 'button';
  button.dataset.bookLyricIndex = String(index);
  button.dataset.bookLyricTime = String(Number(line.time) || 0);
  button.dataset.text = safeText(line.text, playbackLyricText());
  if (translationText) button.dataset.translation = translationText;
  button.setAttribute(
    'aria-label',
    `${formatTime(Number(line.time) || 0)} ${safeText(line.text, '')}${translationText ? ` ${translationText}` : ''}`
  );

  const text = document.createElement('span');
  text.className = 'book-lyric-line-text';
  const lyricText = safeText(line.text, playbackLyricText()).replace(/\s*\r?\n+\s*/g, ' ').trim();
  const base = document.createElement('span');
  base.className = 'book-lyric-copy book-lyric-copy--base';
  const highlight = document.createElement('span');
  highlight.className = 'book-lyric-copy book-lyric-copy--hot';
  const detailedGlyphs = options.lazyGlyphs !== true;
  if (detailedGlyphs) {
    appendBookLyricGlyphs(base, lyricText, [], { progress: false });
    appendBookLyricGlyphs(highlight, lyricText, line.glyphTimings);
  } else {
    base.textContent = lyricText;
    highlight.textContent = lyricText;
  }
  highlight.setAttribute('aria-hidden', 'true');
  text.appendChild(base);
  text.appendChild(highlight);
  button.appendChild(text);
  if (translationText) {
    const translation = document.createElement('span');
    translation.className = 'book-lyric-translation';
    const translationBase = document.createElement('span');
    translationBase.className = 'book-lyric-translation-copy book-lyric-translation-copy--base';
    translationBase.textContent = translationText;
    const translationHighlight = document.createElement('span');
    translationHighlight.className = 'book-lyric-translation-copy book-lyric-translation-copy--hot';
    translationHighlight.textContent = translationText;
    translationHighlight.setAttribute('aria-hidden', 'true');
    translation.appendChild(translationBase);
    translation.appendChild(translationHighlight);
    button.appendChild(translation);
  }
  return button;
}

function renderBookLyricList(list, lines, options = {}) {
  if (!list) return;
  clearElement(list);
  lines.forEach((line, index) => {
    list.appendChild(createBookLyricLine(line, index, options));
  });
}

function renderBookLyricLines(force = false) {
  if (!els.bookLyricList) return;
  const lines = bookLyricDisplayLines();
  const signature = bookLyricSignature(lines);
  if (!force && state.lyricBookSignature === signature) return;
  state.lyricBookSignature = signature;
  state.lyricBookIndex = -2;
  state.lyricBookCurrentLine = null;
  resetBookLyricScrollState();
  renderBookLyricList(els.bookLyricList, lines);
  fitBookLyricLinesToPage();
  scheduleBookLyricFit();
}

function updateBookLyricLines(progressPercent = state.lyricProgressPercent, currentTime = Number.NaN) {
  if (!els.bookLyricList || state.textPreset !== 'book') return;
  renderBookLyricLines();
  const lines = bookLyricDisplayLines();
  const active = state.lyricLines.length ? clamp(state.lyricIndex, -1, Math.max(0, lines.length - 1)) : 0;
  const progressValue = clamp(Number(progressPercent) || 0, 0, 100);
  const progress = `${progressValue.toFixed(2)}%`;
  const currentTimeValue = Number.isFinite(Number(currentTime))
    ? Number(currentTime)
    : effectivePlaybackLyricTime(
        currentPlaybackLyricTime(),
        BOOK_LYRIC_VISUAL_LEAD_SECONDS
      );
  let current = state.lyricBookCurrentLine;

  if (state.lyricBookIndex !== active) {
    state.lyricBookIndex = active;
    state.lyricBookCurrentLine = null;
    els.bookLyricList.querySelectorAll('.book-lyric-line').forEach((line) => {
      const index = Number(line.dataset.bookLyricIndex) || 0;
      const distance = Math.min(6, Math.abs(index - active));
      const isCurrent = index === active;
      const isEnded = isCurrent && progressValue >= 99.6;
      line.classList.toggle('is-current', isCurrent);
      line.classList.toggle('is-ended', isEnded);
      line.classList.toggle('is-past', index < active);
      line.classList.toggle('is-future', index > active);
      line.style.setProperty('--book-line-distance', distance.toFixed(0));
      line.style.setProperty('--book-line-progress', isCurrent ? progress : '0%');
      setBookLyricGlyphProgress(line, isCurrent ? progressValue : 0, isCurrent ? currentTimeValue : Number.NaN);
      if (isCurrent) {
        current = line;
        state.lyricBookCurrentLine = line;
        line.setAttribute('aria-current', 'true');
      } else {
        line.removeAttribute('aria-current');
      }
    });

  } else {
    if (!current || Number(current.dataset.bookLyricIndex) !== active) {
      current = els.bookLyricList.querySelector(`.book-lyric-line[data-book-lyric-index="${active}"]`);
      state.lyricBookCurrentLine = current;
    }
  }

  if (current) {
    current.classList.toggle('is-ended', progressValue >= 99.6);
    current.style.setProperty('--book-line-progress', progress);
    setBookLyricGlyphProgress(current, progressValue, currentTimeValue);
    syncBookLyricScroll(current);
  }
}

function seekToBookLyric(time) {
  const target = Math.max(0, Number(time) || 0);
  if (!els.audio) return;
  try {
    setAudioCurrentTimeWithNativeContinuity(target, 'book-lyric-seek');
    updateProgress();
  } catch (error) {
  }
  apiJson(`/api/player/seek?${query({ position: Math.round(target) })}`).catch(() => {});
}

function formatTime(seconds) {
  const value = Number.isFinite(seconds) ? Math.max(0, seconds) : 0;
  const mins = Math.floor(value / 60);
  const secs = Math.floor(value % 60);
  return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
}

function compactCount(value) {
  const count = Number(value) || 0;
  if (count >= 100000000) return `${(count / 100000000).toFixed(count >= 1000000000 ? 0 : 1)}\u4ebf`;
  if (count >= 10000) return `${(count / 10000).toFixed(count >= 100000 ? 0 : 1)}\u4e07`;
  return String(count);
}

function clearElement(element) {
  while (element.firstChild) element.removeChild(element.firstChild);
}

function removeElement(element) {
  if (element && element.parentNode) element.parentNode.removeChild(element);
}

function emptyFavoriteDirectories() {
  return Object.keys(MUSIC_PROVIDERS).reduce((directories, provider) => {
    directories[provider] = [];
    return directories;
  }, {});
}

function normalizeStoredFavorite(song, fallbackProvider) {
  if (!song || typeof song !== 'object') return null;
  const provider = MUSIC_PROVIDERS[song.provider] ? song.provider : fallbackProvider;
  const id = song.id === undefined || song.id === null ? '' : String(song.id);
  const title = song.title === undefined || song.title === null ? '' : String(song.title);
  if (!id && !title) return null;
  return {
    id,
    title: title || '未命名歌曲',
    artist: song.artist === undefined || song.artist === null ? '' : String(song.artist),
    album: song.album === undefined || song.album === null ? '' : String(song.album),
    cover: song.cover === undefined || song.cover === null ? '' : String(song.cover),
    duration: Number(song.duration) || 0,
    provider
  };
}

function loadFavoriteDirectories() {
  const directories = emptyFavoriteDirectories();
  try {
    const parsed = JSON.parse(window.localStorage.getItem(FAVORITE_SONGS_KEY) || '{}');
    Object.keys(directories).forEach((provider) => {
      const songs = Array.isArray(parsed && parsed[provider]) ? parsed[provider] : [];
      directories[provider] = songs
        .map((song) => normalizeStoredFavorite(song, provider))
        .filter(Boolean);
    });
  } catch (error) {
    return directories;
  }
  return directories;
}

function saveFavoriteDirectories() {
  try {
    window.localStorage.setItem(FAVORITE_SONGS_KEY, JSON.stringify(state.favoriteDirectories));
  } catch (error) {
    toast('收藏目录保存失败');
  }
}

function loadCommunityBioRecords() {
  try {
    const parsed = JSON.parse(window.localStorage.getItem(COMMUNITY_BIOS_KEY) || '{}');
    return parsed && typeof parsed.records === 'object' && !Array.isArray(parsed.records)
      ? parsed.records
      : {};
  } catch (error) {
    return {};
  }
}

function communityBioIdentity(serverUrl, provider, account = {}, profile = {}) {
  const server = safeText(serverUrl, '').replace(/\/+$/, '').toLowerCase();
  const providerId = safeText(provider, state.activeProvider).toLowerCase();
  const platformUserId = safeText(
    profile.platformUserId || account.userId || account.platformUserId || profile.feId,
    ''
  );
  if (!server || !providerId || !platformUserId) return '';
  return JSON.stringify([server, providerId, platformUserId]);
}

function loadCommunityBio(identity = '') {
  if (!identity) return '';
  const record = loadCommunityBioRecords()[identity];
  return safeText(record && record.bio, '').slice(0, 180);
}

function writeCommunityBio(identity, value) {
  if (!identity) return;
  const records = loadCommunityBioRecords();
  records[identity] = {
    bio: safeText(value, '').slice(0, 180),
    updatedAt: Date.now()
  };
  const compactRecords = Object.fromEntries(
    Object.entries(records)
      .filter(([key, record]) => safeText(key, '') && record && typeof record === 'object')
      .sort((left, right) => Number(right[1].updatedAt || 0) - Number(left[1].updatedAt || 0))
      .slice(0, COMMUNITY_BIO_IDENTITY_LIMIT)
  );
  try {
    window.localStorage.setItem(COMMUNITY_BIOS_KEY, JSON.stringify({ version: 2, records: compactRecords }));
  } catch (error) {}
}

function syncCommunityBioIdentity(identity, remoteProfile = {}) {
  const nextIdentity = safeText(identity, '');
  state.community.profileBioIdentity = nextIdentity;
  if (!nextIdentity) {
    state.community.profileBio = '';
    return;
  }
  const hasRemoteBio = Object.prototype.hasOwnProperty.call(remoteProfile, 'bio');
  state.community.profileBio = hasRemoteBio
    ? safeText(remoteProfile.bio, '').slice(0, 180)
    : loadCommunityBio(nextIdentity);
  if (hasRemoteBio) writeCommunityBio(nextIdentity, state.community.profileBio);
}

function saveCommunityBioLocal(value) {
  state.community.profileBio = safeText(value, '').slice(0, 180);
  writeCommunityBio(state.community.profileBioIdentity, state.community.profileBio);
}

function loadCommunityMessageDnd() {
  try {
    return window.localStorage.getItem(COMMUNITY_MESSAGE_DND_KEY) === 'true';
  } catch (error) {
    return false;
  }
}

function saveCommunityMessageDnd(value) {
  state.community.messageBubbleMuted = !!value;
  try {
    window.localStorage.setItem(COMMUNITY_MESSAGE_DND_KEY, String(state.community.messageBubbleMuted));
  } catch (error) {}
}

function normalizeCommunityMessageBackground(value = {}) {
  const source = value && typeof value === 'object' ? value : {};
  const mediaKind = safeText(source.mediaKind, 'image');
  return {
    enabled: source.enabled === true,
    followWallpaperEngine: source.followWallpaperEngine === true,
    wallpaperId: safeText(source.wallpaperId, ''),
    wallpaperUrl: safeText(source.wallpaperUrl, ''),
    wallpaperName: safeText(source.wallpaperName, ''),
    mediaKind: mediaKind === 'video' || mediaKind === 'web' ? mediaKind : 'image'
  };
}

function loadCommunityMessageBackground() {
  try {
    const parsed = JSON.parse(window.localStorage.getItem(COMMUNITY_MESSAGE_BACKGROUND_KEY) || '{}');
    return normalizeCommunityMessageBackground(parsed);
  } catch (error) {
    return normalizeCommunityMessageBackground();
  }
}

function saveCommunityMessageBackground() {
  state.community.messageBackground = normalizeCommunityMessageBackground(state.community.messageBackground);
  try {
    window.localStorage.setItem(
      COMMUNITY_MESSAGE_BACKGROUND_KEY,
      JSON.stringify(state.community.messageBackground)
    );
  } catch (error) {}
  scheduleClientPreferencesSync();
}

function normalizeCommunityEventCursor(value = '') {
  const cursor = safeText(value, '');
  if (!/^\d+$/.test(cursor)) return '';
  const numeric = Number(cursor);
  return Number.isSafeInteger(numeric) && numeric > 0 ? String(numeric) : '';
}

function loadCommunityHistoryLedger() {
  try {
    const parsed = JSON.parse(window.localStorage.getItem(COMMUNITY_HISTORY_LEDGER_KEY) || '{}');
    const records = Array.isArray(parsed && parsed.records) ? parsed.records : [];
    return records
      .filter((record) => record && typeof record === 'object' && safeText(record.identity, ''))
      .map((record) => ({
        identity: safeText(record.identity, ''),
        updatedAt: Math.max(0, Number(record.updatedAt) || 0),
        cursor: normalizeCommunityEventCursor(record.cursor),
        eventKeys: Array.isArray(record.eventKeys)
          ? record.eventKeys.map((key) => safeText(key, '')).filter(Boolean).slice(-COMMUNITY_HISTORY_SEEN_LIMIT)
          : [],
        messageKeys: Array.isArray(record.messageKeys)
          ? record.messageKeys.map((key) => safeText(key, '')).filter(Boolean).slice(-COMMUNITY_HISTORY_SEEN_LIMIT)
          : []
      }))
      .sort((left, right) => right.updatedAt - left.updatedAt)
      .slice(0, COMMUNITY_HISTORY_IDENTITY_LIMIT);
  } catch (error) {
    return [];
  }
}

function saveCommunityHistoryLedger() {
  const identity = safeText(state.community.eventHistoryIdentity, '');
  if (!identity) return;
  try {
    const records = loadCommunityHistoryLedger().filter((record) => record.identity !== identity);
    records.unshift({
      identity,
      updatedAt: Date.now(),
      cursor: normalizeCommunityEventCursor(state.community.eventCursor),
      eventKeys: state.community.eventSeenKeyOrder.slice(-COMMUNITY_HISTORY_SEEN_LIMIT),
      messageKeys: state.community.messageBubbleSeenOrder.slice(-COMMUNITY_HISTORY_SEEN_LIMIT)
    });
    window.localStorage.setItem(COMMUNITY_HISTORY_LEDGER_KEY, JSON.stringify({
      version: 1,
      records: records.slice(0, COMMUNITY_HISTORY_IDENTITY_LIMIT)
    }));
  } catch (error) {}
}

function restoreCommunityHistoryLedger(identity = '') {
  const normalized = safeText(identity, '');
  state.community.eventHistoryIdentity = normalized;
  state.community.eventCursor = '';
  state.community.eventSeenKeys.clear();
  state.community.eventSeenKeyOrder.length = 0;
  state.community.messageBubbleSeenKeys.clear();
  state.community.messageBubbleSeenOrder.length = 0;
  window.clearTimeout(state.community.messageBubbleTimer);
  state.community.messageBubbleTimer = 0;
  state.community.messageBubbleSeenReady = false;
  state.community.messageBubbles = [];
  renderCommunityMessageBubbles();
  state.community.eventHydrationStartedAt = normalized ? Date.now() : 0;
  state.community.eventHistoryBefore = state.community.eventHydrationStartedAt;
  state.community.eventHistoryCalibrated = false;
  if (!normalized) return;

  const record = loadCommunityHistoryLedger().find((item) => item.identity === normalized);
  if (!record) return;
  state.community.eventCursor = record.cursor;
  record.eventKeys.forEach((key) => {
    state.community.eventSeenKeys.add(key);
    state.community.eventSeenKeyOrder.push(key);
  });
  record.messageKeys.forEach((key) => {
    state.community.messageBubbleSeenKeys.add(key);
    state.community.messageBubbleSeenOrder.push(key);
  });
}

function rememberCommunitySeenKey(seen, order, key, persist = true) {
  const normalized = safeText(key, '');
  if (!normalized || seen.has(normalized)) return false;
  seen.add(normalized);
  order.push(normalized);
  while (order.length > COMMUNITY_HISTORY_SEEN_LIMIT) {
    seen.delete(order.shift());
  }
  if (persist) saveCommunityHistoryLedger();
  return true;
}

function rememberCommunityMessageKey(message = {}, persist = true) {
  return rememberCommunitySeenKey(
    state.community.messageBubbleSeenKeys,
    state.community.messageBubbleSeenOrder,
    communityMessageKey(message),
    persist
  );
}

function loadCommunityCardCollapsed() {
  try {
    return window.localStorage.getItem(COMMUNITY_CARD_COLLAPSED_KEY) === 'true';
  } catch (error) {
    return false;
  }
}

function saveCommunityCardCollapsed(value) {
  try {
    window.localStorage.setItem(COMMUNITY_CARD_COLLAPSED_KEY, String(!!value));
  } catch (error) {}
}

function emptyCommunityFavoriteListening() {
  return { friends: {} };
}

function normalizeCommunityFavoriteListening(value = {}) {
  return value && typeof value === 'object' && !Array.isArray(value)
    && value.friends && typeof value.friends === 'object' && !Array.isArray(value.friends)
    ? { friends: { ...value.friends } }
    : emptyCommunityFavoriteListening();
}

function emptyCommunityListeningStats() {
  return { listenMs: 0, songKeys: [], songCountFloor: 0 };
}

function normalizeCommunityListeningStats(value = {}) {
  const stored = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
  const songKeys = Array.isArray(stored.songKeys)
    ? [...new Set(stored.songKeys.map((key) => safeText(key, '').trim()).filter(Boolean))]
    : [];
  return {
    listenMs: Math.max(0, Math.round(Number(stored.listenMs) || 0)),
    songKeys,
    songCountFloor: Math.max(0, Math.round(Number(stored.songCountFloor) || 0))
  };
}

function emptyCommunityScopedStore() {
  return {
    version: 2,
    legacyMigrated: false,
    legacyMigratedTo: '',
    records: {}
  };
}

function loadCommunityScopedStore(storageKey) {
  try {
    const parsed = JSON.parse(window.localStorage.getItem(storageKey) || '{}');
    if (Number(parsed.version) !== 2 || !parsed.records || typeof parsed.records !== 'object') {
      return emptyCommunityScopedStore();
    }
    return {
      version: 2,
      legacyMigrated: parsed.legacyMigrated === true,
      legacyMigratedTo: safeText(parsed.legacyMigratedTo, ''),
      records: { ...parsed.records }
    };
  } catch (error) {
    return emptyCommunityScopedStore();
  }
}

function compactCommunityScopedRecords(records = {}) {
  return Object.fromEntries(
    Object.entries(records)
      .filter(([identity, record]) => (
        safeText(identity, '') && record && typeof record === 'object'
        && Object.prototype.hasOwnProperty.call(record, 'value')
      ))
      .sort((left, right) => Number(right[1].updatedAt || 0) - Number(left[1].updatedAt || 0))
      .slice(0, COMMUNITY_LOCAL_IDENTITY_LIMIT)
  );
}

function writeCommunityScopedStore(storageKey, root) {
  try {
    window.localStorage.setItem(storageKey, JSON.stringify({
      version: 2,
      legacyMigrated: root.legacyMigrated === true,
      legacyMigratedTo: safeText(root.legacyMigratedTo, ''),
      records: compactCommunityScopedRecords(root.records)
    }));
    return true;
  } catch (error) {
    return false;
  }
}

function loadCommunityScopedValue(storageKey, legacyKey, identity, normalize, emptyValue) {
  const currentIdentity = safeText(identity, '');
  if (!currentIdentity) return emptyValue();
  const root = loadCommunityScopedStore(storageKey);
  const record = root.records[currentIdentity];
  if (record && typeof record === 'object' && Object.prototype.hasOwnProperty.call(record, 'value')) {
    return normalize(record.value);
  }
  if (root.legacyMigrated) return emptyValue();

  let migratedValue = emptyValue();
  let hasLegacyValue = false;
  try {
    const raw = window.localStorage.getItem(legacyKey);
    if (raw !== null) {
      migratedValue = normalize(JSON.parse(raw || '{}'));
      hasLegacyValue = true;
    }
  } catch (error) {}

  root.legacyMigrated = true;
  root.legacyMigratedTo = currentIdentity;
  if (hasLegacyValue) {
    root.records[currentIdentity] = {
      updatedAt: Date.now(),
      value: migratedValue
    };
  }
  if (writeCommunityScopedStore(storageKey, root) && hasLegacyValue) {
    try { window.localStorage.removeItem?.(legacyKey); } catch (error) {}
  }
  return migratedValue;
}

function saveCommunityScopedValue(storageKey, identity, value, normalize) {
  const currentIdentity = safeText(identity, '');
  if (!currentIdentity) return false;
  const root = loadCommunityScopedStore(storageKey);
  root.records[currentIdentity] = {
    updatedAt: Date.now(),
    value: normalize(value)
  };
  return writeCommunityScopedStore(storageKey, root);
}

function loadCommunityFavoriteListening(identity = '') {
  return loadCommunityScopedValue(
    COMMUNITY_FAVORITE_LISTEN_KEY,
    COMMUNITY_FAVORITE_LISTEN_LEGACY_KEY,
    identity,
    normalizeCommunityFavoriteListening,
    emptyCommunityFavoriteListening
  );
}

function saveCommunityFavoriteListening() {
  saveCommunityScopedValue(
    COMMUNITY_FAVORITE_LISTEN_KEY,
    state.community.localDataIdentity,
    state.community.favoriteListening,
    normalizeCommunityFavoriteListening
  );
}

function loadCommunityListeningStats(identity = '') {
  return loadCommunityScopedValue(
    COMMUNITY_LISTENING_STATS_KEY,
    COMMUNITY_LISTENING_STATS_LEGACY_KEY,
    identity,
    normalizeCommunityListeningStats,
    emptyCommunityListeningStats
  );
}

function saveCommunityListeningStats() {
  if (saveCommunityScopedValue(
    COMMUNITY_LISTENING_STATS_KEY,
    state.community.localDataIdentity,
    state.community.listeningStats,
    normalizeCommunityListeningStats
  )) {
    state.community.listeningStatsSavedAt = Date.now();
  }
}

function emptyCommunityTogetherReport() {
  return {
    version: 1,
    partners: {}
  };
}

function normalizeCommunityAvatarOrnament(value = null) {
  if (!value || typeof value !== 'object') return null;
  const achievementId = safeText(value.achievementId, '').slice(0, 64);
  const id = safeText(value.id, achievementId ? `achievement-ornament-${achievementId}` : '').slice(0, 96);
  if (!achievementId || !id) return null;
  const accent = /^#[0-9a-f]{6}$/i.test(safeText(value.accent, ''))
    ? safeText(value.accent, '').toLowerCase()
    : '#9ce5ff';
  return {
    id,
    achievementId,
    name: safeText(value.name, '成就挂饰').slice(0, 80),
    accent,
    equippedAt: Math.max(0, Math.round(Number(value.equippedAt || value.changedAt) || 0))
  };
}

function normalizeCommunityTogetherPartner(value = {}, fallbackId = '') {
  const feId = safeText(value.feId || value.friendId || value.id || fallbackId, '').slice(0, 32);
  if (!feId) return null;
  const sessionIds = Array.isArray(value.sessionIds)
    ? [...new Set(value.sessionIds.map((id) => safeText(id, '')).filter(Boolean))].slice(-40)
    : [];
  return {
    feId,
    username: safeText(value.username || value.name || value.displayName, `FE ${feId}`).slice(0, 80),
    avatarUrl: safeText(value.avatarUrl || value.avatar, '').slice(0, 2048),
    avatarOrnament: normalizeCommunityAvatarOrnament(value.avatarOrnament || value.ornament),
    totalMs: Math.max(0, Math.round(Number(
      value.totalMs || value.totalListenMs || value.totalDurationMs || value.listenMs || value.durationMs
    ) || 0)),
    sessionCount: Math.max(
      sessionIds.length,
      Math.round(Number(value.sessionCount || value.totalSessions || value.sessions) || 0)
    ),
    sessionIds,
    lastListenedAt: Math.max(0, Math.round(Number(
      value.lastListenedAt || value.lastTogetherAt || value.updatedAt
    ) || 0))
  };
}

function normalizeCommunityTogetherReport(value = {}) {
  const normalized = emptyCommunityTogetherReport();
  const source = value && typeof value === 'object' ? value : {};
  const list = Array.isArray(source.partners)
    ? source.partners
    : Array.isArray(source.friends)
      ? source.friends
      : Object.entries(source.partners && typeof source.partners === 'object' ? source.partners : {})
        .map(([feId, partner]) => ({ ...(partner || {}), feId }));
  list.forEach((partner) => {
    const next = normalizeCommunityTogetherPartner(partner);
    if (next) normalized.partners[next.feId] = next;
  });
  return normalized;
}

function loadCommunityTogetherReport(identity = '') {
  return loadCommunityScopedValue(
    COMMUNITY_TOGETHER_REPORT_KEY,
    COMMUNITY_TOGETHER_REPORT_LEGACY_KEY,
    identity,
    normalizeCommunityTogetherReport,
    emptyCommunityTogetherReport
  );
}

function saveCommunityTogetherReport() {
  const report = normalizeCommunityTogetherReport(state.community.togetherReport);
  const partners = Object.values(report.partners)
    .sort((left, right) => right.totalMs - left.totalMs || right.lastListenedAt - left.lastListenedAt)
    .slice(0, 64);
  state.community.togetherReport = {
    version: 1,
    partners: Object.fromEntries(partners.map((partner) => [partner.feId, partner]))
  };
  if (saveCommunityScopedValue(
    COMMUNITY_TOGETHER_REPORT_KEY,
    state.community.localDataIdentity,
    state.community.togetherReport,
    normalizeCommunityTogetherReport
  )) {
    state.community.togetherReportSavedAt = Date.now();
  }
}

function mergeCommunityTogetherReport(value = {}) {
  const remote = normalizeCommunityTogetherReport(value);
  const local = normalizeCommunityTogetherReport(state.community.togetherReport);
  let changed = false;
  Object.values(remote.partners).forEach((partner) => {
    const current = local.partners[partner.feId];
    if (!current) {
      local.partners[partner.feId] = partner;
      changed = true;
      return;
    }
    const mergedSessionIds = [...new Set([
      ...(current.sessionIds || []),
      ...(partner.sessionIds || [])
    ])].slice(-40);
    const merged = {
      ...current,
      username: partner.username || current.username,
      avatarUrl: partner.avatarUrl || current.avatarUrl,
      avatarOrnament: partner.avatarOrnament || current.avatarOrnament,
      totalMs: Math.max(current.totalMs, partner.totalMs),
      sessionCount: Math.max(current.sessionCount, partner.sessionCount, mergedSessionIds.length),
      sessionIds: mergedSessionIds,
      lastListenedAt: Math.max(current.lastListenedAt, partner.lastListenedAt)
    };
    if (JSON.stringify(merged) !== JSON.stringify(current)) {
      local.partners[partner.feId] = merged;
      changed = true;
    }
  });
  if (changed) {
    state.community.togetherReport = local;
    saveCommunityTogetherReport();
  }
  return changed;
}

function syncCommunityLocalStateIdentity(identity = '') {
  const nextIdentity = safeText(identity, '');
  const previousIdentity = safeText(state.community.localDataIdentity, '');
  if (nextIdentity === previousIdentity) return false;

  if (previousIdentity) {
    saveCommunityFavoriteListening();
    saveCommunityListeningStats();
    saveCommunityTogetherReport();
  }

  state.community.localDataIdentity = nextIdentity;
  state.community.favoriteListening = nextIdentity
    ? loadCommunityFavoriteListening(nextIdentity)
    : emptyCommunityFavoriteListening();
  state.community.listeningStats = nextIdentity
    ? loadCommunityListeningStats(nextIdentity)
    : emptyCommunityListeningStats();
  state.community.togetherReport = nextIdentity
    ? loadCommunityTogetherReport(nextIdentity)
    : emptyCommunityTogetherReport();
  state.community.listeningStatsLastAt = 0;
  state.community.listeningStatsSavedAt = 0;
  state.community.togetherReportLastAt = 0;
  state.community.togetherReportSessionId = '';
  state.community.togetherReportSavedAt = 0;
  return true;
}

function loadCommunityOrnamentCache() {
  try {
    const source = JSON.parse(window.localStorage.getItem(COMMUNITY_ORNAMENT_CACHE_KEY) || '{}');
    const friends = source && source.friends && typeof source.friends === 'object' ? source.friends : {};
    return {
      friends: Object.fromEntries(Object.entries(friends).flatMap(([feId, value]) => {
        const ornament = normalizeCommunityAvatarOrnament(value);
        return ornament ? [[safeText(feId, ''), ornament]] : [];
      }))
    };
  } catch (error) {
    return { friends: {} };
  }
}

function saveCommunityOrnamentCache() {
  try {
    window.localStorage.setItem(COMMUNITY_ORNAMENT_CACHE_KEY, JSON.stringify({
      version: 1,
      friends: state.community.ornamentCache?.friends || {}
    }));
  } catch (error) {}
}

function rememberCommunityFriendOrnament(friend = {}) {
  const feId = safeText(friend.feId || friend.friendId, '');
  if (!feId) return null;
  const ornament = normalizeCommunityAvatarOrnament(friend.avatarOrnament || friend.ornament);
  if (!state.community.ornamentCache || typeof state.community.ornamentCache !== 'object') {
    state.community.ornamentCache = { friends: {} };
  }
  if (!state.community.ornamentCache.friends || typeof state.community.ornamentCache.friends !== 'object') {
    state.community.ornamentCache.friends = {};
  }
  if (ornament) state.community.ornamentCache.friends[feId] = ornament;
  else if ('avatarOrnament' in friend || 'ornament' in friend) delete state.community.ornamentCache.friends[feId];
  return ornament;
}

function communityFriendOrnament(friend = {}) {
  const direct = normalizeCommunityAvatarOrnament(friend.avatarOrnament || friend.ornament);
  if (direct) return direct;
  const feId = safeText(friend.feId || friend.friendId, '');
  return normalizeCommunityAvatarOrnament(state.community.ornamentCache?.friends?.[feId]);
}

function communityListeningRemoteMaximum(profile = {}, keys = []) {
  const sources = [
    profile,
    profile.stats,
    profile.listening,
    profile.listeningStats,
    profile.musicStats
  ].filter((source) => source && typeof source === 'object');
  return sources.reduce((maximum, source) => keys.reduce((value, key) => {
    const numeric = Number(source[key]);
    return Number.isFinite(numeric) ? Math.max(value, numeric) : value;
  }, maximum), 0);
}

function mergeCommunityListeningStats(profile = {}) {
  const stats = state.community.listeningStats;
  const remoteListenMs = communityListeningRemoteMaximum(profile, [
    'listenMs',
    'listeningMs',
    'totalListenMs',
    'listenDurationMs',
    'listeningDurationMs',
    'totalListeningMs',
    'listenDuration'
  ]);
  const remoteSongCount = communityListeningRemoteMaximum(profile, [
    'songCount',
    'songsCount',
    'listenedSongs',
    'listenedSongCount',
    'uniqueSongCount',
    'totalSongs'
  ]);
  const nextListenMs = Math.max(stats.listenMs, Math.round(remoteListenMs));
  const nextSongFloor = Math.max(stats.songCountFloor, Math.round(remoteSongCount));
  if (nextListenMs === stats.listenMs && nextSongFloor === stats.songCountFloor) return false;
  stats.listenMs = nextListenMs;
  stats.songCountFloor = nextSongFloor;
  saveCommunityListeningStats();
  return true;
}

function formatCommunityListeningDuration(milliseconds) {
  const minutes = Math.floor(Math.max(0, Number(milliseconds) || 0) / 60000);
  if (minutes < 60) return `${minutes} \u5206\u949f`;
  const hours = Math.floor(minutes / 60);
  const remainder = minutes % 60;
  return remainder ? `${hours} \u5c0f\u65f6 ${remainder} \u5206` : `${hours} \u5c0f\u65f6`;
}

function renderCommunityListeningStats(profile = null) {
  if (profile) mergeCommunityListeningStats(profile);
  const stats = state.community.listeningStats;
  const songCount = Math.max(stats.songCountFloor, stats.songKeys.length);
  if (els.communityListeningDuration) {
    els.communityListeningDuration.textContent = formatCommunityListeningDuration(stats.listenMs);
  }
  if (els.communityListeningSongs) {
    els.communityListeningSongs.textContent = `${songCount} \u9996`;
  }
}

function recordCommunityListeningStats(listenMsDelta, song = state.currentSong) {
  const stats = state.community.listeningStats;
  const delta = Math.max(0, Math.min(30000, Math.round(Number(listenMsDelta) || 0)));
  const signature = communitySongSignature(song || {});
  const hadSong = !!signature && stats.songKeys.includes(signature);
  if (delta > 0) {
    stats.listenMs += delta;
    queueHighDifficultyListenInterval(delta, song);
  }
  if (signature && !hadSong) stats.songKeys.push(signature);
  if (delta <= 0 && (!signature || hadSong)) return;
  renderCommunityListeningStats();
  if (!hadSong || Date.now() - state.community.listeningStatsSavedAt >= 15000) {
    saveCommunityListeningStats();
  }
}

function flushCommunityListeningStats() {
  const nowMs = performance.now();
  const previous = state.community.listeningStatsLastAt;
  state.community.listeningStatsLastAt = nowMs;
  if (
    state.community.listeningStatsPlaying
    && previous > 0
    && state.currentSong
    && state.currentSong.id
    && els.audio.src
  ) {
    recordCommunityListeningStats(nowMs - previous, state.currentSong);
  }
  state.community.listeningStatsPlaying = false;
}

function songCoverSource(song = {}) {
  const direct = safeText(song.cover || song.pic || song.image || song.picUrl || song.albumPic || song.albumpic || song.picurl, '');
  if (direct) return direct;
  const album = song.al && typeof song.al === 'object' ? song.al : (song.album && typeof song.album === 'object' ? song.album : null);
  if (!album) return '';
  return safeText(album.picUrl || album.pic || album.cover || album.img || album.image, '');
}

function songAlbumName(song = {}) {
  if (song.album && typeof song.album === 'object') {
    return safeText(song.album.name || song.album.title, '');
  }
  if (song.al && typeof song.al === 'object') {
    return safeText(song.al.name || song.al.title, '');
  }
  return safeText(song.album, '');
}

function normalizedSong(song = {}, fallbackProvider = state.activeProvider) {
  const provider = providerInfo(song.provider || fallbackProvider).id;
  return {
    id: safeText(song.id, ''),
    title: safeText(song.title || song.name, '未命名歌曲'),
    artist: safeText(song.artist || song.singer, ''),
    album: songAlbumName(song),
    cover: songCoverSource(song),
    duration: Number(song.duration) || 0,
    provider,
    sourceRef: song.sourceRef && typeof song.sourceRef === 'object'
      ? { ...song.sourceRef }
      : {},
    guestSearchMatched: song.guestSearchMatched === true
  };
}

function favoriteSongKey(song = {}, fallbackProvider = state.activeProvider) {
  const provider = providerInfo(song.provider || fallbackProvider).id;
  const id = safeText(song.id, '').trim();
  if (id) return `${provider}:${id}`;
  const title = safeText(song.title || song.name, '').trim().toLowerCase();
  const artist = safeText(song.artist || song.singer, '').trim().toLowerCase();
  return title ? `${provider}:${title}|${artist}` : '';
}

function favoriteDirectory(provider = state.activeProvider) {
  const id = providerInfo(provider).id;
  if (!Array.isArray(state.favoriteDirectories[id])) state.favoriteDirectories[id] = [];
  return state.favoriteDirectories[id];
}

function isSongFavorite(song) {
  const key = favoriteSongKey(song);
  if (!key) return false;
  return favoriteDirectory(song && song.provider).some((item) => favoriteSongKey(item) === key);
}

function updateFavoriteButton(button, song) {
  if (!button) return;
  const hasSong = !!(song && (song.id || song.title));
  const active = hasSong && isSongFavorite(song);
  button.classList.toggle('is-active', active);
  button.setAttribute('aria-pressed', String(active));
  if ('disabled' in button) button.disabled = !hasSong;
  const action = active ? '取消收藏' : '收藏';
  const title = hasSong ? `${action}：${safeText(song.title, '当前歌曲')}` : '收藏当前歌曲';
  button.title = title;
  button.setAttribute('aria-label', title);
}

function updateFavoriteControls(song = state.currentSong) {
  if (isLocalSong(song) && els.dockFavoriteButton) {
    els.dockFavoriteButton.disabled = true;
    els.dockFavoriteButton.classList.remove('is-active');
    els.dockFavoriteButton.setAttribute('aria-pressed', 'false');
    els.dockFavoriteButton.title = '本地歌曲仅保留在本次导入歌单';
    els.dockFavoriteButton.setAttribute('aria-label', els.dockFavoriteButton.title);
  } else {
    updateFavoriteButton(els.dockFavoriteButton, song);
  }
  if (!els.searchSuggestions) return;
  els.searchSuggestions.querySelectorAll('.search-favorite-button').forEach((button) => {
    const index = Number(button.dataset.searchIndex);
    updateFavoriteButton(button, state.searchSuggestions.songs[index]);
  });
}

function favoriteProviderIds() {
  return Object.keys(MUSIC_PROVIDERS).filter((provider) => providerConfigured(provider));
}

function favoriteCount(provider) {
  return favoriteDirectory(provider).length;
}

function totalFavoriteCount() {
  return favoriteProviderIds().reduce((total, provider) => total + favoriteCount(provider), 0);
}

function setFavoriteLibraryOpen(open, provider = state.favoriteLibrary.provider) {
  if (!els.favoriteLibrary) return;
  state.favoriteLibrary.open = !!open && playbackTopSearchAvailable();
  state.favoriteLibrary.provider = providerInfo(provider || state.activeProvider).id;
  els.favoriteLibrary.hidden = !state.favoriteLibrary.open;
  if (els.topFavoritesButton) {
    els.topFavoritesButton.setAttribute('aria-expanded', String(state.favoriteLibrary.open));
  }
  if (els.appShell) {
    els.appShell.classList.toggle('is-favorite-library-open', state.favoriteLibrary.open);
  }
  if (state.favoriteLibrary.open) {
    setSearchSuggestionsOpen(false);
    setPlaylistFavoriteOpen(false);
    renderFavoriteLibrary();
  }
}

function renderFavoriteLibraryTabs() {
  if (!els.favoriteLibraryTabs) return;
  clearElement(els.favoriteLibraryTabs);
  const activeProvider = providerInfo(state.favoriteLibrary.provider).id;
  favoriteProviderIds().forEach((provider) => {
    const info = providerInfo(provider);
    const button = document.createElement('button');
    const active = info.id === activeProvider;
    button.className = `favorite-library-tab${active ? ' is-active' : ''}`;
    button.type = 'button';
    button.dataset.favoriteProvider = info.id;
    button.setAttribute('role', 'tab');
    button.setAttribute('aria-selected', String(active));
    button.textContent = `${info.label} ${favoriteCount(info.id)}`;
    els.favoriteLibraryTabs.appendChild(button);
  });
}

function favoriteLibrarySong(provider, index) {
  const directory = favoriteDirectory(provider);
  return directory[Number(index)] || null;
}

function createFavoriteLibraryItem(song, provider, index) {
  const item = document.createElement('div');
  item.className = 'search-suggestion-item favorite-library-item';
  item.setAttribute('role', 'listitem');

  const play = document.createElement('button');
  play.className = 'search-suggestion-play';
  play.type = 'button';
  play.dataset.favoriteProvider = provider;
  play.dataset.favoriteIndex = String(index);
  play.setAttribute('aria-label', `播放收藏：${safeText(song.title, '未命名歌曲')}`);

  const cover = document.createElement('span');
  cover.className = 'search-suggestion-cover';
  cover.textContent = 'FE';
  const imageUrl = proxiedImageUrl(song.cover || '');
  if (imageUrl) {
    const image = document.createElement('img');
    image.alt = '';
    image.loading = 'eager';
    image.decoding = 'async';
    image.src = imageUrl;
    image.addEventListener('load', () => cover.classList.add('has-cover'));
    image.addEventListener('error', () => removeElement(image));
    cover.appendChild(image);
  }

  const copy = document.createElement('span');
  copy.className = 'search-suggestion-copy';
  const title = document.createElement('strong');
  title.textContent = safeText(song.title, '未命名歌曲');
  const meta = document.createElement('small');
  meta.textContent = searchSuggestionSubtitle(song);
  copy.appendChild(title);
  copy.appendChild(meta);

  const remove = document.createElement('button');
  remove.className = 'search-favorite-button is-active';
  remove.type = 'button';
  remove.dataset.favoriteProvider = provider;
  remove.dataset.favoriteIndex = String(index);
  remove.setAttribute('aria-pressed', 'true');
  remove.setAttribute('aria-label', `取消收藏：${safeText(song.title, '歌曲')}`);
  remove.title = remove.getAttribute('aria-label');
  const icon = document.createElement('span');
  icon.className = 'search-favorite-icon';
  icon.setAttribute('aria-hidden', 'true');
  remove.appendChild(icon);

  play.appendChild(cover);
  play.appendChild(copy);
  item.appendChild(play);
  item.appendChild(remove);
  return item;
}

function renderFavoriteLibraryList() {
  if (!els.favoriteLibraryList) return;
  const provider = providerInfo(state.favoriteLibrary.provider).id;
  const info = providerInfo(provider);
  const songs = favoriteDirectory(provider);
  clearElement(els.favoriteLibraryList);
  if (els.favoriteLibraryMeta) {
    els.favoriteLibraryMeta.textContent = `${info.label} ${songs.length} 首 / 共 ${totalFavoriteCount()} 首`;
  }
  if (!songs.length) {
    const empty = document.createElement('div');
    empty.className = 'favorite-library-empty';
    empty.textContent = `暂无${info.label}收藏，搜索歌曲后点星标保存。`;
    els.favoriteLibraryList.appendChild(empty);
    return;
  }
  const fragment = document.createDocumentFragment();
  songs.forEach((song, index) => fragment.appendChild(createFavoriteLibraryItem(song, provider, index)));
  els.favoriteLibraryList.appendChild(fragment);
}

function renderFavoriteLibrary() {
  if (!els.favoriteLibrary) return;
  renderFavoriteLibraryTabs();
  renderFavoriteLibraryList();
}

function normalizePlatformPlaylist(playlist = {}) {
  const cover = playlist.cover || playlist.coverImgUrl || playlist.picUrl || playlist.logo || playlist.image || playlist.imgurl || playlist.imgUrl || playlist.flexible_cover || playlist.pic;
  return {
    id: safeText(playlist.id || playlist.playlistId || playlist.pid || playlist.tid || playlist.disstid || playlist.listid || playlist.global_collection_id || playlist.specialid || playlist.specialId, ''),
    name: safeText(playlist.name || playlist.title || playlist.dissname || playlist.specialname || playlist.specialName, '未命名歌单'),
    cover: safeText(typeof cover === 'string' ? cover.replace('{size}', '400') : cover, ''),
    trackCount: Number(playlist.trackCount || playlist.songCount || playlist.count || playlist.total || playlist.songcount || playlist.song_count || 0) || 0,
    creator: safeText(playlist.creator || playlist.nickname || playlist.userName || playlist.nick, '')
  };
}

function favoriteTargetPlaylists(provider = state.playlistFavorite.provider) {
  const id = providerInfo(provider).id;
  return Array.isArray(state.playlistFavorite.playlistsByProvider[id])
    ? state.playlistFavorite.playlistsByProvider[id]
    : [];
}

function renderPlaylistFavoriteStatus(message, actions = []) {
  if (!els.playlistFavoritePopover) return;
  const status = document.createElement('div');
  status.className = 'playlist-favorite-status';
  status.textContent = message;
  els.playlistFavoritePopover.appendChild(status);
  if (!actions.length) return;
  const actionRow = document.createElement('div');
  actionRow.className = 'playlist-favorite-actions';
  actions.forEach((action) => actionRow.appendChild(action));
  els.playlistFavoritePopover.appendChild(actionRow);
}

function renderPlaylistFavoritePopover() {
  if (!els.playlistFavoritePopover) return;
  clearElement(els.playlistFavoritePopover);
  if (!state.playlistFavorite.open) return;

  const song = state.playlistFavorite.song;
  const provider = providerInfo(state.playlistFavorite.provider);
  const header = document.createElement('div');
  header.className = 'playlist-favorite-head';
  const titleWrap = document.createElement('span');
  const title = document.createElement('strong');
  title.textContent = '收藏到歌单';
  const meta = document.createElement('small');
  meta.textContent = `${provider.label} · 选择目标歌单`;
  titleWrap.appendChild(title);
  titleWrap.appendChild(meta);
  const close = document.createElement('button');
  close.className = 'playlist-favorite-close';
  close.type = 'button';
  close.dataset.playlistFavoriteClose = 'true';
  close.setAttribute('aria-label', '关闭');
  close.textContent = '×';
  header.appendChild(titleWrap);
  header.appendChild(close);
  els.playlistFavoritePopover.appendChild(header);

  if (song) {
    const summary = document.createElement('div');
    summary.className = 'playlist-favorite-song';
    const cover = document.createElement('span');
    cover.className = 'search-suggestion-cover';
    cover.textContent = 'FE';
    const imageUrl = proxiedImageUrl(song.cover || '');
    if (imageUrl) {
      const image = document.createElement('img');
      image.alt = '';
      image.loading = 'lazy';
      image.decoding = 'async';
      image.src = imageUrl;
      image.addEventListener('load', () => cover.classList.add('has-cover'));
      image.addEventListener('error', () => removeElement(image));
      cover.appendChild(image);
    }
    const copy = document.createElement('span');
    copy.className = 'search-suggestion-copy';
    const songTitle = document.createElement('strong');
    songTitle.textContent = safeText(song.title, '未命名歌曲');
    const songMeta = document.createElement('small');
    songMeta.textContent = searchSuggestionSubtitle(song);
    copy.appendChild(songTitle);
    copy.appendChild(songMeta);
    summary.appendChild(cover);
    summary.appendChild(copy);
    els.playlistFavoritePopover.appendChild(summary);
  }

  if (state.playlistFavorite.error) {
    const error = document.createElement('div');
    error.className = 'playlist-favorite-status is-error';
    error.textContent = state.playlistFavorite.error;
    els.playlistFavoritePopover.appendChild(error);
  }

  if (state.playlistFavorite.loading) {
    renderPlaylistFavoriteStatus('正在读取平台歌单...');
    return;
  }

  const playlists = favoriteTargetPlaylists(provider.id);
  const localButton = document.createElement('button');
  localButton.className = 'playlist-favorite-secondary';
  localButton.type = 'button';
  localButton.dataset.playlistFavoriteLocal = 'true';
  localButton.textContent = '保存到本地收藏';
  const refreshButton = document.createElement('button');
  refreshButton.className = 'playlist-favorite-secondary';
  refreshButton.type = 'button';
  refreshButton.dataset.playlistFavoriteRefresh = 'true';
  refreshButton.textContent = '刷新歌单';

  if (!playlists.length) {
    renderPlaylistFavoriteStatus('未读取到平台歌单，请先登录音乐平台或刷新歌单。', [refreshButton, localButton]);
    return;
  }

  const list = document.createElement('div');
  list.className = 'playlist-favorite-list';
  playlists.forEach((playlist) => {
    const button = document.createElement('button');
    button.className = 'playlist-favorite-choice';
    button.type = 'button';
    button.dataset.playlistId = playlist.id;
    button.disabled = state.playlistFavorite.savingId === playlist.id;

    const cover = document.createElement('span');
    cover.className = 'playlist-favorite-cover';
    cover.textContent = 'FE';
    const imageUrl = proxiedImageUrl(playlist.cover || '');
    if (imageUrl) {
      const image = document.createElement('img');
      image.alt = '';
      image.loading = 'lazy';
      image.decoding = 'async';
      image.src = imageUrl;
      image.addEventListener('load', () => cover.classList.add('has-cover'));
      image.addEventListener('error', () => removeElement(image));
      cover.appendChild(image);
    }

    const copy = document.createElement('span');
    copy.className = 'playlist-favorite-copy';
    const name = document.createElement('strong');
    name.textContent = playlist.name;
    const detail = document.createElement('small');
    detail.textContent = playlist.trackCount ? `${playlist.trackCount} 首` : '平台歌单';
    copy.appendChild(name);
    copy.appendChild(detail);

    const action = document.createElement('span');
    action.className = 'playlist-favorite-add';
    action.textContent = state.playlistFavorite.savingId === playlist.id ? '收藏中' : '收藏';

    button.appendChild(cover);
    button.appendChild(copy);
    button.appendChild(action);
    list.appendChild(button);
  });
  els.playlistFavoritePopover.appendChild(list);

  const actions = document.createElement('div');
  actions.className = 'playlist-favorite-actions';
  actions.appendChild(refreshButton);
  actions.appendChild(localButton);
  els.playlistFavoritePopover.appendChild(actions);
}

function setPlaylistFavoriteOpen(open, song = state.playlistFavorite.song, options = {}) {
  if (!els.playlistFavoritePopover) return;
  state.playlistFavorite.open = !!open && playbackTopSearchAvailable();
  if (song) {
    const normalized = normalizedSong(song, song.provider || state.activeProvider);
    state.playlistFavorite.song = normalized;
    state.playlistFavorite.provider = providerInfo(normalized.provider).id;
  }
  if (!state.playlistFavorite.open) {
    state.playlistFavorite.savingId = '';
    state.playlistFavorite.error = '';
  }
  els.playlistFavoritePopover.hidden = !state.playlistFavorite.open;
  if (els.appShell) {
    els.appShell.classList.toggle('is-playlist-favorite-open', state.playlistFavorite.open);
  }
  if (state.playlistFavorite.open) {
    if (!options.keepSearch) setSearchSuggestionsOpen(false);
    setFavoriteLibraryOpen(false);
  }
  renderPlaylistFavoritePopover();
}

async function loadFavoriteTargetPlaylists(provider = state.playlistFavorite.provider, force = false) {
  const id = providerInfo(provider).id;
  const loadedAt = Number(state.playlistFavorite.loadedAtByProvider[id]) || 0;
  if (!force && favoriteTargetPlaylists(id).length && Date.now() - loadedAt < PLAYLIST_FAVORITE_CACHE_MS) return favoriteTargetPlaylists(id);

  state.playlistFavorite.loading = true;
  state.playlistFavorite.error = '';
  renderPlaylistFavoritePopover();
  try {
    const data = await apiJson(providerPath('/user/playlists', id));
    const source = Array.isArray(data) ? data : (Array.isArray(data.playlists) ? data.playlists : []);
    const playlists = source.map(normalizePlatformPlaylist).filter((playlist) => playlist.id);
    state.playlistFavorite.playlistsByProvider[id] = playlists;
    state.playlistFavorite.loadedAtByProvider[id] = Date.now();
    if (id === state.activeProvider) {
      state.userPlaylists = playlists;
      state.playlistsLoggedIn = playlists.length > 0 || !!(data && data.loggedIn);
    }
    return playlists;
  } catch (error) {
    state.playlistFavorite.error = error.message || '读取歌单失败';
    return [];
  } finally {
    state.playlistFavorite.loading = false;
    renderPlaylistFavoritePopover();
  }
}

async function showPlaylistFavoritePicker(song, options = {}) {
  if (!song || (!song.id && !song.title)) {
    toast('播放栏暂无可收藏歌曲');
    return;
  }
  const normalized = normalizedSong(song, song.provider || state.activeProvider);
  setPlaylistFavoriteOpen(true, normalized, options);
  await loadFavoriteTargetPlaylists(normalized.provider);
}

function saveSongToLocalFavorite(song = state.playlistFavorite.song) {
  if (!song) return;
  toggleFavoriteSong(song, { forceAdd: true });
  setPlaylistFavoriteOpen(false);
}

async function addSongToPlatformPlaylist(playlistId) {
  const song = state.playlistFavorite.song;
  if (!song || !playlistId) return;
  const provider = providerInfo(song.provider || state.playlistFavorite.provider).id;
  const playlists = favoriteTargetPlaylists(provider);
  const playlist = playlists.find((item) => item.id === playlistId);
  state.playlistFavorite.savingId = playlistId;
  state.playlistFavorite.error = '';
  renderPlaylistFavoritePopover();
  try {
    const payload = await apiJson(providerPath('/playlist/add', provider), {
      method: 'POST',
      body: JSON.stringify({ playlistId, song })
    });
    if (payload && payload.ok === false) throw new Error(payload.error || '平台收藏失败');
    toggleFavoriteSong(song, { toast: false, forceAdd: true });
    toast(`已收藏到${playlist ? playlist.name : '平台歌单'}：${safeText(song.title, '歌曲')}`);
    setPlaylistFavoriteOpen(false);
  } catch (error) {
    state.playlistFavorite.error = error.message || '平台收藏失败';
    toggleFavoriteSong(song, { toast: false, forceAdd: true });
    toast(`${state.playlistFavorite.error}，已先保存到本地收藏`);
  } finally {
    state.playlistFavorite.savingId = '';
    renderPlaylistFavoritePopover();
  }
}

function toggleFavoriteSong(song, options = {}) {
  if (!song || (!song.id && !song.title)) {
    toast('播放栏暂无可收藏歌曲');
    return false;
  }
  const normalized = normalizedSong(song);
  const directory = favoriteDirectory(normalized.provider);
  const key = favoriteSongKey(normalized);
  const existingIndex = directory.findIndex((item) => favoriteSongKey(item) === key);
  const providerLabel = providerInfo(normalized.provider).label;
  if (existingIndex >= 0 && !options.forceAdd) {
    directory.splice(existingIndex, 1);
    if (options.toast !== false) toast(`已从${providerLabel}收藏目录移除：${safeText(normalized.title, '歌曲')}`);
  } else if (existingIndex < 0) {
    directory.unshift(normalized);
    if (options.toast !== false) toast(`已收藏到${providerLabel}收藏目录：${safeText(normalized.title, '歌曲')}`);
  } else if (options.toast !== false) {
    toast(`已在${providerLabel}收藏目录：${safeText(normalized.title, '歌曲')}`);
  }
  saveFavoriteDirectories();
  if (existingIndex < 0) unlockAppAchievement('first-favorite');
  updateFavoriteControls(state.currentSong);
  if (state.favoriteLibrary.open) renderFavoriteLibrary();
  return existingIndex < 0;
}

function searchSuggestionSubtitle(song) {
  const artist = safeText(song.artist, '');
  const album = safeText(song.album, '');
  const provider = providerInfo(song.provider || state.activeProvider).label;
  const meta = artist && album ? `${artist} · ${album}` : artist || album;
  return meta ? `${meta} · ${provider}` : provider;
}

function setSearchSuggestionsOpen(open) {
  if (!els.searchSuggestions) return;
  open = !!open && playbackTopSearchAvailable();
  if (open && state.favoriteLibrary.open) setFavoriteLibraryOpen(false);
  if (open && state.playlistFavorite.open) setPlaylistFavoriteOpen(false);
  els.searchSuggestions.hidden = !open;
  if (els.appShell) els.appShell.classList.toggle('is-search-suggestions-open', !!open);
}

function renderSearchSuggestionStatus(message) {
  if (!els.searchSuggestions) return;
  clearElement(els.searchSuggestions);
  const status = document.createElement('div');
  status.className = 'search-suggestion-status';
  status.textContent = message;
  els.searchSuggestions.appendChild(status);
  setSearchSuggestionsOpen(true);
}

function renderSearchSuggestions() {
  if (!els.searchSuggestions) return;
  clearElement(els.searchSuggestions);
  const songs = state.searchSuggestions.songs;
  const keyword = els.searchInput ? els.searchInput.value.trim() : '';
  if (!keyword) {
    setSearchSuggestionsOpen(false);
    return;
  }
  if (!songs.length) {
    renderSearchSuggestionStatus(`没有找到「${keyword}」`);
    return;
  }

  const fragment = document.createDocumentFragment();
  songs.forEach((song, index) => {
    const item = document.createElement('div');
    item.className = 'search-suggestion-item';
    item.setAttribute('role', 'option');

    const play = document.createElement('button');
    play.className = 'search-suggestion-play search-suggestion-play--rich';
    play.type = 'button';
    play.dataset.searchIndex = String(index);
    play.setAttribute('aria-label', `播放：${safeText(song.title, '未命名歌曲')}`);

    const number = document.createElement('span');
    number.className = 'search-suggestion-index';
    number.textContent = String(index + 1).padStart(2, '0');

    const cover = document.createElement('span');
    cover.className = 'search-suggestion-cover';
    cover.textContent = 'FE';
    const imageUrl = proxiedImageUrl(song.cover || '');
    if (imageUrl) {
      const image = document.createElement('img');
      image.alt = '';
      image.loading = 'eager';
      image.decoding = 'async';
      image.src = imageUrl;
      image.addEventListener('load', () => cover.classList.add('has-cover'));
      image.addEventListener('error', () => removeElement(image));
      cover.appendChild(image);
    }

    const copy = document.createElement('span');
    copy.className = 'search-suggestion-copy';
    const title = document.createElement('strong');
    title.textContent = safeText(song.title, '未命名歌曲');
    const meta = document.createElement('small');
    meta.textContent = searchSuggestionSubtitle(song);
    copy.appendChild(title);
    copy.appendChild(meta);

    const duration = document.createElement('span');
    duration.className = 'search-suggestion-duration';
    duration.textContent = song.duration ? formatTime(Number(song.duration)) : '--:--';

    const favorite = document.createElement('button');
    favorite.className = 'search-favorite-button';
    favorite.type = 'button';
    favorite.dataset.searchIndex = String(index);
    const icon = document.createElement('span');
    icon.className = 'search-favorite-icon';
    icon.setAttribute('aria-hidden', 'true');
    favorite.appendChild(icon);

    play.appendChild(number);
    play.appendChild(cover);
    play.appendChild(copy);
    play.appendChild(duration);
    item.appendChild(play);
    item.appendChild(favorite);
    fragment.appendChild(item);
  });
  els.searchSuggestions.appendChild(fragment);
  setSearchSuggestionsOpen(true);
  updateFavoriteControls();
}

function normalizeSearchResults(songs) {
  const seen = new Set();
  return (Array.isArray(songs) ? songs : [])
    .map((song) => normalizedSong(song))
    .filter((song) => {
      const key = favoriteSongKey(song);
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

function isQishuiMetadataSong(song = {}) {
  return providerInfo(song.provider || state.activeProvider).id === 'qishui'
    && song.sourceRef
    && typeof song.sourceRef === 'object'
    && song.sourceRef.metadataOnly === true;
}

function isGuestSearchMatchedSong(song = {}) {
  return song.guestSearchMatched === true
    || (song.sourceRef && song.sourceRef.guestSearchMatch === true);
}

function normalizeQishuiMatchText(value) {
  return safeText(value, '')
    .normalize('NFKC')
    .toLocaleLowerCase()
    .replace(/[\p{P}\p{S}\s]+/gu, '');
}

function qishuiGuestMatchScore(source = {}, candidate = {}) {
  const sourceTitle = normalizeQishuiMatchText(source.title);
  const candidateTitle = normalizeQishuiMatchText(candidate.title);
  if (!sourceTitle || !candidateTitle) return Number.NEGATIVE_INFINITY;
  let score = sourceTitle === candidateTitle
    ? 72
    : sourceTitle.includes(candidateTitle) || candidateTitle.includes(sourceTitle)
      ? 46
      : Number.NEGATIVE_INFINITY;
  if (!Number.isFinite(score)) return score;

  const sourceArtist = normalizeQishuiMatchText(source.artist);
  const candidateArtist = normalizeQishuiMatchText(candidate.artist);
  if (sourceArtist) {
    if (!candidateArtist) return Number.NEGATIVE_INFINITY;
    if (sourceArtist === candidateArtist) score += 24;
    else if (sourceArtist.includes(candidateArtist) || candidateArtist.includes(sourceArtist)) score += 14;
    else return Number.NEGATIVE_INFINITY;
  }

  const sourceAlbum = normalizeQishuiMatchText(source.album);
  const candidateAlbum = normalizeQishuiMatchText(candidate.album);
  if (sourceAlbum && candidateAlbum) {
    if (sourceAlbum === candidateAlbum) score += 8;
    else if (sourceAlbum.includes(candidateAlbum) || candidateAlbum.includes(sourceAlbum)) score += 3;
  }

  const sourceDuration = Number(source.duration);
  const candidateDuration = Number(candidate.duration);
  if (sourceDuration > 0 && candidateDuration > 0) {
    const difference = Math.abs(sourceDuration - candidateDuration);
    if (difference <= 2) score += 14;
    else if (difference <= 5) score += 9;
    else if (difference <= 12) score += 3;
    else if (difference > 30) score -= 16;
  }
  return score;
}

function qishuiGuestMatchCacheKey(song = {}) {
  return [
    normalizeQishuiMatchText(song.title),
    normalizeQishuiMatchText(song.artist),
    normalizeQishuiMatchText(song.album),
    Math.round(Number(song.duration) || 0)
  ].join('|');
}

async function qishuiGuestCandidateIsPlayable(song) {
  try {
    const payload = await apiJson(`/api/song/url?${songParams(song, {
      quality: preferredPlaybackQuality(song.provider)
    })}`);
    return payload.playable === true && /^https:\/\//i.test(safeText(payload.url, ''));
  } catch (error) {
    return false;
  }
}

async function resolveQishuiMetadataViaGuestSearch(song) {
  const cacheKey = qishuiGuestMatchCacheKey(song);
  if (!cacheKey || cacheKey.startsWith('|||')) return null;
  const cached = state.qishuiGuestMatches.cache.get(cacheKey);
  if (cached && Date.now() - cached.time < QISHUI_GUEST_MATCH_CACHE_MS) return cached.song;
  if (state.qishuiGuestMatches.requests.has(cacheKey)) {
    return state.qishuiGuestMatches.requests.get(cacheKey);
  }

  const request = (async () => {
    const providers = QISHUI_GUEST_FALLBACK_PROVIDERS.filter((provider) => (
      provider !== 'qishui' && providerConfigured(provider)
    ));
    const keyword = [safeText(song.title, ''), safeText(song.artist, '')]
      .filter(Boolean)
      .join(' ');
    const responses = await Promise.allSettled(providers.map(async (provider) => {
      const payload = await apiJson(`/api/search?${query({ q: keyword, limit: 12, provider })}`);
      return (Array.isArray(payload.songs) ? payload.songs : [])
        .map((candidate) => normalizedSong(candidate, provider))
        .filter((candidate) => candidate.provider === provider);
    }));
    const seen = new Set();
    const candidates = responses
      .filter((response) => response.status === 'fulfilled')
      .flatMap((response) => response.value)
      .map((candidate) => ({
        song: candidate,
        score: qishuiGuestMatchScore(song, candidate)
      }))
      .filter((candidate) => {
        const id = `${candidate.song.provider}:${safeText(candidate.song.id, '')}`;
        if (!Number.isFinite(candidate.score) || candidate.score < 60 || !candidate.song.id || seen.has(id)) return false;
        seen.add(id);
        return true;
      })
      .sort((left, right) => right.score - left.score);

    for (const candidate of candidates.slice(0, 8)) {
      if (!await qishuiGuestCandidateIsPlayable(candidate.song)) continue;
      const matched = {
        ...candidate.song,
        guestSearchMatched: true,
        sourceRef: {
          ...(candidate.song.sourceRef || {}),
          guestSearchMatch: true,
          guestSearchOrigin: 'qishui-local-metadata',
          guestSearchScore: Math.round(candidate.score)
        }
      };
      setBoundedCacheValue(
        state.qishuiGuestMatches.cache,
        cacheKey,
        { time: Date.now(), song: matched },
        QISHUI_GUEST_MATCH_CACHE_LIMIT
      );
      return matched;
    }
    setBoundedCacheValue(
      state.qishuiGuestMatches.cache,
      cacheKey,
      { time: Date.now(), song: null },
      QISHUI_GUEST_MATCH_CACHE_LIMIT
    );
    return null;
  })();
  state.qishuiGuestMatches.requests.set(cacheKey, request);
  try {
    return await request;
  } finally {
    state.qishuiGuestMatches.requests.delete(cacheKey);
  }
}

async function fetchSearchSuggestions(keyword) {
  const provider = providerInfo(state.activeProvider).id;
  if (!providerConfigured(provider)) {
    state.searchSuggestions.songs = [];
    state.searchSuggestions.loading = false;
    renderSearchSuggestionStatus(`请先导入${providerInfo(provider).label} API 插件`);
    return;
  }
  const cacheKey = `${provider}:${keyword.toLowerCase()}`;
  const cached = state.searchSuggestions.cache.get(cacheKey);
  if (cached && Date.now() - cached.time < SEARCH_SUGGESTION_CACHE_MS) {
    state.searchSuggestions.query = keyword;
    state.searchSuggestions.songs = cached.songs;
    state.searchSuggestions.loading = false;
    renderSearchSuggestions();
    return;
  }
  if (state.searchSuggestions.abortController) {
    state.searchSuggestions.abortController.abort();
  }
  const controller = new AbortController();
  state.searchSuggestions.abortController = controller;
  const requestId = state.searchSuggestions.requestId + 1;
  state.searchSuggestions.requestId = requestId;
  state.searchSuggestions.query = keyword;
  state.searchSuggestions.loading = true;
  renderSearchSuggestionStatus(`正在搜索「${keyword}」`);
  try {
    const data = await apiJson(`/api/search?${query({ q: keyword, limit: 8, provider })}`, {
      signal: controller.signal
    });
    if (requestId !== state.searchSuggestions.requestId || (els.searchInput && els.searchInput.value.trim() !== keyword)) return;
    const songs = normalizeSearchResults(data.songs).slice(0, 8);
    state.searchSuggestions.songs = songs;
    setBoundedCacheValue(
      state.searchSuggestions.cache,
      cacheKey,
      { time: Date.now(), songs },
      SEARCH_SUGGESTION_CACHE_LIMIT
    );
    state.searchSuggestions.loading = false;
    renderSearchSuggestions();
    if (state.searchSuggestions.abortController === controller) state.searchSuggestions.abortController = null;
  } catch (error) {
    if (error && error.name === 'AbortError') {
      if (state.searchSuggestions.abortController === controller) state.searchSuggestions.abortController = null;
      return;
    }
    if (requestId !== state.searchSuggestions.requestId || (els.searchInput && els.searchInput.value.trim() !== keyword)) return;
    state.searchSuggestions.songs = [];
    state.searchSuggestions.loading = false;
    if (state.searchSuggestions.abortController === controller) state.searchSuggestions.abortController = null;
    renderSearchSuggestionStatus(error.message || '搜索失败');
  }
}

function scheduleSearchSuggestions() {
  if (!els.searchInput) return;
  const keyword = els.searchInput.value.trim();
  window.clearTimeout(state.searchSuggestions.timer);
  if (!keyword) {
    if (state.searchSuggestions.abortController) {
      state.searchSuggestions.abortController.abort();
      state.searchSuggestions.abortController = null;
    }
    state.searchSuggestions.songs = [];
    state.searchSuggestions.query = '';
    state.searchSuggestions.requestId += 1;
    setSearchSuggestionsOpen(false);
    return;
  }
  if (state.favoriteLibrary.open) setFavoriteLibraryOpen(false);
  if (state.playlistFavorite.open) setPlaylistFavoriteOpen(false);
  state.searchSuggestions.timer = window.setTimeout(() => fetchSearchSuggestions(keyword), 260);
}

async function playSearchSuggestion(song) {
  if (!song) return;
  const loaded = await loadSong(song);
  if (loaded) {
    setSearchSuggestionsOpen(false);
    els.searchInput.blur();
    toast(`正在播放：${safeText(song.title, '歌曲')}`);
  }
}

async function playFavoriteLibrarySong(song) {
  if (!song) return;
  const loaded = await loadSong(song);
  if (loaded) {
    setFavoriteLibraryOpen(false);
    toast(`正在播放：${safeText(song.title, '歌曲')}`);
  }
}

function normalizeMarketMusicSong(value = {}) {
  const workId = safeText(value.marketWorkId || value.workId, '').slice(0, 96);
  const localUrl = safeText(value.localUrl || value.assetUrl, '');
  if (!workId || !/^\/api\/creative-market\/assets\//.test(localUrl)) return null;
  return {
    id: `market-${workId}`,
    title: safeText(value.title, '创作市场音乐').slice(0, 120),
    artist: safeText(value.artist || value.authorName, 'FE 创作者').slice(0, 80),
    album: safeText(value.album, '创作市场').slice(0, 100),
    cover: safeText(value.cover || value.previewUrl, ''),
    duration: Math.max(0, Number(value.duration) || 0),
    provider: 'local',
    source: 'local',
    localUrl,
    localFingerprint: `market|${workId}`,
    fileName: safeText(value.fileName, `${workId}.mp3`).slice(0, 180),
    fileSize: Math.max(0, Number(value.fileSize) || 0),
    lastModified: Math.max(0, Number(value.updatedAt) || Number(value.publishedAt) || 0),
    mimeType: safeText(value.mimeType, 'audio/mpeg').slice(0, 100),
    extension: localAudioExtension(value.fileName || ''),
    marketWorkId: workId,
    marketInstalled: true
  };
}

function loadMarketMusicLibrary() {
  try {
    const values = JSON.parse(window.localStorage?.getItem(MARKET_MUSIC_LIBRARY_KEY) || '[]');
    return (Array.isArray(values) ? values : []).map(normalizeMarketMusicSong).filter(Boolean).slice(0, 300);
  } catch (error) {
    return [];
  }
}

function saveMarketMusicLibrary() {
  try {
    const values = state.localPlaylistSongs
      .filter((song) => song?.marketInstalled)
      .map((song) => ({
        marketWorkId: song.marketWorkId,
        title: song.title,
        artist: song.artist,
        album: song.album,
        cover: song.cover,
        duration: song.duration,
        localUrl: song.localUrl,
        fileName: song.fileName,
        fileSize: song.fileSize,
        mimeType: song.mimeType,
        updatedAt: song.lastModified
      }));
    window.localStorage?.setItem(MARKET_MUSIC_LIBRARY_KEY, JSON.stringify(values));
  } catch (error) {}
}

function addCreativeMarketMusic(item = {}, options = {}) {
  const workId = safeText(item.id || item.workId, '');
  const assetUrl = safeText(item.assetUrl || item.asset?.url, '');
  const song = normalizeMarketMusicSong({
    marketWorkId: workId,
    title: item.metadata?.title || item.title,
    artist: item.metadata?.artist || item.author?.name,
    album: item.metadata?.album || '创作市场',
    cover: item.previewUrl,
    duration: item.metadata?.duration,
    localUrl: assetUrl,
    fileName: item.asset?.fileName || item.metadata?.fileName || item.fileName,
    fileSize: item.asset?.size || item.size,
    mimeType: item.asset?.mimeType || item.mimeType,
    updatedAt: item.updatedAt || item.publishedAt
  });
  if (!song) throw new Error('音乐作品没有可用的服务器音频地址');
  const existingIndex = state.localPlaylistSongs.findIndex((entry) => entry.marketWorkId === workId);
  if (existingIndex >= 0) state.localPlaylistSongs.splice(existingIndex, 1, song);
  else state.localPlaylistSongs.push(song);
  saveMarketMusicLibrary();
  renderPlaylistOrbit(playbackPlaylists());
  if (options.openShelf !== false) {
    state.activePlaylistId = LOCAL_PLAYLIST_ID;
    if (!state.playbackPage) enterPlaybackPage();
    renderPlaylistShelf(localPlaylistDescriptor(), state.localPlaylistSongs);
  }
  unlockAppAchievement('local-import');
  return song;
}

function localAudioExtension(name = '') {
  const match = /\.([^.]+)$/.exec(String(name));
  return match ? match[1].trim().toLowerCase() : '';
}

function isLocalAudioFile(file) {
  if (!file || typeof file.name !== 'string') return false;
  if (safeText(file.type, '').toLowerCase().startsWith('audio/')) return true;
  return LOCAL_AUDIO_EXTENSIONS.has(localAudioExtension(file.name));
}

function isLocalSong(song = state.currentSong) {
  return !!(song && (song.source === 'local' || song.provider === 'local') && safeText(song.localUrl, ''));
}

function localFileFingerprint(file) {
  return `${file.name}|${Number(file.size) || 0}|${Number(file.lastModified) || 0}`;
}

function localFingerprintId(fingerprint) {
  let hash = 2166136261;
  for (let index = 0; index < fingerprint.length; index += 1) {
    hash ^= fingerprint.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `local-${(hash >>> 0).toString(36)}`;
}

function localTrackCopy(file) {
  const extension = localAudioExtension(file.name);
  const baseName = file.name.replace(/\.[^.]+$/, '').trim() || file.name;
  const split = /^(.+?)\s+[-–—]\s+(.+)$/.exec(baseName);
  return {
    title: split ? split[2].trim() : baseName,
    artist: split ? split[1].trim() : '本地音乐',
    album: extension ? `${extension.toUpperCase()} · 本地导入` : '本地导入'
  };
}

function localPlaylistDescriptor() {
  return {
    id: LOCAL_PLAYLIST_ID,
    name: '本地导入歌单',
    creator: '本地设备',
    trackCount: state.localPlaylistSongs.length,
    provider: 'local',
    local: true
  };
}

function playbackPlaylists() {
  const playlists = [
    localPlaylistDescriptor(),
    ...state.recommendedPlaylists,
    ...state.userPlaylists
  ];
  const seen = new Set();
  return playlists.filter((playlist) => {
    if (!playlist || !playlist.id) return false;
    const key = `${safeText(playlist.provider, state.activeProvider)}:${playlist.id}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function openLocalPlaylist() {
  state.activePlaylistId = LOCAL_PLAYLIST_ID;
  updateActivePlaylistCard();
  if (!state.playbackPage) enterPlaybackPage();
  if (!state.localPlaylistSongs.length) {
    renderPlaylistShelf(localPlaylistDescriptor(), [], { preserveScroll: false });
    els.localPlaylistInput?.click();
    return;
  }
  renderPlaylistShelf(localPlaylistDescriptor(), state.localPlaylistSongs, { preserveScroll: true });
}

async function importLocalAudioFiles(fileList, options = {}) {
  const files = Array.from(fileList || []);
  const existing = new Set(state.localPlaylistSongs.map((song) => song.localFingerprint));
  let added = 0;
  let skipped = 0;

  files.forEach((file) => {
    if (!isLocalAudioFile(file)) {
      skipped += 1;
      return;
    }
    const fingerprint = localFileFingerprint(file);
    if (existing.has(fingerprint)) {
      skipped += 1;
      return;
    }
    const localUrl = URL.createObjectURL(file);
    const copy = localTrackCopy(file);
    state.localObjectUrls.add(localUrl);
    state.localPlaylistSongs.push({
      id: localFingerprintId(fingerprint),
      ...copy,
      cover: '',
      duration: 0,
      provider: 'local',
      source: 'local',
      localUrl,
      localFingerprint: fingerprint,
      fileName: file.name,
      fileSize: Number(file.size) || 0,
      lastModified: Number(file.lastModified) || 0,
      mimeType: safeText(file.type, ''),
      extension: localAudioExtension(file.name)
    });
    existing.add(fingerprint);
    added += 1;
  });

  renderPlaylistOrbit(playbackPlaylists());
  if (added > 0 && options.openShelf !== false) {
    state.activePlaylistId = LOCAL_PLAYLIST_ID;
    if (!state.playbackPage) enterPlaybackPage();
    renderPlaylistShelf(localPlaylistDescriptor(), state.localPlaylistSongs);
  }
  if (options.silent !== true) {
    if (added > 0) toast(`已导入 ${added} 首本地歌曲${skipped ? `，跳过 ${skipped} 个重复或非音频文件` : ''}`);
    else toast(files.length ? '没有可新增的本地音频文件' : '未选择本地歌曲');
  }
  if (added > 0) unlockAppAchievement('local-import');
  return { added, skipped, songs: state.localPlaylistSongs };
}

function revokeLocalObjectUrls() {
  state.localObjectUrls.forEach((url) => URL.revokeObjectURL(url));
  state.localObjectUrls.clear();
}

function visiblePlaylists(playlists) {
  return playlists.filter((playlist) => playlist && playlist.id);
}

function playlistSignature(playlists) {
  return playlists
    .map((playlist) => [
      playlist.id,
      playlist.name || '',
      playlist.cover || '',
      playlist.trackCount || 0,
      playlist.playCount || 0,
      playlist.recommended === true ? 'recommended' : ''
    ].join('|'))
    .join('::');
}

function toast(message) {
  els.toast.textContent = message;
  els.toast.classList.add('show');
  window.clearTimeout(toast.timer);
  toast.timer = window.setTimeout(() => els.toast.classList.remove('show'), 2600);
}

function clientVersionDescriptor(value) {
  const normalized = safeText(value, '').trim().replace(/^v(?=\d)/i, '');
  const match = normalized.match(/^(\d+(?:\.\d+)*)(?:-([0-9A-Za-z.-]+))?$/);
  if (!match) return null;
  return {
    parts: match[1].split('.').map((part) => Number(part)),
    prerelease: Boolean(match[2])
  };
}

function compareClientVersions(left, right) {
  const next = clientVersionDescriptor(left);
  const current = clientVersionDescriptor(right);
  if (!next || !current) return 0;
  const length = Math.max(next.parts.length, current.parts.length);
  for (let index = 0; index < length; index += 1) {
    const difference = (next.parts[index] || 0) - (current.parts[index] || 0);
    if (difference) return difference > 0 ? 1 : -1;
  }
  if (next.prerelease === current.prerelease) return 0;
  return next.prerelease ? -1 : 1;
}

function officialGitHubReleaseAsset(asset) {
  const name = safeText(asset?.name, '').trim();
  const url = safeText(asset?.browser_download_url, '').trim();
  if (!name || !/^FE[-_. ]?Monster.*\.exe$/i.test(name)) return false;
  try {
    const parsed = new URL(url);
    return parsed.protocol === 'https:'
      && parsed.hostname.toLowerCase() === 'github.com'
      && parsed.pathname.startsWith('/2292576833/FE-Monster/releases/download/');
  } catch (error) {
    return false;
  }
}

function normalizeGitHubRelease(payload = {}) {
  const version = safeText(payload.tag_name || payload.name, '').trim().replace(/^v(?=\d)/i, '');
  if (!clientVersionDescriptor(version)) return null;
  const assets = Array.isArray(payload.assets) ? payload.assets.filter(officialGitHubReleaseAsset) : [];
  const installer = assets.find((asset) => /(?:setup|installer)/i.test(safeText(asset.name, '')))
    || assets[0]
    || null;
  const digest = safeText(installer?.digest, '');
  return {
    source: 'github',
    version,
    releaseNotes: safeText(payload.body, '').trim() || safeText(payload.name, '').trim() || 'GitHub 已发布新客户端版本。',
    downloadUrl: safeText(installer?.browser_download_url, ''),
    htmlUrl: safeText(payload.html_url, ''),
    fileSize: Number(installer?.size) || 0,
    sha256: digest.toLowerCase().startsWith('sha256:') ? digest.slice(7) : '',
    publishedAt: safeText(payload.published_at, '')
  };
}

function setAvailableClientUpdate(release = {}) {
  const version = safeText(release.version, '').trim();
  if (!version) return false;
  state.update.release = { ...release, version };
  if (els.updateNoticeButton) {
    els.updateNoticeButton.hidden = false;
    els.updateNoticeButton.dataset.version = version;
    els.updateNoticeButton.setAttribute('aria-label', `发现新版本 ${version}`);
    els.updateNoticeButton.title = `发现新版本 ${version}`;
  }
  return true;
}

function clearAvailableClientUpdate(source = '') {
  if (state.update.installing) return;
  if (source && state.update.release?.source !== source) return;
  state.update.release = null;
  if (els.updateNoticeButton) {
    els.updateNoticeButton.hidden = true;
    delete els.updateNoticeButton.dataset.version;
    els.updateNoticeButton.setAttribute('aria-label', '发现新版本');
    els.updateNoticeButton.title = '发现新版本';
  }
}

async function checkGitHubClientUpdate({ force = false } = {}) {
  if (DESKTOP_SCENE_CLIENT || document.hidden || navigator.onLine === false) return state.update.release;
  const now = Date.now();
  if (!force && now - state.update.lastCheckedAt < CLIENT_UPDATE_CHECK_INTERVAL_MS) {
    return state.update.release;
  }
  if (state.update.checkPromise) return state.update.checkPromise;
  state.update.lastCheckedAt = now;
  const controller = typeof AbortController === 'function' ? new AbortController() : null;
  const timeout = controller
    ? window.setTimeout(() => controller.abort(new DOMException('GitHub update check timed out', 'TimeoutError')), 8000)
    : 0;
  state.update.checkPromise = (async () => {
    const [installed, response] = await Promise.all([
      apiJson('/api/app/version', { timeoutMs: 5000 }),
      fetch(CLIENT_UPDATE_GITHUB_API, {
        cache: 'no-store',
        signal: controller?.signal,
        headers: {
          Accept: 'application/vnd.github+json',
          'X-GitHub-Api-Version': '2022-11-28'
        }
      })
    ]);
    if (!response.ok) throw new Error(`GitHub release check failed: ${response.status}`);
    const release = normalizeGitHubRelease(await response.json());
    if (release && compareClientVersions(release.version, installed.version) > 0) {
      setAvailableClientUpdate(release);
      return release;
    }
    clearAvailableClientUpdate('github');
    return null;
  })().catch(() => null).finally(() => {
    window.clearTimeout(timeout);
    state.update.checkPromise = null;
  });
  return state.update.checkPromise;
}

function updateProgress(percent = 0, text = '') {
  const next = clamp(Number(percent) || 0, 0, 100);
  if (els.updateProgressBar) els.updateProgressBar.style.transform = `scaleX(${(next / 100).toFixed(3)})`;
  if (els.updateProgressText) els.updateProgressText.textContent = text || `${Math.round(next)}%`;
}

function showUpdateDialog(release = {}) {
  if (!els.updateDialog) return;
  const version = safeText(release.version, '');
  const downloadUrl = safeText(release.downloadUrl, '');
  if (!version) return;
  state.update.release = release;
  state.update.progressId = '';
  state.update.installing = false;
  if (els.updateVersion) els.updateVersion.textContent = version;
  if (els.updateNotes) els.updateNotes.textContent = safeText(release.releaseNotes || release.notes, '服务器已发布新客户端版本。');
  if (els.updateInstallButton) {
    els.updateInstallButton.disabled = !downloadUrl;
    els.updateInstallButton.textContent = downloadUrl ? '立即更新' : '暂无安装包';
  }
  if (els.updateLaterButton) els.updateLaterButton.disabled = false;
  updateProgress(0, '等待确认');
  els.updateDialog.hidden = false;
}

function hideUpdateDialog() {
  if (!els.updateDialog || state.update.installing) return;
  els.updateDialog.hidden = true;
}

async function startClientUpdate() {
  if (!state.update.release || state.update.installing) return;
  if (!safeText(state.update.release.downloadUrl, '')) {
    updateProgress(0, 'GitHub 发布页暂未提供可安装文件');
    return;
  }
  state.update.installing = true;
  if (els.updateInstallButton) {
    els.updateInstallButton.disabled = true;
    els.updateInstallButton.textContent = '更新中';
  }
  if (els.updateLaterButton) els.updateLaterButton.disabled = true;
  updateProgress(1, '准备更新');
  try {
    const payload = await apiJson('/api/update/install', {
      method: 'POST',
      body: JSON.stringify({ release: state.update.release })
    });
    state.update.progressId = safeText(payload.progressId, '');
    if (!state.update.progressId) throw new Error('更新任务未创建');
    pollClientUpdateProgress();
    window.clearInterval(state.update.progressTimer);
    state.update.progressTimer = window.setInterval(pollClientUpdateProgress, 900);
  } catch (error) {
    state.update.installing = false;
    if (els.updateInstallButton) {
      els.updateInstallButton.disabled = false;
      els.updateInstallButton.textContent = '重试更新';
    }
    if (els.updateLaterButton) els.updateLaterButton.disabled = false;
    updateProgress(0, error.message || '更新启动失败');
  }
}

async function pollClientUpdateProgress() {
  if (document.hidden || !state.update.progressId) return;
  try {
    const payload = await apiJson(`/api/update/progress?${query({ id: state.update.progressId })}`);
    const percent = Number(payload.percent) || 0;
    const status = safeText(payload.status, '');
    updateProgress(percent, safeText(payload.message, `${Math.round(percent)}%`));
    if (status === 'completed' || status === 'ready' || status === 'failed') {
      window.clearInterval(state.update.progressTimer);
      state.update.progressTimer = 0;
      state.update.installing = false;
      if (els.updateInstallButton) {
        els.updateInstallButton.disabled = status !== 'failed';
        els.updateInstallButton.textContent = status === 'failed' ? '重试更新' : '已完成';
      }
      if (els.updateLaterButton) {
        els.updateLaterButton.disabled = false;
        els.updateLaterButton.textContent = '关闭';
      }
      if (status === 'completed' && els.updateNoticeButton) els.updateNoticeButton.hidden = true;
    }
  } catch (error) {
    updateProgress(0, error.message || '读取更新进度失败');
  }
}

function accountName(payload) {
  const account = payload && payload.account ? payload.account : {};
  const profile = payload && payload.profile ? payload.profile : {};
  const nestedProfile = account && account.profile ? account.profile : {};
  return safeText(
    account.nickname
      || account.nick
      || account.username
      || account.userName
      || account.name
      || profile.nickname
      || profile.username
      || nestedProfile.nickname
      || nestedProfile.username
      || account.userId,
    ''
  );
}

function accountAvatar(payload) {
  const account = payload && payload.account ? payload.account : {};
  const profile = payload && payload.profile ? payload.profile : {};
  const nestedProfile = account && account.profile ? account.profile : {};
  let raw = safeText(
    account.avatarUrl
      || account.avatar
      || account.headimg
      || account.pic
      || account.headPic
      || profile.avatarUrl
      || profile.avatar
      || profile.headimg
      || profile.pic
      || nestedProfile.avatarUrl
      || nestedProfile.avatar,
    ''
  );
  const qqUserId = safeText(account.userId || account.uin || account.qq, '');
  if (!raw && payload && payload.provider === 'qq' && /^[1-9]\d{4,}$/.test(qqUserId)) {
    raw = `https://q.qlogo.cn/headimg_dl?dst_uin=${encodeURIComponent(qqUserId)}&spec=140`;
  }
  if (!raw) return '';
  if (/^(data:|blob:)/i.test(raw)) return raw;
  if (/^https?:\/\//i.test(raw)) return proxiedImageUrl(raw);
  return raw;
}

function renderLoginAvatar(payload, loggedIn) {
  if (!els.loginAvatar || !els.loginAvatarImage) return;
  const avatarUrl = loggedIn ? accountAvatar(payload) : '';
  els.loginAvatar.classList.toggle('has-avatar', !!avatarUrl);
  if (avatarUrl) {
    if (els.loginAvatarImage.getAttribute('src') !== avatarUrl) els.loginAvatarImage.src = avatarUrl;
  } else {
    els.loginAvatarImage.removeAttribute('src');
  }
}

function communityAvatarUrl(source = {}) {
  const raw = safeText(source.avatarUrl || source.avatar || source.headimg || source.pic, '');
  if (!raw) return '';
  if (/^(data:|blob:)/i.test(raw)) return raw;
  if (/^https?:\/\//i.test(raw)) return proxiedImageUrl(raw);
  return raw;
}

const communityEntranceAnimations = new WeakMap();

function playCommunityEntrance(element, kind = 'page') {
  if (!element || reducedMotion || typeof element.animate !== 'function') return null;
  const previous = communityEntranceAnimations.get(element);
  if (previous) previous.cancel();
  const frames = kind === 'panel'
    ? [
        { opacity: 0.32, scale: 0.985 },
        { opacity: 1, scale: 1 }
      ]
    : kind === 'mini'
      ? [
          { opacity: 0.24, translate: '0 8px', scale: 0.99 },
          { opacity: 1, translate: '0 0', scale: 1 }
        ]
      : [
          { opacity: 0.28, translate: '10px 0', filter: 'blur(2px)' },
          { opacity: 1, translate: '0 0', filter: 'blur(0)' }
        ];
  const animation = element.animate(frames, {
    duration: kind === 'page' ? 190 : COMMUNITY_ENTRANCE_DURATION_MS,
    easing: 'cubic-bezier(0.16, 1, 0.3, 1)',
    fill: 'none'
  });
  communityEntranceAnimations.set(element, animation);
  const release = () => {
    if (communityEntranceAnimations.get(element) === animation) {
      communityEntranceAnimations.delete(element);
    }
  };
  animation.addEventListener('finish', release, { once: true });
  animation.addEventListener('cancel', release, { once: true });
  return animation;
}

