  reactivity: '音乐响应',
  rendering: '渲染',
  textures: '纹理',
  runtimeControls: '当前运行参数',
  lightingMode: '光照模式',
  weatherMode: '天气模式',
  textPreset: '歌词效果',
  lyricBrightness: '歌词亮度',
  lyricSpeed: '歌词速度',
  cubeIntensity: '场景强度',
  coverBackground: '封面背景',
  freeCubeStyle: '方块样式',
  freeCubeBackground: '柔光背景',
  cubeCount: '方块数量',
  particleCount: '星河粒子',
  planeParticleCount: '平面粒子',
  cubeParticleCount: '3D六面粒子',
  mirrorCount: '镜面数量',
  seamCount: '纵深接缝',
  reflectionMode: '反射方式',
  reflectionResolution: '反射分辨率',
  nodalMode: '节点模态',
