  sonicGroundColor: '地面颜色',
  sonicGroundEmission: '地面自发光',
  sonicGroundMoundHeight: '隆起高度',
  sonicGroundMoundRadius: '隆起宽度',
  sonicFountain: '粒子喷泉',
  sonicFountainColor: '喷泉颜色',
  sonicStarfield: '星空粒子',
  sonicStarfieldColor: '星空颜色',
  sonicGalaxy: '星河粒子',
  sonicGalaxyColor: '星河颜色',
